const ll INF = 1000*1000*1000;

struct Edge {
    ll to, cap, cost, flow;
    size_t rev;
};

class MinCostFlow {
public:
    vector<vector<Edge>> g;
    ll n;
    MinCostFlow(ll n) : n(n), g(n) {}
    void add_edge(ll from, ll to, ll cap, ll cost) {
        Edge a = {to, cap, cost, 0, (ll)g[to].size()};
        Edge b = {from, 0, -cost, 0, (ll)g[from].size()};
        g[from].push_back(a);
        g[to].push_back(b);
    }
    pair<ll,ll> min_cost_flow(ll s, ll t, ll maxf) {
        ll flow = 0, cost = 0;
        while (flow < maxf) {
            vector<ll> id(n, 0);
            vector<ll> d(n, INF);
            vector<ll> q(n);
            vector<ll> p(n);
            vector<size_t> p_edge(n);
            ll qh=0, qt=0;
            q[qt++] = s;
            d[s] = 0;
            while (qh != qt) {
                ll v = q[qh++];
                id[v] = 2;
                if (qh == n) qh = 0;
                for (size_t i=0; i<g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.flow < e.cap && d[v] + e.cost < d[e.to]) {
                        d[e.to] = d[v] + e.cost;
                        if (id[e.to] == 0) {
                            q[qt++] = e.to;
                            if (qt == n) qt = 0;
                        } else if (id[e.to] == 2) {
                            if (--qh == -1) qh = n-1;
                            q[qh] = e.to;
                        }
                        id[e.to] = 1;
                        p[e.to] = v;
                        p_edge[e.to] = i;
                    }
                }
            }
            if (d[t] == INF) break;
            ll add = maxf - flow;
            for (ll v=t; v!=s; v=p[v]) {
                ll pv = p[v]; size_t pe = p_edge[v];
                add = min(add, g[pv][pe].cap - g[pv][pe].flow);
            }
            for (ll v=t; v!=s; v=p[v]) {
                ll pv = p[v]; size_t pe = p_edge[v];
                size_t re = g[pv][pe].rev;
                g[pv][pe].flow += add;
                g[v][re].flow -= add;
                cost += g[pv][pe].cost * add;
            }
            flow += add;
        }
        return {flow, cost};
    }
};

