struct Edge {
    ll to, cap, cost, flow;
    size_t rev;
};

void addEdge(vector<vector<Edge>>& g, ll a, ll b, ll u, ll c) {
    Edge e1 = {b, u, c, 0, g[b].size()};
    Edge e2 = {a, 0, -c, 0, g[a].size()};
