        for (int j = 0; j < tim-1; ++j) {
            for (int l = 0; l < 50; ++l) {
                addEdge(g, j*50+x, (j+1)*50+y, 1, K::c + K::d * ((l+1)*(l+1) - l*l));
                addEdge(g, j*50+y, (j+1)*50+x, 1, K::c + K::d * ((l+1)*(l+1) - l*l));
            }
        }
    }
    s = 0, t = 1;

    ll flow = 0, cost = 0;
    while (flow < K) {
        vector<ll> dist(N, INF);
        vector<ll> prevv(N, -1);
        vector<size_t> preve(N);
