using namespace std;

struct MCMF {
    struct Edge {
        int to, rev, cap, cost, orig;
    };

    int N, S, T;
    vector<vector<Edge>> g;

    MCMF(int n, int s, int t) : N(n), S(s), T(t), g(n) {}

    int add_edge(int v, int u, int cap, int cost) {
        Edge a{u, (int)g[u].size(), cap, cost, cost};
        Edge b{v, (int)g[v].size(), 0, -cost, -cost};
        g[v].push_back(a);
        g[u].push_back(b);
        return (int)g[v].size() - 1;
    }

    pair<int,int> run() {
        int flow = 0, total_cost = 0;
        const int INF = INT_MAX / 2;

        while (true) {
            vector<int> dist(N, INF), prev_v(N, -1), prev_e(N, -1), max_f(N, 0);
            priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;

            dist[S] = 0;
            max_f[S] = INT_MAX;
            pq.push({0, S});

            while (!pq.empty()) {
                int d = pq.top().first;
                int v = pq.top().second;
                pq.pop();
                if (d != dist[v]) continue;

                for (int i = 0; i < (int)g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap <= 0) continue;
                    int nd = d + e.cost;
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        prev_v[e.to] = v;
                        prev_e[e.to] = i;
                        max_f[e.to] = min(max_f[v], e.cap);
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[T] == INF) break;

            int add = max_f[T];
            for (int v = T; v != S; v = prev_v[v]) {
                Edge &e = g[prev_v[v]][prev_e[v]];
                total_cost += add * e.orig;
                e.cap -= add;
                g[v][e.rev].cap += add;
            }
            flow += add;

            for (int v = 0; v < N; ++v) {
                if (dist[v] == INF) continue;
                for (Edge &e : g[v]) {
                    if (dist[e.to] != INF)
                        e.cost += dist[v] - dist[e.to];
                }
            }
        }

        return {flow, total_cost};
    }
};

