using namespace std;

struct PotentialMinCost {
    struct Edge {
        int to, flow, cap, cost;
    };

    int n, source, sink;
    vector<vector<int>> adj;
    vector<Edge> edges;
    vector<int> pot;

    PotentialMinCost(int n, int source, int sink) : n(n), source(source), sink(sink), adj(n) {}

    int add_edge(int a, int b, int cap, int cost) {
        int id = (int)edges.size();
        adj[a].push_back(id);
        edges.push_back({b, 0, cap, cost});
        adj[b].push_back(id + 1);
        edges.push_back({a, 0, 0, -cost});
        return id;
    }

    pair<int,int> solve() {
        const int INF = INT_MAX / 2;
        int flow = 0, cost = 0;
        pot.assign(n, 0);

        while (true) {
            vector<int> dist(n, INF), prev_edge(n, -1), maxf(n, 0);
            priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;

            dist[source] = 0;
            maxf[source] = INT_MAX;
            pq.push(make_pair(0, source));

            while (!pq.empty()) {
                int d = pq.top().first;
                int v = pq.top().second;
                pq.pop();

                if (d != dist[v]) continue;

                for (int id : adj[v]) {
                    Edge &e = edges[id];
                    if (e.flow < e.cap) {
                        int rcost = e.cost + pot[v] - pot[e.to];
                        int nd = d + rcost;

                        if (nd < dist[e.to]) {
                            dist[e.to] = nd;
                            prev_edge[e.to] = id;
                            maxf[e.to] = min(maxf[v], e.cap - e.flow);
                            pq.push(make_pair(nd, e.to));
                        }
                    }
                }
            }

            if (dist[sink] == INF) break;

            int add = maxf[sink];
            for (int v = sink; v != source; v = edges[prev_edge[v] ^ 1].to) {
                Edge &e = edges[prev_edge[v]];
                e.flow += add;
                edges[prev_edge[v] ^ 1].flow -= add;
                cost += add * e.cost;
            }

            for (int v = 0; v < n; ++v)
                if (dist[v] < INF) pot[v] += dist[v];

            flow += add;
        }

        return make_pair(flow, cost);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, K, c, d;
