const int INF = 0x3f3f3f3f;

struct MCMF {
    struct Edge { int to, cap, cost, next; };
    vector<int> head;
    vector<Edge> edges;
    int s, t, n;

    MCMF(int n) : n(n), head(n, -1) {}

    void addEdge(int u, int v, int cap, int cost) {
        int idx = edges.size();
        edges.push_back({v, cap, cost, head[u]});
        head[u] = idx;
        edges.push_back({u, 0, -cost, head[v]});
        head[v] = idx + 1;
    }

    bool spfa(vector<int>& dist, vector<int>& pre, vector<int>& preEdge) {
        vector<int> inq(n, 0);
        dist.assign(n, INF);
        pre.assign(n, -1);
        preEdge.assign(n, -1);
        queue<int> q;
        dist[s] = 0;
        inq[s] = 1;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = 0;
            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                if (edges[e].cap > 0 && dist[v] > dist[u] + edges[e].cost) {
                    dist[v] = dist[u] + edges[e].cost;
                    pre[v] = u;
                    preEdge[v] = e;
                    if (!inq[v]) {
                        inq[v] = 1;
                        q.push(v);
                    }
                }
            }
        }
        return dist[t] < INF;
    }

    int minCostFlow(int s, int t) {
        this->s = s;
        this->t = t;
        int res = 0;
        vector<int> dist, pre, preEdge;
        while (spfa(dist, pre, preEdge)) {
            int add = INF;
            for (int v = t; v != s; v = pre[v])
                add = min(add, edges[preEdge[v]].cap);
            for (int v = t; v != s; v = pre[v]) {
                int e = preEdge[v];
                edges[e].cap -= add;
                edges[e ^ 1].cap += add;
            }
            res += dist[t] * add;
        }
        return res;
    }
};

