        for (int i = h[u]; i != -1; i = eNext[i]) {
            int v = eTo[i];
            if (eCap[i] > 0 && d[v] > d[u] + eCost[i]) {
                d[v] = d[u] + eCost[i];
                from[v] = u;
                edgeIdx[v] = i;
                if (!inQue[v]) {
