};

vector<Edge> edges;
const int MAXN = 14043;
vector<int> adj[MAXN];
long long total_cost = 0;
long long dist[MAXN];
int parent[MAXN];
int parent_edge[MAXN];
int in_queue[MAXN];
const long long INF = (long long)(1e18);
int source = MAXN - 2;
int sink = MAXN - 1;

int residual(int idx) {
    return edges[idx].cap - edges[idx].flow;
}

void augment() {
    for (int i = 0; i < MAXN; ++i) {
        dist[i] = INF;
        parent[i] = -1;
        parent_edge[i] = -1;
        in_queue[i] = 0;
    }
    dist[source] = 0;
    queue<int> q;
    q.push(source);
    in_queue[source] = 1;
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        in_queue[v] = 0;
        for (int idx : adj[v]) {
            if (!residual(idx)) continue;
            int c = edges[idx].cost;
            int to = edges[idx].to;
            if (dist[to] > dist[v] + c) {
                dist[to] = dist[v] + c;
                parent[to] = v;
                parent_edge[to] = idx;
                if (!in_queue[to]) {
                    in_queue[to] = 1;
                    q.push(to);
                }
            }
        }
    }
    int cur = sink;
    while (cur != source) {
        edges[parent_edge[cur]].flow++;
        edges[parent_edge[cur] ^ 1].flow--;
        cur = parent[cur];
    }
    total_cost += dist[sink];
}

