struct edge_t {
    int v, cap, flow, w;
    edge_t() {}
    edge_t(int v, int cap, int flow, int w) : v(v), cap(cap), flow(flow), w(w) {}
};

vector<edge_t> E;
const int V = 14043;
vector<int> G[V];
long long ans = 0;
long long D[V];
int P[V], PE[V], INQ[V];
const long long INF = (long long)(1e18);
int S = V - 2, T = V - 1;

int res(int x) { return E[x].cap - E[x].flow; }

void push() {
    fill(D, D + V, INF);
    fill(P, P + V, -1);
    fill(PE, PE + V, -1);
    fill(INQ, INQ + V, 0);
    D[S] = 0;
    deque<int> q;
    q.push_back(S);
    INQ[S] = 1;
    while (!q.empty()) {
        int u = q.front();
        q.pop_front();
        INQ[u] = 0;
        for (int idx : G[u]) {
            if (!res(idx)) continue;
            int w = E[idx].w;
            int v = E[idx].v;
            if (D[v] > D[u] + w) {
                D[v] = D[u] + w;
                P[v] = u;
                PE[v] = idx;
                if (!INQ[v]) {
                    INQ[v] = 1;
                    if (!q.empty() && D[v] < D[q.front()])
                        q.push_front(v);
                    else
                        q.push_back(v);
                }
            }
        }
    }
    int cur = T;
    while (cur != S) {
        E[PE[cur]].flow++;
        E[PE[cur] ^ 1].flow--;
        cur = P[cur];
    }
    ans += D[T];
}

