        q.push(s);
        inq[s] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = false;
            for (int eid : adj[u]) {
                Edge &e = edges[eid];
                if (e.cap > 0 && dist[u] + e.cost < dist[e.to]) {
                    dist[e.to] = dist[u] + e.cost;
                    prev_v[e.to] = u;
                    prev_e[e.to] = eid;
                    if (!inq[e.to]) {
                        inq[e.to] = true;
                        q.push(e.to);
                    }
                }
            }
        }
        if (dist[t] == INF) return -1;
        ll add = f;
        for (int v = t; v != s; v = prev_v[v])
            add = min(add, edges[prev_e[v]].cap);
        f -= add;
        res += add * dist[t];
        for (int v = t; v != s; v = prev_v[v]) {
            Edge &e = edges[prev_e[v]];
            e.cap -= add;
            edges[prev_e[v] ^ 1].cap += add;
        }
    }
    return res;
}

