}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int INF = 0x3f3f3f3f;
const int T = 99;
const int C = 15;

struct Edge {
    int to, rev;
    ll cap, cost;
};

class MinCostFlow {
public:
    int n;
    vector<vector<Edge>> g;
    vector<ll> pot, dist;
    vector<int> prevv, preve;

    MinCostFlow(int n_) : n(n_), g(n_), pot(n_, 0), dist(n_), prevv(n_), preve(n_) {}

    void add_edge(int from, int to, ll cap, ll cost) {
        g[from].push_back({to, (int)g[to].size(), cap, cost});
        g[to].push_back({from, (int)g[from].size() - 1, 0, -cost});
    }

    ll min_cost_flow(int s, int t, ll maxf) {
        ll res = 0;
        ll flow = 0;
        while (flow < maxf) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            // Bellman-Ford (no potentials, all costs non-negative)
            bool updated;
            for (int iter = 0; iter < n; ++iter) {
                updated = false;
                for (int v = 0; v < n; ++v) {
                    if (dist[v] == INF) continue;
                    for (int i = 0; i < (int)g[v].size(); ++i) {
                        Edge &e = g[v][i];
                        if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                            dist[e.to] = dist[v] + e.cost;
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            updated = true;
                        }
                    }
                }
                if (!updated) break;
            }
            if (dist[t] >= INF) break;
            ll add = maxf - flow;
            for (int v = t; v != s; v = prevv[v]) {
                add = min(add, g[prevv[v]][preve[v]].cap);
