bool bellman_ford() {
    for (int i = s; i <= t; ++i) dis[i] = inf, vis[i] = false;
    dis[s] = 0;
    for (int i = 1; i <= t - s; ++i) {
        bool updated = false;
        for (int x = s; x <= t; ++x) {
            if (dis[x] == inf) continue;
            for (int j = head[x]; j; j = e[j].nxt) {
                int y = e[j].to, c = e[j].c;
                if (dis[y] > dis[x] + c && e[j].v) {
                    dis[y] = dis[x] + c;
                    updated = true;
                }
            }
        }
        if (!updated) break;
    }
    return dis[t] != inf;
}

