    head[from] = edge_cnt;
    e[++edge_cnt] = {from, head[to], 0, -cost};
    head[to] = edge_cnt;
}

bool dijkstra() {
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
    for (int i = s; i <= t; ++i) dis[i] = inf, vis[i] = false;
    dis[s] = 0;
    pq.push({0, s});
    while (!pq.empty()) {
        int d = pq.top().first, x = pq.top().second; pq.pop();
        if (vis[x]) continue;
        vis[x] = true;
        for (int i = head[x]; i; i = e[i].nxt) {
            int y = e[i].to, c = e[i].c + pot[x] - pot[y];
            if (dis[y] > dis[x] + c && e[i].v) {
                dis[y] = dis[x] + c;
                pq.push({dis[y], y});
            }
        }
    }
    for (int i = s; i <= t; ++i)
        if (dis[i] < inf) pot[i] += dis[i];
    return dis[t] != inf;
}

int dfs(int x, int lim) {
    if (x == t) return lim;
    vis[x] = true;
    int flow, res = lim;
    for (int i = head[x]; i; i = e[i].nxt) {
        int y = e[i].to, v = e[i].v;
        int rc = e[i].c + pot[x] - pot[y];
        if (dis[y] != dis[x] + rc || !v || vis[y]) continue;
        flow = dfs(y, min(res, v));
        if (flow) {
            res -= flow;
            e[i].v -= flow;
            e[i ^ 1].v += flow;
            if (!res) break;
        }
    }
    return lim - res;
}

