#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = 1000000000LL;

struct MinCostMaxFlow {
    struct Edge {
        int to;
        ll cap, flow, cost;
    };

    int n;
    vector<vector<int>> adj;
    vector<Edge> edges;
    vector<ll> pot, dist;
    vector<int> pv, pe;

    MinCostMaxFlow(int n) : n(n), adj(n), pot(n, 0) {}

    void add_edge(int v, int u, ll cap, ll cost) {
        int id = (int)edges.size();
        adj[v].push_back(id);
        edges.push_back({u, cap, 0, cost});

        adj[u].push_back(id ^ 1);
        edges.push_back({v, 0, 0, -cost});
    }

    pair<ll, ll> min_cost_flow(int s, int t) {
        ll flow = 0, total_cost = 0;

        while (true) {
            dist.assign(n, INF);
            pv.assign(n, -1);
            pe.assign(n, -1);

            priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
            dist[s] = 0;
            pq.push({0, s});

            while (!pq.empty()) {
                auto [d, v] = pq.top();
                pq.pop();
                if (d != dist[v]) continue;

                for (int id : adj[v]) {
                    const Edge &e = edges[id];
                    if (e.flow >= e.cap) continue;

                    ll nd = d + e.cost + pot[v] - pot[e.to];
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        pv[e.to] = v;
                        pe[e.to] = id;
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;

            for (int i = 0; i < n; ++i) pot[i] += dist[i];

            ll add = INF;
            for (int v = t; v != s; v = pv[v]) {
                int id = pe[v];
                add = min(add, edges[id].cap - edges[id].flow);
            }

            flow += add;

            for (int v = t; v != s; v = pv[v]) {
                int id = pe[v];
                edges[id].flow += add;
                edges[id ^ 1].flow -= add;
                total_cost += add * edges[id].cost;
            }
        }

        return {flow, total_cost};
    }
};

