using ll = long long;
const ll INF = 1000000000LL;

struct Edge {
    int to, rev;
    ll cap, cost;
};

struct MCMF {
    int n;
    vector<vector<Edge>> g;
    vector<ll> pot, dist;
    vector<int> prevv, preve;

    MCMF(int n) : n(n), g(n), pot(n, 0), dist(n), prevv(n), preve(n) {}

    void add_edge(int v, int u, ll cap, ll cost) {
        g[v].push_back({u, (int)g[u].size(), cap, cost});
        g[u].push_back({v, (int)g[v].size() - 1, 0, -cost});
    }

    pair<ll, ll> solve(int s, int t) {
        ll flow = 0, total_cost = 0;

        while (true) {
            fill(dist.begin(), dist.end(), INF);
            prevv.assign(n, -1);
            preve.assign(n, -1);

            priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
            dist[s] = 0;
            pq.push({0, s});

            while (!pq.empty()) {
                auto [d, v] = pq.top();
                pq.pop();
                if (d != dist[v]) continue;

                for (int i = 0; i < (int)g[v].size(); ++i) {
                    const Edge &e = g[v][i];
                    if (e.cap == 0) continue;

                    ll nd = d + e.cost + pot[v] - pot[e.to];
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;

            for (int i = 0; i < n; ++i) {
                if (dist[i] < INF) pot[i] += dist[i];
            }

            ll add = INF;
            for (int v = t; v != s; v = prevv[v]) {
                add = min(add, g[prevv[v]][preve[v]].cap);
            }

            flow += add;

            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                e.cap -= add;
                g[v][e.rev].cap += add;
                total_cost += add * e.cost;
            }
        }

        return {flow, total_cost};
    }
};

