#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;
const int T = 150;

struct Edge {
    int to, rev, cap, flow, cost;
};

class MinCostMaxFlow {
    int n;
    vector<vector<Edge>> g;

public:
    MinCostMaxFlow(int n_) : n(n_), g(n_) {}

    void add_edge(int s, int t, int cap, int cost) {
        Edge a{t, (int)g[t].size(), cap, 0, cost};
        Edge b{s, (int)g[s].size(), 0, 0, -cost};
        g[s].push_back(a);
        g[t].push_back(b);
    }

    pair<int, int> get_flow(int s, int t) {
        int flow = 0, flow_cost = 0;

        while (true) {
            vector<int> dist(n, INF), pv(n, -1), pe(n, -1);
            vector<char> inq(n, 0);
            deque<int> dq;

            dist[s] = 0;
            dq.push_back(s);
            inq[s] = 1;

            while (!dq.empty()) {
                int v = dq.front();
                dq.pop_front();
                inq[v] = 0;

                for (int i = 0; i < (int)g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap - e.flow <= 0) continue;

                    if (dist[e.to] > dist[v] + e.cost) {
                        dist[e.to] = dist[v] + e.cost;
                        pv[e.to] = v;
                        pe[e.to] = i;

                        if (!inq[e.to]) {
                            if (!dq.empty() && dist[e.to] < dist[dq.front()]) {
                                dq.push_front(e.to);
                            } else {
                                dq.push_back(e.to);
                            }
                            inq[e.to] = 1;
                        }
                    }
                }
            }

            if (dist[t] == INF) break;

            int add = INF - flow;
            for (int v = t; v != s; v = pv[v]) {
                Edge &e = g[pv[v]][pe[v]];
                add = min(add, e.cap - e.flow);
            }

            flow += add;
            for (int v = t; v != s; v = pv[v]) {
                Edge &e = g[pv[v]][pe[v]];
                e.flow += add;
                g[v][e.rev].flow -= add;
                flow_cost += add * e.cost;
            }
        }

        return {flow, flow_cost};
    }
};

