#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;
const int T = 150;

struct Edge {
    int to, rev, cap, flow, cost;
};

class MCMF {
    int n;
    vector<vector<Edge>> g;
    vector<int> dist, pot, prevv, preve;

public:
    MCMF(int n_) : n(n_), g(n_), dist(n_), pot(n_, 0), prevv(n_), preve(n_) {}

    void add_edge(int from, int to, int cap, int cost) {
        g[from].push_back({to, (int)g[to].size(), cap, 0, cost});
        g[to].push_back({from, (int)g[from].size() - 1, 0, 0, -cost});
    }

    pair<int, int> run(int s, int t) {
        int flow = 0, flow_cost = 0;

        while (true) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;

            set<pair<int, int>> pq;
            pq.insert({0, s});

            while (!pq.empty()) {
                auto it = pq.begin();
                int d = it->first;
                int v = it->second;
                pq.erase(it);

                if (d != dist[v]) continue;

                for (int i = 0; i < (int)g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap - e.flow <= 0) continue;

                    int nd = d + e.cost + pot[v] - pot[e.to];
                    if (nd < dist[e.to]) {
                        if (dist[e.to] != INF) {
                            pq.erase({dist[e.to], e.to});
                        }
                        dist[e.to] = nd;
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.insert({nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;

            for (int i = 0; i < n; ++i) pot[i] += dist[i];

            int add = INF - flow;
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                add = min(add, e.cap - e.flow);
            }

            flow += add;
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                e.flow += add;
                g[v][e.rev].flow -= add;
                flow_cost += add * e.cost;
            }
        }

        return {flow, flow_cost};
    }
};

