inline int readInt() {
    int x = 0;
    int ch = getchar();
    bool neg = false;
    while (ch < '0' || ch > '9') {
        if (ch == '-') neg = true;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        x = (x << 1) + (x << 3) + (ch - '0');
        ch = getchar();
    }
    return neg ? (~x + 1) : x;
}

inline void addRaw(int a, int b, int cost, int cap) {
    ++ecnt;
    edges[ecnt].to = b;
    edges[ecnt].cap = cap;
    edges[ecnt].cost = cost;
    edges[ecnt].nxt = head[a];
    head[a] = ecnt;
}

inline void addEdge(int a, int b, int cost, int cap) {
    addRaw(a, b, cost, cap);
    addRaw(b, a, -cost, 0);
}

bool spfa() {
    for (int i = 1; i <= nodeCnt; ++i) {
        used[i] = false;
        dist[i] = INF;
    }
    queue<int> q;
    dist[src] = 0;
    q.push(src);
    used[src] = true;
    while (!q.empty()) {
        int x = q.front();
        q.pop();
        used[x] = false;
        for (int e = head[x]; e; e = edges[e].nxt) {
            if (!edges[e].cap) continue;
            int y = edges[e].to;
            if (dist[y] > dist[x] + edges[e].cost) {
                dist[y] = dist[x] + edges[e].cost;
                if (!used[y]) {
                    q.push(y);
                    used[y] = true;
                }
            }
        }
    }
    return dist[sink] < INF;
}

int augment(int x, int flow) {
    if (x == src) return flow;
    used[x] = true;
    int rem = flow;
    for (int e = head[x]; e; e = edges[e].nxt) {
        int y = edges[e].to;
        if (used[y] || !edges[e ^ 1].cap || dist[x] < dist[y] + edges[e ^ 1].cost) continue;
        int got = augment(y, min(rem, edges[e ^ 1].cap));
        if (got) {
            rem -= got;
            edges[e ^ 1].cap -= got;
            edges[e].cap += got;
            if (!rem) break;
        }
    }
    return flow - rem;
}

