struct rib {
	int b, u, c, f;
	size_t back;
};

void add_rib (vector < vector<rib> > & g, int a, int b, int u, int c) {
	rib r1 = { b, u, c, 0, g[b].size() };
	rib r2 = { a, 0, -c, 0, g[a].size() };
	g[a].push_back (r1);
	g[b].push_back (r2);
}

int main()
{
	int N, m, k, c, d;
	scanf("%d %d %d %d %d", &N, &m, &k, &c, &d);
	int n = N * 101 + 2;
	vector < vector<rib> > g (n);
	for (int i = 0; i < k; i++) {
		int x;
		scanf("%d", &x);
		x--;
		add_rib(g, n - 2, x*101, 1, 0);
	}
	for (int i = 0; i < 101; i++)
	{
		add_rib(g, i, n-1, INF, i*c);
	}
	for (int i = 1; i < N; i++) {
		for (int j = 0; j+1 < 101; j++) {
			add_rib(g, i*101 + j, i*101 + j + 1, INF, 0);
		}
	}
	for (int i = 0; i < m; i++) {
		int u, v;
		scanf("%d %d", &u, &v);
		u--;
		v--;
		for (int j = 0; j+1 < 101; j++) {
			for (int K = 1; K <= k; K++) {
				add_rib(g, u*101 + j, v*101 + j + 1, 1, d*K*K - d*(K-1)*(K-1));
				add_rib(g, v*101 + j, u*101 + j + 1, 1, d*K*K - d*(K-1)*(K-1));
			}
		}
	}
	int s, t;
	s = n-2;
	t = n-1;
	int flow = 0, cost = 0;
	while (flow < k) {
		vector<int> id (n, 0);
		vector<int> d (n, INF);
		vector<int> q (n);
		vector<int> p (n);
		vector<size_t> p_rib (n);
		int qh=0, qt=0;
		q[qt++] = s;
		d[s] = 0;
		while (qh != qt) {
			int v = q[qh++];
			id[v] = 2;
			if (qh == n)  qh = 0;
			for (size_t i=0; i<g[v].size(); ++i) {
				rib & r = g[v][i];
				if (r.f < r.u && d[v] + r.c < d[r.b]) {
					d[r.b] = d[v] + r.c;
					if (id[r.b] == 0) {
						q[qt++] = r.b;
						if (qt == n)  qt = 0;
					}
					else if (id[r.b] == 2) {
						if (--qh == -1)  qh = n-1;
						q[qh] = r.b;
					}
					id[r.b] = 1;
					p[r.b] = v;
					p_rib[r.b] = i;
				}
			}
		}
		if (d[t] == INF)  break;
		int addflow = k - flow;
		for (int v=t; v!=s; v=p[v]) {
			int pv = p[v];  size_t pr = p_rib[v];
			addflow = min (addflow, g[pv][pr].u - g[pv][pr].f);
		}
		for (int v=t; v!=s; v=p[v]) {
			int pv = p[v];  size_t pr = p_rib[v],  r = g[pv][pr].back;
			g[pv][pr].f += addflow;
			g[v][r].f -= addflow;
			cost += g[pv][pr].c * addflow;
		}
		flow += addflow;
	}
	assert(flow == k);
	cout<<cost<<endl;

}

#include <bits/stdc++.h>
using namespace std;

const int INF = 1000*1000*1000;

struct Edge {
    int to, rev, cap, cost;
};

void add_edge(vector<vector<Edge>>& g, int from, int to, int cap, int cost) {
    g[from].push_back({to, (int)g[to].size(), cap, cost});
    g[to].push_back({from, (int)g[from].size()-1, 0, -cost});
}

int main() {
    int N, m, k, c, d;
    scanf("%d %d %d %d %d", &N, &m, &k, &c, &d);
    int n = N * 101 + 2;
    vector<vector<Edge>> g(n);
    for (int i = 0; i < k; i++) {
        int x;
        scanf("%d", &x);
        x--;
        add_edge(g, n-2, x*101, 1, 0);
    }
    for (int i = 0; i < 101; i++) {
        add_edge(g, i, n-1, INF, i*c);
    }
    for (int i = 1; i < N; i++) {
        for (int j = 0; j+1 < 101; j++) {
            add_edge(g, i*101 + j, i*101 + j + 1, INF, 0);
        }
    }
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        for (int j = 0; j+1 < 101; j++) {
            for (int K = 1; K <= k; K++) {
                int cost = d * (2*K - 1);
                add_edge(g, u*101 + j, v*101 + j + 1, 1, cost);
                add_edge(g, v*101 + j, u*101 + j + 1, 1, cost);
            }
        }
    }
    int s = n-2, t = n-1;
    int flow = 0, cost = 0;
    vector<int> potential(n, 0);
    while (flow < k) {
        vector<int> dist(n, INF);
        vector<int> prevv(n, -1);
        vector<int> preve(n, -1);
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
        dist[s] = 0;
        pq.push({0, s});
        while (!pq.empty()) {
            auto p = pq.top(); pq.pop();
            int v = p.second;
            if (dist[v] < p.first) continue;
            for (int i = 0; i < (int)g[v].size(); i++) {
                Edge& e = g[v][i];
                if (e.cap > 0) {
                    int nd = dist[v] + e.cost + potential[v] - potential[e.to];
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.push({nd, e.to});
                    }
                }
            }
        }
        if (dist[t] == INF) break;
        for (int v = 0; v < n; v++) {
            if (dist[v] < INF) potential[v] += dist[v];
        }
        int addflow = k - flow;
        for (int v = t; v != s; v = prevv[v]) {
            addflow = min(addflow, g[prevv[v]][preve[v]].cap);
        }
        for (int v = t; v != s; v = prevv[v]) {
            Edge& e = g[prevv[v]][preve[v]];
            e.cap -= addflow;
            g[v][e.rev].cap += addflow;
            cost += e.cost * addflow;
        }
        flow += addflow;
    }
    assert(flow == k);
    printf("%d\n", cost);
    return 0;
}

