#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int INF=1e9;

struct MCF {
    int n;
    struct Edge { int to, f, cap, cost; };
    vector<Edge> edges;
    vector<vector<int>> g;
    vector<int> prio, curflow, prevedge, prevnode, pot;
    MCF(int n): n(n), g(n), prio(n), curflow(n), prevedge(n), prevnode(n), pot(n) {}
    void addEdge(int s, int t, int cap, int cost) {
        edges.push_back({t,0,cap,cost});
        edges.push_back({s,0,0,-cost});
        g[s].push_back((int)edges.size()-2);
        g[t].push_back((int)edges.size()-1);
    }
    pair<int,int> minCostFlow(int s, int t) {
        int flow=0, flowCost=0;
        while(flow<INF) {
            priority_queue<ll, vector<ll>, greater<ll>> q;
            fill(prio.begin(), prio.end(), INT_MAX);
            prio[s]=0;
            curflow[s]=INT_MAX;
            q.push(s);
            while(!q.empty()) {
                ll cur=q.top(); q.pop();
                int d=cur>>32, u=cur;
                if(d!=prio[u]) continue;
                for(int ei: g[u]) {
                    Edge &e=edges[ei];
                    if(e.cap<=e.f) continue;
                    int v=e.to;
                    int nd=d+e.cost+pot[u]-pot[v];
                    if(prio[v]>nd) {
                        prio[v]=nd;
                        q.push(((ll)nd<<32)+v);
                        prevnode[v]=u;
                        prevedge[v]=ei;
                        curflow[v]=min(curflow[u], e.cap-e.f);
                    }
                }
            }
            if(prio[t]==INT_MAX) break;
            for(int i=0;i<n;++i) pot[i]+=prio[i];
            int df=min(curflow[t], INF-flow);
            flow+=df;
            for(int v=t; v!=s; v=prevnode[v]) {
                Edge &e=edges[prevedge[v]];
                e.f+=df;
                edges[prevedge[v]^1].f-=df;
                flowCost+=df*e.cost;
            }
        }
        return {flow, flowCost};
    }
};

