struct MCMF {
    int n;
    vector<vector<Edge>> g;

    MCMF(int n_) : n(n_), g(n_) {}

    void addEdge(int u, int v, int cap, int cost) {
        if (cap <= 0) return;
        Edge a{v, (int)g[v].size(), cap, cost};
        Edge b{u, (int)g[u].size(), 0, -cost};
        g[u].push_back(a);
        g[v].push_back(b);
    }

    pair<int,int> minCostFlow(int s, int t, int need) {
        const int INF = INT_MAX / 2;
        int flow = 0, cost = 0;

        while (flow < need) {
            vector<int> dist(n, INF), prevv(n, -1), preve(n, -1);
            dist[s] = 0;

            for (int it = 0; it < n - 1; ++it) {
                bool updated = false;
                for (int v = 0; v < n; ++v) {
                    if (dist[v] == INF) continue;
                    for (int i = 0; i < (int)g[v].size(); ++i) {
                        Edge &e = g[v][i];
                        if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                            dist[e.to] = dist[v] + e.cost;
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            updated = true;
                        }
                    }
                }
                if (!updated) break;
            }

            if (dist[t] == INF) break;

            int add = need - flow;
            for (int v = t; v != s; v = prevv[v])
                add = min(add, g[prevv[v]][preve[v]].cap);

            flow += add;
            cost += add * dist[t];

            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                e.cap -= add;
                g[v][e.rev].cap += add;
            }
        }

        return {flow, cost};
    }
};

