#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, rev, cap, cost;
};

class MinCostFlow {
public:
    int n;
    vector<vector<Edge>> g;
    vector<int> pot, level, iter;

    MinCostFlow(int n_) : n(n_), g(n_), pot(n_, 0) {}

    void addEdge(int u, int v, int cap, int cost) {
        Edge a{v, (int)g[v].size(), cap, cost};
        Edge b{u, (int)g[u].size(), 0, -cost};
        g[u].push_back(a);
        g[v].push_back(b);
    }

    bool bfs(int s, int t) {
        level.assign(n, -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (const Edge &e : g[v]) {
                if (e.cap > 0 && level[e.to] < 0 && e.cost + pot[v] - pot[e.to] == 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    int dfs(int v, int t, int f) {
        if (v == t) return f;
        for (int &i = iter[v]; i < (int)g[v].size(); ++i) {
            Edge &e = g[v][i];
            if (e.cap > 0 && level[e.to] == level[v] + 1 && e.cost + pot[v] - pot[e.to] == 0) {
                int ret = dfs(e.to, t, min(f, e.cap));
                if (ret) {
                    e.cap -= ret;
                    g[e.to][e.rev].cap += ret;
                    return ret;
                }
            }
        }
        return 0;
    }

    int sendBlocking(int s, int t, int limit) {
        int flow = 0;
        while (flow < limit && bfs(s, t)) {
            iter.assign(n, 0);
            while (flow < limit) {
                int f = dfs(s, t, limit - flow);
                if (!f) break;
                flow += f;
            }
        }
        return flow;
    }

    pair<int,int> minCostFlow(int s, int t, int need) {
        const int INF = INT_MAX / 2;
        int flow = 0, cost = 0;
        vector<int> dist(n);

        while (flow < need) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
            pq.push({0, s});

            while (!pq.empty()) {
                auto cur = pq.top(); pq.pop();
                int d = cur.first;
                int v = cur.second;
                if (d != dist[v]) continue;

                for (const Edge &e : g[v]) {
                    if (e.cap <= 0) continue;
                    int nd = d + e.cost + pot[v] - pot[e.to];
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;

            for (int v = 0; v < n; ++v)
                if (dist[v] < INF) pot[v] += dist[v];

            int pushed = sendBlocking(s, t, need - flow);
            if (pushed == 0) break;
            flow += pushed;
            cost += pushed * pot[t];
        }

        return {flow, cost};
    }
};

