    for(int i=1; i<=t; i++) dist[i] = INF, flow[i] = pre[i] = las[i] = 0, inq[i] = 0;
    deque<int> q;
    dist[s] = 0; flow[s] = INF; q.push_back(s); inq[s] = 1;
    while(!q.empty()) {
        int u = q.front(); q.pop_front(); inq[u] = 0;
