        fill(head, head + n, -1);
        e = 0;
    }

    void add(int u, int v, int c, int w) {
        to[e] = v; nxt[e] = head[u]; cap[e] = c; cost[e] = w; head[u] = e++;
    }

    void link(int u, int v, int c, int w) {
        add(u, v, c, w);
        add(v, u, 0, -w);
    }

    bool spfa() {
        fill(dis, dis + n, INF);
        fill(inq, inq + n, 0);
        queue<int> q;
        q.push(s);
        inq[s] = 1;
        dis[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = 0;
            for (int i = head[u]; ~i; i = nxt[i]) {
                if (cap[i] > 0 && dis[u] + cost[i] < dis[to[i]]) {
                    dis[to[i]] = dis[u] + cost[i];
                    pre[to[i]] = i;
                    if (!inq[to[i]]) {
                        q.push(to[i]);
                        inq[to[i]] = 1;
                    }
                }
            }
        }
        return dis[t] != INF;
    }

    int run(int _s, int _t) {
        s = _s; t = _t;
        int flow = 0, mincost = 0;
        while (spfa()) {
            int add = INF;
            for (int p = t; p != s; p = to[pre[p] ^ 1])
                add = min(add, cap[pre[p]]);
            for (int p = t; p != s; p = to[pre[p] ^ 1]) {
                cap[pre[p]] -= add;
                cap[pre[p] ^ 1] += add;
            }
            mincost += add * dis[t];
            flow += add;
        }
        return mincost;
    }
};

MCMF mcmf;
int n, m, k, c, d, a[55], id[55][2500];

int main() {
