#define fst first
#define snd second

const int MAXN=50*100+15;
int SRC = MAXN-1;
int SNC = MAXN-2;

typedef ll tf; const tf INFFLUJO=1e14;
typedef ll tc; const tc INFCOSTO=1e14;
struct edge {
    int rev; // index of reverse edge in the other node's list
    int v; tf cap, flow; tc cost;
    tf rem() { return cap-flow; }
};
int nodes=MAXN;
vector<vector<edge>> g(MAXN); // each node has its own list of edges (including reverse)
void add_edge(int u, int v, tf cap, tc cost) {
    if(DEBUG) {
        string dem=to_string(u),pen=to_string(v);
        if(u==SRC)dem="SRC";
        if(u==SNC)dem="SINC";
        if(v==SRC)pen="SRC";
        if(v==SNC)pen="SINC";
        cout<<"add edge: "<<dem<<" "<<pen<<" "<<cap<<" "<<cost<<endl;
    }
    edge a = { (int)g[v].size(), v, cap, 0, cost };
    edge b = { (int)g[u].size(), u, 0, 0, -cost };
    g[u].pb(a);
    g[v].pb(b);
}

tc dist[MAXN], mncost;
int pre[MAXN], pre_edge[MAXN]; // pre[node] = previous node, pre_edge[node] = index in g[pre[node]]
tf cap[MAXN], mxflow;
bool in_queue[MAXN];

void flow(int s, int t) {
    mset(in_queue,0);
    mxflow = mncost = 0;
    while(1) {
        fill(dist, dist+nodes, INFCOSTO); dist[s] = 0;
        mset(pre, -1); pre[s] = s;
        mset(cap, 0); cap[s] = INFFLUJO;
        queue<int> q; q.push(s); in_queue[s] = 1;
        while(SZ(q)) {
            int u = q.front(); q.pop(); in_queue[u] = 0;
            fore(i, 0, SZ(g[u])) {
                edge &E = g[u][i];
                if(E.rem() && dist[E.v] > dist[u] + E.cost + 1e-9) {
                    dist[E.v] = dist[u] + E.cost;
                    pre[E.v] = u;
                    pre_edge[E.v] = i;
                    cap[E.v] = min(cap[u], E.rem());
                    if(!in_queue[E.v]) { q.push(E.v); in_queue[E.v] = 1; }
                }
            }
        }
        if(pre[t] < 0) break;
        mxflow += cap[t];
        mncost += cap[t] * dist[t];
        for(int v = t; v != s; v = pre[v]) {
            int u = pre[v];
            edge &E = g[u][pre_edge[v]];
            E.flow += cap[t];
            g[v][E.rev].flow -= cap[t];
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    ll n,m,k,c,d;
    cin>>n>>m>>k>>c>>d;
    int MAXT = n + k;
    if(DEBUG) cout<<"MAXT: "<<MAXT<<endl;
    vector<int> a(k);
    fore(i,0,k) {
        cin>>a[i]; a[i]--;
        add_edge(SRC, a[i]*MAXT, 1, 0);
    }
    fore(j,0,MAXT) add_edge(j, SNC, k, 0);
    fore(i,0,m) {
        int x,y; cin>>x>>y; x--,y--;
        fore(j,0,MAXT-1) fore(K,1,k+1) {
            add_edge(x*MAXT+j, y*MAXT+j+1, 1, c + d*(2*K-1));
        }
        fore(j,0,MAXT-1) fore(K,1,k+1) {
            add_edge(y*MAXT+j, x*MAXT+j+1, 1, c + d*(2*K-1));
        }
    }
    fore(i,0,n) {
        fore(j,0,MAXT-1) fore(K,1,k+1) {
            add_edge(i*MAXT+j, i*MAXT+j+1, 1, c);
        }
    }
    flow(SRC, SNC);
    if(DEBUG) cout<<"mncost: "<<mncost<<" mxflow: "<<mxflow<<endl;
    cout<<mncost<<endl;
}

