#include<iostream>
#include<cstdio>
#include<cstring>
#include<queue>
#include<vector>
#define N 100010
using namespace std;
typedef int typ;
#define M 1000010
#define inf 1000000000
#define winf 1000000000
struct edge{
    int to,rev;
    int cap;
    typ cost;
};
vector<edge> G[N];
int all;
void add_edge(int u,int v,int cap,typ cost)
{
    G[u].push_back((edge){v,(int)G[v].size(),cap,cost});
    G[v].push_back((edge){u,(int)G[u].size()-1,0,-cost});
}
namespace min_cost_flow{
    int prevv[N],preve[N];
    typ dist[N];
    bool inq[N];
    bool spfa(int s,int t)
    {
        for(int i=1;i<=all;i++) dist[i]=winf,inq[i]=false;
        dist[s]=0;
        queue<int>q;
        q.push(s);
        inq[s]=true;
        while(!q.empty())
        {
            int u=q.front();q.pop();
            inq[u]=false;
            for(int i=0;i<(int)G[u].size();i++)
            {
                edge &e=G[u][i];
                if(e.cap>0 && dist[u]+e.cost<dist[e.to])
                {
                    dist[e.to]=dist[u]+e.cost;
                    prevv[e.to]=u;
                    preve[e.to]=i;
                    if(!inq[e.to]) q.push(e.to),inq[e.to]=true;
                }
            }
        }
        return dist[t]!=winf;
    }
    int maxf;typ minw;
    void work(int s,int t)
    {
        while(spfa(s,t))
        {
            int d=inf;
            for(int v=t;v!=s;v=prevv[v])
                d=min(d,G[prevv[v]][preve[v]].cap);
            maxf+=d;
            minw+=d*dist[t];
            for(int v=t;v!=s;v=prevv[v])
            {
                edge &e=G[prevv[v]][preve[v]];
                e.cap-=d;
                G[v][e.rev].cap+=d;
            }
        }
    }
}
int ss=1,tt=2,n,m,k,c,d;
vector<int>g[N];
