/* upsolve with Dukkha */
#include <stdio.h>
#include <string.h>

#define N	50
#define M	50
#define K	50
#define T	(N + K + 1)
#define N_	(N * T + 1)
#define M_	(K + (M * 2 * K + N) * (T - 1))
#define INF	0x3f3f3f3f

#define LT(u, v)	(pi[u] < pi[v] || pi[u] == pi[v] && kk[u] < kk[v])

int pi[N_], kk[N_], bb[N_];
int pq[1 + N_], iq[N_], cnt;

int i2(int i) {
	return (i *= 2) > cnt ? 0 : i < cnt && LT(pq[i + 1], pq[i]) ? i + 1 : i;
}

void pq_up(int u) {
	int i, j;

	for (i = iq[u]; (j = i / 2) && LT(u, pq[j]); i = j)
		pq[iq[pq[j]] = i] = pq[j];
	pq[iq[u] = i] = u;
}

void pq_dn(int u) {
	int i, j;

	for (i = iq[u]; (j = i2(i)) && LT(pq[j], u); i = j)
		pq[iq[pq[j]] = i] = pq[j];
	pq[iq[u] = i] = u;
}

void pq_add(int u) {
	iq[u] = ++cnt;
	pq_up(u);
}

int pq_remove_first() {
	int u = pq[1], v = pq[cnt--];

	iq[v] = 1;
	pq_dn(v);
	return u;
}

struct L {
	struct L *next;
	int j;
} aa[N], aa_[N_];

void add(int i, int j) {
	static struct L l91[M * 2], *l = l91;

	l->j = j;
	l->next = aa[i].next; aa[i].next = l++;
}

void add_(int i, int h) {
	static struct L l91[M_ * 2], *l = l91;

	l->j = h;
	l->next = aa_[i].next; aa_[i].next = l++;
}

int n_, m_;
int uu[M_], vv[M_], uv[M_], cost[M_], cost_[M_];
int cc[M_ * 2];

void link(int u, int v, int cap, int cos) {
	int h = m_++;

	uu[h] = u, vv[h] = v, uv[h] = u ^ v;
	cost[h] = cos;
	cc[h << 1 ^ 0] = cap;
	add_(u, h << 1 ^ 0);
	add_(v, h << 1 ^ 1);
}

void dijkstra(int s) {
	memset(pi, 0x3f, n_ * sizeof *pi);
	pi[s] = 0;
	pq_add(s);
	while (cnt) {
		struct L *l;
		int u = pq_remove_first(), v;
		int h, h_, p, k = kk[u] + 1;

		for (l = aa_[u].next; l; l = l->next)
			if (cc[h_ = l->j]) {
				h = h_ >> 1;
				p = pi[u] + ((h_ & 1) == 0 ? cost_[h] : -cost_[h]);
				v = u ^ uv[h];
				if (pi[v] == INF) {
					pi[v] = p;
					kk[v] = k;
					bb[v] = h_;
					pq_add(v);
				} else if (pi[v] > p || pi[v] == p && kk[v] > k) {
					pi[v] = p;
					kk[v] = k;
					bb[v] = h_;
					pq_up(v);
				}
			}
	}
}

void push(int s, int t) {
#if 0
	int u, h, h_, c = INF;

	for (u = t; u != s; u ^= uv[h]) {
		h = (h_ = bb[u]) >> 1;
		if (c > cc[h_])
			c = cc[h_];
	}
	for (u = t; u != s; u ^= uv[h]) {
		h = (h_ = bb[u]) >> 1;
		cc[h_] -= c, cc[h_ ^ 1] += c;
	}
#else
	int u, h, h_;

	for (u = t; u != s; u ^= uv[h]) {
		h = (h_ = bb[u]) >> 1;
		cc[h_]--, cc[h_ ^ 1]++;
	}
#endif
}

int edmonds_karp(int s, int t) {
	int c, h;

	memcpy(cost_, cost, m_ * sizeof *cost);
	while (1) {
		dijkstra(s);
		if (pi[t] == INF)
			break;
		push(s, t);
		for (h = 0; h < m_; h++) {
			int u = uu[h], v = vv[h];

			if (pi[u] != INF && pi[v] != INF)
				cost_[h] += pi[u] - pi[v];
		}
	}
	c = 0;
	for (h = 0; h < m_; h++)
		c += cost[h] * cc[h << 1 ^ 1];
	return c;
}

int main() {
	static int ii[K];
	int n, m, k, t, c, d, h, i, j, s, u, v, x;

	scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
	for (h = 0; h < k; h++)
		scanf("%d", &ii[h]), ii[h]--;
	while (m--) {
		scanf("%d%d", &i, &j), i--, j--;
		add(i, j), add(j, i);
	}
	t = n + k + 1;
	n_ = n * t + 1;
	m_ = 0;
	for (i = 0; i < n; i++)
		for (s = 0; s < t - 1; s++) {
			struct L *l;

			u = i * t + s;
			for (l = aa[i].next; l; l = l->next) {
				j = l->j;
				v = j * t + s + 1;
				for (x = 1; x <= k; x++)
					link(u, v, 1, c + (x * 2 - 1) * d);
			}
		}
	for (i = 0; i < n; i++)
		for (s = 0; s < t - 1; s++) {
			u = i * t + s, v = u + 1;
			link(u, v, k, i == 0 ? 0 : c);
		}
	for (h = 0; h < k; h++)
		link(n_ - 1, ii[h] * t + 0, 1, 0);
	printf("%d\n", edmonds_karp(n_ - 1, 0 * t + t - 1));
	return 0;
}

#include <cstdio>
#include <cstring>
#include <vector>
#include <queue>
#include <iostream>
#include <algorithm>

const int N = 50, M = 50, K = 50;
const int T = N + K + 1;
const int N_ = N * T + 1;
const int M_ = K + (M * 2 * K + N) * (T - 1);
const int INF = 0x3f3f3f3f;

// Edge structure for min-cost flow
struct Edge {
    int u, v, uv, cost, cap;
};

std::vector<Edge> edges;
std::vector<std::vector<int>> adj; // adjacency list of edge indices

int dist[N_];    // pi
int hop[N_];     // kk (number of edges from source)
int prev_edge[N_]; // bb (edge index leading to node)

// Priority queue entry: (dist, hop, node)
typedef std::pair<int, std::pair<int, int>> PQEntry; // (dist, (hop, node))

struct Compare {
    bool operator()(const PQEntry& a, const PQEntry& b) const {
        if (a.first != b.first) return a.first > b.first;
        return a.second.first > b.second.first;
    }
};

std::priority_queue<PQEntry, std::vector<PQEntry>, Compare> pq;

void dijkstra(int s) {
    memset(dist, 0x3f, sizeof(dist));
    memset(hop, 0x3f, sizeof(hop)); // not strictly needed, hop will be set
    dist[s] = 0;
    hop[s] = 0;
    pq.push({0, {0, s}});
    while (!pq.empty()) {
        auto top = pq.top(); pq.pop();
        int u = top.second.second;
        int d = top.first;
        int h = top.second.first;
        if (d != dist[u] || h != hop[u]) continue; // outdated
        for (int ei : adj[u]) {
            if (edges[ei].cap == 0) continue;
            int v = edges[ei].v;
            int nd = dist[u] + (edges[ei].cost);
            int nh = hop[u] + 1;
            if (nd < dist[v] || (nd == dist[v] && nh < hop[v])) {
                dist[v] = nd;
                hop[v] = nh;
                prev_edge[v] = ei;
                pq.push({nd, {nh, v}});
            }
        }
    }
}

void push(int s, int t) {
    // Unit flow push as in original
    int u = t;
    while (u != s) {
        int ei = prev_edge[u];
        edges[ei].cap--;
        edges[ei ^ 1].cap++;
        u = edges[ei].u;
    }
}

void add_edge(int u, int v, int cap, int cost) {
    int idx = edges.size();
    edges.push_back({u, v, u ^ v, cost, cap});
    edges.push_back({v, u, v ^ u, -cost, 0});
    adj[u].push_back(idx);
    adj[v].push_back(idx + 1);
}

int min_cost_flow(int s, int t) {
    int flow_cost = 0;
    // copy original costs (the cost_ is not needed if we use reduced costs directly)
    // In this variant, we maintain reduced costs in edges[].cost and update after each dijkstra
    // But the original updates cost_ after each dijkstra. We need to replicate that.
    // To keep it simple, let's keep a separate cost array 'orig_cost' and modify after each iteration.
    // Actually, we can modify edges[].cost directly and restore later? The algorithm uses cost_ that is updated.
    // So we need to store original cost separately and apply updates.
    std::vector<int> orig_cost(edges.size());
    for (size_t i = 0; i < edges.size(); i++) orig_cost[i] = edges[i].cost;

    while (true) {
        dijkstra(s);
        if (dist[t] == INF) break;
        push(s, t);
        for (int u = 0; u < N_; u++) {
            if (dist[u] == INF) continue;
            for (int ei : adj[u]) {
                if (edges[ei].cap > 0 && dist[ edges[ei].v ] != INF) {
                    edges[ei].cost += dist[u] - dist[ edges[ei].v ];
                }
            }
        }
    }
    for (size_t ei = 0; ei < edges.size(); ei++) {
        // original cost is orig_cost[ei], and we add cost of back edges (ei^1) which have cap > 0 after flow
        if (ei % 2 == 1) { // back edge (the one that was added second)
            flow_cost += orig_cost[ei] * edges[ei].cap;
        }
    }
    return flow_cost;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(0);

    int n, m, k, c, d;
    std::cin >> n >> m >> k >> c >> d;
    std::vector<int> start(k);
    for (int i = 0; i < k; i++) {
        std::cin >> start[i];
        start[i]--;
    }

    // Build initial adjacency (undirected)
    std::vector<std::vector<int>> base_adj(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        std::cin >> a >> b;
        a--; b--;
        base_adj[a].push_back(b);
        base_adj[b].push_back(a);
    }

    int t = n + k + 1;
    int N_total = n * t + 1;
    adj.assign(N_total, std::vector<int>());

    // Add edges for movement
    for (int i = 0; i < n; i++) {
        for (int s = 0; s < t - 1; s++) {
            int u = i * t + s;
            for (int j : base_adj[i]) {
                int v = j * t + s + 1;
                for (int x = 1; x <= k; x++) {
                    add_edge(u, v, 1, c + (x * 2 - 1) * d);
                }
            }
        }
    }

    // Stay edges
    for (int i = 0; i < n; i++) {
        for (int s = 0; s < t - 1; s++) {
            int u = i * t + s, v = u + 1;
            int stay_cost = (i == 0 ? 0 : c);
            add_edge(u, v, k, stay_cost);
        }
    }

    // Source to start positions
    int source = N_total - 1;
    for (int h = 0; h < k; h++) {
        add_edge(source, start[h] * t + 0, 1, 0);
    }

    int sink = 0 * t + t - 1;
    int result = min_cost_flow(source, sink);
    std::cout << result << "\n";
    return 0;
}

