class MinCostFlow {
public:
    struct Edge {
        int to, rev, cap, cost;
    };
    std::vector<Edge> graph[MAX_NODES];
    int dist[MAX_NODES], h[MAX_NODES], prevv[MAX_NODES], preve[MAX_NODES];
    int node_cnt;

    MinCostFlow(int n) : node_cnt(n) {
        for (int i = 0; i < n; i++) graph[i].clear();
    }

    void add_edge(int from, int to, int cap, int cost) {
        graph[from].push_back((Edge){to, (int)graph[to].size(), cap, cost});
        graph[to].push_back((Edge){from, (int)graph[from].size() - 1, 0, -cost});
    }

    int min_cost_flow(int s, int t, int flow_needed) {
        int res = 0;
        memset(h, 0, sizeof(h));
        while (flow_needed > 0) {
            // Dijkstra with potentials
            for (int i = 0; i < node_cnt; i++) dist[i] = INF;
            dist[s] = 0;
            int pq[1 + MAX_NODES], iq[MAX_NODES], cnt = 0;
            auto lt = [&](int u, int v) -> bool {
                return dist[u] < dist[v] || (dist[u] == dist[v] && h[u] < h[v]);
            };
            auto i2 = [&](int i) -> int {
                return (i *= 2) > cnt ? 0 : i < cnt && lt(pq[i + 1], pq[i]) ? i + 1 : i;
            };
            auto pq_up = [&](int u) {
                int i, j;
                for (i = iq[u]; (j = i / 2) && lt(u, pq[j]); i = j)
                    pq[iq[pq[j]] = i] = pq[j];
                pq[iq[u] = i] = u;
            };
            auto pq_dn = [&](int u) {
                int i, j;
                for (i = iq[u]; (j = i2(i)) && lt(pq[j], u); i = j)
                    pq[iq[pq[j]] = i] = pq[j];
                pq[iq[u] = i] = u;
            };
            auto pq_add = [&](int u) {
                iq[u] = ++cnt;
                pq_up(u);
            };
            auto pq_pop = [&]() -> int {
                int u = pq[1], v = pq[cnt--];
                iq[v] = 1;
                pq_dn(v);
                return u;
            };

            pq_add(s);
            while (cnt) {
                int u = pq_pop();
                for (const auto &e : graph[u]) {
                    if (e.cap > 0 && dist[e.to] > dist[u] + e.cost + h[u] - h[e.to]) {
                        dist[e.to] = dist[u] + e.cost + h[u] - h[e.to];
                        prevv[e.to] = u;
                        preve[e.to] = &e - &graph[u][0];
                        if (dist[e.to] == INF) pq_add(e.to);
                        else pq_up(e.to);
                    }
                }
            }
            if (dist[t] == INF) return -1;
            for (int v = 0; v < node_cnt; v++) h[v] += dist[v];
            int d = flow_needed;
            for (int v = t; v != s; v = prevv[v]) {
                d = std::min(d, graph[prevv[v]][preve[v]].cap);
            }
            flow_needed -= d;
            res += d * h[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = graph[prevv[v]][preve[v]];
                e.cap -= d;
                graph[v][e.rev].cap += d;
            }
        }
        return res;
    }
};

