// Variant 1: Use Bellman-Ford instead of SPFA
#include<bits/stdc++.h>
using namespace std;
#define pii pair<int,int>
#define mp make_pair
#define inf 100000000
#define nn 6000

namespace mcmf {
    vector<int> v[nn], rev[nn], cost[nn], cap[nn];
    void add_edge(int x, int y, int c, int w) {
        rev[x].push_back(v[y].size());
        rev[y].push_back(v[x].size());
        v[x].push_back(y);
        v[y].push_back(x);
        cost[x].push_back(w);
        cost[y].push_back(-w);
        cap[x].push_back(c);
        cap[y].push_back(0);
    }

    int dist[nn];
    int prex[nn], prei[nn];
    void bellman_ford(int s) {
        memset(dist, 0x3f, sizeof dist);
        memset(prex, -1, sizeof prex);
        dist[s] = 0;
        int N = nn; // number of nodes (max)
        for (int iter = 0; iter < N - 1; ++iter) {
            bool updated = false;
            for (int x = 0; x < N; ++x) {
                if (dist[x] > 1e9) continue;
                for (int i = 0; i < (int)v[x].size(); ++i) {
                    int y = v[x][i];
                    int cc = dist[x] + cost[x][i];
                    if (dist[y] > cc && cap[x][i]) {
                        dist[y] = cc;
                        prex[y] = x;
                        prei[y] = i;
                        updated = true;
                    }
                }
            }
            if (!updated) break;
        }
    }

    int tot = 0;
    int dfs(int x, int flow) {
        if (prex[x] == -1) return flow;
        int y = x;
        x = prex[y];
        int i = prei[y], j = rev[x][i];
        int f = dfs(x, min(flow, cap[x][i]));
        cap[x][i] -= f;
        cap[y][j] += f;
        return f;
    }

    pii solve(int s, int t) {
        int ans = 0;
        tot = 0;
        while (1) {
            bellman_ford(s);
            if (dist[t] > 1e9) break;
            int f = dfs(t, inf);
            tot += f * dist[t];
            ans += f;
        }
        return mp(ans, tot);
    }
};

int n, m, s = nn - 1, t = nn - 2;
int k, c, d;
int get(int x, int tim) {
    return tim * 52 - 52 + x;
}

int main() {
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    int kk = k;
    while (k--) {
        int x;
        scanf("%d", &x);
        mcmf::add_edge(s, get(x, 1), 1, 0);
    }
    k = kk;
    while (m--) {
        int x, y;
        scanf("%d%d", &x, &y);
        for (int i = 1; i < 100; i++)
            for (int j = 1; j <= k; j++)
                mcmf::add_edge(get(x, i), get(y, i + 1), 1, d * (j + j - 1));
        swap(x, y);
        for (int i = 1; i < 100; i++)
            for (int j = 1; j <= k; j++)
                mcmf::add_edge(get(x, i), get(y, i + 1), 1, d * (j + j - 1));
    }
    for (int i = 1; i < 100; i++) {
        for (int j = 1; j <= n; j++)
            mcmf::add_edge(get(j, i), get(j, i + 1), inf, 0);
        mcmf::add_edge(get(1, i), t, inf, c * (i - 1));
    }
    printf("%d", mcmf::solve(s, t).second);
    return 0;
}

