class MinCostFlow {
public:
    int n, m;
    vector<vector<int>> adj;
    vector<Edge> edges;
    vector<int> dist, parent, aug;
    vector<char> inq;

    MinCostFlow(int n) : n(n) {
        adj.resize(n);
        dist.resize(n);
        parent.resize(n);
        aug.resize(n);
        inq.resize(n);
    }

    void addEdge(int u, int v, int cap, int cost) {
        edges.push_back({u, v, cap, 0, cost});
        edges.push_back({v, u, 0, 0, -cost});
        m = (int)edges.size();
        adj[u].push_back(m - 2);
        adj[v].push_back(m - 1);
    }

    bool spfa(int s, int t) {
        fill(dist.begin(), dist.end(), INF);
        fill(inq.begin(), inq.end(), 0);
        dist[s] = 0;
        inq[s] = 1;
        parent[s] = -1;
        aug[s] = INF;

        deque<int> dq;
        dq.push_back(s);

        while (!dq.empty()) {
            int u = dq.front();
            dq.pop_front();
            inq[u] = 0;

            for (int id : adj[u]) {
                Edge &e = edges[id];
                if (e.cap > e.flow && dist[e.v] > dist[u] + e.cost) {
                    dist[e.v] = dist[u] + e.cost;
                    parent[e.v] = id;
                    aug[e.v] = min(aug[u], e.cap - e.flow);
                    if (!inq[e.v]) {
                        inq[e.v] = 1;
                        if (!dq.empty() && dist[e.v] < dist[dq.front()])
                            dq.push_front(e.v);
                        else
                            dq.push_back(e.v);
                    }
                }
            }
        }
        return dist[t] != INF;
    }

    pair<int,int> minCost(int s, int t) {
        int flow = 0, cost = 0;
        while (spfa(s, t)) {
            int f = aug[t];
            flow += f;
            cost += f * dist[t];
            for (int v = t; v != s; v = edges[parent[v]].u) {
                edges[parent[v]].flow += f;
                edges[parent[v] ^ 1].flow -= f;
            }
        }
        return {flow, cost};
    }
};

