#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int N = 1000000;
int fr[N+2], sr, sn;
vector<int> gr[N+2];
const int INF = 1000000000;

class MinCostFlow {
public:
    struct Edge { int to, rev; int cap, cost; };
    vector<vector<Edge>> g;
    vector<int> h, dist, prevv, preve;
    MinCostFlow(int n) : g(n), h(n, 0), dist(n), prevv(n), preve(n) {}
    void addEdge(int from, int to, int cap, int cost) {
        g[from].push_back({to, (int)g[to].size(), cap, cost});
        g[to].push_back({from, (int)g[from].size()-1, 0, -cost});
    }
    pair<int,int> minCostFlow(int s, int t, int maxf) {
        int flow = 0, cost = 0;
        while (flow < maxf) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
            pq.push({0, s});
            while (!pq.empty()) {
                auto [d, v] = pq.top(); pq.pop();
                if (dist[v] < d) continue;
                for (int i = 0; i < (int)g[v].size(); ++i) {
                    auto &e = g[v][i];
                    if (e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
                        dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.push({dist[e.to], e.to});
                    }
                }
            }
            if (dist[t] == INF) break;
            for (int v = 0; v < (int)g.size(); ++v) h[v] += dist[v];
            int d = maxf - flow;
            for (int v = t; v != s; v = prevv[v]) d = min(d, g[prevv[v]][preve[v]].cap);
            flow += d;
            cost += d * h[t];
            for (int v = t; v != s; v = prevv[v]) {
                auto &e = g[prevv[v]][preve[v]];
                e.cap -= d;
