		int ret = psum[r2][c2];
		if (r1 > 0) ret -= psum[r1 - 1][c2];
		if (c1 > 0) ret -= psum[r2][c1 - 1];
		if (r1 > 0 && c1 > 0) ret += psum[r1 - 1][c1 - 1];
		return ret;
	}
};
class DisjointSet {
	int N;
	vector<int> P, R, A;
public:
	DisjointSet(int n) {
		N = n;
		P = vector<int>(n + 1);
		R = vector<int>(n + 1);
		A = vector<int>(n + 1);
		for (int i = 1; i <= n; i++) P[i] = i, R[i] = 0, A[i] = 1;
	}
	int getA(int x) {
		return A[x];
	}
	int find_set(int x) {
		if (P[x] == x) return x;
		int pa = find_set(P[x]);
		return P[x] = pa;
	}
	int union_set(int x, int y) {
		int px, py;
		px = find_set(x); py = find_set(y);
		if (px == py) return px;
		if (R[px]>R[py]) {
			P[py] = px;
			A[px] += A[py];
			return px;
		}
		else {
			P[px] = py;
			A[py] += A[px];
			if (R[px] == R[py]) R[py]++;
			return py;
		}
	}
};
class LIS { // 0-based index
	int N, BI;
public:
	LIS(int n) {
		N = n;
	}
	int execute(vector<int> &A) { // nlogn
		int i, lo, hi, x, vi;
		vector<int> v = vector<int>(N, 0);
		vi = -1;
		v[++vi] = A[0];
		for (i = 1; i < N; i++) {
			if (A[i] > v[vi]) {
				v[++vi] = A[i];
				continue;
			}
			for (lo = 0, hi = vi; lo < hi; ) {
				if (v[(lo + hi) / 2] >= A[i]) hi = (lo + hi) / 2;
				else lo = (lo + hi) / 2 + 1;
			}
			v[hi] = A[i];
		}
		return vi + 1;
	}

	vector<int> execute2(vector<int> &A, int &len) { // nlogn
		vector<int> v, v1, p, ret; int i, j; // 0-based index
		v.push_back(A[0]); v1.push_back(0);
		p = vector<int>(N, -1);
		for (int i = 1; i < A.size(); i++) {
			if (v.back() < A[i]) {
				p[i] = v1.back();
				v.push_back(A[i]);
				v1.push_back(i);
			}
			else {
				vector<int>::iterator itr = lower_bound(v.begin(), v.end(), A[i]);
				*itr = A[i];
				int idx = itr - v.begin();
				if (idx != 0) {
					p[i] = v1[idx - 1];
				}
				v1[idx] = i;
			}
		}
		len = v1.size();
		ret = vector<int>(len);
		for (i = v1.back(), j = len - 1; i != -1; i = p[i], j--) ret[j] = A[i];
		return ret;
	}

	int execute3(vector<int> &A) { // n^2
		int i, j, ret = 0;
		vector<int> v = vector<int>(N, 0);
		for (i = 0; i<A.size(); i++) {
			for (j = 0; j<i; j++) if (A[j]<A[i] && v[i]<v[j]) v[i] = v[j];
			v[i]++;
		}
		for (i = 0; i<v.size(); i++) if (v[i]>ret) ret = v[i];
		return ret;
	}
};
