	}
	int isPalindrome(ll xx) {
		ll x; int i, n; vector <int> v;
		for (x = xx; x > 0; x /= 10) {
			v.push_back(x % 10);
		}
		n = v.size();
		for (i = 0; i < n / 2; i++) {
			if (v[i] != v[n - i - 1]) return 0;
		}
		return 1;
	}
};
class BigNumber {
public:
	BigNumber() {

	}
	string add(string &s1, string &s2) {
		int i, j, k, n1, n2, a; string s3; vector<int> v;
		n1 = s1.size();
		n2 = s2.size();
		v.reserve(max(n1, n2) + 1);
		for (i = n1 - 1, j = n2 - 1; i >= 0 && j >= 0; i--, j--) {
			a = s1[i] - '0' + s2[j] - '0';
			v.push_back(a);
		}
		while (i >= 0) {
			a = s1[i] - '0';
			v.push_back(a);
			i--;
		}
		while (j >= 0) {
			a = s2[j] - '0';
			v.push_back(a);
			j--;
		}
		for (i = 0, a = 0; i < v.size(); i++) {
			a += v[i];
			if (a >= 10) {
				v[i] = a - 10;
				a = 1;
			}
			else {
				v[i] = a;
				a = 0;
			}
		}
		if (a) v.push_back(a);
		s3.reserve(v.size());
		for (i = v.size() - 1; i >= 0; i--) s3 += (char)(v[i] + '0');
		s3 += '\n';
		return s3;
	}
};
class PrimeNumber {
	int N; vector<int> NP, P;
	ll _powmod(ll a, ll b) {
		if (b == 0) return 1;
		if (b & 1) return a * _powmod(a, b - 1) % MOD;
		return _powmod(a * a % MOD, b / 2);
	}
public:
	PrimeNumber() {

	}
	PrimeNumber(int n) {
		N = n;
		NP.reserve(N + 4);
		P.reserve(N / 4);
		for (int i = 2; i*i <= N; i++) {
			if (NP[i]) continue;
			for (int j = i*i; j <= N; j += i) NP[i] = 1;
		}
		for (int i = 2; i <= N; i++) if (!NP[i]) P.push_back(i);
	}

	ll gcd(ll x, ll y) {
		ll z;
		while (x) {
			z = y%x;
			y = x;
			x = z;
		}
		return y;
	}

	ll powermod(ll p, ll q) {
		ll g = gcd(p, q);
		p /= g; q /= g;
		return p * _powmod(q, MOD - 2) % MOD;
	}

	vector<int> factorization(int x) {
		vector<int> ret; int i;
		if (x == 1) {
			ret.push_back(1);
			return ret;
		}
		ret.push_back(1); ret.push_back(x);
		for (i = 2; i*i < x; i++) {
			if (x%i == 0) {
				ret.push_back(i);
				ret.push_back(x / i);
			}
		}
		if (i*i == x) ret.push_back(i);
		return ret;
	}

	int factorization2(int x) {
		int ret = 0, i;
		if (x == 1) {
			return 1;
		}
		ret = 2;
		for (i = 2; i*i < x; i++) {
			if (x%i == 0) {
				ret += 2;
			}
		}
		if (i*i == x) ret++;
		return ret;
	}
};
