int a[6];

int main() {
    int n;
    cin >> n;

    if (n - 0 > 0) cin >> a[0];
    if (n - 1 > 0) cin >> a[1];
    if (n - 2 > 0) cin >> a[2];
    if (n - 3 > 0) cin >> a[3];
    if (n-- == 5) cin >> a[4];

    sort(a, a + n + 1);

    int t = (a[0] + a[n]) >> 1;
    int i = 0;
    while (i < n && a[i] <= t) ++i;

    int j = n;
    while (j > 0 && a[j] >= t) --j;

    int ans;
    if (a[i] - t < t - a[j] && a[i - 1] - t > a[i] - t)
        ans = a[i];
    else if (i - 1 >= 0 && a[i - 1] - t < t - a[j] && a[i - 1] - t < t - a[j])
        ans = a[i - 1];
    else
        ans = a[j];

    cout << ans;
    return 0;
}

