        scanf("%lf", &p[i]);
    }

    int m = 1 << n;
    vector<double> dp(2 * m, 0.0);

    vector<unsigned char> pc(m, 0);
    for (int mask = 1; mask < m; ++mask) {
        pc[mask] = (unsigned char)(pc[mask >> 1] + (mask & 1));
    }

    vector<char> good_flag(n, 0);
    vector<int> good;
    for (int i = 0; i < n; ++i) {
        if (p[i] != 0.0) {
            good_flag[i] = 1;
            good.push_back(i);
        }
    }

    vector<double> remain(m, 0.0);
    remain[0] = 1.0;
    for (int mask = 1; mask < m; ++mask) {
        int low = mask & -mask;
        int id = __builtin_ctz(low);
        remain[mask] = remain[mask ^ low] - p[id];
    }

    dp[0] = 1.0;
    int layer = 1;

    for (int step = 0; step < k && step < (int)good.size(); ++step) {
        fill(dp.begin() + layer * m, dp.begin() + (layer + 1) * m, 0.0);

        for (int mask = 0; mask < m; ++mask) {
            if (pc[mask] != step) {
                continue;
            }

            for (int gi = 0; gi < (int)good.size(); ++gi) {
                int v = good[gi];
                if (mask & (1 << v)) {
                    continue;
                }

                int target = mask | (1 << v);
                dp[layer * m + target] +=
                    dp[(layer ^ 1) * m + mask] * p[v] / remain[mask];
            }
        }

        layer ^= 1;
    }

    layer ^= 1;

    for (int i = 0; i < n; ++i) {
        if (!good_flag[i]) {
            printf("%.12f \n", 0.0);
        } else {
            double ans = 0.0;
            for (int mask = 0; mask < m; ++mask) {
                if (mask & (1 << i)) {
                    ans += dp[layer * m + mask];
                }
            }
            printf("%.12f \n", ans);
        }
    }
}

