struct SingleAnswer {
    vector<double> p;
    vector<double> memo;
    vector<char> ready;
    double base;
    int m;

    SingleAnswer(const vector<double>& allp, int banned, int n)
        : base(allp[banned]), m(n - 1) {
        p.reserve(m);
        for (int i = 0; i < n; ++i)
            if (i != banned) p.push_back(allp[i]);
        int total = 1 << m;
        memo.assign(total, 0.0);
        ready.assign(total, 0);
    }

    double get(int mask) {
        if (ready[mask]) return memo[mask];
        double res;
        if (mask == 0) {
            res = base;
        } else {
            double sumP = 0.0;
            double sum = 0.0;
            for (int bit = 0; bit < m; ++bit) {
                if (mask & (1 << bit)) {
                    sumP += p[bit];
                    sum += p[bit] * get(mask ^ (1 << bit));
                }
            }
            res = sum / (1.0 - sumP);
        }
        memo[mask] = res;
        ready[mask] = 1;
        return res;
    }

    double answer(int k) {
        double ans = get(0);
        int total = 1 << m;
        for (int mask = 1; mask < total; ++mask)
            if (__builtin_popcount((unsigned)mask) < k) ans += get(mask);
        return ans;
    }
};

void solve() {
    int n, k;
    cin >> n >> k;
    vector<double> allp(n);
    for (int i = 0; i < n; ++i) cin >> allp[i];

    for (int i = 0; i < n; ++i) {
        if (fabs(allp[i]) < 1e-6) {
            cout << "0 ";
        } else {
            SingleAnswer solver(allp, i, n);
            cout << solver.answer(k) << ' ';
        }
    }
}

