double calc(int mask) {
    if (dp[mask] >= 0) return dp[mask];
    double res = 0.0;
    int m = mask;
    while (m) {
        int lowbit = m & -m;
        int i = 0;
        while ((1 << i) != lowbit) ++i;
        int prev = mask ^ lowbit;
        int rmask = (~prev) & ((1 << n) - 1);
        if (p[i] > 1e-5) {
            res += calc(prev) * p[i] / sum[rmask];
        }
        m ^= lowbit;
    }
    dp[mask] = res;
    return res;
}

