void handle(int mask) {
    vector<int> chosen;
    vector<int> left;
    double leftSum = 0.0;

    for (int i = 0; i < n; ++i) {
        if (mask & (1 << i)) {
            chosen.push_back(i);
        } else {
            left.push_back(i);
            leftSum += p[i];
        }
    }

    int c = (int)chosen.size();
    if (c == m || (c < m && leftSum < 1e-5)) {
        for (int x : chosen) ans[x] += way[mask];
