using namespace std;

const int MOD = 1000000007;
const int LIM = 1000010;

int parentArr[LIM], rankArr[LIM];

int findRootIter(int x) {
    int root = x;
    while (parentArr[root] != root)
        root = parentArr[root];

    while (parentArr[x] != x) {
        int nxt = parentArr[x];
        parentArr[x] = root;
        x = nxt;
    }
    return root;
}

void unionRoots(int a, int b) {
    if (rankArr[a] >= rankArr[b]) {
        parentArr[b] = a;
        ++rankArr[a];
    } else {
        parentArr[a] = b;
        ++rankArr[b];
    }
}

long long fastPow(long long a, long long b) {
    long long ans = 1;
    while (b) {
        if (b & 1LL)
            ans = (ans * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1LL;
    }
    return ans;
}

int main() {
    int P, K;
    scanf("%d%d", &P, &K);

    memset(rankArr, 0, sizeof(rankArr));
    for (int i = 1; i < P; ++i) {
        parentArr[i] = i;
        rankArr[i] = 1;
    }
    parentArr[0] = 0;

    for (int i = 1; i < P; ++i) {
        int to = (int)((long long)K * i % P);
        int a = findRootIter(i);
        int b = findRootIter(to);
        if (a != b)
            unionRoots(a, b);
    }

    set<int> groups;
    for (int i = 1; i < P; ++i)
        groups.insert(findRootIter(i));

    long long ways;
    if (!K)
        ways = fastPow(P, P - 1);
    else if (K == 1)
        ways = fastPow(P, P);
    else
        ways = fastPow(P, (long long)groups.size());

    printf("%d\n", (int)ways);
