const long long MOD = 1000000007LL;

long long binpow(long long base, long long exp) {
    long long result = 1;
    while (exp) {
        if (exp & 1LL)
            result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1LL;
    }
    return result;
}

int main() {
    int P, K;
    scanf("%d%d", &P, &K);

    vector<int> parent(P);
    vector<int> compSize(P, 1);
    for (int i = 0; i < P; ++i)
        parent[i] = i;

    function<int(int)> find = [&](int x) -> int {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    };

    auto unite = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (compSize[ra] < compSize[rb])
            swap(ra, rb);
        parent[rb] = ra;
        compSize[ra] += compSize[rb];
    };

    for (int i = 1; i < P; ++i) {
        int value = (int)((long long)K * i % P);
        unite(i, value);
    }

    int groups = 0;
    vector<char> seenRoot(P, 0);
    for (int i = 1; i < P; ++i) {
        int r = find(i);
        if (!seenRoot[r]) {
            seenRoot[r] = 1;
            ++groups;
        }
    }

    long long ways;
    if (K == 0)
        ways = binpow(P, P - 1);
    else if (K == 1)
        ways = binpow(P, P);
    else
        ways = binpow(P, groups);

    printf("%lld\n", ways);
    return 0;
}

