const long modulo = 1000000007;

int main() {
    long long p, k;
    cin >> p >> k;

    if (k != 1 && k != 0) {
        bool* residue = new bool[p];
        memset(residue, true, p * sizeof(bool));
        long long answer = 1;
        for (int i = 1; i < p; ++i) {
            if (residue[i]) {
                long long temp = i;
                for (int j = 1; j < p; ++j) {
                    temp = (temp * k) % p;
                    if (temp == i) break;
                    residue[temp] = false;
                }
                answer = (answer * p) % modulo;
            }
        }
        delete[] residue;
        cout << answer << endl;
    } else if (k == 1) {
        long long answer = 1;
        for (int i = 0; i < p; ++i)
            answer = (answer * p) % modulo;
        cout << answer << endl;
    } else {
        long long answer = 1;
        for (int i = 0; i < p - 1; ++i)
            answer = (answer * p) % modulo;
        cout << answer << endl;
    }
    return 0;
}

