#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll p, k;
    cin >> p >> k;

    int n = (int)p;
    vector<int> head(n, -1);
    vector<int> to(2 * n + 5, 0);
    vector<int> nxt(2 * n + 5, 0);
    int ec = 0;

    auto add_edge = [&](int u, int v) {
        to[ec] = v;
        nxt[ec] = head[u];
        head[u] = ec++;
    };

    for (ll i = 1; i < p; ++i) {
        ll r = (k * i) % p;
        if (r != 0) {
            int u = (int)i;
            int v = (int)r;
            add_edge(u, v);
            add_edge(v, u);
        }
    }

    vector<char> vis(n, 0);
    ll components = 0;

    for (ll s = 1; s < p; ++s) {
        int start = (int)s;
        if (vis[start]) continue;
        ++components;

        stack<int> st;
        st.push(start);
        vis[start] = 1;

        while (!st.empty()) {
            int v = st.top();
            st.pop();
            for (int e = head[v]; e != -1; e = nxt[e]) {
                int w = to[e];
                if (!vis[w]) {
                    vis[w] = 1;
                    st.push(w);
                }
            }
        }
    }

    if (k == 1) components = p;

    const ll MOD = 1000000007LL;
    ll ans = 1;
    for (ll i = 0; i < components; ++i) {
        ans = ans * p % MOD;
    }

    cout << ans << '\n';
    return 0;
}

