int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll p, k;
    cin >> p >> k;

    vector<char> state((size_t)p, 0);
    ll cycles = 0;
    ll zeroCnt = 0;

    for (ll i = 1; i < p; ++i) {
        if ((k * i) % p == 0) ++zeroCnt;

        if (state[(int)i]) continue;

        vector<ll> path;
        ll cur = i;

        while (cur != 0 && !state[(int)cur]) {
            state[(int)cur] = 1;
            path.push_back(cur);
            cur = (k * cur) % p;
        }

        if (cur != 0 && state[(int)cur] == 1) ++cycles;

        for (ll v : path) state[(int)v] = 2;
    }

    ll components = cycles + zeroCnt;
    if (k == 1) components = p;

    const ll MOD = 1000000007LL;
    ll ans = 1;
    for (ll i = 0; i < components; ++i) {
        ans = ans * p % MOD;
    }

    cout << ans << '\n';
    return 0;
}

