using ll = long long;
const ll MOD = 1000000007LL;

ll bin_pow(ll a, ll e, ll m) {
  ll r = 1;
  while (e != 0) {
    if (e % 2 != 0) r = (r * a) % m;
    a = (a * a) % m;
    e /= 2;
  }
  return r;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);

  ll p, k;
  while (cin >> p >> k) {
    if (k == 0) {
      cout << bin_pow(p, p - 1, MOD) << '\n';
      continue;
    }
    if (k == 1) {
      cout << bin_pow(p, p, MOD) << '\n';
      continue;
    }

    unordered_set<ll> seen;
    seen.reserve((size_t)p);

    ll cycles = 0;

    for (ll i = 1; i < p; ++i) {
      if (seen.find(i) != seen.end()) continue;

      ll j = i;
      ll w = 0;

      while (seen.find(j) == seen.end()) {
        ++w;
        seen.insert(j);
        j = (j * k) % p;
      }

      if (bin_pow(k, w, p) == 1) ++cycles;
    }

    cout << bin_pow(p, cycles, MOD) << '\n';
  }

  return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

ll power_mod(ll base, ll exponent, ll modulus) {
  ll result = 1;
  while (exponent != 0) {
    if (exponent % 2 != 0) result = (result * base) % modulus;
    base = (base * base) % modulus;
    exponent /= 2;
  }
  return result;
}

ll solve_case(ll p, ll k) {
  if (k == 0) return power_mod(p, p - 1, MOD);
  if (k == 1) return power_mod(p, p, MOD);

  vector<char> used(p, 0);
  ll good = 0;

  for (ll i = 1; i < p; ++i) {
    if (used[i]) continue;

    ll cur = i;
    ll steps = 0;

    while (!used[cur]) {
      ++steps;
      used[cur] = 1;
      cur = (cur * k) % p;
    }

    if (power_mod(k, steps, p) == 1) ++good;
  }

  return power_mod(p, good, MOD);
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  ll p, k;
  while (cin >> p >> k) {
    cout << solve_case(p, k) << '\n';
  }

  return 0;
}

