#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 MOD = 1000000007LL;

class Solver {
    int64 p, k;
    vector<int> seen;

    int64 mod_pow(int64 base, int64 exp) const {
        int64 res = 1;
        base %= p;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % p;
            base = (base * base) % p;
            exp >>= 1;
        }
        return res;
    }

    int64 cycle_factor(int64 len) const {
        if (len == 0) return p;
        return mod_pow(k, len) == 1 ? p : 1;
    }

public:
    void run() {
        cin >> p >> k;

        if (k == 0 || k == 1) {
            int64 ans = 1;
            for (int64 i = 0; i < p - 1; ++i) {
                ans = (ans * p) % MOD;
            }
            if (k == 1) ans = (ans * p) % MOD;
            cout << ans << '\n';
            return;
        }

        seen.assign((size_t)p, 0);
        int64 ans = 1;

        for (int64 i = 1; i < p; ++i) {
            if (seen[i]) continue;
            int64 x = i;
            int64 len = 0;
            while (!seen[x]) {
                seen[x] = 1;
                x = (k * x) % p;
                ++len;
            }
            ans = (ans * cycle_factor(len)) % MOD;
        }

        cout << ans << '\n';
    }
};

