#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

ll p, k;

ll factor_for_len(ll len) {
    ll val = 1;
    for (ll i = 0; i < len; ++i) {
        val = (val * k) % p;
    }
    return (val == 1) ? p : 1;
}

int32_t main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> p >> k;

    if (k == 0 || k == 1) {
        ll ans = 1;
        for (ll i = 0; i < p - 1; ++i) {
            ans = (ans * p) % MOD;
        }
        if (k == 1) ans = (ans * p) % MOD;
        cout << ans << '\n';
        return 0;
    }

    vector<char> seen(p, 0);
    vector<ll> contrib;
    contrib.reserve((size_t)p);

    for (ll start = 1; start < p; ++start) {
        if (seen[start]) continue;
        ll x = start;
        ll len = 0;
        while (!seen[x]) {
            seen[x] = 1;
            x = (k * x) % p;
            ++len;
        }
        contrib.push_back(factor_for_len(len));
    }

    ll ans = accumulate(contrib.begin(), contrib.end(), 1LL,
        [](ll a, ll b) -> ll { return (a * b) % MOD; });

    cout << ans << '\n';
    return 0;
}

