#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll MOD = 1000000007LL;

ll mod_pow(ll a, ll e) {
    if (e < 0) e = -e;
    a %= MOD;
    ll res = 1;
    while (e) {
        if (e & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k;
    cin >> n >> k;

    if (k == 0) {
        cout << mod_pow(n, n - 1) << '\n';
        return 0;
    }

    vector<unsigned char> seen(n, 0);
    vector<ll> cnt(n + 1, 0), mult(n + 1, 0);

    for (ll start = 0; start < n; ++start) {
        if (seen[start]) continue;
        ll cur = start;
        ll len = 0;
        while (!seen[cur]) {
            seen[cur] = 1;
            cur = (cur * k) % n;
            ++len;
        }
        ++cnt[len];
    }

    vector<ll> active;
    active.reserve(n);
    for (ll i = 1; i <= n; ++i) {
        if (cnt[i]) active.push_back(i);
    }

    for (ll d : active) {
        ll add = d * cnt[d];
        for (ll m = d; m <= n; m += d) {
            if (cnt[m]) mult[m] += add;
        }
    }

    ll ans = 1;
    for (ll i : active) {
        ans = ans * mod_pow(mult[i], cnt[i]) % MOD;
    }

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll MOD = 1000000007LL;
const ll MAXN = 1000505;

ll rep[MAXN], seen[MAXN], mult[MAXN];

ll pw(ll a, ll b) {
    if (b == 0) return 1;
    ll half = pw(a, b / 2);
    ll sq = (half * half) % MOD;
    if (b % 2 == 0) return sq;
    return (a * sq) % MOD;
}

ll measure(ll start, ll k, ll n) {
    ll cur = start, len = 0;
    while (true) {
        if (seen[cur]) break;
        seen[cur] = 1;
        cur = (cur * k) % n;
        ++len;
    }
    return len;
}

int main() {
    ll n, k;
    scanf("%lld %lld", &n, &k);

    if (k == 0) {
        printf("%lld\n", pw(n, n - 1));
        return 0;
    }

    for (ll i = 0; i < n; ++i) {
        if (!seen[i]) {
            ll w = measure(i, k, n);
            ++rep[w];
        }
    }

    for (ll i = 1; i <= n; ++i) {
        for (ll j = i; j <= n; j += i) {
            if (rep[j]) mult[j] += rep[i] * i;
        }
    }

    ll ans = 1;
    for (ll i = 1; i <= n; ++i) {
        if (mult[i]) ans = ans * pw(mult[i], rep[i]) % MOD;
    }

    printf("%lld\n", ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll MOD = 1000000007LL;

class Solver {
    ll n, k;
    vector<char> used;
    vector<ll> freq, weight;

    ll binpow(ll a, ll e) {
        if (e < 0) e = -e;
        a %= MOD;
        ll r = 1;
        while (e) {
            if (e & 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    ll journey(ll start) {
        ll cur = start;
        ll length = 0;
        while (!used[cur]) {
            used[cur] = 1;
            cur = (cur * k) % n;
            ++length;
        }
        return length;
    }

public:
    Solver(ll n_, ll k_) : n(n_), k(k_), used(n_, 0), freq(n_ + 1, 0), weight(n_ + 1, 0) {}

    ll solve() {
        if (k == 0) return binpow(n, n - 1);

        for (ll i = 0; i < n; ++i) {
            if (!used[i]) {
                ++freq[journey(i)];
            }
        }

        for (ll len = 1; len <= n; ++len) {
            if (freq[len] == 0) continue;
            ll add = len * freq[len];
            for (ll multiple = len; multiple <= n; multiple += len) {
                if (freq[multiple]) weight[multiple] += add;
            }
        }

        ll ans = 1;
        for (ll i = 1; i <= n; ++i) {
            if (freq[i]) ans = ans * binpow(weight[i], freq[i]) % MOD;
        }
        return ans;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k;
    cin >> n >> k;

    Solver solver(n, k);
    cout << solver.solve() << '\n';
    return 0;
}

