using namespace std;
using ll = long long;

const ll MOD = 1000000007LL;
const ll MAXN = 1000505;

ll cntLen[MAXN], vis[MAXN], multSum[MAXN];

ll mod_pow(ll a, ll e) {
    if (e < 0) e = -e;
    a %= MOD;
    ll r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

ll traverse(ll start, ll mul, ll n) {
    ll cur = start;
    ll len = 0;
again:
    if (vis[cur]) goto done;
    vis[cur] = 1;
    cur = (cur * mul) % n;
    ++len;
    goto again;
done:
    return len;
}

int main() {
    ll n, k;
    scanf("%lld %lld", &n, &k);

    if (k == 0) {
        printf("%lld\n", mod_pow(n, n - 1));
        return 0;
    }

    for (ll i = 0; i < n; ++i) {
        if (!vis[i]) {
            ll w = traverse(i, k, n);
            ++cntLen[w];
        }
    }

    for (ll i = 1; i <= n; ++i) {
        for (ll j = i; j <= n; j += i) {
            if (cntLen[j]) multSum[j] += cntLen[i] * i;
        }
    }

    ll ans = 1;
    for (ll i = 1; i <= n; ++i) {
        if (multSum[i]) ans = ans * mod_pow(multSum[i], cntLen[i]) % MOD;
    }

    printf("%lld\n", ans);
    return 0;
}

