const long long MOD = 1000000007LL;
const int MAXN = 2000005;

long long parent[MAXN];
long long rating[MAXN];

long long findparent(long long root) {
    while (parent[root] != root) {
        root = parent[root];
    }
    return root;
}

void findunion(long long root1, long long root2) {
    long long par1 = findparent(root1);
    long long par2 = findparent(root2);
    if (rating[par1] >= rating[par2]) {
        parent[par2] = par1;
        ++rating[par1];
    } else {
        parent[par1] = par2;
        ++rating[par2];
    }
}

long long modPow(long long base, long long exp) {
    base %= MOD;
    long long res = 1;
    while (exp > 0) {
        if (exp & 1LL) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

