int edmondsKarp(int N, int S, int T) {
    while (1) {
        memset(pre, -1, sizeof(pre));
        queue<int> q;
        d[S] = INF;
        q.push(S);
        while (!q.empty() && pre[T] < 0) {
            int u = q.front(); q.pop();
            for (int v = 0; v < N; ++v) {
                int r = cap[u][v] - flow[u][v];
                if (pre[v] < 0 && r > 0) {
                    pre[v] = u;
                    d[v] = min(d[u], r);
                    q.push(v);
                }
            }
        }
        if (pre[T] < 0) break;
        for (int v = T; v != S; v = pre[v]) {
            int u = pre[v];
            flow[u][v] += d[T];
            flow[v][u] -= d[T];
        }
    }
    int ans = 0;
    for (int i = 0; i < N; ++i) ans += flow[S][i];
    return ans;
}

