    Flow(int n_) : n(n_) {
        memset(c, 0, sizeof(c));
        memset(f, 0, sizeof(f));
    }
    void link(int u, int v, int w) { c[u][v] = w; }
    int maxflow(int S, int T) {
        while (true) {
            int pre[NN], d[NN];
            memset(pre, -1, sizeof(pre));
            queue<int> q;
            d[S] = INF;
            q.push(S);
            while (!q.empty() && pre[T] < 0) {
                int u = q.front(); q.pop();
                for (int v = 0; v < n; ++v) {
                    int r = c[u][v] - f[u][v];
                    if (pre[v] < 0 && r > 0) {
                        pre[v] = u;
                        d[v] = min(d[u], r);
                        q.push(v);
                    }
                }
            }
            if (pre[T] < 0) break;
            for (int v = T; v != S; v = pre[v]) {
                int u = pre[v];
                f[u][v] += d[T];
                f[v][u] -= d[T];
            }
        }
        int ans = 0;
        for (int i = 0; i < n; ++i) ans += f[S][i];
        return ans;
    }
};

