    while (!st.empty()) {
        int u = st.top(); st.pop();
        if (u == superSink) break;
        for (int v = 0; v <= superSink; ++v) {
            if (graph[u][v] && prev[v] == -1) {
                prev[v] = u;
                st.push(v);
            }
        }
    }
    if (prev[superSink] == -1) return 0;
    int add = 10000;
    for (int v = superSink; v != 0; v = prev[v]) add = min(add, graph[prev[v]][v]);
    for (int v = superSink; v != 0; v = prev[v]) {
        graph[prev[v]][v] -= add;
        graph[v][prev[v]] += add;
    }
    return add;
}

