class Solver {
    int n, T, sinkNode;
    int srcCap[10][10], snkCap[10][10], srcId[10][10], snkId[10][10];
    int plant[10][10][61];
    int F[250][250];
    static const int dr[4], dc[4];

    bool valid(int r, int c) const {
        return r>=0 && r<n && c>=0 && c<n;
    }

    int findPath() {
        vector<int> parent(sinkNode+1, -1);
        parent[0] = 0;
        stack<int> st;
        st.push(0);
        while(!st.empty()) {
            int u = st.top(); st.pop();
            if (u == sinkNode) break;
            for (int v=0; v<=sinkNode; ++v) {
                if (F[u][v] && parent[v]==-1) {
                    parent[v] = u;
                    st.push(v);
                }
            }
        }
        if (parent[sinkNode] == -1) return 0;
        int add = 10000;
        for (int v=sinkNode; v!=0; v=parent[v]) add = min(add, F[parent[v]][v]);
        for (int v=sinkNode; v!=0; v=parent[v]) {
            F[parent[v]][v] -= add;
            F[v][parent[v]] += add;
        }
        return add;
    }

    void simulatePlants() {
        for (int tm=1; tm<=T; ++tm) {
            for (int i=0; i<n; ++i)
                for (int j=0; j<n; ++j)
                    plant[i][j][tm] = plant[i][j][tm-1];
            for (int i=0; i<n; ++i)
                for (int j=0; j<n; ++j)
                    if (plant[i][j][tm-1] == 2)
                        for (int k=0; k<4; ++k) {
                            int ni=i+dr[k], nj=j+dc[k];
                            if (valid(ni,nj) && plant[ni][nj][tm-1]==0)
                                plant[ni][nj][tm] = 2;
                        }
        }
    }

    void addReachabilityEdges() {
        for (int i=0; i<n; ++i) {
            for (int j=0; j<n; ++j) {
                if (srcCap[i][j] == 0) continue;
                queue<pair<int,pair<int,int>>> q;
                q.push({0,{i,j}});
                vector<vector<bool>> vis(n, vector<bool>(n, false));
                vis[i][j] = true;
                int src = srcId[i][j];
                while (!q.empty()) {
                    auto cur = q.front(); q.pop();
                    int tm = cur.first;
                    int r = cur.second.first;
                    int c = cur.second.second;
                    if (snkCap[r][c] != 0) F[src][snkId[r][c]] = 10000;
                    if (tm == T) continue;
                    if (plant[r][c][tm] != 0) continue;
                    for (int k=0; k<4; ++k) {
                        int nr = r+dr[k], nc = c+dc[k];
                        if (valid(nr,nc) && plant[nr][nc][tm]==0 && !vis[nr][nc]) {
                            vis[nr][nc] = true;
                            q.push({tm+1,{nr,nc}});
                        }
                    }
                }
            }
        }
    }

    void addBoundaryEdges() {
        for (int i=0; i<n; ++i) {
            for (int j=0; j<n; ++j) {
                if (srcCap[i][j] != 0) F[0][srcId[i][j]] = srcCap[i][j];
                if (snkCap[i][j] != 0) F[snkId[i][j]][sinkNode] = snkCap[i][j];
            }
        }
    }

public:
    Solver() {
        memset(F, 0, sizeof(F));
    }

    void run() {
        cin >> n >> T;
        vector<string> s(n);
        for (int i=0; i<n; ++i) cin >> s[i];

        for (int i=0; i<n; ++i)
            for (int j=0; j<n; ++j)
                if (s[i][j]=='Y' || s[i][j]=='Z') {
                    plant[i][j][0] = s[i][j]-'X';
                    srcCap[i][j] = 0;
                } else {
                    plant[i][j][0] = 0;
                    srcCap[i][j] = s[i][j]-'0';
                }

        for (int i=0; i<n; ++i) cin >> s[i];

        for (int i=0; i<n; ++i)
            for (int j=0; j<n; ++j)
                if (s[i][j]=='Y' || s[i][j]=='Z') {
                    plant[i][j][0] = s[i][j]-'X';
                    snkCap[i][j] = 0;
                } else {
                    plant[i][j][0] = 0;
                    snkCap[i][j] = s[i][j]-'0';
                }

        simulatePlants();

        sinkNode = 1;
        memset(srcId, -1, sizeof(srcId));
        memset(snkId, -1, sizeof(snkId));
        for (int i=0; i<n; ++i)
            for (int j=0; j<n; ++j)
                if (srcCap[i][j] != 0) srcId[i][j] = sinkNode++;
        for (int i=0; i<n; ++i)
            for (int j=0; j<n; ++j)
                if (snkCap[i][j] != 0) snkId[i][j] = sinkNode++;

        addReachabilityEdges();
        addBoundaryEdges();

        int ans = 0;
        while (true) {
            int f = findPath();
            if (!f) break;
            ans += f;
        }
        cout << ans << '\n';
    }
};

const int Solver::dr[4] = {0,0,-1,1};
const int Solver::dc[4] = {-1,1,0,0};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    Solver solver;
    solver.run();
    return 0;
}

