struct EdmondsKarp {
    vector<int> adj[MAXV];
    int cap[MAXV][MAXV];

    EdmondsKarp() { memset(cap, 0, sizeof(cap)); }

    void addEdge(int u, int v, int c) {
        adj[u].push_back(v);
        adj[v].push_back(u);
        cap[u][v] = c;
        cap[v][u] = 0;
    }

    int maxFlow(int s, int t) {
        int ans = 0;
        while (true) {
            int parent[MAXV];
            memset(parent, -1, sizeof(parent));
            queue<int> q;
            parent[s] = s;
            q.push(s);
            while (!q.empty() && parent[t] == -1) {
                int u = q.front(); q.pop();
                for (int v : adj[u]) {
                    if (cap[u][v] > 0 && parent[v] == -1) {
                        parent[v] = u;
                        q.push(v);
                    }
                }
            }
            if (parent[t] == -1) break;
            int push = INF;
            for (int v = t; v != s; v = parent[v])
                push = min(push, cap[parent[v]][v]);
            for (int v = t; v != s; v = parent[v]) {
                int u = parent[v];
                cap[u][v] -= push;
                cap[v][u] += push;
            }
            ans += push;
        }
        return ans;
    }
};

