const int MAXM = 100100;
const int oo = (1<<29);

vector<int> last, now, lev, cola;
vector<int> ady, flow, cap, nxt;
int E, n, s, t, enq, deq;

void init_maxflow( int nn, int ss, int tt ){
    n = nn; s = ss; t = tt; E = 2;
    last.assign(n+1, 0);
    ady.resize(2*MAXM);
    flow.resize(2*MAXM);
    cap.resize(2*MAXM);
    nxt.resize(2*MAXM);
    now.resize(n+1);
    lev.resize(n+1);
    cola.resize(n+1);
}
void add_edge( int u, int v, int c ){
    ady[E] = v; flow[E] = 0; cap[E] = c; nxt[E] = last[u]; last[u] = E++;
    ady[E] = u; flow[E] = 0; cap[E] = 0; nxt[E] = last[v]; last[v] = E++;
}
bool bfs(){
    fill(lev.begin(), lev.begin()+n+1, 0);
    enq = deq = 0;
    cola[enq++] = s;
    lev[s] = 1;
    while( deq < enq && !lev[t] ){
        int u = cola[deq++];
        for( int e = last[u]; e; e = nxt[e] ){
            int v = ady[e];
            if( !lev[v] && flow[e] < cap[e] ){
                lev[v] = lev[u] + 1;
                cola[enq++] = v;
            }
        }
    }
    return lev[t];
}
int dfs( int u, int F ){
    if( u == t ) return F;
    for( int &e = now[u]; e; e = nxt[e] ){
        int v = ady[e];
        if( lev[u] < lev[v] && flow[e] < cap[e] ){
            int f = dfs( v , min( F , cap[e] - flow[e] ) );
            if( f ){
                flow[e] += f;
                flow[e^1] -= f;
                return f;
            }
        }
    }
    return 0;
}
int max_flow(){
    int F = 0;
    while( bfs() ){
        copy(last.begin(), last.begin()+n+1, now.begin());
        int f;
        while( (f = dfs( s , oo )) ) F += f;
    }
    return F;
}

int R;
string m1[MAXR];
string m2[MAXR];

int movI[] = { 0 , 1 , 0 , -1 };
int movJ[] = { 1 , 0 , -1 , 0 };

bool can_move( int i, int j ){
    return ( i >= 0 && j >= 0 && i < R && j < R && m1[i][j] != 'Y' && m1[i][j] != 'Z' );
}

int tim[2][MAXR][MAXR];

void bfs2( int i, int j, int cc ){
    for( int k = 0; k < R; k++ ){
        for( int l = 0; l < R; l++ ){
            tim[cc][k][l] = 0;
        }
    }

    tim[cc][i][j] = 1;
    queue<par> q;
    q.push( make_pair( i , j ) );
    while( !q.empty() ){
        int ci = q.front().first;
        int cj = q.front().second;
        q.pop();

        if( cc == 1 && (tim[0][ci][cj] && tim[0][ci][cj] <= tim[1][ci][cj]) ){
            continue;
        }

        for( int k = 0; k < 4; k++ ){
            int ii = ci + movI[k];
            int jj = cj + movJ[k];

            if( can_move( ii , jj ) && !tim[cc][ii][jj] ){
                tim[cc][ii][jj] = tim[cc][ci][cj] + 1;
                q.push( make_pair( ii , jj ) );
            }
        }
    }
}

int nod[2][MAXR][MAXR];

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);

    int T; cin >> R >> T;

    int zi = 0, zj = 0;

    int n = 0, s = 0, t = 0;

    for( int i = 0; i < R; i++ ){
        cin >> m1[i];
        for( int j = 0; j < R; j++ ){
            if( m1[i][j] == 'Z' ){
                zi = i;
                zj = j;
            }
            else if( m1[i][j] != 'Y' ){
                n++;
                nod[0][i][j] = n;
            }
        }
    }

    for( int i = 0; i < R; i++ ){
        cin >> m2[i];
        for( int j = 0; j < R; j++ ){
            if( m2[i][j] != 'Y' && m2[i][j] != 'Z' ){
                n++;
                nod[1][i][j] = n;
            }
        }
    }

    n++;
    s = 0;
    t = n;

    init_maxflow( n , s , t );

    for( int i = 0; i < R; i++ ){
        for( int j = 0; j < R; j++ ){
            if( m1[i][j] != 'Z' && m1[i][j] != 'Y' ){
                add_edge( s , nod[0][i][j] , m1[i][j] - '0' );
                add_edge( nod[1][i][j] , t , m2[i][j] - '0' );
            }
        }
    }

    bfs2( zi , zj, 0 );

    for( int i = 0; i < R; i++ ){
        for( int j = 0; j < R; j++ ){
            if( m1[i][j] > '0' && m1[i][j] <= '9' ){
                bfs2( i , j , 1 );
                for( int ii = 0; ii < R; ii++ ){
                    for( int jj = 0; jj < R; jj++ ){
                        if( m2[ii][jj] > '0' && m2[ii][jj] <= '9' ){
                            if( tim[1][ii][jj] && (!tim[0][ii][jj] || tim[0][ii][jj] >= tim[1][ii][jj]) &&
                                tim[1][ii][jj]-1 <= T ){
                                add_edge( nod[0][i][j] , nod[1][ii][jj] , oo );
                            }
                        }
                    }
                }
            }
        }
    }

    cout << max_flow() << '\n';
}

