#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

int n, t;
struct pkt
{
    int x, y;
};

struct kraw
{
    int a, res;
};

int dx[] = {-1, 0, 1, 0, 0};
int dy[] = {0, 1, 0, -1, 0};

bool Ok(int x, int y)
{
    return (x >= 0 && x < n && y >= 0 && y < n);
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin >> n >> t;
    vector<string> nau(n), pom(n);
    for (int i = 0; i < n; ++i)
        cin >> nau[i];
    for (int i = 0; i < n; ++i)
        cin >> pom[i];
    vector< vector<int> > odl(n, vector<int>(n, 1000));
    pkt start;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (nau[i][j] == 'Z')
                start = {i, j};
    queue<pkt> Q;
    odl[start.x][start.y] = 0;
    Q.push(start);
    while (!Q.empty())
    {
        pkt akt = Q.front();
        Q.pop();
        for (int i = 0; i < 4; ++i)
        {
            pkt nowy = {akt.x + dx[i], akt.y + dy[i]};
            if (Ok(nowy.x, nowy.y) && nau[nowy.x][nowy.y] >= '0' && nau[nowy.x][nowy.y] <= '9' && odl[nowy.x][nowy.y] == 1000)
            {
                odl[nowy.x][nowy.y] = odl[akt.x][akt.y] + 1;
                Q.push(nowy);
            }
        }
    }
    bool moge[60][10][10][10][10];
    for (int i = 0; i < 60; ++i)
        for (int j = 0; j < 10; ++j)
            for (int k = 0; k < 10; ++k)
                for (int l = 0; l < 10; ++l)
                    for (int m = 0; m < 10; ++m)
                        moge[i][j][k][l][m] = false;
    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < n; ++j)
        {
            for (int k = 0; k < 5; ++k)
            {
                int l = i + dx[k], m = j + dy[k];
                if (Ok(l, m) && nau[i][j] >= '0' && nau[i][j] <= '9' && nau[l][m] >= '0' && nau[l][m] <= '9')
                    moge[0][i][j][l][m] = true;
            }
        }
    }
    for (int i = 0; i <= t - 2; ++i)
    {
        for (int j = 0; j < n; ++j)
        {
            for (int k = 0; k < n; ++k)
            {
                for (int l = 0; l < n; ++l)
                {
                    for (int m = 0; m < n; ++m)
                    {
                        if (!moge[i][j][k][l][m])
                            continue;
                        for (int o = 0; o < 5; ++o)
                        {
                            int p = l + dx[o], r = m + dy[o];
                            if (Ok(p, r) && nau[p][r] >= '0' && nau[p][r] <= '9' && odl[l][m] >= i + 2 && odl[p][r] >= i + 2)
                                moge[i + 1][j][k][p][r] = true;
                        }
                    }
                }
            }
        }
    }
    vector<pkt> a;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (nau[i][j] >= '0' && nau[i][j] <= '9')
                a.push_back({i, j});
    int wie = 2 * a.size() + 2;
    vector< vector<kraw> > G(wie);
    for (int i = 0; i < a.size(); ++i)
    {
        G[0].push_back({i + 1, nau[a[i].x][a[i].y] - '0'});
        G[i + 1].push_back({0, 0});
        G[a.size() + 1 + i].push_back({wie - 1, pom[a[i].x][a[i].y] - '0'});
        G[wie - 1].push_back({a.size() + 1 + i, 0});
    }
    for (int i = 0; i < a.size(); ++i)
    {
        for (int j = 0; j < a.size(); ++j)
        {
            int ok = false;
            for (int k = 0; k <= t - 1; ++k)
                ok |= moge[k][a[i].x][a[i].y][a[j].x][a[j].y];
            if (ok)
            {
                G[i + 1].push_back({a.size() + 1 + j, 1000});
                G[a.size() + 1 + j].push_back({i + 1, 0});
            }
        }
    }
    int odp = 0;
    while (true)
    {
        vector<bool> odw(wie, false);
        queue<int> Q2;
        odw[0] = true;
        Q2.push(0);
        vector<int> pop(wie, -1);
        while (!Q2.empty())
        {
            int akt = Q2.front();
            Q2.pop();
            for (int i = 0; i < G[akt].size(); ++i)
            {
                if (!odw[G[akt][i].a] && G[akt][i].res > 0)
                {
                    Q2.push(G[akt][i].a);
                    pop[G[akt][i].a] = akt;
                    odw[G[akt][i].a] = true;
                }
            }
        }
        if (pop[wie - 1] == -1)
            break;
        vector<int> path;
        int akt = wie - 1;
        while (akt != -1)
        {
            path.push_back(akt);
            akt = pop[akt];
        }
        reverse(path.begin(), path.end());
        int flow = 1000;
        for (int i = 0; i < path.size() - 1; ++i)
            for (int j = 0; j < G[path[i]].size(); ++j)
                if (G[path[i]][j].a == path[i + 1])
                    flow = min(flow, G[path[i]][j].res);
        odp += flow;
        for (int i = 0; i < path.size() - 1; ++i)
            for (int j = 0; j < G[path[i]].size(); ++j)
                if (G[path[i]][j].a == path[i + 1])
                    G[path[i]][j].res -= flow;
        for (int i = 1; i < path.size(); ++i)
            for (int j = 0; j < G[path[i]].size(); ++j)
                if (G[path[i]][j].a == path[i - 1])
                    G[path[i]][j].res += flow;
    }
    cout << odp;
