}

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <array>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, t;
    cin >> n >> t;

    vector<string> nau(n), pom(n);
    for (auto& s : nau) cin >> s;
    for (auto& s : pom) cin >> s;

    vector<vector<int>> odl(n, vector<int>(n, 1000));

    // Find start
    int sx = -1, sy = -1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (nau[i][j] == 'Z') { sx = i; sy = j; }

    // Directions
    const array<int, 5> dx = {-1, 0, 1, 0, 0};
    const array<int, 5> dy = {0, 1, 0, -1, 0};

    auto ok = [n](int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    };

    // BFS from start
    queue<pair<int,int>> Q;
    odl[sx][sy] = 0;
    Q.emplace(sx, sy);
    while (!Q.empty()) {
        auto [x, y] = Q.front(); Q.pop();
        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (ok(nx, ny) && nau[nx][ny] >= '0' && nau[nx][ny] <= '9' && odl[nx][ny] == 1000) {
                odl[nx][ny] = odl[x][y] + 1;
                Q.emplace(nx, ny);
            }
        }
    }

    // Reachability DP: moge[k][x1][y1][x2][y2]
    using Moge = array<array<array<array<array<bool,10>,10>,10>,10>,60>;
    Moge moge;
    for (auto& t1 : moge)
        for (auto& t2 : t1)
            for (auto& t3 : t2)
                for (auto& t4 : t3)
                    for (auto& t5 : t4)
                        t5 = false;

    // Initialize step 0
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            for (int d = 0; d < 5; ++d) {
                int ni = i + dx[d], nj = j + dy[d];
                if (ok(ni, nj) && isdigit(nau[i][j]) && isdigit(nau[ni][nj]))
                    moge[0][i][j][ni][nj] = true;
            }

    // DP steps
    for (int k = 0; k <= t - 2; ++k)
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                for (int l = 0; l < n; ++l)
                    for (int m = 0; m < n; ++m) {
                        if (!moge[k][i][j][l][m]) continue;
                        for (int d = 0; d < 5; ++d) {
                            int nl = l + dx[d], nm = m + dy[d];
                            if (ok(nl, nm) && isdigit(nau[nl][nm]) && odl[l][m] >= k+2 && odl[nl][nm] >= k+2)
                                moge[k+1][i][j][nl][nm] = true;
                        }
                    }

    // Collect digit positions
    vector<pair<int,int>> a;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(nau[i][j]))
                a.emplace_back(i, j);

    int V = 2 * (int)a.size() + 2;
    vector<vector<pair<int,int>>> G(V); // (to, capacity)

    // Source edges
    for (int i = 0; i < (int)a.size(); ++i) {
        int cap = nau[a[i].first][a[i].second] - '0';
        G[0].emplace_back(i + 1, cap);
        G[i + 1].emplace_back(0, 0);
        cap = pom[a[i].first][a[i].second] - '0';
        G[a.size() + 1 + i].emplace_back(V - 1, cap);
        G[V - 1].emplace_back(a.size() + 1 + i, 0);
    }

    // Middle edges based on reachability
    for (int i = 0; i < (int)a.size(); ++i) {
        for (int j = 0; j < (int)a.size(); ++j) {
            bool ok = false;
            for (int k = 0; k <= t - 1; ++k)
                if (moge[k][a[i].first][a[i].second][a[j].first][a[j].second]) {
                    ok = true;
                    break;
                }
            if (ok) {
                G[i + 1].emplace_back(a.size() + 1 + j, 1000);
                G[a.size() + 1 + j].emplace_back(i + 1, 0);
            }
        }
    }

    // Max flow (Edmonds-Karp)
    int flow = 0;
    while (true) {
        vector<bool> vis(V, false);
        vector<int> par(V, -1);
        queue<int> q;
        vis[0] = true;
        q.push(0);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& [v, cap] : G[u]) {
                if (!vis[v] && cap > 0) {
                    vis[v] = true;
                    par[v] = u;
                    q.push(v);
                }
            }
        }
        if (par[V - 1] == -1) break;

        // Find bottleneck
        int add = 1000;
        for (int v = V - 1; v != 0; v = par[v]) {
            int u = par[v];
            for (auto& [to, cap] : G[u])
                if (to == v) { add = min(add, cap); break; }
        }

        // Augment
        for (int v = V - 1; v != 0; v = par[v]) {
            int u = par[v];
            for (auto& [to, cap] : G[u])
                if (to == v) { cap -= add; break; }
            for (auto& [to, cap] : G[v])
                if (to == u) { cap += add; break; }
        }
        flow += add;
    }

    cout << flow;
    return 0;
}

