#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int MAXN = 150;

struct FlowEdge {
    int to, rev;
    ll cap;
    FlowEdge(int t, int r, ll c) : to(t), rev(r), cap(c) {}
};

struct Dinic {
    int n, s, t;
    vector<vector<FlowEdge>> g;
    vector<int> level, it;
    Dinic(int n, int s, int t) : n(n), s(s), t(t) { g.resize(n); level.resize(n); it.resize(n); }
    void addEdge(int u, int v, ll c) {
        g[u].emplace_back(v, (int)g[v].size(), c);
        g[v].emplace_back(u, (int)g[u].size()-1, 0);
    }
    bool bfs() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0; q.push(s);
        while(!q.empty()) {
            int u = q.front(); q.pop();
            for(auto &e : g[u]) if(e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
        return level[t] != -1;
    }
    ll dfs(int u, ll f) {
        if(u == t) return f;
        for(int &i = it[u]; i < (int)g[u].size(); ++i) {
            FlowEdge &e = g[u][i];
            if(e.cap > 0 && level[e.to] == level[u] + 1) {
                ll ret = dfs(e.to, min(f, e.cap));
                if(ret) {
                    e.cap -= ret;
                    g[e.to][e.rev].cap += ret;
                    return ret;
                }
            }
        }
        return 0;
    }
    ll maxflow() {
        ll ans = 0;
        while(bfs()) {
            fill(it.begin(), it.end(), 0);
            while(ll f = dfs(s, 1e18)) ans += f;
        }
        return ans;
    }
};

int pos[MAXN][MAXN], tempo[MAXN][MAXN], alc[MAXN][MAXN];

void fillTempo(int i, int j, vector<string>& sc, int n, int cur) {
    if(i<0||i>=n||j<0||j>=n) return;
    if(!isdigit(sc[i][j]) && sc[i][j]!='Z') return;
    if(tempo[i][j]!=-1 && tempo[i][j]<=cur) return;
    tempo[i][j] = (tempo[i][j]==-1)?cur:min(tempo[i][j],cur);
    fillTempo(i+1,j,sc,n,cur+1);
    fillTempo(i-1,j,sc,n,cur+1);
    fillTempo(i,j+1,sc,n,cur+1);
    fillTempo(i,j-1,sc,n,cur+1);
}

void fillAlc(int i, int j, vector<string>& sc, int n, int cur) {
    if(i<0||i>=n||j<0||j>=n) return;
    if(!isdigit(sc[i][j])) return;
    if(alc[i][j]!=-1 && alc[i][j]<=cur) return;
    alc[i][j] = (alc[i][j]==-1)?cur:min(alc[i][j],cur);
    fillAlc(i+1,j,sc,n,cur+1);
    fillAlc(i-1,j,sc,n,cur+1);
    fillAlc(i,j+1,sc,n,cur+1);
    fillAlc(i,j-1,sc,n,cur+1);
}

