void ff(int x,int y,vector<vector<int> >& v)
{
	queue<int> q;
	q.push(x*N+y);
	while(q.size())
	{
		x = q.front()/N;
		y = q.front()%N;
		q.pop();
		for(int i=0;i<4;i++)
		{
			int nx = x+dx[i];
			int ny = y+dy[i];
			if(nx<0 || nx>=N ||ny<0 || ny>=N || v[nx][ny]!=-1 || mat[nx][ny]=='Y')
				continue;
			if(isdigit(mat2[nx][ny]) && mat2[nx][ny]!='0' && (v[x][y]+1<= v1[nx][ny]||v1[nx][ny]==-1) )
			{
				v[nx][ny] = v[x][y]+1;
				if(v[nx][ny]!=v1[nx][ny])
					q.push(nx*N+ny);
			}
			else if(v1[nx][ny]==-1 || v1[nx][ny]> v[x][y]+1)
			{
				v[nx][ny] = v[x][y]+1;
				q.push(nx*N+ny);
			}
		}
	}
}
