    memset(levelArr, -1, sizeof(levelArr));
    queue<int> q;
    levelArr[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int u = 0; u < MAXN; ++u) {
            if (residual[v][u] > 0 && levelArr[u] == -1) {
                levelArr[u] = levelArr[v] + 1;
                q.push(u);
            }
        }
    }
    return levelArr[t] != -1;
}

int dfs(int v, int t, int f) {
    if (v == t) return f;
    for (int &u = itArr[v]; u < MAXN; ++u) {
        if (residual[v][u] > 0 && levelArr[v] + 1 == levelArr[u]) {
            int pushed = dfs(u, t, min(f, residual[v][u]));
            if (pushed) {
                residual[v][u] -= pushed;
                residual[u][v] += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxflow(int s, int t) {
    int flow = 0;
    while (bfs(s, t)) {
        memset(itArr, 0, sizeof(itArr));
        while (true) {
            int pushed = dfs(s, t, 1 << 30);
            if (!pushed) break;
            flow += pushed;
        }
    }
    return flow;
}

