int A[12][12], B[12][12], F[12][12];
vector<vector<int> > graph;
vector<int> objects[12][12];
int monsters = 0, treasures = 0;

class Hungarian {
public:
    int solve(int leftN, vector<vector<int> >& g, int rightN) {
        vector<int> left(leftN, -1);
        vector<int> right(rightN, -1);
        vector<int> used(rightN, 0);
        int result = 0;
        for (int i = 0; i < leftN; ++i) {
            fill(used.begin(), used.end(), 0);
            if (augment(i, g, left, right, used)) ++result;
        }
        return result;
    }

private:
    bool augment(int u, vector<vector<int> >& g, vector<int>& left,
                 vector<int>& right, vector<int>& used) {
        for (int i = 0; i < (int)g[u].size(); ++i) {
            int v = g[u][i];
            if (used[v]) continue;
            used[v] = 1;
            if (right[v] == -1 || augment(right[v], g, left, right, used)) {
                left[u] = v;
                right[v] = u;
                return true;
            }
        }
        return false;
    }
};

Hungarian matcher;

void bfsDist(int sr, int sc) {
    queue<pair<int, int> > q;
