        }
    }
    for (int i = 1; i <= N; ++i)
        for (int j = 1; j <= N; ++j)
            if (F[i][j] < 0) F[i][j] = INF;
    for (int i = 1; i <= N; ++i)
        for (int j = 1; j <= N; ++j)
