const int dx[4]={0,0,-1,1};
const int dy[4]={1,-1,0,0};

char G[MAXN][MAXN], H[MAXN][MAXN];
int n, timeLim, sx, sy, S, T, tot;
int id[MAXN][MAXN], distZ[MAXN][MAXN], seen[MAXN][MAXN];
int cap[MAXV][MAXV], height[MAXV], excess[MAXV];
bool active[MAXV];
queue<int> activeQ;
int distCell[MAXN][MAXN];
struct Point { int x, y; };

inline bool valid(int x, int y) {
    if (x < 0 || y < 0 || x >= n || y >= n || seen[x][y] || G[x][y] < '0' || G[x][y] > '9') return 0;
    return 1;
}

void addEdge(int u, int v, int c) {
    cap[u][v] += c;
}

void bfsZ() {
    memset(distZ, 60, sizeof(distZ));
    memset(seen, 0, sizeof(seen));
    queue<Point> q;
    distZ[sx][sy] = 0;
    seen[sx][sy] = 1;
    q.push(Point{sx, sy});
    while (!q.empty()) {
        Point cur = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = cur.x + dx[k], ny = cur.y + dy[k];
            if (valid(nx, ny)) {
                distZ[nx][ny] = distZ[cur.x][cur.y] + 1;
                seen[nx][ny] = 1;
                q.push(Point{nx, ny});
            }
        }
    }
}

void findLinks(int tx, int ty, int node) {
    memset(seen, 0, sizeof(seen));
    memset(distCell, 60, sizeof(distCell));
    queue<Point> q;
    seen[tx][ty] = 1;
    distCell[tx][ty] = 0;
    q.push(Point{tx, ty});
    while (!q.empty()) {
        Point cur = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = cur.x + dx[k], ny = cur.y + dy[k];
            if (valid(nx, ny)) {
                distCell[nx][ny] = distCell[cur.x][cur.y] + 1;
                seen[nx][ny] = 1;
                if (distCell[nx][ny] < distZ[nx][ny]) q.push(Point{nx, ny});
            }
        }
    }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (distCell[i][j] <= timeLim && H[i][j] > '0' && H[i][j] <= '9' && distCell[i][j] <= distZ[i][j])
                addEdge(node, id[i][j] + tot, INF);
}

void enqueue(int u) {
    if (u != S && u != T && excess[u] > 0 && !active[u]) {
        active[u] = true;
        activeQ.push(u);
    }
}

void pushFlow(int u, int v) {
    int d = min(excess[u], cap[u][v]);
    cap[u][v] -= d;
    cap[v][u] += d;
    excess[u] -= d;
    excess[v] += d;
    enqueue(v);
}

void relabel(int u) {
    int mn = INF;
    for (int v = 0; v < MAXV; ++v)
        if (cap[u][v] > 0) mn = min(mn, height[v]);
    height[u] = mn + 1;
}

void discharge(int u) {
    while (excess[u] > 0) {
        bool pushed = false;
        for (int v = 0; v < MAXV; ++v) {
            if (cap[u][v] > 0 && height[u] == height[v] + 1) {
                pushFlow(u, v);
                pushed = true;
                if (excess[u] == 0) break;
            }
        }
        if (!pushed) relabel(u);
    }
}

int maxflow() {
    memset(height, 0, sizeof(height));
    memset(excess, 0, sizeof(excess));
    memset(active, 0, sizeof(active));
    while (!activeQ.empty()) activeQ.pop();

    height[S] = MAXV;
    for (int v = 0; v < MAXV; ++v) {
        if (cap[S][v] > 0) {
            int d = cap[S][v];
            cap[S][v] = 0;
            cap[v][S] += d;
            excess[v] += d;
            excess[S] -= d;
            enqueue(v);
        }
    }

    while (!activeQ.empty()) {
        int u = activeQ.front();
        activeQ.pop();
        active[u] = false;
        discharge(u);
    }

    return excess[T];
}

