struct Dinic {
    struct Edge { int to, rev; ll cap; };
    vector<vector<Edge>> g;
    vector<int> level, ptr;
    int s, t;

    Dinic(int n, int s, int t) : g(n), level(n), ptr(n), s(s), t(t) {}

    void addEdge(int u, int v, ll cap) {
        Edge a = {v, (int)g[v].size(), cap};
        Edge b = {u, (int)g[u].size(), 0};
        g[u].push_back(a);
        g[v].push_back(b);
    }

    bool bfs() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (const Edge &e : g[u]) {
                if (level[e.to] == -1 && e.cap > 0) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                    if (e.to == t) return true;
                }
            }
        }
        return false;
    }

    ll dfs(int u, ll f) {
        if (f == 0) return 0;
        if (u == t) return f;
        for (int &i = ptr[u]; i < (int)g[u].size(); ++i) {
            Edge &e = g[u][i];
            if (level[e.to] != level[u] + 1 || e.cap == 0) continue;
            ll pushed = dfs(e.to, min(f, e.cap));
            if (pushed) {
                e.cap -= pushed;
                g[e.to][e.rev].cap += pushed;
                return pushed;
            }
        }
        return 0;
    }

    ll maxflow() {
        ll ans = 0;
        while (bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (ll pushed = dfs(s, INF)) ans += pushed;
        }
        return ans;
    }
};

