int main() {
    int i, j, k, l;
    Cell temp, temp1;

    scanf("%d %d", &n, &limit);

    for (i = 0; i <= n; i++) {
        for (j = 0; j <= n; j++) {
            distA[i][j] = INF;
        }
    }

    for (i = 0; i < n; i++) {
        scanf("%s", gridA[i]);
    }

    for (i = 0; i < n; i++) {
        scanf("%s", gridB[i]);
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (gridA[i][j] == 'Z') {
                temp.x = i;
                temp.y = j;
                bfsFrom(temp);
            }
        }
    }

    int marker = 1;
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (isdigit(gridB[i][j])) {
                k = gridB[i][j] - '0';
                if (k > 0) caps[i][j].active = 1;
                caps[i][j].count = k;
                for (l = 1; l <= k; l++) {
                    caps[i][j].ids[l] = marker++;
                }
            }
        }
    }

    marker = 1;
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (isdigit(gridA[i][j])) {
                k = gridA[i][j] - '0';
                for (l = 1; l <= k; l++) {
                    temp.x = i; temp.y = j; temp.id = marker++;
                    bfsTo(temp);
                }
            }
        }
    }

    printf("%d\n", maxMatching(marker - 1));
    return 0;
}

bool findPath(int u) {
    if (visited[u]) return false;
    visited[u] = 1;
    for (int i = 0; i < (int)adj[u].size(); i++) {
        int v = adj[u][i];
        if (leftMatch[v] == -1) {
            leftMatch[v] = u;
            rightMatch[u] = i;
            return true;
        } else if (findPath(leftMatch[v])) {
            leftMatch[v] = u;
            rightMatch[u] = i;
            return true;
        }
    }
    return false;
}

int maxMatching(int nodes) {
    memset(leftMatch, -1, sizeof(leftMatch));
    memset(rightMatch, -1, sizeof(rightMatch));
    int done;
    do {
        done = 1;
        memset(visited, 0, sizeof(visited));
        for (int i = 1; i <= nodes; i++) {
            if (rightMatch[i] == -1 && findPath(i)) done = 0;
        }
    } while (!done);
    int cnt = 0;
    for (int i = 1; i <= nodes; i++) {
        if (rightMatch[i] != -1) cnt++;
    }
    return cnt;
}

void bfsTo(Cell start) {
    int i, j, k, l;
    Cell temp, temp1;
    for (i = 0; i <= n; i++) {
        for (j = 0; j <= n; j++) {
            distB[i][j] = INF;
        }
