#include <bits/stdc++.h>
using namespace std;

struct P {
    int r, c;
    P(int _r = 0, int _c = 0) : r(_r), c(_c) {}
};

int N, T;
vector<string> B;
vector<vector<int> > D1, D2;
const int dr[4] = {-1, 0, 0, 1};
const int dc[4] = {0, -1, 1, 0};

void bfs_z(const P& src) {
    D1.assign(N + 2, vector<int>(N + 2, -1));
    queue<P> q;
    D1[src.r][src.c] = 0;
    q.push(src);
    while (!q.empty()) {
        P u = q.front();
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nr = u.r + dr[k], nc = u.c + dc[k];
            if (B[nr][nc] != '.') continue;
            if (D1[nr][nc] != -1) continue;
            D1[nr][nc] = D1[u.r][u.c] + 1;
            q.push(P(nr, nc));
        }
    }
}

void bfs_src(const P& src) {
    D2.assign(N + 2, vector<int>(N + 2, -1));
    queue<P> q;
    D2[src.r][src.c] = 0;
    q.push(src);
    while (!q.empty()) {
        P u = q.front();
        q.pop();
        if (D1[u.r][u.c] >= 0 && D2[u.r][u.c] >= D1[u.r][u.c]) continue;
        for (int k = 0; k < 4; ++k) {
            int nr = u.r + dr[k], nc = u.c + dc[k];
            if (B[nr][nc] != '.') continue;
            if (D2[nr][nc] != -1) continue;
            if (D1[nr][nc] >= 0 && D1[nr][nc] < D2[u.r][u.c] + 1) continue;
            D2[nr][nc] = D2[u.r][u.c] + 1;
            q.push(P(nr, nc));
        }
    }
}

int edmonds_karp(int s, int t, vector<vector<int> > cap) {
    int n = (int)cap.size();
    int flow = 0;
    while (true) {
        vector<int> parent(n, -1);
        queue<int> q;
        parent[s] = s;
        q.push(s);
        while (!q.empty() && parent[t] == -1) {
            int u = q.front();
            q.pop();
            for (int v = 0; v < n; ++v) {
                if (parent[v] == -1 && cap[u][v] > 0) {
                    parent[v] = u;
                    q.push(v);
                }
            }
        }
        if (parent[t] == -1) break;
        int add = INT_MAX;
