#include <bits/stdc++.h>
using namespace std;

const int N = 12;
const int INF = 1000000009;
const int dx[4] = {0, 1, 0, -1};
const int dy[4] = {1, 0, -1, 0};

int n, t;
char a[N * N], b[N * N]; // flattened grids
int sx, sy;
int dist[N * N];

inline int id(int x, int y) { return x * n + y; }
inline bool digit(char c) { return c >= '0' && c <= '9'; }

void bfsDist(int start) {
    fill(dist, dist + n * n, INF);
    bool vis[N * N] = {};
    queue<int> q;
    vis[start] = true;
    dist[start] = 0;
    q.push(start);
    while (!q.empty()) {
        int cur = q.front(); q.pop();
        int x = cur / n, y = cur % n;
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                int nid = id(nx, ny);
                if (!vis[nid] && digit(a[nid])) {
                    vis[nid] = true;
                    dist[nid] = dist[cur] + 1;
                    q.push(nid);
                }
            }
        }
    }
}

const int STATES = N * N * N * N;
bool dp[72][STATES];
bool reachable[STATES];

void solve() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i) {
        scanf(" %s", a + i * n); // read row into flattened array
    }
    for (int i = 0; i < n; ++i) {
        scanf(" %s", b + i * n);
    }
    scanf("%d%d", &sx, &sy);
    for (int i = 0; i < n * n; ++i) {
        if (a[i] == 'Z') {
            sx = i / n;
            sy = i % n;
        }
    }
    bfsDist(id(sx, sy));

    // Initialize dp[0]
    for (int i = 0; i < n * n; ++i) {
        if (digit(a[i])) {
            int state = (i * n * n) + i; // (sx,sy,x,y) all same
            dp[0][state] = true;
        }
    }

    // DP transitions
    for (int yt = 0; yt < t; ++yt) {
        for (int state = 0; state < STATES; ++state) {
            if (!dp[yt][state]) continue;
            int s = state / (n * n);
            int x = (state % (n * n)) / n;
            int y = (state % (n * n)) % n;
            if (dist[id(x, y)] <= yt) continue;
            for (int k = 0; k < 4; ++k) {
                int nx = x + dx[k], ny = y + dy[k];
                if (nx >= 0 && nx < n && ny >= 0 && ny < n && digit(a[id(nx, ny)]) && dist[id(nx, ny)] >= yt + 1) {
                    int nstate = s * n * n + id(nx, ny);
                    dp[yt + 1][nstate] = true;
                }
            }
        }
    }

    // Build reachable
    for (int yt = 0; yt <= t; ++yt)
        for (int s = 0; s < STATES; ++s)
            if (dp[yt][s])
                reachable[s] = true;

    // Max flow graph
    int V = 2 * n * n + 2;
    int cap[V][V] = {};
    // Source to first layer
    for (int i = 0; i < n * n; ++i) {
        if (digit(a[i]))
            cap[0][i + 1] = a[i] - '0';
    }
    // Second layer to sink
    for (int i = 0; i < n * n; ++i) {
        if (digit(b[i]))
            cap[n * n + i + 1][2 * n * n + 1] = b[i] - '0';
    }
    // Between layers
    for (int i = 0; i < n * n; ++i) {
        if (!digit(a[i])) continue;
        for (int j = 0; j < n * n; ++j) {
            if (!digit(a[j])) continue;
            if (reachable[i * n * n + j])
                cap[i + 1][n * n + j + 1] = INF;
        }
    }

    // Ford-Fulkerson with BFS
    int parent[V];
    bool vis[V];
    while (true) {
        memset(vis, 0, sizeof(vis));
        memset(parent, 0, sizeof(parent));
        queue<int> q;
        vis[0] = true;
        q.push(0);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            if (v == 2 * n * n + 1) break;
            for (int u = 0; u < V; ++u) {
                if (cap[v][u] > 0 && !vis[u]) {
                    vis[u] = true;
                    parent[u] = v;
                    q.push(u);
                }
            }
        }
        if (!vis[2 * n * n + 1]) break;
        int flow = INF;
        for (int v = 2 * n * n + 1; v; v = parent[v])
            flow = min(flow, cap[parent[v]][v]);
        for (int v = 2 * n * n + 1; v; v = parent[v]) {
            cap[parent[v]][v] -= flow;
            cap[v][parent[v]] += flow;
        }
    }

    int ans = 0;
    for (int i = 0; i < V; ++i)
        ans += cap[i][0];
    printf("%d\n", ans);
}

int main() {
    solve();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 12;
const int INF = 1000000009;
const int dx[4] = {0, 1, 0, -1};
const int dy[4] = {1, 0, -1, 0};

int n, t;
char a[N][N], b[N][N];
int sx, sy;
int dist[N][N];

void computeDist() {
    for (int i = 0; i < n; ++i)
        fill(dist[i], dist[i] + n, INF);
    bool seen[N][N] = {};
    queue<pair<int,int>> q;
    seen[sx][sy] = true;
    dist[sx][sy] = 0;
    q.emplace(sx, sy);
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !seen[nx][ny] && isdigit(a[nx][ny])) {
                seen[nx][ny] = true;
                dist[nx][ny] = dist[x][y] + 1;
                q.emplace(nx, ny);
            }
        }
    }
}

bool reachable[N][N][N][N];
int cap[2 * N * N + 2][2 * N * N + 2];
int parent[2 * N * N + 2];
bool vis[2 * N * N + 2];

bool augment() {
    memset(vis, 0, sizeof(vis));
    memset(parent, 0, sizeof(parent));
    queue<int> q;
    vis[0] = true;
    q.push(0);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        if (v == 2 * n * n + 1) return true;
        for (int u = 0; u <= 2 * n * n + 1; ++u) {
            if (cap[v][u] > 0 && !vis[u]) {
                vis[u] = true;
                parent[u] = v;
                q.push(u);
            }
        }
    }
    return false;
}

void solve() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i) scanf(" %s", a[i]);
    for (int i = 0; i < n; ++i) scanf(" %s", b[i]);
    scanf("%d%d", &sx, &sy);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (a[i][j] == 'Z') { sx = i; sy = j; }
    computeDist();

    // Use queue for DP propagation
    queue<tuple<int,int,int,int,int>> q; // (yt, sx, sy, x, y)
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(a[i][j]))
                q.emplace(0, i, j, i, j);

    while (!q.empty()) {
        auto [yt, s1, s2, x, y] = q.front(); q.pop();
        if (reachable[s1][s2][x][y]) continue; // already processed at this or earlier yt? Actually we need to allow multiple yt? We'll use a visited array per yt? Simpler: we store in reachable and also process all yt up to t. But we need to ensure we don't miss states with larger yt. We'll use a 5D visited? Instead, we'll use a queue that processes each state once per yt, but we can just use the DP array as before but with queue. Let's do a queue for each yt: we'll store states in a vector per yt.
    }

    // Actually easier: use DP array but populate via queue for each time step.
    bool dp[72][N][N][N][N] = {};
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(a[i][j]))
                dp[0][i][j][i][j] = true;

    for (int yt = 0; yt < t; ++yt) {
        // Collect all states at time yt into a queue
        queue<tuple<int,int,int,int>> cur;
        for (int s1 = 0; s1 < n; ++s1)
            for (int s2 = 0; s2 < n; ++s2)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (dp[yt][s1][s2][x][y])
                            cur.emplace(s1, s2, x, y);

        while (!cur.empty()) {
            auto [s1, s2, x, y] = cur.front(); cur.pop();
            if (dist[x][y] <= yt) continue;
            for (int k = 0; k < 4; ++k) {
                int nx = x + dx[k], ny = y + dy[k];
                if (nx >= 0 && nx < n && ny >= 0 && ny < n && isdigit(a[nx][ny]) && dist[nx][ny] >= yt + 1) {
                    if (!dp[yt + 1][s1][s2][nx][ny]) {
                        dp[yt + 1][s1][s2][nx][ny] = true;
                    }
                }
            }
        }
    }

    for (int yt = 0; yt <= t; ++yt)
        for (int s1 = 0; s1 < n; ++s1)
            for (int s2 = 0; s2 < n; ++s2)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (dp[yt][s1][s2][x][y])
                            reachable[s1][s2][x][y] = true;

    memset(cap, 0, sizeof(cap));
    for (int x = 0; x < n; ++x)
        for (int y = 0; y < n; ++y) {
            if (isdigit(a[x][y]))
                cap[0][x * n + y + 1] = a[x][y] - '0';
            if (isdigit(b[x][y]))
                cap[n * n + x * n + y + 1][2 * n * n + 1] = b[x][y] - '0';
        }

    for (int x1 = 0; x1 < n; ++x1)
        for (int y1 = 0; y1 < n; ++y1)
            if (isdigit(a[x1][y1]))
                for (int x2 = 0; x2 < n; ++x2)
                    for (int y2 = 0; y2 < n; ++y2)
                        if (isdigit(a[x2][y2]) && reachable[x1][y1][x2][y2])
                            cap[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF;

    while (augment()) {
        int flow = INF;
        for (int v = 2 * n * n + 1; v; v = parent[v])
            flow = min(flow, cap[parent[v]][v]);
        for (int v = 2 * n * n + 1; v; v = parent[v]) {
            cap[parent[v]][v] -= flow;
            cap[v][parent[v]] += flow;
        }
    }

    int ans = 0;
    for (int i = 0; i <= 2 * n * n + 1; ++i)
        ans += cap[i][0];
    printf("%d\n", ans);
}

