void spfa() {
    int front = 0, rear = 1;
    for (int i = 1; i <= N; ++i) dist[i] = INF;
    int start = (zr-1)*n + zc;
    dist[start] = 0;
    q[0] = start;
    while (front < rear) {
        int u = q[front++];
        for (int v = 1; v <= N; ++v) {
            if (graph[u][v] == 1 && dist[v] > dist[u] + 1) {
                dist[v] = dist[u] + 1;
                q[rear++] = v;
            }
        }
    }
}

void floyd() {
    for (int k = 1; k <= N; ++k) {
        for (int i = 1; i <= N; ++i) {
            if (graph[i][k] == -1) continue;
            for (int j = 1; j <= N; ++j) {
                if (graph[k][j] == -1) continue;
                if (graph[i][j] == -1 || graph[i][j] > graph[i][k] + graph[k][j])
                    graph[i][j] = graph[i][k] + graph[k][j];
            }
        }
    }
}

