bool make_level_graph(int src, int sink) {
    memset(level, -1, sizeof(level));
    queue<int> q;
    level[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v=0; v<=sink; ++v) {
            if (level[v] == -1 && cap[u][v] > 0) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[sink] != -1;
}

