    for (int i = 1; i <= n; ++i) {
        char s[15];
        scanf("%s", s + 1);
        for (int j = 1; j <= n; ++j) {
            if (isdigit(s[j]))
                sci[i][j] = s[j] - '0';
            else if (s[j] == 'Y')
                maze[0][i][j] = 1;
            else if (s[j] == 'Z')
                maze[0][i][j] = 2;
        }
    }
    for (int i = 1; i <= n; ++i) {
        char s[15];
        scanf("%s", s + 1);
        for (int j = 1; j <= n; ++j) {
            if (isdigit(s[j]))
                cap[i][j] = s[j] - '0';
        }
    }
    init();
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (sci[i][j])
                addEdge(src, getId(i, j, 0), sci[i][j]);
            if (cap[i][j])
                addEdge(getId(i, j, 1), sink, cap[i][j]);
        }
    }
    for (int x = 1; x <= n; ++x)
        for (int y = 1; y <= n; ++y)
            for (int xx = 1; xx <= n; ++xx)
                for (int yy = 1; yy <= n; ++yy)
                    if (sci[x][y] && cap[xx][yy] && dp[T][x][y][xx][yy])
                        addEdge(getId(x, y, 0), getId(xx, yy, 1), INF);
    printf("%d\n", dinic(src, sink));
    return 0;
}

