    // assign node ids
    for (int time = 0; time <= t+1; ++time) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                node_id[time][i][j] = id_counter++;
            }
        }
    }
    int source = 0, sink = id_counter;
    id_counter++;

    for (int i = 1; i <= n; ++i) {
        cin >> (grid2[i] + 1);
    }

    // BFS from all 'Z' cells
    queue<pii> q;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Z') {
                q.emplace(i, j);
                dist[i][j] = 0;
            }
        }
    }
