int dx[] = {1, -1, 0, 0};

struct MaxFlow {
    struct Edge { int to, cap, rev; };
    vector<vector<Edge>> graph;
    vector<int> level, work;
    int S, T;
    MaxFlow(int V, int s, int t) : graph(V), level(V), work(V), S(s), T(t) {}
    void addEdge(int from, int to, int cap) {
        graph[from].push_back({to, cap, (int)graph[to].size()});
        graph[to].push_back({from, 0, (int)graph[from].size() - 1});
    }
    bool levelize() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(S);
        level[S] = 0;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int i = 0; i < (int)graph[v].size(); ++i) {
                Edge &e = graph[v][i];
                if (level[e.to] < 0 && e.cap > 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[T] >= 0;
    }
    int augment(int v, int f) {
        if (v == T) return f;
        for (int &i = work[v]; i < (int)graph[v].size(); ++i) {
            Edge &e = graph[v][i];
            if (level[e.to] == level[v] + 1 && e.cap > 0) {
                int ret = augment(e.to, min(f, e.cap));
                if (ret) {
                    e.cap -= ret;
                    graph[e.to][e.rev].cap += ret;
                    return ret;
                }
            }
        }
        return 0;
    }
    ll solve() {
        ll total = 0;
        while (levelize()) {
            fill(work.begin(), work.end(), 0);
            while (true) {
                int get = augment(S, 2e9);
                if (!get) break;
                total += get;
            }
        }
        return total;
    }
};

