        for (int it = 0; it < sz; ++it) {
            int pos = q.front(); q.pop();
            int y = pos / N;
            int x = pos % N;
            for (int d = 0; d < 4; ++d) {
                int ny = y + dirY[d];
                int nx = x + dirX[d];
                if (ny < 0 || ny >= N || nx < 0 || nx >= N) continue;
                if (cost[ny][nx] || grid[ny][nx] == 'Y') continue;
                cost[ny][nx] = depth;
                q.push(ny * N + nx);
            }
        }
        ++depth;
        if (depth > T) depth = T;
    }
}

