    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (!reachable(i, j, grid1)) continue;

            vector<vector<int>> cur = computeDistances(i, j, grid1);

            for (int x = 0; x < n; ++x) {
                for (int y = 0; y < n; ++y) {
                    if (!reachable(x, y, grid1) || cur[x][y] > timeLimit || cur[x][y] > toZ[x][y])
                        continue;

                    if (cur[x][y] == toZ[x][y]) {
                        bool ok = false;
                        for (int dir = 0; dir < 4; ++dir) {
                            int nx = x + mx[dir];
                            int ny = y + my[dir];
                            if (!reachable(nx, ny, grid1) || cur[nx][ny] >= toZ[nx][ny])
                                continue;
                            ok = true;
                        }
                        if (!ok) continue;
