                    for (int u = 1; u <= grid1[i][j] - '0'; ++u) {
                        for (int v = 1; v <= grid2[x][y] - '0'; ++v) {
                            adj[L + u].push_back(R + v);
                        }
                    }
                }
            }
        }
    }
}

