bool isGood(int x, int y, const vector<string>& table) {
    return x >= 0 && y >= 0 && x < (int)table.size() && y < (int)table.size() &&
           table[x][y] != 'Y' && table[x][y] != 'Z';
}

vector<vector<int>> getDist(int startX, int startY, const vector<string>& table) {
    int n = (int)table.size();
    vector<vector<int>> dist(n, vector<int>(n, INF));
    queue<pair<int,int>> q;
    dist[startX][startY] = 0;
    q.push({startX, startY});

    while (!q.empty()) {
        pair<int,int> cur = q.front();
        q.pop();

        for (int k = 0; k < 4; ++k) {
            int nx = cur.first + dX[k];
            int ny = cur.second + dY[k];

            if (!isGood(nx, ny, table) || dist[nx][ny] != INF) continue;

            dist[nx][ny] = dist[cur.first][cur.second] + 1;
            q.push({nx, ny});
        }
    }

    return dist;
}

void addEdges(const vector<string>& A, const vector<string>& B, int i, int j, int x, int y) {
    int L = 100 * i + 10 * j;
    int R = 100 * x + 10 * y;

    for (int u = 1; u <= A[i][j] - '0'; ++u) {
        for (int v = 1; v <= B[x][y] - '0'; ++v) {
            adj[L + u].push_back(R + v);
        }
    }
}

signed main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    cout.precision(10);

