    cin >> n >> t;

    vector<string> A(n), B(n);
    for (int i = 0; i < n; ++i) cin >> A[i];
    for (int i = 0; i < n; ++i) cin >> B[i];

    int zx = 0, zy = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (A[i][j] == 'Z') zx = i, zy = j;

    vector<vector<int>> toReactor = getDist(zx, zy, A);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (!isGood(i, j, A)) continue;

            vector<vector<int>> fromStart = getDist(i, j, A);

            for (int x = 0; x < n; ++x) {
                for (int y = 0; y < n; ++y) {
                    if (!isGood(x, y, A) || fromStart[x][y] > t || fromStart[x][y] > toReactor[x][y])
                        continue;

                    if (fromStart[x][y] == toReactor[x][y]) {
                        bool better = false;
                        for (int d = 0; d < 4; ++d) {
                            int nx = x + dX[d];
                            int ny = y + dY[d];
                            if (!isGood(nx, ny, A) || fromStart[nx][ny] >= toReactor[nx][ny])
                                continue;
                            better = true;
                        }
                        if (!better) continue;
                    }

                    addEdges(A, B, i, j, x, y);
                }
            }
        }
    }

    std::function<bool(int)> augment;
    augment = [&](int v) -> bool {
        if (seen[v]) return false;
        seen[v] = true;

        for (int to : adj[v]) {
            if (matched[to] == 0 || augment(matched[to])) {
                matched[to] = v;
                return true;
            }
        }

        return false;
    };

    for (int i = 0; i < MAXN; ++i) {
        augment(i);
        fill(seen, seen + MAXN, false);
    }

    int result = 0;
    for (int i = 0; i < MAXN; ++i) result += (matched[i] != 0);

    cout << result;
    return 0;
}

