bool bfsHK() {
    deque<int> q;
    for (int i = 1; i <= leftCnt; ++i) {
        if (match[i] == 0) {
            dist[i] = 0;
            q.push_back(i);
        } else {
            dist[i] = 3010;
        }
    }
    dist[0] = 3010;
    while (!q.empty()) {
        int u = q.front();
        q.pop_front();
        if (dist[u] < dist[0]) {
            for (int v : adj[u]) {
                int w = match[v];
                if (dist[w] > dist[u] + 1) {
                    dist[w] = dist[u] + 1;
                    q.push_back(w);
                }
            }
        }
    }
    return dist[0] != 3010;
}

bool dfsHK(int x) {
    if (x == 0) return true;
    for (int v : adj[x]) {
        int u = match[v];
        if (dist[u] == dist[x] + 1) {
            if (dfsHK(u)) {
                match[x] = v;
                match[v] = x;
                return true;
            }
        }
    }
    return false;
}

int hopcroftKarp() {
    int res = 0;
    while (bfsHK()) {
        for (int i = 1; i <= leftCnt; ++i) {
            if (match[i] == 0) {
                res += dfsHK(i);
            }
        }
    }
    return res;
}

