                flow[idx ^ 1] -= curFlow;
                return true;
            }
        }
        return false;
    }

    int getMaxFlow(int S, int T) {
        int curFlow = 1 << 30;
        int resFlow = 0;
        while (curFlow > 0) {
            if (dfs(S, T, curFlow)) {
                resFlow += curFlow;
            } else {
                curFlow >>= 1;
            }
            memset(used, false, sizeof used);
