#include <cstdio>
#include <algorithm>
#include <cstdlib>
#include <cstring>
#include <queue>

using namespace std;

struct Cell { int r,c,dis; };

const int dr[4] = {-1,0,1,0};
const int dc[4] = {0,-1,0,1};

queue<Cell> bfsQueue;
char s[20];

int n, n1, m, lim, pathLen, bottleneck, sink;
int sourceNode[12][12], sinkNode[12][12], zDist[12][12];
int cap[205][205], flo[205][205], pathNodes[205], height[205], heightCnt[203];
bool alive, found, passable[12][12], passableCopy[12][12];

void dfsAugment(int x, int limit)
{
    if (x == sink)
    {
        bottleneck = limit;
        found = true;
        return;
    }
    int bestHeight = n + 2;
    for (int y = 0; y <= n + 1; ++y)
    {
        if (flo[x][y] < cap[x][y])
        {
            bestHeight = min(bestHeight, height[y]);
            if (height[x] == height[y] + 1)
            {
                pathNodes[++pathLen] = y;
                dfsAugment(y, min(limit, cap[x][y] - flo[x][y]));
                if ((!alive) || found)
                    return;
                pathNodes[pathLen--] = 0;
            }
        }
        if (flo[y][x] > 0)
        {
            bestHeight = min(bestHeight, height[y]);
            if (height[x] == height[y] + 1)
            {
                pathNodes[++pathLen] = -y;
                dfsAugment(y, min(limit, flo[y][x]));
                if ((!alive) || found)
                    return;
                pathNodes[pathLen--] = 0;
            }
        }
    }
    if (bestHeight + 1 != height[x])
    {
        --heightCnt[height[x]];
        if (heightCnt[height[x]] == 0)
            alive = false;
        height[x] = bestHeight + 1;
        ++heightCnt[height[x]];
    }
}

bool tryAugment()
{
    found = false;
    bottleneck = n1;
    pathLen = 0;
    pathNodes[0] = 0;
    dfsAugment(0, n1);
    return found;
}

void improve()
{
    for (int x = 1; x <= pathLen; ++x)
    {
        if (pathNodes[x] > 0)
            flo[abs(pathNodes[x-1])][pathNodes[x]] += bottleneck;
        else
            flo[-pathNodes[x]][abs(pathNodes[x-1])] -= bottleneck;
    }
}

void readSrcGrid()
{
    for (int i = 1; i <= m; ++i)
    {
        scanf("%s", s + 1);
        for (int j = 1; j <= m; ++j)
        {
            if (s[j] == 'Z')
            {
                Cell c;
                c.r = i;
                c.c = j;
                c.dis = 0;
                bfsQueue.push(c);
            }
            else if (s[j] != 'Y')
            {
                passable[i][j] = true;
                zDist[i][j] = lim;
                int k = s[j] - '0';
                if (k > 0)
                {
                    sourceNode[i][j] = ++n;
                    cap[0][n] = k;
                    n1 += k;
                }
            }
        }
    }
    memcpy(passableCopy, passable, sizeof(passable));
}

void readDstGrid()
{
    for (int i = 1; i <= m; ++i)
    {
        scanf("%s", s + 1);
        for (int j = 1; j <= m; ++j)
        {
            if (s[j] == 'Z' || s[j] == 'Y')
                continue;
            int k = s[j] - '0';
            if (k > 0)
            {
                sinkNode[i][j] = ++n;
                cap[n][m * m + 1] = k;
            }
        }
    }
    if (n != m * m)
    {
        for (int i = 1; i <= m; ++i)
            for (int j = 1; j <= m; ++j)
                if (sinkNode[i][j] > 0)
                {
                    int v = sinkNode[i][j];
                    cap[v][n + 1] = cap[v][m * m + 1];
                    cap[v][m * m + 1] = 0;
                }
    }
    sink = n + 1;
}

void computeZDist()
{
    while (!bfsQueue.empty())
    {
        Cell cur = bfsQueue.front();
        bfsQueue.pop();
        int i = cur.r, j = cur.c;
        zDist[i][j] = cur.dis;
        for (int d = 0; d < 4; ++d)
        {
            int ni = i + dr[d], nj = j + dc[d];
            if (passable[ni][nj])
            {
                passable[ni][nj] = false;
                Cell nxt;
                nxt.r = ni;
                nxt.c = nj;
                nxt.dis = cur.dis + 1;
                bfsQueue.push(nxt);
            }
        }
    }
}

void buildGraph()
{
    for (int i = 1; i <= m; ++i)
    {
        for (int j = 1; j <= m; ++j)
        {
            if (sourceNode[i][j] == 0)
                continue;
            memcpy(passable, passableCopy, sizeof(passableCopy));
            passable[i][j] = false;
            Cell start;
            start.r = i;
            start.c = j;
            start.dis = 0;
            bfsQueue.push(start);
            while (!bfsQueue.empty())
            {
                Cell cur = bfsQueue.front();
                bfsQueue.pop();
                int x = cur.r, y = cur.c;
                if (sinkNode[x][y] > 0 && cur.dis <= zDist[x][y])
                    cap[sourceNode[i][j]][sinkNode[x][y]] = n1;
                if (cur.dis + 1 > lim || cur.dis >= zDist[x][y])
                    continue;
                for (int d = 0; d < 4; ++d)
                {
                    int nx = x + dr[d], ny = y + dc[d];
                    if (passable[nx][ny])
                    {
                        passable[nx][ny] = false;
                        Cell nxt;
                        nxt.r = nx;
                        nxt.c = ny;
                        nxt.dis = cur.dis + 1;
                        bfsQueue.push(nxt);
                    }
                }
            }
        }
    }
}

int main()
{
    scanf("%d %d", &m, &lim);
    memset(cap, 0, sizeof(cap));
    memset(flo, 0, sizeof(flo));
    memset(sourceNode, 0, sizeof(sourceNode));
    memset(sinkNode, 0, sizeof(sinkNode));
    memset(passable, 0, sizeof(passable));
    memset(zDist, 0, sizeof(zDist));
    memset(height, 0, sizeof(height));
    memset(heightCnt, 0, sizeof(heightCnt));

    readSrcGrid();
    readDstGrid();
    computeZDist();
    buildGraph();

    heightCnt[0] = n + 2;
    alive = true;
    while (alive && height[0] <= n + 2)
        while (tryAugment())
            improve();

    int ans = 0;
    for (int i = 1; i <= n; ++i)
        ans += flo[i][sink];
    printf("%d\n", ans);
    return 0;
}

