bool bfsLevels()
{
    memset(level, -1, sizeof(level));
    queue<int> qq;
    level[0] = 0;
    qq.push(0);
    while (!qq.empty())
    {
        int u = qq.front();
        qq.pop();
        for (int v = 0; v <= sinkNode; ++v)
        {
            if (level[v] < 0 && residual[u][v] > 0)
            {
                level[v] = level[u] + 1;
                qq.push(v);
            }
        }
    }
    return level[sinkNode] >= 0;
}

int dfsSend(int u, int pushed)
{
    if (u == sinkNode)
        return pushed;
    for (int &v = ptr[u]; v <= sinkNode; ++v)
    {
        if (residual[u][v] > 0 && level[v] == level[u] + 1)
        {
            int tr = dfsSend(v, min(pushed, residual[u][v]));
            if (tr > 0)
            {
                residual[u][v] -= tr;
                residual[v][u] += tr;
                return tr;
            }
        }
    }
    return 0;
}

