template<int N>
struct Flow {
    int head[N], tot, cur[N], d[N], u, v, s, t, src, sink;

    struct Edge {
        int v, nxt, cap;
    } E[111111];

    void add(int u, int v, int cap) {
        E[tot] = {v, head[u], cap};
        head[u] = tot++;
        E[tot] = {u, head[v], 0};
        head[v] = tot++;
    }

    void init() {
        memset(head, -1, sizeof head);
        tot = 0;
    }

    bool bfs() {
        memset(d, -1, sizeof d);
        memcpy(cur, head, sizeof head);
        d[src] = 0;
        queue<int> Q;
        Q.push(src);
        while (!Q.empty()) {
            u = Q.front(); Q.pop();
            for (int i = head[u]; ~i; i = E[i].nxt) {
                v = E[i].v;
                if (d[v] == -1 && E[i].cap) {
                    d[v] = d[u] + 1;
                    Q.push(v);
                }
            }
        }
        return d[sink] != -1;
    }

    int dfs(int u, int in) {
        if (u == sink) return in;
        int flow = 0, f;
        for (int &i = cur[u]; ~i; i = E[i].nxt) {
            v = E[i].v;
            if (d[v] == d[u] + 1 && E[i].cap) {
                f = dfs(v, min(in - flow, E[i].cap));
                if (f) {
                    flow += f;
                    E[i].cap -= f;
                    E[i ^ 1].cap += f;
                    if (flow == in) break;
                }
            }
        }
        if (flow < in) d[u] = -1;
        return flow;
    }

    const int inf = 1e9;
    int dinic(int _src, int _sink) {
        src = _src, sink = _sink;
        int flow = 0;
        while (bfs())
            flow += dfs(src, inf);
        return flow;
    }
};

