struct ScalingMaxFlow {
    struct Edge {
        int to, rev, cap;
    };

    int N;
    vector<vector<Edge>> g;

    ScalingMaxFlow(int n) : N(n), g(n) {}

    void add_edge(int v, int to, int cap) {
        Edge a{to, (int)g[to].size(), cap};
        Edge b{v, (int)g[v].size(), 0};
        g[v].push_back(a);
        g[to].push_back(b);
    }

    bool bfs(int s, int t, int delta, vector<int> &parent_node,
             vector<int> &parent_edge) {
        parent_node.assign(N, -1);
        parent_edge.assign(N, -1);

        queue<int> q;
        parent_node[s] = s;
        q.push(s);

        while (!q.empty()) {
            int v = q.front();
            q.pop();

            for (int i = 0; i < (int)g[v].size(); i++) {
                Edge &e = g[v][i];

                if (e.cap >= delta && parent_node[e.to] == -1) {
                    parent_node[e.to] = v;
                    parent_edge[e.to] = i;

                    if (e.to == t) return true;

                    q.push(e.to);
                }
            }
        }

        return parent_node[t] != -1;
    }

    int max_flow(int s, int t) {
        int total = 0;
        int biggest = 0;

        for (const Edge &e : g[s]) {
            biggest = max(biggest, e.cap);
        }

        int delta = 1;
        while ((delta << 1) <= biggest) delta <<= 1;

        for (; delta > 0; delta >>= 1) {
            while (true) {
                vector<int> parent_node, parent_edge;

                if (!bfs(s, t, delta, parent_node, parent_edge)) break;

                int aug = INT_MAX;

                for (int v = t; v != s; v = parent_node[v]) {
                    aug = min(aug, g[parent_node[v]][parent_edge[v]].cap);
                }

                for (int v = t; v != s; v = parent_node[v]) {
                    Edge &e = g[parent_node[v]][parent_edge[v]];
                    e.cap -= aug;
                    g[v][e.rev].cap += aug;
                }

                total += aug;
            }
        }

        return total;
    }
};

