int pre[MAXN], vis[MAXN];

bool findPath() {
    memset(vis, 0, sizeof(vis));
    queue<int> q;
    vis[S] = 1;
    q.push(S);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int e = head[u]; e != -1; e = edges[e].nxt) {
            int v = edges[e].to;
            if (edges[e].cap > 0 && !vis[v]) {
                pre[v] = e;
                if (v == T) return true;
                vis[v] = 1;
                q.push(v);
            }
        }
    }
    return false;
}

int maxFlow() {
    int ans = 0;
    while (findPath()) {
        int add = 10000000;
        for (int v = T; v != S; ) {
            int e = pre[v];
            add = min(add, edges[e].cap);
            v = edges[e ^ 1].to;
        }
        for (int v = T; v != S; ) {
            int e = pre[v];
            edges[e].cap -= add;
            edges[e ^ 1].cap += add;
            v = edges[e ^ 1].to;
        }
        ans += add;
    }
    return ans;
}

