    int bestNum;
    int bestDen;
    double bestDiff;

    BestFractionFinder(int px, int py, double pEps)
        : x(px), y(py), target((double)px / (double)py), eps(pEps),
          bestNum(px), bestDen(py), bestDiff(1000000.0) {}

    void consider(int i) {
        double scaled = (double)x * i / (double)y;
        double low = floor(scaled);
        double high = ceil(scaled);

        double diffLow = abs(low / i - target);
        double diffHigh = abs(high / i - target);

        double chosenValue;
        double chosenDiff;

        if (diffHigh == diffLow) {
            chosenValue = low;
            chosenDiff = diffLow;
        } else if (diffHigh < diffLow) {
            chosenValue = high;
            chosenDiff = diffHigh;
        } else {
            chosenValue = low;
            chosenDiff = diffLow;
        }

        if (chosenDiff < bestDiff - eps) {
            bestNum = (int)chosenValue;
            bestDen = i;
            bestDiff = chosenDiff;
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int x, y, nn;
    cin >> x >> y >> nn;

    BestFractionFinder finder(x, y, 0.000000000000001);

    for (int i = 1; i <= nn; ++i) {
        finder.consider(i);
    }

    cout << finder.bestNum << "/" << finder.bestDen;
    return 0;
}

