using namespace std;

void simplify(long long &num, long long &den)
{
    long long p, q, r;
    if (num > den) { p = num; q = den; }
    else { p = den; q = num; }

    if (q == 0) return;

    while (q != 0)
    {
        r = p % q;
        p = q;
        q = r;
    }

    num /= p;
    den /= p;
}

int main()
{
