    while (cin >> x >> y >> n)
    {
        long long a, b;

        if (y <= n)
        {
            a = x;
            b = y;
        }
        else
        {
            float min = 1.0f;
            float mi;

            for (long long i = 1; i <= n; i++)
            {
                long long k = i * x / y;

                mi = (float)((double)x / y - (double)k / i);
                if (mi < min)
                {
                    min = mi;
                    a = k;
                    b = i;
                }

                mi = (float)((double)(k + 1) / i - (double)x / y);
                if (mi < min)
                {
                    min = mi;
                    a = k + 1;
                    b = i;
                }
            }
        }

        simplify(a, b);
        cout << a << "/" << b << endl;
    }

    return 0;
}

