    long long x, y, limit;
    while (cin >> x >> y >> limit)
    {
        long long num, den, greater, smaller, rest = 1, floor_val;
        float best = 1.0f, diff;

        if (y <= limit)
        {
            num = x;
            den = y;
        }
        else
        {
            double ratio = (double)x / (double)y;

            for (long long i = 1; i <= limit; i++)
            {
                floor_val = i * x / y;

                diff = (float)(ratio - (double)floor_val / (double)i);
                if (diff < best)
                {
                    best = diff;
                    num = floor_val;
                    den = i;
                }

                diff = (float)((double)(floor_val + 1) / (double)i - ratio);
                if (diff < best)
                {
                    best = diff;
                    num = floor_val + 1;
                    den = i;
                }
            }
        }

        if (num > den) { greater = num; smaller = den; }
        else { greater = den; smaller = num; }

        if (smaller == 0)
        {
            greater = 1;
        }
        else
        {
            while (smaller != 0)
            {
                rest = greater % smaller;
                greater = smaller;
                smaller = rest;
            }
        }

        if (rest != 1)
        {
            num /= greater;
            den /= greater;
        }

        cout << num << "/" << den << endl;
