        if (d1 < t) {
            if (d1 > t - 1e-15 && d1 < t + 1e-15) {
                // skip
            } else {
                t = d1;
                a = (int)(t1 * i);
                b = i;
            }
        }
        double v2 = (double)(int)(t1 * i + 1) / i;
        double d2 = fabs(v2 - t1);
        if (d2 < t) {
            if (d2 > t - 1e-15 && d2 < t + 1e-15) {
                // skip
            } else {
                t = d2;
                a = (int)(t1 * i) + 1;
                b = i;
            }
        }
    }
    cout << a << "/" << b;
    cin.get();
    cin.get();
    return 0;
}

