    double bestA = 0.0, bestB = 0.0, bestError = 999.0;
    double b = 1.0;

    while (b <= n) {
        update((int)floor(target * b), b, target, bestA, bestB, bestError);
        update((int)ceil(target * b), b, target, bestA, bestB, bestError);
        b += 1.0;
    }

    printf("%d/%d", (int)bestA, (int)bestB);
    return 0;
}

