#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ldbl = long double;

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll x, y, n;
    cin >> x >> y >> n;

    ll g = gcd(x, y);
    x /= g;
    y /= g;
    ll q = x / y;
    ll rem = x % y;

    bool have = false;
    ldbl bestDist = 0;
    ll bestDen = 0;
    ll bestNum = 0;

    auto consider = [&](ll b, ll u, ll z, ll t, ll a)
    {
        ll gg = gcd(a, b);
        ldbl dist = ldbl(abs(u - a * z)) / t;
        ll den = b / gg;
        ll num = a / gg;

        if (!have)
        {
            have = true;
            bestDist = dist;
            bestDen = den;
            bestNum = num;
            return;
        }

        if (dist < bestDist)
        {
            bestDist = dist;
            bestDen = den;
            bestNum = num;
        }
        else if (!(bestDist < dist))
        {
            if (den < bestDen || (den == bestDen && num < bestNum))
            {
                bestDist = dist;
                bestDen = den;
                bestNum = num;
            }
        }
    };

    for (ll b = 1; b <= n; ++b)
    {
        ll gb = gcd(y, b);
        ll c = b / gb;
        ll z = y / gb;
        ll t = b * z;
        ll u = q * t + rem * c;

        consider(b, u, z, t, u / z);
        if (u % z)
            consider(b, u, z, t, (u + z - 1) / z);
    }

    cout << bestNum << '/' << bestDen;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ldbl = long double;

struct RawCandidate
{
    ll a, b, u, z, t;
};

struct CandidateCompare
{
    bool operator()(const RawCandidate& lhs, const RawCandidate& rhs) const
    {
        auto key = [](const RawCandidate& c)
        {
            ll g = gcd(c.a, c.b);
            ll den = c.b / g;
            ll num = c.a / g;
            ldbl dist = ldbl(abs(c.u - c.a * c.z)) / c.t;
            return tuple<ldbl, ll, ll>{dist, den, num};
        };

        return key(lhs) < key(rhs);
    }
};

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll x, y, n;
    cin >> x >> y >> n;

    ll g = gcd(x, y);
    x /= g;
    y /= g;
    ll q = x / y;
    ll rem = x % y;

    multiset<RawCandidate, CandidateCompare> candidates;

    auto add = [&](ll b, ll u, ll z, ll t, ll a)
    {
        candidates.insert(RawCandidate{a, b, u, z, t});
    };

    for (ll b = 1; b <= n; ++b)
    {
        ll gb = gcd(y, b);
        ll c = b / gb;
        ll z = y / gb;
        ll t = b * z;
        ll u = q * t + rem * c;

        add(b, u, z, t, u / z);
        if (u % z)
            add(b, u, z, t, (u + z - 1) / z);
    }

    auto it = candidates.begin();
    ll gg = gcd(it->a, it->b);
    cout << it->a / gg << '/' << it->b / gg;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ldbl = long double;

struct Candidate
{
    ldbl dist;
    ll den;
    ll num;
};

struct CandidateGreater
{
    bool operator()(const Candidate& a, const Candidate& b) const
    {
        if (a.dist != b.dist) return a.dist > b.dist;
        if (a.den != b.den) return a.den > b.den;
        return a.num > b.num;
    }
};

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll x, y, n;
    cin >> x >> y >> n;

    ll g = gcd(x, y);
    x /= g;
    y /= g;
    ll q = x / y;
    ll rem = x % y;

    priority_queue<Candidate, vector<Candidate>, CandidateGreater> pq;

    auto add = [&](ll b, ll u, ll z, ll t, ll a)
    {
        ll gg = gcd(a, b);
        ldbl dist = ldbl(abs(u - a * z)) / t;
        pq.push({dist, b / gg, a / gg});
    };

    for (ll b = 1; b <= n; ++b)
    {
        ll gb = gcd(y, b);
        ll c = b / gb;
        ll z = y / gb;
        ll t = b * z;
        ll u = q * t + rem * c;

        add(b, u, z, t, u / z);
        if (u % z)
            add(b, u, z, t, (u + z - 1) / z);
    }

    cout << pq.top().num << '/' << pq.top().den;
}

