frac diff_abs(frac a, frac b) {
    ll common = lcm(a.second, b.second);
    ll na = a.first * (common / a.second);
    ll nb = b.first * (common / b.second);
    ll d = na - nb;
    if (d < 0) d = -d;
    ll g = gcd(d, common);
    return {d / g, common / g};
}

int cmp_frac(frac a, frac b) {
    ll common = lcm(a.second, b.second);
    ll na = a.first * (common / a.second);
    ll nb = b.first * (common / b.second);
    if (na == nb) return 0;
    return na < nb ? -1 : 1;
}

