static inline void relax(long long &A, long long &B, long long cand_num,
                         long long cand_den, long long x, long long y) {
    long long lhs = 1LL * abs(x * cand_den - y * cand_num) * y * B;
    long long rhs = 1LL * abs(x * B - y * A) * y * cand_den;
    if (lhs < rhs) {
        A = cand_num;
        B = cand_den;
    }
}

