void solve() {
    double x, y, n;
    cin >> x >> y >> n;

    ll a, b;
    double req = x / y;
    double mn = 1e9;

    if (y <= n) {
        a = (ll)x;
        b = (ll)y;
    } else {
        for (ll deno = (ll)n; deno >= 1; --deno) {
            double z = (double)deno * req;
            ll num = rounded(z);
            double now = (double)num / (double)deno;
            double diff = std::abs(now - req);

            if (diff <= mn) {
                mn = diff;
                a = num;
                b = deno;
            }
        }
    }

    ll g = gcd(a, b);
    a /= g;
    b /= g;

    cout << a << "/" << b << "\n";
}

