                    best_den = (int)b;
                }
            }

            diff(x, y, ceil(a), b, temp_num, temp_den);
            temp = temp_num / temp_den;

            if (temp < best)
            {
                best_num = (int)ceil(a);
                best_den = (int)b;
                best = temp;
            }
            else if (temp == best)
            {
                if (ceil(a) < best_num)
                {
                    best_num = (int)ceil(a);
                    best_den = (int)b;
                }
            }
        }
    }

    reduce_fraction(best_num, best_den);
    cout << best_num << "/" << best_den << endl;

    return 0;
}

#include <iostream>
