using namespace std;

class FractionFinder
{
public:
    int findGcd(int a, int b)
    {
        int g = (a > b) ? a : b;
        while (!(a % g == 0 && b % g == 0))
        {
            g--;
        }
        return g;
    }

    void getDifference(double x, double y, double a, double b, double &num, double &den)
    {
        num = fabs(x * b - y * a);
        den = y * b;
    }

    void reduceFraction(int &num, int &den)
    {
        int g = findGcd(num, den);
        if (g != 1)
        {
            num = num / g;
            den = den / g;
        }
    }

    void run()
    {
        double x, y, n, a, b;
        double best = 1000000.0;
        int bestA = 0;
        int bestB = 0;

        cin >> x >> y >> n;

        if (n > y)
        {
            int g = findGcd((int)x, (int)y);
            if (g != 1)
            {
                x = x / g;
                y = y / g;
            }
            cout << x << "/" << y << endl;
            return;
        }

        for (b = n; b >= 1.0; b = b - 1.0)
        {
            a = (x * b) / y;

            if (floor(a) == a)
            {
                bestA = (int)a;
                bestB = (int)b;
                break;
            }

            double num, den, temp;

            getDifference(x, y, floor(a), b, num, den);
            temp = num / den;

            if (temp < best)
            {
                best = temp;
                bestA = (int)floor(a);
                bestB = (int)b;
            }
            else if (temp == best && floor(a) < bestA)
            {
                bestA = (int)floor(a);
                bestB = (int)b;
            }

            getDifference(x, y, ceil(a), b, num, den);
            temp = num / den;

            if (temp < best)
            {
                best = temp;
                bestA = (int)ceil(a);
                bestB = (int)b;
            }
            else if (temp == best && ceil(a) < bestA)
            {
                bestA = (int)ceil(a);
                bestB = (int)b;
            }
        }

        reduceFraction(bestA, bestB);
        cout << bestA << "/" << bestB << endl;
    }
};

int main()
{
    FractionFinder finder;
    finder.run();
    return 0;
}

