    {
        int g = gcdValue((int)x, (int)y);
        if (g != 1)
        {
            x = x / g;
            y = y / g;
        }
        cout << x << "/" << y << endl;
        return 0;
    }

    b = n;
    while (b >= 1.0)
    {
        a = (x * b) / y;

        if (floor(a) == a)
        {
            bestA = (int)a;
            bestB = (int)b;
            break;
        }

        tryCandidate(floor(a), b, x, y, best, bestA, bestB);
        tryCandidate(ceil(a), b, x, y, best, bestA, bestB);

        b -= 1.0;
    }

    int g = gcdValue(bestA, bestB);
    if (g != 1)
    {
        bestA = bestA / g;
        bestB = bestB / g;
    }

    cout << bestA << "/" << bestB << endl;
    return 0;
