  for (int i = 0; i <= m; ++i) { cnt_suf += suf[i].size(); sort(suf[i].begin(), suf[i].end()); }
  pos = 1; for (int c = 1; c < 10; ++c) dfs1(c);
  cout << res() << '\n';
  return 0;
}

