}

LL Cnt2, Tpow[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

int cmp(const void *a, const void *b) {
    LL x = *(LL*)a, y = *(LL*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

void DFS2(LL A, LL B) {
    if (B > n) return;
    if (check(B)) {
        for (LL i = 0; i <= 6; i++) {
            LL cur = Cnt2 + 1 - B * Tpow[i];
            cur %= Mod1;
            if (cur < 0) cur += Mod1;
            LL target = Mod1 - cur;
            LL pos = lower_bound(val[i].begin(), val[i].end(), target) - val[i].begin();
            LL add = sum[i] + cur * val[i].size() - Mod1 * (val[i].size() - pos);
            add %= Mod2;
            if (add < 0) add += Mod2;
            ans = (ans + add) % Mod2;
        }
        Cnt2 += Cnt1;
