        Cnt2++;
        LL add = Cnt2 - B;
        add %= Mod1;
        if (add < 0) add += Mod1;
        ans = (ans + add) % Mod2;
        for (LL i = !A; i <= 9; i++) DFS2(A+1, B*10+i);
