	b[i]=j;
	for (int p=i+1;p<=di;p++) b[p]=0;
	int bas=F(b,di);
	for (int p=i+1;p<=di;p++){
		b[p]=1;
		dif[p]=(F(b,di)+mo1-bas)%mo1;
		b[p]=0;
	}
	if (di-i==0){
		ans=(ans+bas)%mo2;
		//cout<<"UPD1 "<<di<<' '<<i<<' '<<j<<' '<<ans<<' '<<bas<<endl;
		return;
	}
	if (di-i==1){
		for (int p=0;p<=9;p++)
			ans=(ans+(bas+1ll*p*dif[di])%mo1)%mo2;
		//cout<<"UPD2 "<<di<<' '<<i<<' '<<j<<' '<<ans<<' '<<bas<<' '<<dif[di]<<endl;
		return;
	}
	int mid=(di+i)/2;
	*q1=*q2=0;
	dfs(i+1,mid,q1,bas);
	dfs(mid+1,di,q2,0);
	sort(q2+1,q2+*q2+1);
	int sq2=0;
	for (int i=1;i<=*q2;i++)
