#include<bits/stdc++.h>
using namespace std;

const int MOD1 = 998244353;
const int MOD2 = 1000000007;
long long N;
int dig[15], tmp[15], result;

long long make_number(int *arr, int len) {
    long long val = 0;
    for (int i = 1; i <= len; ++i)
        val = val * 10 + arr[i];
    return val;
}

long long rank_number(int *arr, int len) {
    long long total = 0;
    for (int d = 1; d <= dig[0]; ++d) {
        int lim = min(len, d);
        for (int i = 1; i <= lim; ++i) {
            int start = (i == 1) ? 1 : 0;
            for (int j = start; j < arr[i]; ++j) {
                long long left = 0, right = 0;
                for (int p = 1; p < i; ++p)
                    left = right = left * 10 + arr[p];
                left = right = left * 10 + j;
                for (int p = i + 1; p <= d; ++p) {
                    left = left * 10;
                    right = right * 10 + 9;
                }
                right = min(right, N);
                if (left <= right)
                    total += right - left + 1;
            }
        }
        if (d <= len) ++total;
    }
    return total;
}

int F(int *arr, int len) {
    long long val = make_number(arr, len);
    long long rnk = rank_number(arr, len);
    return (( -val + rnk) % MOD1 + MOD1) % MOD1;
}

int diff[15];
int q1[1000010];
int q2[1000010];
long long sum_q2[1000010];

void dfs(int t, int ed, int *q, int v) {
    if (t == ed) {
        for (int i = 0; i <= 9; ++i)
            q[++q[0]] = (v + 1LL * i * diff[t]) % MOD1;
        return;
    }
    for (int i = 0; i <= 9; ++i)
        dfs(t + 1, ed, q, (v + 1LL * i * diff[t]) % MOD1);
}

void update(int len, int pos, int val) {
    memcpy(tmp, dig, sizeof(tmp));
    tmp[pos] = val;
    for (int p = pos + 1; p <= len; ++p) tmp[p] = 0;
    int base = F(tmp, len);
    for (int p = pos + 1; p <= len; ++p) {
        tmp[p] = 1;
        diff[p] = (F(tmp, len) - base + MOD1) % MOD1;
        tmp[p] = 0;
    }
    if (len - pos == 0) {
        result = (result + base) % MOD2;
        return;
    }
    if (len - pos == 1) {
        for (int p = 0; p <= 9; ++p)
            result = (result + (base + 1LL * p * diff[len]) % MOD1) % MOD2;
        return;
    }
    int mid = (len + pos) / 2;
    q1[0] = q2[0] = 0;
    dfs(pos + 1, mid, q1, base);
    dfs(mid + 1, len, q2, 0);
    sort(q2 + 1, q2 + q2[0] + 1);
    long long sum = 0;
    for (int i = 1; i <= q2[0]; ++i)
        sum = (sum + q2[i]) % MOD2;
    for (int i = 1; i <= q1[0]; ++i) {
        int p = lower_bound(q2 + 1, q2 + q2[0] + 1, MOD1 - q1[i]) - q2;
        result = (result + sum + 1LL * q2[0] * q1[i]) % MOD2;
        result = (result + 1LL * (q2[0] - p + 1) * (MOD2 - MOD1)) % MOD2;
    }
}

int main() {
    scanf("%lld", &N);
    for (long long m = N; m; dig[++dig[0]] = m % 10, m /= 10);
    reverse(dig + 1, dig + dig[0] + 1);
    for (int len = 1; len <= dig[0]; ++len) {
        for (int i = 1; i <= len; ++i) {
            int low = (i == 1) ? 1 : 0;
            int high = (len == dig[0]) ? dig[i] - 1 : 9;
            for (int j = low; j <= high; ++j)
                if (j != dig[i]) update(len, i, j);
        }
        result = (result + F(dig, len)) % MOD2;
    }
    printf("%d\n", result);
