auto mod1_sub = [](int a, int b) -> int {
  int r = (a - b) % mod1;
  return r < 0 ? r + mod1 : r;
};

auto mod1_add = [](int a, int b) -> int {
  return (a + b) % mod1;
};

auto mod2_add = [](int a, int b) -> int {
  return (a + b) % mod2;
};

auto mod2_sub = [](int a, int b) -> int {
  int r = (a - b) % mod2;
  return r < 0 ? r + mod2 : r;
};

inline void dfs1_func(int k, int num);
