  if (k == 7) return ;
  tot ++;
  int back = mod1_sub(tot, num);
  vec[k].emplace_back(back);
  sum[k] = mod2_add(sum[k], back);
  for (int i = 0; i <= 9; i ++)
    dfs1_func(k + 1, num * 10 + i);
