const int MOD_A=998244353,MOD_B=1000000007,BIG=1000000;
vector<int> vals[7];
int sums[7];
long long N,order,result;
void generate(int num,int depth){
    ++order;
    int tmp=(order-num)%MOD_A;
    if(tmp<0) tmp+=MOD_A;
    vals[depth].push_back(tmp);
    sums[depth]=(sums[depth]+tmp)%MOD_B;
    if(depth==6) return;
    for(int d=0;d<=9;++d) generate(num*10+d,depth+1);
}
void compute(long long num){
    if(num>N) return;
    if(num*BIG+BIG-1<=N && num*BIG*10>N){
        long long cur=order;
        for(int i=0,mult=1;i<=6;++i,mult*=10){
            int sz=vals[i].size(),diff=(cur-num*mult)%MOD_A;
            if(diff<0) diff+=MOD_A;
            int pos=lower_bound(vals[i].begin(),vals[i].end(),MOD_A-diff)-vals[i].begin();
            result=(result+1LL*diff*sz+sums[i])%MOD_B;
            result=(result-1LL*(sz-pos)*MOD_A%MOD_B+MOD_B)%MOD_B;
            order+=sz;
        }
        return;
    }
    ++order;
    int diff=(order-num)%MOD_A;
    if(diff<0) diff+=MOD_A;
    result=(result+diff)%MOD_B;
    for(int d=0;d<=9;++d) compute(num*10+d);
}
