using namespace std;
const int P=998244353,Q=1000000007,R=1000000;
vector<int> A[7];
int B[7];
long long C,D,E;
void F(int G,int H){
    ++D;
    int I=(D-G)%P;
    if(I<0) I+=P;
    A[H].push_back(I);
    B[H]=(B[H]+I)%Q;
    if(H==6) return;
    for(int J=0;J<=9;++J) F(G*10+J,H+1);
}
void K(long long L){
    if(L>C) return;
    if(L*R+R-1<=C && L*R*10>C){
        long long M=D;
        for(int N=0,O=1;N<=6;++N,O*=10){
            int S=A[N].size(),T=(M-L*O)%P;
            if(T<0) T+=P;
            int U=lower_bound(A[N].begin(),A[N].end(),P-T)-A[N].begin();
            E=(E+1LL*T*S+B[N])%Q;
            E=(E-1LL*(S-U)*P%Q+Q)%Q;
            D+=S;
        }
        return;
    }
    ++D;
    int V=(D-L)%P;
    if(V<0) V+=P;
    E=(E+V)%Q;
    for(int W=0;W<=9;++W) K(L*10+W);
}
int main(){
    cin>>C;
    F(0,0);
    D=0;
    for(int X=0;X<=6;++X) sort(A[X].begin(),A[X].end());
    for(int Y=1;Y<=9;++Y) K(Y);
    cout<<E;
    return 0;
}

