            for (int oth = 1; oth <= R; ++oth) {
                int cnst = (-c * st[oth] + number + mod * mod) % mod;
                int to = lower_bound(ok[R][oth].begin(), ok[R][oth].end(), mod - cnst) - ok[R][oth].begin();
