#include<bits/stdc++.h>
using namespace std;
using ll=long long;
const int M=1000000;
const int P=998244353;
const int Q=1000000007;
ll N,counter;
vector<int> data[10];
int total[10],result,batch;
inline int normalize(ll x){
    return (x%P+P)%P;
}
void generate(int level,int number){
    counter++;
    data[level].push_back(normalize(counter-number));
    if(level==6)return;
    for(int digit=0;digit<=9;digit++){
        generate(level+1,number*10+digit);
    }
}
void process(int level,ll number){
    if(number>N)return;
    if(level>=1){
        if(number*M>N/10&&(number+1)*M-1<=N){
            int step=1;
            for(int i=0;i<=6;i++,step*=10){
                int w=normalize(counter-step*number);
                int idx=lower_bound(data[i].begin(),data[i].end(),P-w)-data[i].begin();
                result=(result+1LL*w*data[i].size()+total[i]-1LL*P*((int)data[i].size()-idx))%Q;
            }
            counter+=batch;
            return;
        }
        counter++;
        result=(result+normalize(counter-number))%Q;
    }
    for(int d=(level==0?1:0);d<=9;d++){
        process(level+1,number*10+d);
    }
}
int main(){
