    generate(0,0);
    for(int i=0;i<=6;i++){
        sort(data[i].begin(),data[i].end());
        total[i]=accumulate(data[i].begin(),data[i].end(),0LL)%Q;
    }
    batch=counter;
    counter=0;
    process(0,0);
    cout<<(result+Q)%Q<<'\n';
    return 0;
}

