int sums[10],answer,full_count;
inline int adjust(ll x){
    return ((x%MOD_A)+MOD_A)%MOD_A;
}
void first_dfs(int depth,int current){
    ++count_val;
    layers[depth].push_back(adjust(count_val-current));
    if(depth==6)return;
    for(int digit=0;digit<=9;++digit){
        first_dfs(depth+1,current*10+digit);
    }
}
void second_dfs(int depth,ll current){
    if(current>N)return;
    if(depth>=1){
        if(current*ONE_MILLION>N/10&&(current+1)*ONE_MILLION-1<=N){
            int multiplier=1;
            for(int i=0;i<=6;++i,multiplier*=10){
                int w=adjust(count_val-multiplier*current);
                int pos=lower_bound(layers[i].begin(),layers[i].end(),MOD_A-w)-layers[i].begin();
                answer=(answer+1LL*w*layers[i].size()+sums[i]-1LL*MOD_A*((int)layers[i].size()-pos))%MOD_B;
            }
            count_val+=full_count;
            return;
        }
        ++count_val;
        answer=(answer+adjust(count_val-current))%MOD_B;
    }
    for(int i=(depth==0?1:0);i<=9;++i){
        second_dfs(depth+1,current*10+i);
    }
}
