struct State {
    ll val;
    int cost;
};

void dfs(ll start, int startCost) {
    stack<State> st;
    st.push({start, startCost});
    while (!st.empty()) {
        State cur = st.top(); st.pop();
        ll v = cur.val;
        int c = cur.cost;
        if (c >= sol) continue;
