#include <vector>
using namespace std;
using ll = long long;

const ll INF = 100000000LL;
ll A[20];

struct Frame {
    int ind;
    ll n;
    ll m;
    int stage;
    ll first;
    ll second;
};

ll iterative_dfs(int root_ind, ll start) {
    vector<Frame> st;
    st.push_back({root_ind, start, 0, 0, 0, 0});
    ll result = 0;

    while (!st.empty()) {
        Frame &f = st.back();

        if (f.ind == 0) {
            result = (f.n == 0 ? 0 : INF);
            st.pop_back();
            continue;
        }

        if (f.n < 0) f.n = -f.n;

        if (f.stage == 0) {
            f.m = f.n / A[f.ind];
            ll c1 = f.n - f.m * A[f.ind];
            f.stage = 1;
            st.push_back({f.ind - 1, c1, 0, 0, 0, 0});
        } else if (f.stage == 1) {
            f.first = result;
            f.stage = 2;
            ll c2 = f.n - (f.m + 1) * A[f.ind];
            st.push_back({f.ind - 1, c2, 0, 0, 0, 0});
        } else {
            f.second = result;
            result = min(f.first + f.m * f.ind,
                         f.second + (f.m + 1) * f.ind);
            st.pop_back();
        }
    }

    return result;
}

