    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    for (int i = 1; i <= 16; ++i)
        A[i] = A[i - 1] * 10 + 1;

    cout << iterative_dfs(16, n) << '\n';
    return 0;
}

