const ll INF = 100000000LL;
const ll BIG = (1LL << 62);
ll A[20];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    for (int i = 1; i <= 16; ++i)
        A[i] = A[i - 1] * 10 + 1;

    if (n < 0) n = -n;

    unordered_map<ll, ll> cur;
    cur[n] = 0;

    for (int i = 16; i >= 1; --i) {
        unordered_map<ll, ll> nxt;

        for (const auto &kv : cur) {
            ll v = kv.first;
            ll base = kv.second;
            ll q = v / A[i];

            ll c1 = v - q * A[i];
            ll cost1 = base + q * i;
            if (i - 1 > 0 && c1 < 0) c1 = -c1;
            auto it = nxt.find(c1);
            if (it == nxt.end()) nxt.emplace(c1, cost1);
            else if (cost1 < it->second) it->second = cost1;

            ll c2 = v - (q + 1) * A[i];
            ll cost2 = base + (q + 1) * i;
            if (i - 1 > 0 && c2 < 0) c2 = -c2;
            it = nxt.find(c2);
            if (it == nxt.end()) nxt.emplace(c2, cost2);
            else if (cost2 < it->second) it->second = cost2;
        }

        cur.swap(nxt);
    }

    ll ans = BIG;
    for (const auto &kv : cur) {
        ll total = kv.second;
        if (kv.first != 0) total += INF;
        if (total < ans) ans = total;
    }

    cout << ans << '\n';
    return 0;
}

