    cin.tie(nullptr);

    ll n;
    cin >> n;

    for (int i = 1; i <= 16; ++i)
        A[i] = A[i - 1] * 10 + 1;

    ll best = BIG;
    int totalMasks = 1 << 16;

    for (int mask = 0; mask < totalMasks; ++mask) {
        ll cur = n;
        ll cost = 0;

        for (int i = 16; i >= 1; --i) {
            if (cur < 0) cur = -cur;

            ll m = cur / A[i];

            if ((mask >> (i - 1)) & 1) {
                cost += (m + 1) * i;
                cur -= (m + 1) * A[i];
            } else {
                cost += m * i;
                cur -= m * A[i];
            }
        }

        ll total = cost;
        if (cur != 0) total += INF;
        if (total < best) best = total;
    }

    cout << best << '\n';
    return 0;
}

