struct Frame
{
    ll x;
    int d;
    int phase;
    int base;
    ll rem;
    int leftResult;
};

int main()
{
    ll rep[17] = {};
    for (int i = 1; i <= 16; ++i)
        rep[i] = rep[i - 1] * 10 + 1;

    ll n;
    cin >> n;

    vector<Frame> st;
    st.reserve(64);
    st.push_back({n, 16, 0, 0, 0, 0});
    int returned = 0;

    while (!st.empty())
    {
        Frame &f = st.back();

        if (f.phase == 0)
        {
            ll q = f.x / rep[f.d];
            f.base = (int)(q * f.d);
            f.rem = f.x - q * rep[f.d];

            if (f.rem == 0)
            {
                returned = f.base;
                st.pop_back();
            }
            else
            {
                f.phase = 1;
                st.push_back({rep[f.d] - f.rem, f.d - 1, 0, 0, 0, 0});
            }
        }
        else if (f.phase == 1)
        {
            f.leftResult = returned + f.d;
            f.phase = 2;
            st.push_back({f.rem, f.d - 1, 0, 0, 0, 0});
        }
        else
        {
            returned = f.base + (f.leftResult < returned ? f.leftResult : returned);
            st.pop_back();
        }
    }

    printf("%d\n", returned);
    return 0;
}

