    if (memo.count(key)) return memo[key];
    ll k = cur / rep[d];
    ll ans = min(k * d + solve(cur - k * rep[d], d - 1),
                 (k + 1) * d + solve((k + 1) * rep[d] - cur, d - 1));
    memo[key] = ans;
    return ans;
}

