typedef long long ll;

ll rep[20];

ll rec(ll cur, int d) {
    cur = abs(cur);
    if (cur % rep[d] == 0)
        return cur / rep[d] * d;
    ll k = cur / rep[d];
    ll temp1 = k * d + rec(cur - k * rep[d], d - 1);
    ll temp2 = (k + 1) * d + rec((k + 1) * rep[d] - cur, d - 1);
    return min(temp1, temp2);
}

