struct State {
    LL n;
    LL best;
    int stage;
    LL rep, len, mult, next_rep;
};

LL solve(LL n) {
    if (n == 0) return 0;
    stack<State> st;
    st.push({n, (LL)1 << 29, 0, 0, 0, 0, 0});
    LL result = 0;
    while (!st.empty()) {
        State &s = st.top();
        if (s.stage == 0) {
            if (s.n == 0) {
                result = 0;
                st.pop();
                continue;
            }
            s.rep = 1;
            s.len = 1;
            while (s.rep <= s.n) {
                s.rep = s.rep * 10 + 1;
                ++s.len;
            }
            --s.len;
            s.rep = (s.rep - 1) / 10;
            if (s.rep == s.n) {
                result = s.len;
                st.pop();
                continue;
            }
            s.next_rep = s.rep * 10 + 1;
            s.stage = 1;
            if (s.next_rep - s.n < s.n) {
                st.push({s.next_rep - s.n, (LL)1 << 29, 0, 0, 0, 0, 0});
            } else {
                s.stage = 2;
            }
        } else if (s.stage == 1) {
            LL sub = result;
            s.best = sub + s.len + 1;
            s.stage = 2;
            s.mult = 1;
            while (s.rep * s.mult <= s.n)
                ++s.mult;
            --s.mult;
            st.push({s.n - s.rep * s.mult, (LL)1 << 29, 0, 0, 0, 0, 0});
        } else if (s.stage == 2) {
            LL sub = result;
            LL cand = sub + s.len * s.mult;
            result = min(cand, s.best);
            st.pop();
        }
    }
    return result;
}

