struct State {
    int64_t n, sign, acc, max;
    int phase; // 0 = before first branch, 1 = after first branch, 2 = after second branch
    int64_t d, ones_d;
    int64_t res1, res2;
    std::vector<int> already_in;
};

int64_t nb_digits(int64_t n) {
