    if (n == 0) return 0;
    n = n < 0 ? -n : n;
    int64_t d = nb_digits(n);
    return d + aux2(n - ones(d));
}

int64_t aux(int64_t n, int64_t sign, int64_t acc, int64_t max, std::vector<int> &already_in) {
    std::stack<State> st;
    st.push({n, sign, acc, max, 0, 0, 0, 0, 0, already_in});

    int64_t result = max;
    while (!st.empty()) {
        State &s = st.top();
        if (s.acc >= s.max) {
            st.pop();
            if (st.empty()) continue;
            State &p = st.top();
            if (p.phase == 1) {
                p.res1 = result;
                p.phase = 2;
                // prepare second branch
                s.n = p.n - 10 * p.ones_d - 1;
                s.sign = p.sign;
                s.acc = p.acc + p.d + 1;
                s.max = p.res1;
                s.phase = 0;
                s.already_in = p.already_in; // copy
                s.already_in[p.d + 1] += p.sign;
                st.push(s);
            } else if (p.phase == 2) {
                p.res2 = result;
                p.phase = 3;
                result = p.res1 < p.res2 ? p.res1 : p.res2;
                st.pop();
            }
            continue;
        }
        if (s.n == 0) {
            result = s.acc;
            st.pop();
            if (!st.empty()) {
                State &p = st.top();
                if (p.phase == 1) {
                    p.res1 = result;
                    p.phase = 2;
                    // second branch
                    State child;
                    child.n = p.n - 10 * p.ones_d - 1;
                    child.sign = p.sign;
                    child.acc = p.acc + p.d + 1;
                    child.max = p.res1;
                    child.phase = 0;
                    child.already_in = p.already_in;
                    child.already_in[p.d + 1] += p.sign;
                    st.push(child);
                } else if (p.phase == 2) {
                    p.res2 = result;
                    p.phase = 3;
                    result = p.res1 < p.res2 ? p.res1 : p.res2;
                    st.pop();
                }
            }
            continue;
        }
        if (s.n < 0) { s.n = -s.n; s.sign = -s.sign; }
        s.d = nb_digits(s.n);
        s.ones_d = ones(s.d);
        s.phase = 0;
        // first branch
        if (0 <= s.already_in[s.d] * s.sign && -10 < s.already_in[s.d] && s.already_in[s.d] < 10) {
            s.phase = 1;
            State child;
            child.n = s.n - s.ones_d;
            child.sign = s.sign;
            child.acc = s.acc + s.d;
            child.max = s.max;
            child.phase = 0;
            child.already_in = s.already_in;
            child.already_in[s.d] += s.sign;
            st.push(child);
        } else {
            // no first branch possible, go directly to second branch check
            s.phase = 2;
            continue;
        }
        // after first branch returns, result updated, then go to second branch
        // Actually we handle above via phase transitions
        // This loop handles phases
        break; // should not reach
    }
    return result;
}

