struct SearchNode {
    int64_t n, sign, acc, max;
    std::vector<int> already_in;
};

int64_t aux(int64_t n, int64_t sign, int64_t acc, int64_t max, std::vector<int>& already_in) {
    std::function<int64_t(SearchNode&)> dfs = [&dfs](SearchNode& node) -> int64_t {
        if (node.acc >= node.max) return node.max;
        if (node.n == 0) return node.acc;
        if (node.n < 0) { node.n = -node.n; node.sign = -node.sign; }
        int64_t d = nb_digits(node.n);
        int64_t ones_d = ones(d);
        int64_t res1 = node.max, res2 = node.max;

        // check second branch first (d+1)
        if (0 <= node.already_in[d+1] * node.sign && -10 < node.already_in[d+1] && node.already_in[d+1] < 10) {
            node.already_in[d+1] += node.sign;
            SearchNode child2 = {node.n - 10*ones_d - 1, node.sign, node.acc + d + 1, res1, node.already_in};
            res2 = dfs(child2);
            node.already_in[d+1] -= node.sign;
        }
        // check first branch (d)
        if (0 <= node.already_in[d] * node.sign && -10 < node.already_in[d] && node.already_in[d] < 10) {
            node.already_in[d] += node.sign;
            SearchNode child1 = {node.n - ones_d, node.sign, node.acc + d, res2, node.already_in};
            res1 = dfs(child1);
            node.already_in[d] -= node.sign;
        }
        return res1 < res2 ? res1 : res2;
    };
    SearchNode root = {n, sign, acc, max, already_in};
    return dfs(root);
}

