// Use a class to encapsulate the state
class RepunitSolver {
    std::vector<int> already_in; // mutable state
public:
    RepunitSolver() : already_in(20,0) {}
    int64_t solve(int64_t n, int64_t sign, int64_t acc, int64_t max) {
        if (acc >= max) return max;
        if (n == 0) return acc;
        if (n < 0) { n = -n; sign = -sign; }
        int64_t d = nb_digits(n);
        int64_t ones_d = ones(d);
        int64_t res1 = max, res2 = max;

        if (can_use(d, sign)) {
            already_in[d] += sign;
            res1 = solve(n - ones_d, sign, acc + d, max);
            already_in[d] -= sign;
        }
        if (can_use(d+1, sign)) {
            already_in[d+1] += sign;
            res2 = solve(n - 10*ones_d - 1, sign, acc + d + 1, res1);
            already_in[d+1] -= sign;
        }
        return std::min(res1, res2);
    }
private:
    bool can_use(int idx, int64_t sign) const {
        int v = already_in[idx];
        return (v * sign >= 0) && (v > -10) && (v < 10);
    }
};

