        n /= 10;
    }
    return digits;
}

int64_t ones(int64_t n) {
    int64_t res = 0;
    for (int i = 0; i < n; ++i)
        res = 10 * res + 1;
    return res;
}

int64_t aux2(int64_t n) {
    if (n == 0) return 0;
    n = n < 0 ? -n : n;
    int64_t d = nb_digits(n);
    return d + aux2(n - ones(d));
}

// Use a map instead of vector for already_in, but only store non-zero entries
typedef std::map<int, int> used_map;

int64_t aux_rec(int64_t n, int64_t sign, int64_t acc, int64_t max, used_map& used) {
    if (acc >= max) return max;
    if (n == 0) return acc;
    if (n < 0) { n = -n; sign = -sign; }
    int64_t d = nb_digits(n);
    int64_t ones_d = ones(d);
    int64_t res1 = max, res2 = max;

    auto check_add = [&](int idx) -> bool {
        auto it = used.find(idx);
        int v = (it == used.end()) ? 0 : it->second;
        return (v * sign >= 0) && (v > -10) && (v < 10);
    };

    if (check_add(d)) {
        used[d] += sign;
        res1 = aux_rec(n - ones_d, sign, acc + d, max, used);
        used[d] -= sign;
        if (used[d] == 0) used.erase(d);
    }
    if (check_add(d+1)) {
        used[d+1] += sign;
        res2 = aux_rec(n - 10*ones_d - 1, sign, acc + d + 1, res1, used);
        used[d+1] -= sign;
        if (used[d+1] == 0) used.erase(d+1);
    }
    return std::min(res1, res2);
}

int main(int argc, char* argv[]) {
    int64_t n;
    std::cin >> n;
    used_map used;
    std::cout << aux_rec(n, 1, 0, aux2(n), used) << std::endl;
    return 0;
}

