using namespace std;

long long calc(long long n) {
    struct Frame {
        long long value;
        int state;
        long long k;
        long long digits;
        long long left;
        long long right;
    };
    stack<Frame> st;
    st.push(Frame{n, 0, 0, 0, 0, 0});
    long long ret = 0;

    while (!st.empty()) {
        Frame &cur = st.top();
        if (cur.state == 0) {
            if (cur.value == 0) {
                ret = 0;
                st.pop();
                continue;
            }
            cur.k = 0;
            cur.digits = 0;
            while (cur.k * 10 + 1 <= cur.value) {
                cur.k = cur.k * 10 + 1;
                ++cur.digits;
            }
            cur.left = cur.digits * (cur.value / cur.k);
            cur.state = 1;
            st.push(Frame{cur.value % cur.k, 0, 0, 0, 0, 0});
        } else if (cur.state == 1) {
            cur.left += ret;
            long long other = 10 * cur.k + 1 - cur.value;
            cur.right = cur.digits + 1 + cur.digits * (other / cur.k);
            cur.state = 2;
            st.push(Frame{other % cur.k, 0, 0, 0, 0, 0});
        } else {
            cur.right += ret;
            ret = cur.left < cur.right ? cur.left : cur.right;
            st.pop();
        }
    }
    return ret;
}

