#include <stack>
#include <cstdlib>
using namespace std;

long long v;
long long cand[17];

struct Frame {
    int ind;
    long long val;
    int state;      // 0: before first child, 1: after first child, 2: after second child
    long long a1;   // floor quotient
    long long a2;   // ceil quotient
    int res1, res2; // results from children
};

int rec(int ind, long long val) {
    stack<Frame> st;
    st.push({ind, llabs(val), 0, 0, 0, 0, 0});
    int result = 0;
    while (!st.empty()) {
        Frame &f = st.top();
        if (f.ind == 0) {
            result = (int)f.val;
            st.pop();
            if (!st.empty()) {
                Frame &parent = st.top();
                if (parent.state == 0) {
                    parent.res1 = result;
                    parent.state = 1;
                } else {
                    parent.res2 = result;
                    parent.state = 2;
                }
            }
            continue;
        }
        if (f.state == 0) {
            f.a1 = f.val / cand[f.ind];
            f.a2 = f.a1 + 1;
            st.push({f.ind - 1, f.val - f.a1 * cand[f.ind], 0, 0, 0, 0, 0});
            f.state = 1;
        } else if (f.state == 1) {
            st.push({f.ind - 1, f.val - f.a2 * cand[f.ind], 0, 0, 0, 0, 0});
            f.state = 2;
        } else {
            int cost1 = (int)(f.a1 * (f.ind + 1) + f.res1);
            int cost2 = (int)(f.a2 * (f.ind + 1) + f.res2);
            result = min(cost1, cost2);
            st.pop();
            if (!st.empty()) {
                Frame &parent = st.top();
                if (parent.state == 0) {
                    parent.res1 = result;
                    parent.state = 1;
                } else {
                    parent.res2 = result;
                    parent.state = 2;
                }
            }
        }
    }
    return result;
}

