using namespace std;
typedef long long ll;
const ll INF = 1000LL * 1000 * 1000;
ll rep[18];
map<pair<ll,int>, ll> memo;

ll f(ll m, int idx) {
    if (m == 0) return 0;
    if (idx < 0) return INF; // should not happen
    auto key = make_pair(m, idx);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;
    ll q = m / rep[idx];
    ll r = m % rep[idx];
    ll base = q * (idx + 1);
    if (r == 0) {
        memo[key] = base;
        return base;
    }
    ll opt1 = idx + 1 + f(rep[idx] - r, idx - 1);
    ll opt2 = f(r, idx - 1);
    ll res = base + min(opt1, opt2);
    memo[key] = res;
    return res;
}

