integer_type n, arr[18];

integer_type compute(integer_type val, integer_type pos) {
    integer_type quotient = val / arr[pos];
    integer_type remainder = val % arr[pos];
    integer_type part = quotient * (pos + 1);
    if (remainder == 0) return part;
    integer_type left_way = compute(remainder, pos - 1);
    integer_type right_way = pos + 1 + compute(arr[pos] - remainder, pos - 1);
    return part + (left_way < right_way ? left_way : right_way);
}

