#include <iostream>
#include <vector>
#include <stack>
#include <cmath>
#include <cstdlib>
using namespace std;

int solve(long long n) {
    vector<int> dp(10000000, 0);
    stack<long long> st;
    st.push(n);
    while (!st.empty()) {
        long long cur = st.top();
        if (cur == 0) {
            st.pop();
            continue;
        }
        if (dp[cur] != 0) {
            st.pop();
            continue;
        }
        // compute the two possible next values
        long long lastdif = 1e18;
        long long x = 1;
        int i = 0;
        while (abs(x - cur) <= lastdif) {
            lastdif = abs(x - cur);
            x = x * 10 + 1;
            i++;
        }
        x /= 10;
        long long a = abs(x - cur);
        long long b = (x > cur && x / 10) ? abs(x / 10 - cur) : -1;
        // check if dependencies are computed
        bool ready = true;
        if (dp[a] == 0 && a != 0) ready = false;
        if (b != -1 && dp[b] == 0 && b != 0) ready = false;
        if (!ready) {
            if (dp[a] == 0 && a != 0) st.push(a);
            if (b != -1 && dp[b] == 0 && b != 0) st.push(b);
            continue;
        }
        // compute dp[cur]
        if (b != -1) {
            dp[cur] = min(i + dp[a], i - 1 + dp[b]);
        } else {
            dp[cur] = i + dp[a];
        }
        st.pop();
    }
    return dp[n];
}

