void precompute_repunits() {
    long long x = 1;
    while (x <= 1e18) {
        repunits.push_back(x);
        x = x * 10 + 1;
    }
}

int solve(long long n) {
    if (n == 0) return 0;
    if (memo.count(n)) return memo[n];

    // find closest repunit using binary search
    auto it = lower_bound(repunits.begin(), repunits.end(), n);
    long long x;
    int i;
    if (it == repunits.end()) {
        x = repunits.back();
        i = repunits.size() - 1;
    } else {
        x = *it;
        i = it - repunits.begin();
    }
    // check if previous repunit is closer
    if (it != repunits.begin()) {
        long long prev = *(it - 1);
        int prev_i = i - 1;
        if (abs(prev - n) < abs(x - n)) {
            x = prev;
            i = prev_i;
        }
    }
    // now x is the repunit with minimal absolute difference
    // but we need to consider both if x > n and x/10 exists
    if (x > n && i > 0) {
        long long prev = repunits[i - 1];
        return memo[n] = min(i + solve(abs(x - n)), i - 1 + solve(abs(prev - n)));
    }
    return memo[n] = i + solve(abs(x - n));
}

