#include <iostream>
#include <algorithm>
#include <stack>
using namespace std;
typedef long long LL;
LL ones[17];

struct Frame {
    LL n; int i; int t; int res1; int state;
    Frame(LL n, int i): n(n), i(i), t(0), res1(0), state(0) {}
};

int solve(LL n, int i) {
    stack<Frame> st;
    st.push(Frame(n, i));
    int result;
    while (!st.empty()) {
        Frame &f = st.top();
        if (f.state == 0) {
            if (f.i == 0) { result = 0; st.pop(); continue; }
            f.t = f.i * (f.n / ones[f.i]);
            f.n %= ones[f.i];
            if (f.n == 0) {
                result = f.t;
                st.pop();
                continue;
            }
            f.state = 1;
            st.push(Frame(ones[f.i] - f.n, f.i - 1));
        } else if (f.state == 1) {
            f.res1 = result;
            f.state = 2;
            st.push(Frame(f.n, f.i - 1));
        } else {
            int res = f.t + min(f.i + f.res1, result);
            result = res;
            st.pop();
        }
    }
    return result;
}

