    while (current > 1) {
        long long rep = 1;
        int digits = 0;
        while (current > rep) {
            digits++;
            rep = rep * 10 + 1;
        }
        long long prev_rep = rep / 10;
        long long threshold = 6 * pow(10.0, digits - 1) + prev_rep / 10;
        if (current > threshold) {
            current = rep - current;
            steps += digits + 1;
        } else {
            current -= prev_rep;
            steps += digits;
        }
    }
    if (current == 1) steps += 1;
    cout << steps;
    return 0;
}

