    cin >> n;

    f[1] = 1;
    for (int i = 2; i <= 16; i++) f[i] = f[i - 1] * 10 + 1;

    ans = MAXLL;

    stack<Frame> st;
    st.push({16, 0, 0, 0});

    while (!st.empty()) {
        Frame &cur = st.top();

        if (n == 0) {
            ans = min(ans, cur.k);
            st.pop();
            if (!st.empty()) {
                Frame &parent = st.top();
                n -= parent.delta;
                parent.delta = 0;
            }
            continue;
        }
        if (cur.nom == 0) {
            st.pop();
            if (!st.empty()) {
                Frame &parent = st.top();
                n -= parent.delta;
                parent.delta = 0;
            }
            continue;
        }

        if (cur.state == 0) {
            bool found = false;
            for (ll i = -10; i <= 10; i++) {
                if (n + i * f[cur.nom] > 0) {
                    cur.delta = i * f[cur.nom];
                    n += cur.delta;
                    cur.state = 1;
                    st.push({cur.nom - 1, cur.k + Abs(i) * cur.nom, 0, 0});
                    found = true;
                    break;
                }
            }
            if (!found) cur.state = 1;
        } else if (cur.state == 1) {
            bool found = false;
            for (ll i = -10; i <= 10; i++) {
                if (n + i * f[cur.nom] == 0) {
                    cur.delta = i * f[cur.nom];
                    n += cur.delta;
                    cur.state = 2;
                    st.push({cur.nom - 1, cur.k + Abs(i) * cur.nom, 0, 0});
                    found = true;
                    break;
                }
            }
            if (!found) cur.state = 2;
        } else if (cur.state == 2) {
            bool found = false;
            for (ll i = 10; i >= -10; i--) {
                if (n + i * f[cur.nom] < 0) {
                    cur.delta = i * f[cur.nom];
                    n += cur.delta;
                    cur.state = 3;
                    st.push({cur.nom - 1, cur.k + Abs(i) * cur.nom, 0, 0});
                    found = true;
                    break;
                }
            }
            if (!found) cur.state = 3;
        } else if (cur.state == 3) {
            st.pop();
            if (!st.empty()) {
                Frame &parent = st.top();
                n -= parent.delta;
                parent.delta = 0;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

