LL biggestOne(LL n) {
    LL cur = 0, mul = 1;
    while (cur * 10 + 1 <= n) {
        cur = cur * 10 + 1;
    }
    if (cur == 0) return 0; // should not happen for n>=1
    return cur;
}

LL proc(LL n) {
    if (n <= 6) return n;
    if (n <= 11) return 13 - n;
