            ans = cntDigits(less) * n / less;
        else
            ans = cntDigits(more) + proc(more - n);
    } else {
        LL _m = (n / less) * less;
        ans = proc(_m) + proc(n - _m);
        if (n > more / 2)
            ans = min(ans, cntDigits(more) + proc(more - n));
    }
    memo[n] = ans;
    return ans;
