    return ans + min(solve(n, step - 1), step + 1 + solve(a[step] - n, step - 1));
}

int main() {
    a[0] = 1;
    for (int i = 1; i <= MAX_STEP; ++i)
        a[i] = a[i-1] * 10 + 1;
    long long n;
    cin >> n;
    cout << solve(n, MAX_STEP);
}

#include <iostream>
using namespace std;

long long a[16];

long long solve(long long n, int step) {
    long long ans = (step + 1LL) * (n / a[step]);
    long long r = n % a[step];
    if (r == 0) return ans;
    long long opt1 = solve(r, step - 1);
    long long opt2 = step + 1 + solve(a[step] - r, step - 1);
    return ans + (opt1 < opt2 ? opt1 : opt2);
}

int main() {
    a[0] = 1;
    for (int i = 1; i < 16; ++i)
        a[i] = a[i-1] * 10 + 1;
    long long n;
    cin >> n;
    cout << solve(n, 15);
}

