string proc(const string& s,int i,int& f)
{
    if(i>=s.size()) return "";
    if(i!=0&&i!=s.size()-2&&f==0&&s[i]=='a'&&s[i+1]=='t')
    {
        f=1;
        return "@"+proc(s,i+2,f);
    }
    else if(i!=0&&i!=s.size()-3&&s[i]=='d'&&s[i+1]=='o'&&s[i+2]=='t')
    {
        return "."+proc(s,i+3,f);
    }
    else
    {
        return s[i]+proc(s,i+1,f);
    }
}
