#include <iostream>
#include <string>
using namespace std;

string process(const string& s, int start, int end, bool addAt) {
    string res, buf;
    for (int i = start; i <= end; ++i) {
        if (i <= end - 2 && s[i] == 'd' && s[i+1] == 'o' && s[i+2] == 't') {
            res += buf + ".";
            buf = "";
            i += 2;
        } else {
            buf += s[i];
        }
    }
    res += buf;
    if (addAt) res += '@';
    return res;
}

int main() {
    string a;
    cin >> a;
    int n = a.size() - 1;
    int atPos = -1;
    for (int i = 1; i <= n; ++i) {
        if (a[i] == 'a' && a[i+1] == 't') {
            atPos = i;
            break;
        }
    }
    string ta;
    ta += a[0];
    ta += process(a, 1, atPos - 1, true);
    ta += process(a, atPos + 2, n, false);
    cout << ta;
    return 0;
}

