string s;

string f() {
    // Replace first "at" from index 1 onward using iterators
    auto it = s.begin() + 1;
    while (it + 1 < s.end()) {
        if (*it == 'a' && *(it + 1) == 't') {
            it = s.erase(it, it + 2);
            it = s.insert(it, '@');
            break;
        }
        ++it;
    }
    // Replace all "dot" from index 1 onward
    it = s.begin() + 1;
    while (it + 2 < s.end()) {
        if (*it == 'd' && *(it + 1) == 'o' && *(it + 2) == 't') {
            it = s.erase(it, it + 3);
            it = s.insert(it, '.');
            // After insertion, move past the inserted '.' to avoid re-scanning
            ++it;
        } else {
            ++it;
        }
    }
    return s;
}

