string solve(string& email) {
    size_t at_pos = email.find("at", 1);
    if (at_pos != string::npos) {
        email.replace(at_pos, 2, "@");
    }

    if (email.size() > 1) {
        regex dot_re("dot");
        smatch match;
        string::const_iterator start = email.cbegin() + 1;
        while (regex_search(start, email.cend(), match, dot_re)) {
            size_t pos = 1 + static_cast<size_t>(match.position());
            if (email.size() == pos + 3) break;
            email.replace(pos, 3, ".");
            start = email.cbegin() + 1;
        }
    }
    return email;
}

