int main() {
    std::string x;
    std::cin >> x;
    std::string y;
    y.reserve(x.size());
    y += x[0];
    if (x.empty()) {
        std::cout << y;
        return 0;
    }

    std::regex re("at(?=.)|dot(?=.)");
    std::size_t last = 1;
    bool at_done = false;

    auto begin = std::sregex_iterator(x.begin(), x.end(), re);
    auto end = std::sregex_iterator();
    for (auto it = begin; it != end; ++it) {
        std::smatch m = *it;
        std::size_t pos = static_cast<std::size_t>(m.position());
        if (pos < last) continue;
        std::string tok = m.str();

        if (tok == "at" && !at_done) {
            y.append(x, last, pos - last);
            y.push_back('@');
            last = pos + 2;
            at_done = true;
        } else if (tok == "dot") {
            y.append(x, last, pos - last);
            y.push_back('.');
            last = pos + 3;
        } else {
            y.append(x, last, pos - last);
            y += tok;
            last = pos + 2;
        }
    }
    y.append(x, last, std::string::npos);

    std::cout << y;
    return 0;
}

