void solve() {
    string s;
    cin >> s;
    string res;
    int n = s.length();
    bool at_replaced = false;
    enum State { NORMAL, SEEN_A, SEEN_D, SEEN_DO };
    State state = NORMAL;
    for (int i = 0; i < n; ++i) {
        char c = s[i];
        switch (state) {
            case NORMAL:
                if (i == 0) {
                    res += c;
                    break;
                }
                if (!at_replaced && c == 'a' && i <= n-3) {
                    state = SEEN_A;
                } else if (c == 'd' && i <= n-4) {
                    state = SEEN_D;
                } else {
                    res += c;
                }
                break;
            case SEEN_A:
                if (c == 't' && !at_replaced) {
                    res += '@';
                    at_replaced = true;
                    state = NORMAL;
                } else {
                    res += 'a';
                    res += c;
                    state = NORMAL;
                }
                break;
            case SEEN_D:
                if (c == 'o') {
                    state = SEEN_DO;
                } else {
                    res += 'd';
                    res += c;
                    state = NORMAL;
                }
                break;
            case SEEN_DO:
                if (c == 't') {
                    res += '.';
                    state = NORMAL;
                } else {
                    res += 'd';
                    res += 'o';
                    res += c;
                    state = NORMAL;
                }
                break;
        }
    }
    cout << res;
}

