int main() {
    string s;
    cin >> s;

    long long n = (long long)s.size();
    string ans;
    ans.reserve(n);
    ans.push_back(s[0]);

    bool at_done = false;
    long long i = 1;

    while (i < n) {
        long long at_pos = -1;
        if (!at_done) {
            size_t p = s.find("at", (size_t)i);
            if (p != string::npos) {
                long long q = (long long)p;
                if (q < n - 2) at_pos = q;
            }
        }

        long long dot_pos = -1;
        size_t dp = s.find("dot", (size_t)i);
        if (dp != string::npos) {
            long long q = (long long)dp;
            if (q < n - 3) dot_pos = q;
        }

        if (at_pos != -1 && (dot_pos == -1 || at_pos < dot_pos)) {
            ans.append(s, (size_t)i, (size_t)(at_pos - i));
            ans.push_back('@');
            at_done = true;
            i = at_pos + 2;
        } else if (dot_pos != -1) {
            ans.append(s, (size_t)i, (size_t)(dot_pos - i));
            ans.push_back('.');
            i = dot_pos + 3;
        } else {
            ans.append(s, (size_t)i, string::npos);
            i = n;
        }
    }

    cout << ans;
    return 0;
}

