void walk(const string& s, int i, bool& replaced_at) {
    int l = (int)s.size();
    if (i >= l) {
        return;
    }

    if (s[i] == 'a' && !replaced_at && i + 1 < l && s[i + 1] == 't') {
        cout << '@';
        replaced_at = true;
        walk(s, i + 2, replaced_at);
        return;
    }

    if (s[i] == 'd' && i + 2 < l - 1 && s[i + 1] == 'o' && s[i + 2] == 't') {
        cout << '.';
        walk(s, i + 3, replaced_at);
        return;
    }

    cout << s[i];
    walk(s, i + 1, replaced_at);
}

