void scan(const string& s, int i, int l, bool& at_done) {
    if (i >= l) return;
    if (i != l - 3 && i + 2 < l &&
        s[i] == 'd' && s[i + 1] == 'o' && s[i + 2] == 't') {
        cout << '.';
        scan(s, i + 3, l, at_done);
