               s[i] == 'a' && s[i + 1] == 't' && !at_done) {
        cout << '@';
        at_done = true;
        scan(s, i + 2, l, at_done);
    } else {
        cout << s[i];
        scan(s, i + 1, l, at_done);
    }
}

