            size_t found = s.find("dot", (size_t)pos);
            if (found == string::npos)
                return n;
            int f = (int)found;
            if (f + 2 < n && f + 2 != n - 1)
                return f;
            pos = f + 1;
        }
        return n;
    };

    cout << s[0];

    int i = 1;
    while (i < n) {
        int dot = next_dot(i);
        int at = (atpos >= i) ? atpos : n;

        if (dot == n && at == n) {
            cout << s.substr(i);
            break;
        }

        if (at < dot) {
            cout << s.substr(i, at - i);
            cout << '@';
            i = at + 2;
        } else {
            cout << s.substr(i, dot - i);
            cout << '.';
