    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            scanf("%d", &a[i][j]);
            a[i][j] = divv(a[i][j], 100);
        }

    vector<pair<vector<int>, int>> cur, nxt;
    cur.push_back({{0}, 1});

    for (int col = 0; col < n; ++col) {
        nxt.clear();
        for (int mask = 0; mask < (1 << n); ++mask) {
            int prob = 1;
            for (int row = 0; row < n; ++row) {
                if (mask & (1 << row))
                    prob = mul(prob, a[row][col]);
                else
                    prob = mul(prob, sub(1, a[row][col]));
            }
            for (auto &p : cur) {
                vector<int> tmp;
                for (int m : p.first) {
                    int diff = (~m) & mask;
                    // iterate over all masks that are m plus exactly one bit from diff
                    for (int bit = 1; bit < (1 << n); bit <<= 1) {
                        if (diff & bit) {
                            tmp.push_back(m | bit);
                        }
                    }
                }
                if (tmp.empty()) continue;
                sort(tmp.begin(), tmp.end());
                tmp.erase(unique(tmp.begin(), tmp.end()), tmp.end());
                nxt.push_back({tmp, mul(p.second, prob)});
            }
        }
        sort(nxt.begin(), nxt.end());
        cur.clear();
        int i = 0;
        while (i < (int)nxt.size()) {
            int j = i;
            int sum = 0;
            while (j < (int)nxt.size() && nxt[j].first == nxt[i].first) {
                sum = add(sum, nxt[j].second);
                ++j;
            }
            cur.push_back({nxt[i].first, sum});
            i = j;
        }
    }

    int ans = 0;
    for (auto &p : cur)
        ans = add(ans, p.second);
    printf("%d\n", ans);
    return 0;
}

#include <iostream>
#include <vector>
