using namespace std;

const int MOD = 1000000007;
const int MAXN = 10;

int a[MAXN][MAXN];

int add(int x, int y) {
    x += y;
    return x >= MOD ? x - MOD : x;
}

int sub(int x, int y) {
    x -= y;
    return x < 0 ? x + MOD : x;
}

int mul(int x, int y) {
    return (1LL * x * y) % MOD;
}

int power(int x, int e) {
    int res = 1;
    while (e) {
        if (e & 1) res = mul(res, x);
        x = mul(x, x);
        e >>= 1;
    }
    return res;
}

int inv(int x) {
    return power(x, MOD - 2);
}

int divv(int x, int y) {
    return mul(x, inv(y));
}

// hash for vector<int>
struct VectorHash {
    size_t operator()(const vector<int>& v) const {
        size_t h = 0;
        for (int x : v) {
            h ^= hash<int>()(x) + 0x9e3779b9 + (h << 6) + (h >> 2);
        }
        return h;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
            a[i][j] = divv(a[i][j], 100);
        }

    unordered_map<vector<int>, int, VectorHash> dp;
    dp[{0}] = 1;

    for (int col = 0; col < n; ++col) {
        unordered_map<vector<int>, int, VectorHash> ndp;
        for (int mask = 0; mask < (1 << n); ++mask) {
            int prob = 1;
            for (int row = 0; row < n; ++row) {
                if (mask & (1 << row))
                    prob = mul(prob, a[row][col]);
                else
                    prob = mul(prob, sub(1, a[row][col]));
            }
            for (auto &entry : dp) {
                vector<int> newVec;
                for (int m : entry.first) {
                    int diff = (~m) & mask;
                    while (diff) {
                        int bit = diff & -diff;
                        newVec.push_back(m | bit);
                        diff ^= bit;
                    }
                }
                if (newVec.empty()) continue;
                sort(newVec.begin(), newVec.end());
                newVec.erase(unique(newVec.begin(), newVec.end()), newVec.end());
                int val = mul(entry.second, prob);
                auto it = ndp.find(newVec);
                if (it == ndp.end())
                    ndp[newVec] = val;
                else
                    it->second = add(it->second, val);
            }
        }
        dp = move(ndp);
    }

    int ans = 0;
    for (auto &entry : dp)
        ans = add(ans, entry.second);
    cout << ans << "\n";
    return 0;
}

