// Precompute all 20 masks with exactly 3 bits set from 0..5
const int masks20[20] = {
	0b000111, 0b001011, 0b001101, 0b001110,
	0b010011, 0b010101, 0b010110, 0b011001,
	0b011010, 0b011100, 0b100011, 0b100101,
	0b100110, 0b101001, 0b101010, 0b101100,
	0b110001, 0b110010, 0b110100, 0b111000
};
map<int,int> mp;

void init(vector<vector<Mod>>& pers) {
	for(int i=0;i<20;++i) mp[masks20[i]]=i;
	int N; cin>>N;
	int s=3-(N+1)/2;
	for(int i=0;i<s;++i) pers[i][i]=Mod(1);
	for(int i=s;i<s+N;++i) {
		for(int j=s;j<s+N;++j) {
			int p; cin>>p;
			pers[i][j]=Mod(p)/Mod(100);
		}
	}
	for(int i=s+N;i<6;++i) pers[i][i]=Mod(1);
}

vector<Mod> solve(const vector<vector<Mod>>& pers, int al=0) {
	vector<Mod> l_nums(1<<20);
	for(int xx=0; xx<(1<<18); ++xx) {
		Mod per=1;
		int haves[3][6] = {0};
		for(int i=0;i<3;++i) {
			for(int j=0;j<6;++j) {
				int k=i*6+j;
				if(xx>>k & 1) {
					haves[i][j]=1;
					per *= pers[al+i][j];
				} else {
					per *= (Mod(1)-pers[al+i][j]);
				}
			}
		}
		int flags=0;
		for(int i=0;i<6;++i) if(haves[0][i])
		for(int j=0;j<6;++j) if(haves[1][j] && i!=j)
		for(int k=0;k<6;++k) if(haves[2][k] && i!=k && j!=k) {
			int anum = (1<<i) ^ (1<<j) ^ (1<<k);
			flags |= 1<<mp[anum];
		}
		l_nums[flags] += per;
	}
	return l_nums;
}

int main() {
	ios::sync_with_stdio(false);
	vector<vector<Mod>> pers(6, vector<Mod>(6));
	init(pers);
	auto u_nums = solve(pers,0);
	auto d_nums = solve(pers,3);
	for(int x=1; x<(1<<20); x<<=1) {
		for(int i=0; i<(1<<20); ++i) {
			if((i&x)==0) d_nums[i^x] += d_nums[i];
		}
	}
	Mod ans=0;
	for(int i=0; i<(1<<20); ++i) {
		if(u_nums[i].num) {
			int need=0;
			for(int x=0;x<20;++x) if(i>>x & 1) need |= 1<<(19-x);
			Mod nans = u_nums[i] * (Mod(1) - d_nums[((1<<20)-1)^need]);
			ans += nans;
		}
	}
	cout << ans.num << endl;
	return 0;
}

