    for (int i = 1; i <= 6; ++i)
        for (int j = i+1; j <= 6; ++j)
            for (int k = j+1; k <= 6; ++k)
                maska[(1<<i) ^ (1<<j) ^ (1<<k)] = (1<<xd++);
