        tab[i][i] = 100;
    VPII kraw;
    n = 6;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            kraw.push_back({i, j});
    LL odw = pot(100, mod-2);
    for (int k = 0; k < 2; ++k) {
        for (int i = 0; i < (1<<18); ++i) {
            LL p = 1;
            for (int j = 0; j < 18; ++j) {
                int idx = j + k * 18;
                int u = kraw[idx].fi, v = kraw[idx].se;
                if ((1<<j) & i) {
                    p = p * tab[u][v] % mod * odw % mod;
                    elo[v][u] = 1;
                } else {
                    p = p * (100 - tab[u][v]) % mod * odw % mod;
                    elo[v][u] = 0;
                }
            }
            int cur = daj(k);
            dp[cur][k] = (dp[cur][k] + p) % mod;
        }
    }
    LL res = 1;
    for (int i = 0; i < 20; ++i)
        for (int j = 0; j < (1<<20); ++j)
            if ((1<<i) & j)
                dp[j][0] = (dp[j][0] + dp[j ^ (1<<i)][0]) % mod;
    for (int i = 0; i < (1<<20); ++i)
        res = (res - dp[i][0] * dp[((1<<20)-1) ^ i][1]) % mod;
    res = (res + mod) % mod;
    cout << res;
    return 0;
}

