// Recursive function to generate all subsets of edges and compute probability
void generateStates(int row, int maxRow, int n, int state, LLI prob, int* P, int inv100, vector<int>& masks, vector<int>& probArr, int offset) {
    if (row == maxRow) {
        // state is a bitmask of edges for rows offset..offset+maxRow-1
        int poss = 0;
        for (int idx = 0; idx < (int)masks.size(); idx++) {
            int mask = masks[idx];
            // Check if there is a permutation of columns (selected by mask) that matches state
            vector<int> cols;
            for (int k = 0; k < n; k++) {
                if (offset == 0 ? (mask & (1 << k)) : !(mask & (1 << k))) cols.push_back(k);
            }
            sort(cols.begin(), cols.end());
            do {
                int pmask = 0;
                for (int r = 0; r < (int)cols.size(); r++) {
                    int edge = (offset + r) * n + cols[r];
                    pmask |= (1 << edge);
                }
                if ((state & pmask) == pmask) {
                    poss |= (1 << idx);
                    break;
                }
            } while (next_permutation(cols.begin(), cols.end()));
        }
        probArr[poss] = (probArr[poss] + prob) % MOD;
        return;
    }
    for (int col = 0; col < n; col++) {
        int edge = (offset + row) * n + col;
        // edge present
        LLI newProb = prob * ((LLI)P[offset + row * n + col] * inv100 % MOD) % MOD;
        generateStates(row+1, maxRow, n, state | (1 << edge), newProb, P, inv100, masks, probArr, offset);
        // edge absent
        newProb = prob * ((LLI)(100 - P[offset + row * n + col]) * inv100 % MOD) % MOD;
        generateStates(row+1, maxRow, n, state, newProb, P, inv100, masks, probArr, offset);
    }
}

