    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) scanf("%d", &P[i][j]);
    }

    int h = (n + 1) / 2;
    int h2 = n - h;
    int inv100 = inv(100);

    // Use arrays instead of vectors for masks (max size 20)
    int masks[20], masks2[20];
    int M = 0, M2 = 0;
    for (int m = 0; m < (1 << n); m++) {
        int cnt = __builtin_popcount(m);
        if (cnt == h) masks[M++] = m;
        if (cnt == h2) masks2[M2++] = m;
    }

    int prob[1 << 20] = {0};
    int prob2[1 << 20] = {0};

    // First half
    int totalEdges1 = n * h;
    for (int state = 0; state < (1 << totalEdges1); state++) {
        LLI p = 1;
        for (int e = 0; e < totalEdges1; e++) {
            int x = e / n, y = e % n;
            if (state & (1 << e))
                p = p * ((LLI)P[x][y] * inv100 % MOD) % MOD;
            else
                p = p * ((LLI)(100 - P[x][y]) * inv100 % MOD) % MOD;
        }
        int poss = 0;
        for (int idx = 0; idx < M; idx++) {
            int mask = masks[idx];
            vi cols;
            for (k = 0; k < n; k++) if (mask & (1 << k)) cols.push_back(k);
            sort(cols.begin(), cols.end());
            do {
                int ok = 1;
                for (k = 0; k < (int)cols.size(); k++) {
                    int edge = k * n + cols[k];
                    if (!(state & (1 << edge))) { ok = 0; break; }
                }
                if (ok) { poss |= (1 << idx); break; }
            } while (next_permutation(cols.begin(), cols.end()));
        }
        prob[poss] = (prob[poss] + p) % MOD;
    }

    // Second half
    int totalEdges2 = n * h2;
    for (int state = 0; state < (1 << totalEdges2); state++) {
        LLI p = 1;
        for (int e = 0; e < totalEdges2; e++) {
            int x = e / n + h, y = e % n;
            if (state & (1 << e))
                p = p * ((LLI)P[x][y] * inv100 % MOD) % MOD;
            else
                p = p * ((LLI)(100 - P[x][y]) * inv100 % MOD) % MOD;
        }
        int poss = 0;
        for (int idx = 0; idx < M; idx++) {
            int mask = masks[idx];
            vi cols;
            for (k = 0; k < n; k++) if (!(mask & (1 << k))) cols.push_back(k);
            sort(cols.begin(), cols.end());
            do {
                int ok = 1;
                for (k = 0; k < (int)cols.size(); k++) {
                    int edge = k * n + cols[k];
                    if (!(state & (1 << edge))) { ok = 0; break; }
                }
                if (ok) { poss |= (1 << idx); break; }
            } while (next_permutation(cols.begin(), cols.end()));
        }
        prob2[poss] = (prob2[poss] + p) % MOD;
    }

    // SOS DP on prob2
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < (1 << M); j++) {
            if (j & (1 << i)) {
                prob2[j] = (prob2[j] + prob2[j ^ (1 << i)]) % MOD;
            }
        }
    }

    LLI ans = 0;
    int fullMask = (1 << M) - 1;
    for (int i = 0; i < (1 << M); i++) {
        ans = (ans + (LLI)prob[i] * prob2[fullMask ^ i]) % MOD;
    }
    printf("%I64d\n", (MOD + 1 - ans) % MOD);

    return 0;
}

