void buildProb(int prob[], int phase) {
    int sel[18], unsel[18];
    int id = 0;
    for (int x = 1; x <= 6; ++x) {
        for (int y = (phase ? 4 : 1); y <= (phase ? 6 : 3); ++y) {
            sel[id] = a[x][y];
            unsel[id] = mod + 1 - a[x][y];
            ++id;
        }
    }
    prob[0] = 1;
    for (int i = 0; i < 18; ++i) {
        int bit = 1 << i;
        for (int mask = 0; mask < bit; ++mask) {
            int base = prob[mask];
            prob[mask] = 1LL * base * unsel[i] % mod;
            prob[mask | bit] = 1LL * base * sel[i] % mod;
        }
    }
}

