#include <bits/stdc++.h>
using namespace std;

const int mod = 1000000007;
const int LIM = (1 << 20) - 1;

int n, lim, ans;
int a[10][10], h[10][10][10];
int p1[(1 << 20) + 5], p2[(1 << 20) + 5];
bool flag[10][10];
int rowProb[2][7][8];

int fpow(int x, int y) {
    int res = 1;
    while (y) {
        if (y & 1) res = 1LL * res * x % mod;
        x = 1LL * x * x % mod;
        y >>= 1;
    }
    return res;
}

int inv(int x) {
    return fpow(x, mod - 2);
}

bool checkTriple(int x, int y, int z) {
    int v[3] = {x, y, z};
    int p[3] = {0, 1, 2};
    do {
        if (flag[v[p[0]]][1] && flag[v[p[1]]][2] && flag[v[p[2]]][3]) return true;
    } while (next_permutation(p, p + 3));
    return false;
}

void finishFirst(int P) {
    int sta = 0;
    for (int i = 1; i <= 6; ++i)
        for (int j = i + 1; j <= 6; ++j)
            for (int k = j + 1; k <= 6; ++k)
                if (checkTriple(i, j, k)) {
                    int x = 1;
                    while (x == i || x == j || x == k) ++x;
                    int y = x + 1;
                    while (y == i || y == j || y == k) ++y;
                    int z = y + 1;
                    while (z == i || z == j || z == k) ++z;
                    sta |= h[x][y][z];
                }
    p1[sta] = (p1[sta] + P) % mod;
}

void finishSecond(int P) {
    int sta = 0;
    for (int i = 1; i <= 6; ++i)
        for (int j = i + 1; j <= 6; ++j)
            for (int k = j + 1; k <= 6; ++k)
                if (checkTriple(i, j, k)) sta |= h[i][j][k];
    p2[sta] = (p2[sta] + P) % mod;
    ans = (ans + 1LL * p1[lim ^ sta] * P) % mod;
}

void dfsRows(int x, int P, int phase) {
    if (x == 7) {
        if (phase == 0) finishFirst(P);
        else finishSecond(P);
        return;
    }

    for (int r = 0; r < 8; ++r) {
        for (int y = 1; y <= 3; ++y)
            flag[x][y] = (r >> (y - 1)) & 1;
        dfsRows(x + 1, 1LL * P * rowProb[phase][x][r] % mod, phase);
    }
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            scanf("%d", &a[i][j]);
            a[i][j] = 1LL * a[i][j] * inv(100) % mod;
        }
    for (int i = n + 1; i <= 6; ++i) a[i][i] = 1;

    int tot = 0;
    for (int i = 1; i <= 6; ++i)
        for (int j = i + 1; j <= 6; ++j)
            for (int k = j + 1; k <= 6; ++k)
                h[i][j][k] = 1 << tot++;

    for (int x = 1; x <= 6; ++x) {
        for (int r = 0; r < 8; ++r) {
            int prob0 = 1, prob1 = 1;
            for (int y = 1; y <= 3; ++y) {
                int bit = (r >> (y - 1)) & 1;
                if (bit) {
                    prob0 = 1LL * prob0 * a[x][y] % mod;
                    prob1 = 1LL * prob1 * a[x][y + 3] % mod;
                } else {
                    prob0 = 1LL * prob0 * (mod + 1 - a[x][y]) % mod;
                    prob1 = 1LL * prob1 * (mod + 1 - a[x][y + 3]) % mod;
                }
            }
            rowProb[0][x][r] = prob0;
            rowProb[1][x][r] = prob1;
        }
    }

    lim = LIM;

    dfsRows(1, 1, 0);

    for (int i = 0; i < 20; ++i)
        for (int mask = 0; mask <= lim; ++mask)
            if ((mask >> i) & 1) {
                p1[mask] += p1[mask ^ (1 << i)];
                if (p1[mask] >= mod) p1[mask] -= mod;
            }

    dfsRows(1, 1, 1);

    ans = (mod + 1 - ans) % mod;
    printf("%d\n", ans);
    return 0;
}

#include <algorithm>
#include <cassert>
#include <iostream>
#include <map>
#include <vector>
using namespace std;

const int MOD = 1e9 + 7;

struct mod_int {
    int val;

    mod_int(long long v = 0) {
        if (v < 0)
            v = v % MOD + MOD;

        if (v >= MOD)
            v %= MOD;

        val = v;
    }

    static int mod_inv(int a, int m = MOD) {
        // https://en.wikipedia.org/wiki/Extended_Euclidean_algorithm#Example
        int g = m, r = a, x = 0, y = 1;

        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }

        return x < 0 ? x + m : x;
    }

    explicit operator int() const {
        return val;
    }

    mod_int& operator+=(const mod_int &other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }

    mod_int& operator-=(const mod_int &other) {
        val -= other.val;
        if (val < 0) val += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
    #if !defined(_WIN32) || defined(_WIN64)
        return x % m;
    #endif
        // Optimized mod for Codeforces 32-bit machines.
        // x must be less than 2^32 * m for this to work, so that x / m fits in a 32-bit integer.
        unsigned x_high = x >> 32, x_low = (unsigned) x;
        unsigned quot, rem;
        asm("divl %4\n"
            : "=a" (quot), "=d" (rem)
            : "d" (x_high), "a" (x_low), "r" (m));
        return rem;
    }

    mod_int& operator*=(const mod_int &other) {
        val = fast_mod((uint64_t) val * other.val);
        return *this;
    }

    mod_int& operator/=(const mod_int &other) {
        return *this *= other.inv();
    }

    friend mod_int operator+(const mod_int &a, const mod_int &b) { return mod_int(a) += b; }
    friend mod_int operator-(const mod_int &a, const mod_int &b) { return mod_int(a) -= b; }
    friend mod_int operator*(const mod_int &a, const mod_int &b) { return mod_int(a) *= b; }
    friend mod_int operator/(const mod_int &a, const mod_int &b) { return mod_int(a) /= b; }

    mod_int& operator++() {
        val = val == MOD - 1 ? 0 : val + 1;
        return *this;
    }

    mod_int& operator--() {
        val = val == 0 ? MOD - 1 : val - 1;
        return *this;
    }

    mod_int operator++(int) { mod_int before = *this; ++*this; return before; }
    mod_int operator--(int) { mod_int before = *this; --*this; return before; }

    mod_int operator-() const {
        return val == 0 ? 0 : MOD - val;
    }

    bool operator==(const mod_int &other) const { return val == other.val; }
    bool operator!=(const mod_int &other) const { return val != other.val; }

    mod_int inv() const {
        return mod_inv(val);
    }

    mod_int pow(long long p) const {
        assert(p >= 0);
        mod_int a = *this, result = 1;

        while (p > 0) {
            if (p & 1)
                result *= a;

            a *= a;
            p >>= 1;
        }

        return result;
    }
};


const int N_MAX = 7;

int N;
mod_int probability[N_MAX][N_MAX];

int main() {
    cin >> N;

    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            int p;
            cin >> p;
            probability[i][j] = mod_int(p) / mod_int(100);
        }

    map<vector<bool>, mod_int> possible_masks;
    vector<bool> starting(1 << N, false);
    starting[0] = true;
    possible_masks[starting] = 1;
    vector<bool> new_possible;

    for (int left = 0; left < N; left++) {
        map<vector<bool>, mod_int> new_possible_masks;

        for (int current = 0; current < 1 << N; current++) {
            mod_int product = 1;

            for (int right = 0; right < N; right++)
                product *= (current >> right & 1) ? probability[left][right] : 1 - probability[left][right];

            for (auto &p : possible_masks) {
                const vector<bool> &possible = p.first;
                mod_int prob = p.second;
                new_possible.assign(1 << N, false);

                for (int mask = 0; mask < 1 << N; mask++)
                    if (possible[mask])
                        for (int i = 0; i < N; i++)
                            if ((current >> i & 1) != 0 && (mask >> i & 1) == 0)
                                new_possible[mask | 1 << i] = true;

                new_possible_masks[new_possible] += prob * product;
            }
        }

        possible_masks = new_possible_masks;
        cerr << possible_masks.size() << endl;
    }

    mod_int answer = 0;

    for (auto &p : possible_masks)
        if (p.first[(1 << N) - 1])
            answer += p.second;

    cout << (int) answer << '\n';
}

