void genSubsets(int n, vector<vector<int>>& subs, vector<vector<int>>& ids) {
    for (int sz = 0; sz <= n; ++sz) {
        ids[sz].assign(1 << n, -1);
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (__builtin_popcount(mask) == sz) {
                ids[sz][mask] = (int)subs[sz].size();
                subs[sz].push_back(mask);
            }
        }
    }
}

