int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<vector<int>> p(n, vector<int>(n));
    int inv100 = power_mod(100, MOD - 2);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> p[i][j];
            p[i][j] = (i64)p[i][j] * inv100 % MOD;
        }
    }

    // Precompute subsets of each size and their IDs
    vector<vector<int>> comb(n + 1);
    vector<vector<int>> sid(n + 1, vector<int>(1 << n, -1));
    for (int sz = 0; sz <= n; ++sz) {
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (__builtin_popcount(mask) == sz) {
                sid[sz][mask] = (int)comb[sz].size();
                comb[sz].push_back(mask);
            }
        }
    }

    vector<map<i64, int>> dp(n + 1);
    dp[0][1] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int s = 0; s < (1 << n); ++s) {
            int prob = 1;
            for (int j = 0; j < n; ++j) {
                if ((s >> j) & 1) {
                    prob = (i64)prob * p[i - 1][j] % MOD;
                } else {
                    prob = (i64)prob * ((1 - p[i - 1][j] + MOD) % MOD) % MOD;
                }
            }

            for (const auto &pr : dp[i - 1]) {
                i64 mask_old = pr.first;
                int val_old = pr.second;
                i64 mask_new = 0;

                for (int t : comb[i]) {
                    // Test if t is "compatible" with s and old mask
                    bool ok = false;
                    int ttemp = t;
                    while (ttemp) {
                        int bit = ttemp & -ttemp;
                        int j = __builtin_ctz(bit);
                        if ((s & bit) && (mask_old & (1LL << sid[i - 1][t ^ bit]))) {
                            ok = true;
                            break;
                        }
                        ttemp ^= bit;
                    }
                    if (ok) {
                        mask_new |= (1LL << sid[i][t]);
                    }
                }

                dp[i][mask_new] = (dp[i][mask_new] + (i64)val_old * prob) % MOD;
            }
        }
    }

    cout << dp[n][1] << "\n";
    return 0;
}

