using namespace std;
using ll = long long;
const int MOD = 1'000'000'007;

int powmod(int a, int b) {
    int r = 1;
    while (b) {
        if (b & 1) r = (ll)r * a % MOD;
        a = (ll)a * a % MOD;
        b >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> mat(n, vector<int>(n));
    int inv = powmod(100, MOD - 2);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> mat[i][j];
            mat[i][j] = (ll)mat[i][j] * inv % MOD;
        }
    }

    vector<vector<int>> pieces(n + 1);
    vector<vector<int>> pos(n + 1);
    for (int sz = 0; sz <= n; ++sz) {
        pos[sz].assign(1 << n, -1);
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (__builtin_popcount(mask) == sz) {
                pos[sz][mask] = (int)pieces[sz].size();
                pieces[sz].push_back(mask);
            }
        }
    }

    vector<map<ll, int>> dyn(n + 1);
    dyn[0][1] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int s = 0; s < (1 << n); ++s) {
            // Compute probability for row i-1 and set s
            int cur = 1;
            for (int j = 0; j < n; ++j) {
                int v = (s & (1 << j)) ? mat[i - 1][j] : ((1 - mat[i - 1][j] + MOD) % MOD);
                cur = (ll)cur * v % MOD;
            }

            for (const auto &pair : dyn[i - 1]) {
                ll old_mask = pair.first;
                int old_val = pair.second;
                ll new_mask = 0;

                for (int t : pieces[i]) {
                    bool hit = false;
                    // iterate over each 1-bit in t
                    for (int j = 0; j < n; ++j) {
                        if ((t & (1 << j)) && (s & (1 << j)) && (old_mask & (1LL << pos[i - 1][t ^ (1 << j)]))) {
                            hit = true;
                            break;
                        }
                    }
                    if (hit) {
                        new_mask |= (1LL << pos[i][t]);
                    }
                }

                dyn[i][new_mask] = (dyn[i][new_mask] + (ll)old_val * cur) % MOD;
            }
        }
    }

    cout << dyn[n][1] << "\n";
    return 0;
}

