    void set(int x) { if (x < 64) a |= 1ULL << x; else b |= 1ULL << (x - 64); }
    void reset() { a = b = 0; }
    LLL& operator|=(const LLL& o) { a |= o.a; b |= o.b; return *this; }
    bool operator==(const LLL& o) const { return a == o.a && b == o.b; }
    bool operator[](int x) const { return x < 64 ? (a >> x) & 1 : (b >> (x - 64)) & 1; }
    bool operator<(const LLL& o) const { return b < o.b || (b == o.b && a < o.a); }
};

ll fpm(ll a, ll b) {
    ll r = 1;
    while (b) { if (b & 1) r = r * a % MOD; a = a * a % MOD; b >>= 1; }
    return r;
}

int n;
ll a[11][11];
ll f[11][131];
int is[131];
ll i100;
map<LLL, ll> st[8];
LLL mx, stt;

ll dfs(int x, LLL w) {
    if (x == n) return w == mx;
    auto it = st[x].find(w);
    if (it != st[x].end()) return it->second;
    ll ans = 0;
    LLL s[11];
    for (int j = 0; j < n; ++j) s[j].reset();
    for (int i = 0; i < (1 << n); ++i) if (w[i])
        for (int j = 0; j < n; ++j) if (!(i & (1 << j)))
            s[j].set(i | (1 << j));
    for (int i = 0; i < (1 << n); ++i) {
        LLL ng = w;
        for (int j = 0; j < n; ++j) if (i & (1 << j)) ng |= s[j];
        ans = (ans + f[x][i] * dfs(x + 1, ng)) % MOD;
    }
    return st[x][w] = ans;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> n;
    for (int i = 0; i < (1 << n); ++i) mx.set(i);
