struct ModInt {
    int v;
    ModInt(long long a = 0) { if (a < 0) a += MOD; if (a >= MOD) a %= MOD; v = a; }
    static int inv(int a) {
        int g = MOD, r = a, x = 0, y = 1;
        while (r) { int q = g / r; g %= r; swap(g, r); x -= q * y; swap(x, y); }
        return x < 0 ? x + MOD : x;
    }
    ModInt& operator+=(const ModInt &o) { v += o.v; if (v >= MOD) v -= MOD; return *this; }
    ModInt& operator-=(const ModInt &o) { v -= o.v; if (v < 0) v += MOD; return *this; }
    ModInt& operator*=(const ModInt &o) { v = (long long)v * o.v % MOD; return *this; }
    ModInt& operator/=(const ModInt &o) { return *this *= o.inv(); }
    friend ModInt operator+(ModInt a, const ModInt &b) { return a += b; }
    friend ModInt operator-(ModInt a, const ModInt &b) { return a -= b; }
    friend ModInt operator*(ModInt a, const ModInt &b) { return a *= b; }
    friend ModInt operator/(ModInt a, const ModInt &b) { return a /= b; }
    ModInt operator-() const { return v ? MOD - v : 0; }
    ModInt inv() const { return inv(v); }
    explicit operator int() const { return v; }
};

const int N_MAX = 10;
