        int cnt = __builtin_popcount(mask);
        idx[mask] = subsets[cnt].size();
        subsets[cnt].push_back(mask);
    }

    unordered_map<ll, ModInt, custom_hash> dp;
    dp[1LL << idx[0]] = 1;

    for (int stage = 0; stage < N; stage++) {
        unordered_map<ll, ModInt, custom_hash> ndp;
        vector<ModInt> prod(1 << N, 1);
        for (int cur = 0; cur < (1 << N); cur++)
            for (int j = 0; j < N; j++)
                prod[cur] *= (cur >> j & 1) ? prob[stage][j] : 1 - prob[stage][j];

        for (auto &entry : dp) {
            ll st = entry.first;
