using ll = long long;

ll inv_mod(ll a, ll m) {
	ll b = m, u = 1, v = 0;
	if (m == 1) return 0;
	a %= m;
	if (a < 0) a += m;
	assert(a != 0);
	while (a > 1) {
		ll q = a / m;
		ll t = m;
		m = a % m;
		a = t;
		t = v;
		v = u - q * v;
		u = t;
	}
	return (u % b + b) % b;
}

template<int MD>
struct Modular {
	ll val;
