	Modular& operator+=(const Modular& o) { val += o.val; if (val >= mod) val -= mod; return *this; }
	Modular& operator-=(const Modular& o) { val -= o.val; if (val < 0) val += mod; return *this; }
	Modular& operator*=(const Modular& o) { val = val * o.val % mod; return *this; }
	Modular& operator/=(const Modular& o) { return *this *= ~o; }
	friend Modular operator+(const Modular& a, const Modular& b) { return Modular(a) += b; }
