	auto build = [&](int t) {
		for (int e = 0; e < (1 << 18); ++e) {
			num prob = 1;
			int rows[3] = {};
			for (int bit = 0; bit < 18; ++bit) {
				bool on = (e >> bit) & 1;
				num pv = p[(bit / n) * 2 + t][bit % n];
				prob *= on ? pv : (1 - pv);
				rows[bit / n] |= (int)on << (bit % n);
			}
			int wmask = 0;
			for (int a = 0; a < (int)masks[t].size(); ++a) {
				int msk = masks[t][a];
				int r0 = rows[0] & msk, r1 = rows[1] & msk, r2 = rows[2] & msk;
				if (r0 && r1 && r2) {
					int combined = r0 | r1 | r2;
					if (__builtin_popcount(combined) == 3 &&
						__builtin_popcount(r0 | r1) >= 2 &&
						__builtin_popcount(r0 | r2) >= 2 &&
						__builtin_popcount(r1 | r2) >= 2) {
						wmask |= (1 << a);
					}
				}
			}
			dp[t][wmask] += prob;
		}
	};
	build(0);
	build(1);

	for (int i = 0; i < f; i++) {
		for (int submask = 0; submask < (1 << f); submask++) {
			if ((submask >> i) & 1) continue;
			dp[0][submask ^ (1 << i)] += dp[0][submask];
		}
	}

	num ans = 0;
	for (int mask = 0; mask < (1 << f); mask++) {
		ans += dp[0][mask] * dp[1][((1 << f) - 1) ^ mask];
	}
	ans = 1 - ans;
	cout << (int)ans << '\n';
	return 0;
}

