using namespace std;
using ll = long long;

ll modinv(ll a, ll m) {
	assert(m > 0);
	if (m == 1) return 0;
	a %= m;
	if (a < 0) a += m;
	assert(a != 0);
	if (a == 1) return 1;
	return m - modinv(m, a) * m / a;
}

template<int MOD>
struct Z {
	int x;
	static const int mod = MOD;
	Z() : x(0) {}
	Z(ll v) : x((int)(v % mod)) { if (x < 0) x += mod; }
	explicit operator int() const { return x; }
	friend bool operator==(const Z& a, const Z& b) { return a.x == b.x; }
	friend bool operator!=(const Z& a, const Z& b) { return a.x != b.x; }
	Z operator~() const { Z r; r.x = modinv(x, mod); return r; }
	Z& operator+=(const Z& o) { x += o.x; if (x >= mod) x -= mod; return *this; }
	Z& operator-=(const Z& o) { x -= o.x; if (x < 0) x += mod; return *this; }
	Z& operator*=(const Z& o) { x = (int)((ll)x * o.x % mod); return *this; }
	Z& operator/=(const Z& o) { return *this *= ~o; }
	friend Z operator+(const Z& a, const Z& b) { return Z(a) += b; }
	friend Z operator-(const Z& a, const Z& b) { return Z(a) -= b; }
	friend Z operator*(const Z& a, const Z& b) { return Z(a) *= b; }
	friend Z operator/(const Z& a, const Z& b) { return Z(a) /= b; }
};
using num = Z<1000000007>;

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	const int N = 6;
	vector<vector<num>> p(N, vector<num>(N));
	for (int i = 0; i < N; i++) p[i][i] = num(1);
	int sz; cin >> sz;
	for (int i = 0; i < sz; i++) {
		for (int j = 0; j < sz; j++) {
			int v; cin >> v;
			p[i][j] = num(v) / num(100);
		}
	}

	int F = 20;
	vector<num> a(1 << F, 0), b(1 << F, 0);
	vector<int> maskA, maskB;

	// generate all 3-combinations of 6 vertices
	for (int i = 0; i < N; i++) {
		for (int j = i + 1; j < N; j++) { // different order but same set
			for (int k = j + 1; k < N; k++) {
				int msk = (1 << i) | (1 << j) | (1 << k);
				maskA.push_back(msk);
				maskB.push_back(((1 << N) - 1) ^ msk);
			}
		}
	}
	assert((int)maskA.size() == F);

	auto fill = [&](int t, vector<int>& masks, vector<num>& arr) {
		for (int e = 0; e < (1 << 18); ++e) {
			num cur = 1;
			int edge[3] = {0,0,0};
			for (int i = 0; i < 18; ++i) {
				int bit = (e >> i) & 1;
				num pr = p[(i / N) * 2 + t][i % N];
				cur *= bit ? pr : (num(1) - pr);
				edge[i / N] |= bit << (i % N);
			}
			int good = 0;
			for (int idx = 0; idx < F; idx++) {
				int msk = masks[idx];
				int r[3];
				for (int q = 0; q < 3; q++) r[q] = edge[q] & msk;
				if (r[0] && r[1] && r[2] && __builtin_popcount(r[0]|r[1]|r[2]) == 3) {
					int u = __builtin_popcount(r[0]|r[1]);
					int v = __builtin_popcount(r[0]|r[2]);
					int w = __builtin_popcount(r[1]|r[2]);
					if (u>=2 && v>=2 && w>=2) good |= 1 << idx;
				}
			}
			arr[good] += cur;
		}
	};
	fill(0, maskA, a);
	fill(1, maskB, b);

	for (int i = 0; i < F; i++) {
		for (int mask = 0; mask < (1 << F); mask++) {
			if (!((mask >> i) & 1)) a[mask ^ (1 << i)] += a[mask];
		}
	}

	num ans = 0;
	for (int mask = 0; mask < (1 << F); mask++) {
		ans += a[mask] * b[((1 << F) - 1) ^ mask];
	}
	ans = 1 - ans;
	cout << (int)ans << '\n';
	return 0;
}

