                    mm |= (1<<data[i]);
                }
                if(R==N) mm ^= (1<<N)-1;
                s |= (1 << maskValue[mm]);
                comb_next:;
                // increment data
                for(int i=len-1; i>=0; i--){
                    if(data[i] == N-1){ data[i]=0; }
                    else { data[i]++; break; }
                }
                // check if overflow all zeros
                bool isAllZero = true;
                for(int i=0;i<len;i++) if(data[i]!=0){ isAllZero=false; break; }
                if(isAllZero && N>0) done=true; // since we started from all zero? Actually we need to stop when we return to all zeros after increment.
            }
            handle(s, pr);
            next_edge:;
        }
    };
    assert(mid<N);
    process(0,mid,[&](int s, modular p){ sum[s]+=p; });
    for(int d=1; d<(int)sum.size(); d<<=1)
        for(int i=0;i<(int)sum.size();i++)
            if((i&d)==0) sum[i|d]+=sum[i];
    modular ans=0;
    process(mid,N,[&](int s, modular p){ ans += p*(sum.back() - sum[sum.size()-1-s]); });
    std::cout << (int)ans << '\n';
}

