using modular=Modular<1000000007>;

int main(){
    std::ios::sync_with_stdio(0);std::cin.tie(0);
    int n;
    std::cin >> n;
    std::vector<modular> p(n*n);
    for(int i=0; i<n*n; ++i) {
        int u; std::cin>>u;
        p[i] = modular(1) / 100 * u;
    }

    std::vector<modular> tot;
    int m = n/2;

    // Build maskValue and size of tot
    std::array<int,1<<6> mv;
    int sz = 0;
    for(int mask=0; mask<(1<<6); ++mask) {
        if(__builtin_popcount(mask)==m) mv[mask] = sz++;
        else mv[mask] = -1;
    }
    tot.resize(1<<sz);

    auto handle = [&](int L, int R, auto call) {
        int len = R-L;
        int maxEdge = 1<<(len*n);
        for(int edge=0; edge<maxEdge; ++edge) {
            modular prob = 1;
            bool valid = true;
            for(int tmp=edge, idx=L*n; idx<R*n; ++idx, tmp>>=1) {
                modular term = (tmp&1) ? p[idx] : (1-p[idx]);
                prob *= term;
                if(prob == 0) { valid=false; break; }
            }
            if(!valid) continue;

            int matchSets = 0;
            std::array<char,3> d;
            d.fill(0);
            bool any = true;
            while(any) {
                int mm = 0;
                bool ok = true;
                for(int i=0;i<len;i++){
                    int bit = (edge >> (i*n + d[i])) & 1;
                    if(!bit) { ok=false; break; }
                    if(mm & (1<<d[i])) { ok=false; break; }
                    mm |= 1<<d[i];
                }
                if(ok) {
                    if(R==n) mm ^= (1<<n)-1;
                    matchSets |= (1 << mv[mm]);
                }
                // increment d
                int i = len-1;
                while(i>=0 && d[i]==n-1){ d[i]=0; --i; }
                if(i>=0) ++d[i];
                else any = false;
            }
            call(matchSets, prob);
        }
    };

    handle(0, m, [&](int s, modular p){ tot[s] += p; });
    for(int d=1; d<(int)tot.size(); d<<=1)
        for(int i=0;i<(int)tot.size();i++)
            if((i&d)==0) tot[i|d] += tot[i];

    modular ans = 0;
    handle(m, n, [&](int s, modular p){ ans += p * (tot.back() - tot[tot.size()-1-s]); });
    std::cout << (int)ans << '\n';
}

