using modular=Modular<1000000007>;

int main(){
    std::ios::sync_with_stdio(0);std::cin.tie(0);
    int n; std::cin>>n;
    std::vector<std::vector<modular>> prob(n, std::vector<modular>(n));
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        int x; std::cin>>x;
        prob[i][j] = modular(1)/100 * x;
    }
    int mid = n/2;
    std::vector<modular> sum;
    std::array<int,1<<6> valOfMask;
    int cnt=0;
    for(int m=0; m<(1<<6); ++m){
        if(__builtin_popcount(m)==mid) valOfMask[m]=cnt++;
        else valOfMask[m]=-1;
    }
    sum.resize(1<<cnt);
    auto run = [&](int L, int R, auto cb){
        int len = R-L;
        for(int mask=0; mask<(1<<(len*n)); ++mask){
            modular p=1;
            for(int t=mask, i=L; i<R; ++i){
                for(int j=0;j<n;j++, t>>=1){
                    modular x = (t&1) ? prob[i][j] : (1-prob[i][j]);
                    p *= x;
                    if(p==0) goto SKIP;
                }
            }
            // enumerate assignments
            int sets = 0;
            std::array<char,3> assign;
            assign.fill(0);
            bool notDone = true;
            while(notDone) {
                int msk = 0;
                bool good = true;
                for(int i=0;i<len;i++){
                    int bit = (mask >> (i*n + assign[i])) & 1;
                    if(!bit) { good=false; break; }
                    if(msk & (1<<assign[i])) { good=false; break; }
                    msk |= 1<<assign[i];
                }
                if(good) {
                    if(R==n) msk ^= (1<<n)-1;
                    sets |= (1<<valOfMask[msk]);
                }
                // increment assign
                int idx = len-1;
                while(idx>=0 && assign[idx]==n-1){ assign[idx]=0; --idx; }
                if(idx>=0) ++assign[idx];
                else notDone=false;
            }
            cb(sets,p);
            SKIP:;
        }
    };
    run(0,mid,[&](int s, modular p){ sum[s]+=p; });
    // subset sum
    for(int d=1; d<(int)sum.size(); d<<=1)
        for(int i=0;i<(int)sum.size();i++)
            if((i&d)==0) sum[i|d]+=sum[i];
    modular ans=0;
    run(mid,n,[&](int s, modular p){ ans += p * (sum.back() - sum[sum.size()-1-s]); });
    std::cout << (int)ans << '\n';
}

