using modular=Modular<1000000007>;

int main(){
    std::ios::sync_with_stdio(0);std::cin.tie(0);
    int N; std::cin>>N;
    auto prob = new modular[N*N];
    for(int i=0;i<N*N;i++){
        int x; std::cin>>x;
        prob[i] = modular(1) / 100 * x;
    }
    int mid = N/2;
    std::vector<modular> total;
    std::array<int, 1<<6> maskToIdx;
    int idxCount = 0;
    for(int mask=0; mask<(1<<6); mask++) {
        if(__builtin_popcount(mask)==mid) maskToIdx[mask] = idxCount++;
        else maskToIdx[mask] = -1;
    }
    total.resize(1<<idxCount);

    // function to process a half
    auto processHalf = [&](int left, int right, auto callback){
        int len = right-left;
        for(int edge = 0; edge < (1<<(len*N)); ++edge){
            modular p = 1;
            int shift = edge;
            for(int pos = left*N; pos < right*N; ++pos, shift >>= 1){
                modular term = (shift & 1) ? prob[pos] : (1 - prob[pos]);
                p *= term;
                if(p==0) goto skip;
            }
            {
                std::array<char,3> data{};
                int sets = 0;
                while(true){
                    int mm = 0;
                    bool ok = true;
                    for(int i=0;i<len;i++){
                        int pos = i*N + data[i];
                        if(((edge>>pos)&1)==0) { ok=false; break; }
                        if(mm & (1<<data[i])) { ok=false; break; }
                        mm |= (1<<data[i]);
                    }
                    if(ok){
                        if(right==N) mm ^= (1<<N)-1;
                        sets |= (1<<maskToIdx[mm]);
                    }
                    // increment data
                    int i=len-1;
                    for(; i>=0; --i){
                        if(data[i]<N-1){ ++data[i]; break; }
                        else data[i]=0;
                    }
                    if(i<0) break;
                }
                callback(sets, p);
            }
            skip:;
        }
    };

    processHalf(0, mid, [&](int s, modular p){ total[s] += p; });

    for(int d=1; d<(int)total.size(); d<<=1)
        for(int i=0;i<(int)total.size(); i++)
            if(!(i&d)) total[i|d] += total[i];

    modular ans = 0;
    processHalf(mid, N, [&](int s, modular p){ ans += p * (total.back() - total[total.size()-1-s]); });

    delete[] prob;
    std::cout << (int)ans << '\n';
}

