using modular=Modular<1000000007>;

// A class to encapsulate the solution
class Solution {
public:
    int n, mid;
    std::vector<modular> prob;
    std::vector<modular> total;
    std::array<int,1<<6> idxOfMask;
    Solution(int n, std::istream& in) : n(n) {
        mid = n/2;
        prob.resize(n*n);
        for(int i=0;i<n*n;i++){
            int x; in>>x;
            prob[i] = modular(1)/100*x;
        }
        int cnt=0;
        for(int mask=0; mask<(1<<6); mask++){
            if(__builtin_popcount(mask)==mid) idxOfMask[mask]=cnt++;
            else idxOfMask[mask]=-1;
        }
        total.resize(1<<cnt);
    }
    void process(int L, int R, auto callback) {
        int len = R-L;
        for(int edge=0; edge < (1<<(len*n)); edge++) {
            modular p = 1;
            for(int tmp=edge, pos=L*n; pos<R*n; ++pos, tmp>>=1){
                p *= (tmp&1) ? prob[pos] : (1-prob[pos]);
                if(p==0) goto skip;
            }
            // enumerate all choices of data (len elements from 0..n-1)
            std::array<char,3> data;
            data.fill(0);
            bool go = true;
            while(go) {
                int mm=0;
                bool ok = true;
                for(int i=0;i<len;i++){
                    if(((edge>>(i*n+data[i]))&1)==0){ ok=false; break; }
                    if(mm & (1<<data[i])){ ok=false; break; }
                    mm |= 1<<data[i];
                }
                if(ok){
                    if(R==n) mm ^= (1<<n)-1;
                    callback( (1<<idxOfMask[mm]), p);
                }
                // increment data
                int i=len-1;
                for(; i>=0; --i){
                    if(data[i] < n-1){ ++data[i]; break; }
                    else data[i]=0;
                }
                if(i<0) go=false;
            }
            skip:;
        }
    }
    void run() {
        process(0, mid, [&](int s, modular p){ total[s]+=p; });
        // subset sum
        for(int d=1; d<(int)total.size(); d<<=1)
            for(int i=0;i<(int)total.size(); i++)
                if((i&d)==0) total[i|d]+=total[i];
        modular ans=0;
        process(mid, n, [&](int s, modular p){ ans += p * (total.back() - total[total.size()-1-s]); });
        std::cout << (int)ans << '\n';
    }
};

int main(){
    std::ios::sync_with_stdio(0);std::cin.tie(0);
    int n; std::cin>>n;
    Solution sol(n, std::cin);
    sol.run();
}

