#include <bits/stdc++.h>
using namespace std;
using LL = long long;
const int MOD = 1000000007;
const int NN = 1 << 7;

int n;
int p[NN][NN], prod[NN][NN];
int pc[NN], id[NN];
array<vector<int>, NN> masks;
LL q[NN][NN];
map<pair<int, LL>, int> memo;

inline void addmod(int &a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
}

int power(int a, int e, int m) {
    int r = 1;
    while (e) {
        if (e & 1) r = (LL)r * a % m;
        a = (LL)a * a % m;
        e >>= 1;
    }
    return r;
}

int dfs(int curLevel, LL state) {
    if (state == 0) return 0;
    if (curLevel == n) return 1;
    auto it = memo.find({curLevel, state});
    if (it != memo.end()) return it->second;

    int ans = 0;
    for (int picked = 1; picked < (1 << n); ++picked) {
        LL nstate = 0;
        for (int idx = 0; idx < (int)masks[curLevel].size(); ++idx) {
            if (((state >> idx) & 1LL) == 0) continue;
            int cur = masks[curLevel][idx];
            nstate |= q[cur][picked - (picked & cur)];
        }
        addmod(ans, (LL)prod[curLevel][picked] * dfs(curLevel + 1, nstate) % MOD);
    }
    memo[{curLevel, state}] = ans;
    return ans;
}

