#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;
using LL = long long;
const int MOD = 1000000007;
const int NN = 1 << 7;

int n;
int p[NN][NN], prob[NN][NN];
int pcnt[NN], idx[NN];
vector<int> bucket[NN];
ull trans[NN][NN];

int modpow(int a, int e, int m) {
    int r = 1;
    for (; e; e >>= 1, a = (LL)a * a % m)
        if (e & 1) r = (LL)r * a % m;
    return r;
}

int solve(int step, ull state) {
    static map<pair<int, ull>, int> memo;
    if (state == 0) return 0;
    if (step == n) return 1;

    pair<int, ull> key = {step, state};
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;

    int ans = 0;
    for (int picked = (1 << n) - 1; picked >= 1; --picked) {
        ull ns = 0;
        for (int k = 0; k < (int)bucket[step].size(); ++k) {
            if ((state >> k) & 1ULL) {
                int cur = bucket[step][k];
                int nxt = picked - (picked & cur);
                ns |= trans[cur][nxt];
            }
        }
        ans = (ans + (LL)prob[step][picked] * solve(step + 1, ns)) % MOD;
    }

    memo[key] = ans;
    return ans;
}

