    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            scanf("%d", &p[i][j]);
            p[i][j] = (LL)p[i][j] * inv100 % MOD;
        }

    for (int i = 0; i < n; ++i)
        for (int mask = 0; mask < (1 << n); ++mask) {
            int prod = 1;
            for (int j = 0; j < n; ++j)
                if ((mask >> j) & 1)
                    prod = (LL)prod * p[i][j] % MOD;
                else
                    prod = (LL)prod * (MOD + 1 - p[i][j]) % MOD;
            prob[i][mask] = prod;
        }

    for (int mask = 0; mask < (1 << n); ++mask) {
        pcnt[mask] = __builtin_popcount(mask);
        bucket[pcnt[mask]].push_back(mask);
        idx[mask] = (int)bucket[pcnt[mask]].size() - 1;
    }

    for (int mask = 0; mask < (1 << n); ++mask) {
        for (int bit = 0; bit < n; ++bit)
            if (!((mask >> bit) & 1))
                trans[mask][1 << bit] = 1ULL << idx[mask | (1 << bit)];
        for (int sub = 1; sub < (1 << n); ++sub) {
            int low = sub & -sub;
            trans[mask][sub] = trans[mask][low] | trans[mask][sub ^ low];
        }
    }

