#include <bits/stdc++.h>
using namespace std;

const int MAXS = 100000 + 10;
const int MOD = 1000000007;
using ull = unsigned long long;

int n, cnt = 0;
int nxtState[MAXS][64];
int prob[10][10];
int transProb[10][64];
int dp[10][MAXS];
map<ull,int> mp;

int modPow(int a,int b) {
    int res = 1;
    while(b) {
        if(b & 1) res = 1LL * res * a % MOD;
        a = 1LL * a * a % MOD;
        b >>= 1;
    }
    return res;
}

int construct(ull s) {
    auto it = mp.find(s);
    if(it != mp.end()) return it->second;
    int cur = ++cnt;
    mp[s] = cur;
    int M = 1 << n;
    for(int mask = 0; mask < M; ++mask) {
        ull ns = s;
        for(int j = 0; j < M; ++j) {
            for(int k = 0; k < n; ++k) {
                if( ((j >> k) & 1) && ((mask >> k) & 1) && ((s >> (j ^ (1 << k))) & 1) ) {
                    ns |= (1ull << j);
                }
            }
        }
        nxtState[cur][mask] = construct(ns);
    }
    return cur;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    construct(1);

    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < n; ++j) {
            cin >> prob[i][j];
            prob[i][j] = 1LL * prob[i][j] * modPow(100, MOD - 2) % MOD;
        }
    }

    for(int i = 0; i < n; ++i) {
        for(int mask = 0; mask < (1 << n); ++mask) {
            transProb[i][mask] = 1;
            for(int k = 0; k < n; ++k) {
                if((mask >> k) & 1)
                    transProb[i][mask] = 1LL * transProb[i][mask] * prob[k][i] % MOD;
                else
                    transProb[i][mask] = 1LL * transProb[i][mask] * (MOD + 1 - prob[k][i]) % MOD;
            }
        }
    }

    dp[0][1] = 1;
    for(int i = 0; i < n; ++i) {
        for(int j = 1; j <= cnt; ++j) {
            for(int mask = 0; mask < (1 << n); ++mask) {
                int to = nxtState[j][mask];
                dp[i + 1][to] = (dp[i + 1][to] + 1LL * dp[i][j] * transProb[i][mask]) % MOD;
            }
        }
    }

    if(n < 6)
        cout << dp[n][mp[(1ull << (1 << n)) - 1]] << '\n';
    else
        cout << dp[n][mp[ULLONG_MAX]] << '\n';

    return 0;
}

