#include <bits/stdc++.h>
using namespace std;
using ll = long long;
constexpr ll MOD = 1000000007LL;
constexpr ll INV = 570000004LL;
constexpr int MN = 22;
using vi = vector<int>;
using vll = vector<ll>;

ll p[MN][MN];
vi permsA[20];
vi permsB[20];
ll bmA[1<<20];
ll bmB[1<<20];
ll f[1<<20];

void computePerms() {
    int arr[6] = {0,1,2,3,4,5};
    int idx = 0;
    do {
        if (arr[0] < arr[1] && arr[1] < arr[2] && arr[3] < arr[4] && arr[4] < arr[5]) {
            permsA[idx] = {arr[0], arr[1], arr[2]};
            permsB[idx] = {arr[3], arr[4], arr[5]};
            idx++;
        }
    } while (next_permutation(arr, arr+6));
}

void buildMaskProb(int mask, ll& prob1, ll& prob2) {
    prob1 = 1;
    prob2 = 1;
    for (int j = 0; j < 6; ++j) {
        for (int k = 0; k < 3; ++k) {
            int res = j*3 + k;
            if (mask & (1<<res)) {
                prob1 = prob1 * p[j][k] % MOD;
                prob2 = prob2 * p[j][k+3] % MOD;
            } else {
                prob1 = prob1 * (1+MOD-p[j][k]) % MOD;
                prob2 = prob2 * (1+MOD-p[j][k+3]) % MOD;
            }
        }
    }
}

bool okPermutation(vi perm, int mask) {
    int ord[3] = {0,1,2};
    do {
        bool ok = true;
        for (int j = 0; j < 3; ++j) {
            int val = perm[ord[j]];
            int loc = val*3 + j;
            if (!(mask & (1<<loc))) {
                ok = false;
                break;
            }
        }
        if (ok) return true;
    } while (next_permutation(ord, ord+3));
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    computePerms();

    int n;
    cin >> n;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            cin >> p[i][j];
            p[i][j] = (p[i][j] * INV) % MOD;
        }

    for (int i = 0; i < 6; ++i) {
        for (int j = n; j <= 5; ++j) {
            if (i == j) p[i][j] = 1;
            else { p[i][j] = 0; p[j][i] = 0; }
        }
    }
    n = 6;

    for (int mask = 0; mask < (1<<18); ++mask) {
        ll prob1, prob2;
        buildMaskProb(mask, prob1, prob2);
        int bma = 0, bmb = 0;
        for (int ot = 0; ot < 20; ++ot) {
            if (okPermutation(permsA[ot], mask)) bma |= (1<<ot);
            if (okPermutation(permsB[ot], mask)) bmb |= (1<<ot);
        }
        bmA[bma] = (bmA[bma] + prob1) % MOD;
        bmB[bmb] = (bmB[bmb] + prob2) % MOD;
    }

    copy(bmA, bmA+(1<<20), f);
    for (int i = 0; i < 20; ++i) {
        for (int mask = 0; mask < (1<<20); ++mask) {
            if (mask & (1<<i)) {
                f[mask] = (f[mask] + f[mask ^ (1<<i)]) % MOD;
            }
        }
    }

    ll ans = 0;
    int full = (1<<20)-1;
    for (int i = 0; i < (1<<20); ++i) {
        ans = (ans + bmB[i] * f[full ^ i]) % MOD;
    }
    cout << (1 + MOD - ans) % MOD << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
static const ll mod = 1000000007LL;
static const ll inv = 570000004LL;
const int N = 22;
ll a[N][N];
vector<int> permA[20], permB[20];
ll dpA[1<<20], dpB[1<<20], sum[1<<20];

void gen_perms() {
    int x[] = {0,1,2,3,4,5};
    int cnt = 0;
    do {
        if (x[0]<x[1] && x[1]<x[2] && x[3]<x[4] && x[4]<x[5]) {
            permA[cnt] = vector<int>{x[0], x[1], x[2]};
            permB[cnt] = vector<int>{x[3], x[4], x[5]};
            ++cnt;
        }
    } while (next_permutation(x, x+6));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    gen_perms();

    int n;
    cin >> n;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
            a[i][j] = (a[i][j] * inv) % mod;
        }

    for (int i = 0; i < 6; ++i)
        for (int j = n; j < 6; ++j) {
            if (i == j) a[i][j] = 1;
            else { a[i][j] = 0; a[j][i] = 0; }
        }

    int m = 6;
    for (int bit = 0; bit < (1<<18); ++bit) {
        ll p1 = 1, p2 = 1;
        int b1 = 0, b2 = 0;
        for (int r = 0; r < 6; ++r) {
            for (int c = 0; c < 3; ++c) {
                int loc = r*3 + c;
                ll x = a[r][c], y = a[r][c+3];
                if (bit & (1<<loc)) {
                    p1 = p1 * x % mod;
                    p2 = p2 * y % mod;
                } else {
                    p1 = p1 * (mod+1-x) % mod;
                    p2 = p2 * (mod+1-y) % mod;
                }
            }
        }
        for (int pr = 0; pr < 20; ++pr) {
            auto &pa = permA[pr];
            auto &pb = permB[pr];
            bool okA = false, okB = false;
            vector<int> ord = {0,1,2};
            do {
                bool goodA = true, goodB = true;
                for (int j = 0; j < 3; ++j) {
                    int la = pa[ord[j]]*3 + j;
                    int lb = pb[ord[j]]*3 + j;
                    if (!(bit & (1<<la))) goodA = false;
                    if (!(bit & (1<<lb))) goodB = false;
                }
                if (goodA) okA = true;
