                sum[mask] %= mod;
            }

    ll ans = 0;
    for (int i = 0; i < (1<<20); ++i)
        ans = (ans + dpB[i] * sum[((1<<20)-1)^i]) % mod;
    cout << (1 + mod - ans) % mod << '\n';
    return 0;
