using ll = long long;
constexpr ll MOD = 1000000007LL;
constexpr ll INV = 570000004LL;

int p[22][22];
vector<array<int,3>> A, B;
ll pa[1<<20], pb[1<<20], pc[1<<20];

void init() {
    array<int,6> v = {0,1,2,3,4,5};
    int cnt = 0;
    do {
        if (v[0] < v[1] && v[1] < v[2] && v[3] < v[4] && v[4] < v[5]) {
            A.push_back({v[0], v[1], v[2]});
            B.push_back({v[3], v[4], v[5]});
            ++cnt;
        }
    } while (next_permutation(v.begin(), v.end()));
}

bool check(array<int,3> perm, int mask) {
    int order[3] = {0,1,2};
    do {
        bool ok = true;
        for (int j = 0; j < 3; ++j) {
            int pos = perm[order[j]] * 3 + j;
            if (!(mask & (1<<pos))) { ok = false; break; }
        }
        if (ok) return true;
    } while (next_permutation(order, order+3));
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    init();

