    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            cin >> p[i][j];
            p[i][j] = (ll(p[i][j]) * INV) % MOD;
        }
    for (int i = 0; i < 6; ++i)
        for (int j = n; j < 6; ++j) {
            if (i == j) p[i][j] = 1;
            else { p[i][j] = 0; p[j][i] = 0; }
        }

    for (int mask = 0; mask < (1<<18); ++mask) {
        ll prob1 = 1, prob2 = 1;
        int bitsA = 0, bitsB = 0;
        for (int i = 0; i < 6; ++i) {
            for (int j = 0; j < 3; ++j) {
                int idx = i*3+j;
                int x = p[i][j], y = p[i][j+3];
                if (mask & (1<<idx)) {
                    prob1 = prob1 * x % MOD;
                    prob2 = prob2 * y % MOD;
                } else {
                    prob1 = prob1 * (MOD+1-x) % MOD;
                    prob2 = prob2 * (MOD+1-y) % MOD;
                }
            }
        }
        for (int t = 0; t < 20; ++t) {
            if (check(A[t], mask)) bitsA |= (1<<t);
            if (check(B[t], mask)) bitsB |= (1<<t);
        }
        pa[bitsA] = (pa[bitsA] + prob1) % MOD;
        pb[bitsB] = (pb[bitsB] + prob2) % MOD;
