	for(int len=1; len<lim; len<<=1)
		for(int i=0; i<lim; i+=len*2)
			for(int j=0; j<len; ++j)
				reduce(a[i+j] += a[i+j+len] - mod);
}
inline void fwt2(int * a, int lim){
	for(int len=1; len<lim; len<<=1)
		for(int i=0; i<lim; i+=len*2)
			for(int j=0; j<len; ++j)
				a[i+j] = (a[i+j] - a[i+j+len] + mod) % mod;
}
main(){
	ios::sync_with_stdio(false),in.tie(0);
	in>>n;
	rep(i,0,n-1) rep(j,0,n-1){
		in>>a[i][j];
		a[i][j] = ll(a[i][j]) * inv(100) % mod;
		b[i * n + j] = a[i][j];
	}
	rep(i,0,(1<<n)-1){
		v[pc(i)].push_back(i);
		mp[i] = tot[pc(i)]++;
	}
	const int m = n / 2;
	rep(i,0,(1<<(m * n))-1){
		int p = 1; int S[3];
		for(int j=0;j<m * n;++j) p = ll(p) * (i >> j & 1 ? b[j] : mod + 1 - b[j]) % mod;
		for(int j=0;j<m;++j) S[j] = (i >> j * n) & ((1 << n) - 1); 
		int st = 0;
		for(int j : v[m]){
			int s[3],tot = 0;
			for(int k=j;k;k&=k-1) s[tot++] = __builtin_ctz(k);
			sort(s,s + m);
			do{
				bool ok = true;
				for(int jj=0;jj<m;++jj)
					if((S[jj] >> s[jj] & 1) == 0) { ok = false; break; }
				if(ok) st |= 1 << mp[j];
			}while(next_permutation(s,s+m));
		}
		f[st] = (f[st] + p) % mod;
	}
	const int M = n - m;
	rep(i,0,(1<<(M * n))-1){
		int p = 1; int S[3];
		for(int j=0;j<M * n;++j) p = ll(p) * (i >> j & 1 ? b[j + n * m] : mod + 1 - b[j + n * m]) % mod;
		for(int j=0;j<M;++j) S[j] = (i >> j * n) & ((1 << n) - 1); 
		int st = 0;
		for(int j : v[n - m]){
			int s[3],tot = 0;
			for(int k=j;k;k&=k-1) s[tot++] = __builtin_ctz(k);
			sort(s,s + M);
			do{
				bool ok = true;
				for(int jj=0;jj<M;++jj) if((S[jj] >> s[jj] & 1) == 0) { ok = false; break; }
				if(ok) st |= 1 << mp[(~j) & (1 << n) - 1];
			}while(next_permutation(s,s+M));
		}
		g[st] = (g[st] + p) % mod;
	}
	int ans = 0;
	fwt(f,1 << tot[m]); fwt(g,1 << tot[m]);
	for(int i=0;i<1<<tot[m];++i) f[i] = ll(f[i]) * g[i] % mod;
	fwt2(f,1<<tot[m]);
	for(int i=1;i<1<<tot[m];++i) ans = (ans + f[i]) % mod;
	out<<ans<<'\n';
}

