void process_half(int start_row, int num_rows, int * arr, int target_size) {
	rep(i,0,(1<<(num_rows * n))-1){
		int p = 1; int S[3];
		for(int j=0;j<num_rows * n;++j) p = ll(p) * (i >> j & 1 ? b[j + start_row * n] : mod + 1 - b[j + start_row * n]) % mod;
		for(int j=0;j<num_rows;++j) S[j] = (i >> j * n) & ((1 << n) - 1); 
		int st = 0;
		for(int j : v[target_size]){
			int s[3],tot = 0;
			for(int k=j;k;k&=k-1) s[tot++] = __builtin_ctz(k);
			sort(s,s + target_size);
			do{
				bool ok = true;
				for(int jj=0;jj<target_size;++jj)
					if((S[jj] >> s[jj] & 1) == 0) { ok = false; break; }
				if(ok) {
					int idx = (target_size == m) ? mp[j] : mp[(~j) & (1 << n) - 1];
					st |= 1 << idx;
				}
			}while(next_permutation(s,s+target_size));
		}
		arr[st] = (arr[st] + p) % mod;
	}
}
