      kraw.pb({i, j});
  LL odw = pot(100, mod - 2);
  for(int k = 0;k < 2;k++)
    for(int i = 0;i < (1<<18);i++)
    {
      LL p = 1LL;
      VPII xd;
      for(int j = 0;j < 18;j++)
        if((1<<j) & i)
        {
          p = p * tab[kraw[j + k * 18].fi][kraw[j + k * 18].se] % mod * odw % mod;//pot(100, mod - 2) % mod;
          xd.pb(kraw[j + k * 18]);
        }
        else
        {
          p = p * (100 - tab[kraw[j + k * 18].fi][kraw[j + k * 18].se]) % mod * odw % mod;//* pot(100, mod - 2) % mod;
        }
      int cur = daj(xd, k);
      dp[cur][k] += p;
      dp[cur][k] %= mod;
    }
  LL res = 1;
  for(int i = 0;i < 20;i++)
    for(int j = 0;j < (1<<20);j++)
      if((1<<i) & j)
      {
        dp[j][0] += dp[j ^ (1<<i)][0];
        dp[j][0] %= mod;
      }
  for(int i = 0;i < (1<<20);i++)
    res = (res - dp[i][0] * dp[((1<<20) - 1) ^ i][1]) % mod;
  res += mod;
  res %= mod;
  cout<<res;
	return 0;
}

