const int MOD = 1000000007;
struct Mint {
	ll v;
	Mint(ll _v=0){ v = _v % MOD; if(v<0) v+=MOD; }
	Mint& operator+=(const Mint& o){ v += o.v; if(v>=MOD) v-=MOD; return *this; }
	Mint& operator-=(const Mint& o){ v -= o.v; if(v<0) v+=MOD; return *this; }
	Mint& operator*=(const Mint& o){ v = (v*o.v)%MOD; return *this; }
	Mint& operator/=(const Mint& o){ return *this *= o.inv(); }
	Mint operator+(const Mint& o) const { return Mint(*this) += o; }
	Mint operator-(const Mint& o) const { return Mint(*this) -= o; }
	Mint operator*(const Mint& o) const { return Mint(*this) *= o; }
	Mint operator/(const Mint& o) const { return Mint(*this) /= o; }
	Mint operator-() const { return Mint(-v); }
	bool operator==(const Mint& o) const { return v==o.v; }
	bool operator!=(const Mint& o) const { return v!=o.v; }
	Mint inv() const {
		ll a = v, b = MOD, x = 1, y = 0;
		while(b){ ll t = a/b; swap(a -= t*b, b); swap(x -= t*y, y); }
		return Mint(x < 0 ? x + MOD : x);
	}
	Mint pow(ll p) const {
		if(p<0) return inv().pow(-p);
		Mint a=1, x=*this;
		while(p){ if(p&1) a*=x; x*=x; p>>=1; }
		return a;
	}
	friend istream& operator>>(istream& in, Mint& x){ ll t; in>>t; x = Mint(t); return in; }
