			for(int t = 0; t < (1<<n); ++t) if(b[t]) ones.push_back(t);
			for(int e = 0; e < (1<<n); ++e){
				mint pr = 1;
				for(int j = 0; j < n; ++j){
					if(B(e,j)) pr *= p[i][j];
					else pr *= mint(1) - p[i][j];
				}
				BS nb;
				for(int x : ones){
					for(int r = 0; r < n; ++r){
						if(B(e,r) && !B(x,r)) nb[x | (1<<r)] = true;
					}
				}
				nxt[nb] += it->second * pr;
			}
		}
		cur = nxt;
		nxt.clear();
		++i;
	}
	mint ans = 0;
	for(auto it = cur.begin(); it != cur.end(); ++it) if(it->first[(1<<n)-1]) ans += it->second;
	cout << ans << endl;
}

