inline void modadd(int &a, int b) {
    a += b;
    if (a >= mod) a -= mod;
    if (a < 0) a += mod;
}

struct Mat {
    int n;
    int v[maxn][maxn];
    Mat(int nn = 0, int x = 0) : n(nn) {
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                v[i][j] = (i == j) ? x : 0;
    }
    int* operator[](int i) { return v[i]; }
    const int* operator[](int i) const { return v[i]; }
    Mat mul(const Mat& b) const {
        Mat res(n, 0);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j) {
                int s = 0;
                for (int k = 0; k < n; ++k)
                    modadd(s, (ll)v[i][k] * b[k][j] % mod);
                res[i][j] = s;
            }
        return res;
    }
    Mat add(const Mat& b) const {
        Mat res(n, 0);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                res[i][j] = (v[i][j] + b[i][j]) % mod;
        return res;
    }
    bool equal(const Mat& b) const {
        if (n != b.n) return false;
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (v[i][j] != b[i][j]) return false;
        return true;
    }
};

Mat matpow(Mat a, ll b) {
    Mat r(a.n, 1);
    while (b) {
        if (b & 1) r = r.mul(a);
        a = a.mul(a);
        b >>= 1;
    }
    return r;
}

