#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007LL;

struct Mat {
    int n;
    vector<ll> v;
    Mat(int sz = 0) : n(sz), v(sz * sz, 0) {}
    ll& at(int r, int c) { return v[r * n + c]; }
    ll at(int r, int c) const { return v[r * n + c]; }
    void make_identity() {
        fill(v.begin(), v.end(), 0);
        for (int i = 0; i < n; ++i) at(i, i) = 1;
    }
};

Mat mul(const Mat& a, const Mat& b) {
    Mat r(a.n);
    int n = a.n;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            ll val = 0;
            for (int k = 0; k < n; ++k) {
                val += a.at(i, k) * b.at(k, j);
                val %= MOD;
            }
            r.at(i, j) = val;
        }
    }
    return r;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    ll N, K;
    cin >> N >> K;
    vector<int> digit;
    while (N) {
        digit.push_back((int)(N % K));
        N /= K;
    }
    int k = (int)K;
    int len = (int)digit.size();
    auto idx = [k](int p, int d) { return p * k + d; };

    vector<Mat> base(60 * k, Mat(k + 1));
    for (int d = 0; d < k; ++d) {
        base[idx(0, d)].make_identity();
        for (int r = 0; r <= k; ++r) base[idx(0, d)].at(r, d) = 1;
    }
    vector<Mat> pref(60 * k, Mat(k + 1)), suf(60 * k, Mat(k + 1));
    for (int p = 1; p < len; ++p) {
        pref[idx(p - 1, 0)] = base[idx(p - 1, 0)];
        for (int j = 1; j < k; ++j)
            pref[idx(p - 1, j)] = mul(pref[idx(p - 1, j - 1)], base[idx(p - 1, j)]);
        suf[idx(p - 1, k - 1)] = base[idx(p - 1, k - 1)];
        for (int j = k - 2; j >= 0; --j)
            suf[idx(p - 1, j)] = mul(base[idx(p - 1, j)], suf[idx(p - 1, j + 1)]);
        base[idx(p, 0)] = pref[idx(p - 1, k - 1)];
        for (int j = 1; j < k; ++j)
            base[idx(p, j)] = mul(suf[idx(p - 1, j)], pref[idx(p - 1, j - 1)]);
    }
    Mat trans(k + 1);
    trans.make_identity();
    int sum = 0;
    for (int p = len - 1; p >= 0; --p) {
        int x = digit[p];
        for (int j = 0; j < x; ++j) {
            trans = mul(trans, base[idx(p, sum)]);
            ++sum;
            if (sum == k) sum = 0;
        }
    }
    ll ans = 1;
    for (int i = 0; i < k; ++i) ans = (ans + trans.at(k, i)) % MOD;
    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007LL;

struct Mat {
    int n;
    vector<vector<ll>> a;
    Mat(int sz = 0) : n(sz), a(sz, vector<ll>(sz, 0)) {}
};

Mat identity(int n) {
    Mat r(n);
    for (int i = 0; i < n; ++i) r.a[i][i] = 1;
    return r;
}

Mat multiply(const Mat& x, const Mat& y) {
    Mat r(x.n);
    for (int i = 0; i < x.n; ++i)
        for (int j = 0; j < x.n; ++j)
            for (int k = 0; k < x.n; ++k)
                r.a[i][j] = (r.a[i][j] + x.a[i][k] * y.a[k][j]) % MOD;
    return r;
}

void ensure_level(int level, vector<vector<Mat>>& base, int k) {
    if (!base[level].empty()) return;
    if (level == 0) {
        base[level].reserve(k);
        for (int d = 0; d < k; ++d) {
            Mat m = identity(k + 1);
            for (int r = 0; r <= k; ++r) m.a[r][d] = 1;
            base[level].push_back(m);
        }
        return;
    }
    ensure_level(level - 1, base, k);
    vector<Mat> pref(k), suf(k);
    pref[0] = base[level - 1][0];
    for (int j = 1; j < k; ++j)
        pref[j] = multiply(pref[j - 1], base[level - 1][j]);
    suf[k - 1] = base[level - 1][k - 1];
    for (int j = k - 2; j >= 0; --j)
        suf[j] = multiply(base[level - 1][j], suf[j + 1]);
    base[level].push_back(pref[k - 1]);
    for (int j = 1; j < k; ++j)
        base[level].push_back(multiply(suf[j], pref[j - 1]));
}

