#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007LL;
const int MAXL = 60;
const int MAXK = 30;

struct Mat {
    int n;
    ll a[65][65];
};

Mat unit(int n) {
    Mat r;
    r.n = n;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            r.a[i][j] = (i == j);
    return r;
}

Mat mulM(const Mat& x, const Mat& y) {
    Mat r;
    r.n = x.n;
    for (int i = 0; i < x.n; ++i)
        for (int j = 0; j < x.n; ++j) {
            r.a[i][j] = 0;
            for (int k = 0; k < x.n; ++k)
                r.a[i][j] = (r.a[i][j] + x.a[i][k] * y.a[k][j]) % MOD;
        }
    return r;
}

static Mat base[MAXL][MAXK], pref[MAXL][MAXK], suf[MAXL][MAXK];

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    ll N, Kll;
    cin >> N >> Kll;
    int K = (int)Kll;
    vector<int> num;
    while (N) {
        num.push_back((int)(N % K));
        N /= K;
    }
    for (int i = 0; i < K; ++i) {
        base[0][i] = unit(K + 1);
        for (int j = 0; j <= K; ++j) {
            base[0][i].a[j][i] = 1;
        }
    }
    for (int i = 1; i < (int)num.size(); ++i) {
        pref[i - 1][0] = base[i - 1][0];
        for (int j = 1; j < K; ++j) {
            pref[i - 1][j] = mulM(pref[i - 1][j - 1], base[i - 1][j]);
        }
        suf[i - 1][K - 1] = base[i - 1][K - 1];
        for (int j = K - 2; j >= 0; --j) {
            suf[i - 1][j] = mulM(base[i - 1][j], suf[i - 1][j + 1]);
        }
        base[i][0] = pref[i - 1][K - 1];
        for (int j = 1; j < K; ++j) {
            base[i][j] = mulM(suf[i - 1][j], pref[i - 1][j - 1]);
        }
    }
    Mat trans = unit(K + 1);
    int sum = 0;
    for (int i = (int)num.size() - 1; i >= 0; --i) {
        int x = num[i];
        for (int j = 0; j < x; ++j) {
            trans = mulM(trans, base[i][sum]);
            ++sum;
            if (sum >= K) sum -= K;
        }
    }
    ll ans = 1;
    for (int i = 0; i < K; ++i) {
        ans += trans.a[K][i];
        ans %= MOD;
    }
    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007LL;
using Mat = vector<vector<ll>>;

Mat make_id(int n) {
    Mat r(n, vector<ll>(n, 0));
    for (int i = 0; i < n; ++i) r[i][i] = 1;
    return r;
}

Mat mul(const Mat& A, const Mat& B) {
    int n = (int)A.size();
    Mat C(n, vector<ll>(n, 0));
    for (int i = 0; i < n; ++i) {
        for (int k = 0; k < n; ++k) {
            if (A[i][k] == 0) continue;
            for (int j = 0; j < n; ++j) {
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
            }
        }
    }
    return C;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll N, Kll;
    cin >> N >> Kll;
    int K = (int)Kll;
    vector<int> num;
    while (N) {
        num.push_back((int)(N % K));
        N /= K;
    }
    int len = (int)num.size();

    vector<vector<Mat>> base(60, vector<Mat>(K, Mat(K + 1, vector<ll>(K + 1, 0))));
    for (int i = 0; i < K; ++i) {
        base[0][i] = make_id(K + 1);
        for (int r = 0; r <= K; ++r) base[0][i][r][i] = 1;
    }
    vector<vector<Mat>> pref(60, vector<Mat>(K, Mat(K + 1, vector<ll>(K + 1, 0))));
    vector<vector<Mat>> suf(60, vector<Mat>(K, Mat(K + 1, vector<ll>(K + 1, 0))));
    for (int p = 1; p < len; ++p) {
        pref[p - 1][0] = base[p - 1][0];
        for (int j = 1; j < K; ++j)
            pref[p - 1][j] = mul(pref[p - 1][j - 1], base[p - 1][j]);
        suf[p - 1][K - 1] = base[p - 1][K - 1];
        for (int j = K - 2; j >= 0; --j)
            suf[p - 1][j] = mul(base[p - 1][j], suf[p - 1][j + 1]);
        base[p][0] = pref[p - 1][K - 1];
        for (int j = 1; j < K; ++j)
            base[p][j] = mul(suf[p - 1][j], pref[p - 1][j - 1]);
    }
    Mat trans = make_id(K + 1);
    int sum = 0;
    for (int p = len - 1; p >= 0; --p) {
        int x = num[p];
        for (int j = 0; j < x; ++j) {
            trans = mul(trans, base[p][sum]);
            ++sum;
            if (sum == K) sum = 0;
        }
    }
    ll ans = 1;
    for (int i = 0; i < K; ++i) ans = (ans + trans[K][i]) % MOD;
    cout << ans << '\n';
    return 0;
}

