        for(i = 1; i < m; i++){
            // Rotate rows and columns of bi[t][i-1] to get bi[t][i]
            M tmp = bi[t][i-1];
            for(j = m - 2; j >= 0; j--){
                for(k = 0; k <= m; k++){
                    swap(tmp.s[j][k], tmp.s[j+1][k]);
                }
            }
            for(j = m - 2; j >= 0; j--){
                for(k = 0; k <= m; k++){
                    swap(tmp.s[k][j], tmp.s[k][j+1]);
                }
            }
            bi[t][i] = tmp;
        }
    }
    for(i = 0; i <= m; i++){
        I.n = m + 1;
        I.s[i][i] = 1;
    }
    while(add < n){
        if(add <= n - y){
            add += y;
            I = I * bi[x][z];
            z = (z + 1) % m;
        } else {
            y /= m;
            x--;
        }
    }
    ull ans = 0;
    for(i = 0; i <= m; i++){
        ans = (ans + I.s[i][m]) % MOD;
    }
    printf("%llu\n", ans);
}

#include<bits/stdc++.h>
