#define MOD 1000000007
typedef unsigned long long int ull;
struct M{
    ull s[35][35], n;
    friend M operator * (M a, M b){
        M c;
        c.n = a.n;
        int i, j, k;
        for(i = 0; i < a.n; i++){
            for(j = 0; j < a.n; j++){
                c.s[i][j] = 0;
                for(k = 0; k < a.n; k++){
                    c.s[i][j] += a.s[i][k] * b.s[k][j];
                    c.s[i][j] %= MOD;
                }
            }
        }
        return c;
    }
} bi[65][65], I;
int main(){
    ull n, m, t, x, y, z, add;
    int i, j, k;
    scanf("%llu%llu", &n, &m);
    bi[0][0].n = m + 1;
    for(i = 0; i <= m; i++){
        bi[0][0].s[i][i] = 1;
        bi[0][0].s[0][i] = 1;
    }
    // Compute max power
    x = 0; y = 1;
    while(y * m <= n){
        y *= m;
        x++;
    }
    // Precompute matrices for each power and rotation
    for(t = 0; t <= x; t++){
        if(t){
            bi[t][0] = bi[t-1][0];
            for(i = 1; i < m; i++){
                bi[t][0] = bi[t][0] * bi[t-1][i];
            }
        }
        for(i = 1; i < m; i++){
            bi[t][i] = bi[t][i-1];
            for(j = m - 2; j >= 0; j--){
                for(k = 0; k <= m; k++){
                    swap(bi[t][i].s[j][k], bi[t][i].s[j+1][k]);
                }
            }
            for(j = m - 2; j >= 0; j--){
                for(k = 0; k <= m; k++){
                    swap(bi[t][i].s[k][j], bi[t][i].s[k][j+1]);
                }
            }
        }
    }
    // Initialize I as identity
    I.n = m + 1;
    for(i = 0; i <= m; i++){
        I.s[i][i] = 1;
    }
    // Process digits of n in base m
    ull remaining = n;
    z = 0;
    for(t = x; t >= 0; t--){
        ull power = 1;
        for(int p = 0; p < t; p++) power *= m; // compute m^t
        ull digit = remaining / power;
        for(i = 0; i < digit; i++){
            I = I * bi[t][z];
            z = (z + 1) % m;
        }
        remaining %= power;
    }
    ull ans = 0;
    for(i = 0; i <= m; i++){
        ans = (ans + I.s[i][m]) % MOD;
    }
    printf("%llu\n", ans);
}

