matrix A[64][30], sum[64][30], suf[64][30], ans;
LL N, K;
int dig[70], cnt;

void build(int level) {
    if (level == 0) {
        for (int i = 0; i < K; ++i) {
            for (int j = 0; j <= K; ++j) {
                A[0][i].A[j][j] = 1;
                A[0][i].A[j][i] = 1;
            }
            A[0][i].N = K;
        }
        sum[0][0] = A[0][0];
        for (int i = 1; i < K; ++i) sum[0][i] = sum[0][i-1] * A[0][i];
        suf[0][K-1] = A[0][K-1];
        for (int i = K-2; i >= 0; --i) suf[0][i] = A[0][i] * suf[0][i+1];
        return;
    }
    build(level - 1);
    A[level][0] = suf[level-1][0];
    for (int j = 1; j < K; ++j)
        A[level][j] = suf[level-1][j] * sum[level-1][j-1];
    sum[level][0] = A[level][0];
    for (int j = 1; j < K; ++j) sum[level][j] = sum[level][j-1] * A[level][j];
    suf[level][K-1] = A[level][K-1];
    for (int j = K-2; j >= 0; --j) suf[level][j] = A[level][j] * suf[level][j+1];
}

void process(int idx, int &last) {
    if (idx < 0) return;
    for (int j = 0; j < dig[idx]; ++j)
        ans = ans * A[idx][(j + last) % K];
    last += dig[idx];
    process(idx - 1, last);
}

