    ans = ans * sum[cnt-1][dig[cnt-1] - 1];
    int last = dig[cnt-1];
    process(cnt - 2, last);
    LL res = 0;
    for (int i = 0; i <= K; ++i) res += ans.A[0][i];
    printf("%lld\n", res % MOD);
    return 0;
}

