		hp[i].dp[d][d] = 2;
		hp[i].dp[d][i] = -1;
		hp[i].dp[i][d] = 1;
		hp[i].mark[i] = true;
		md[0].mrg(hp[i]);
		hp[i] = md[0];
	}
	for(int i = 1; i <= (int)v.size(); i++) {
		md[i] = md[i - 1];
		ht = md[i - 1];
		for(int j = 1; j < d; j++) {
			ht.shift(1);
			md[i].mrg(ht);
		}
	}
	node ans = get(m);
	cout << ans.dp[d][d] << endl;
	return 0;
}

