using namespace std;
const int N=65;
const int mod=1e9+7;
int m,len;
LL n,v[N];
struct node
{
	int v[35][35];
	node(){memset(v,0,sizeof(v));}
}S,T[N][35],s1[N][35],s2[N][35];
node operator * (node a,node b)
{
	node c;
	for(int i=0;i<=m;i++)
		for(int j=0;j<=m;j++)
			for(int k=0;k<=m;k++)
				c.v[i][j]=(c.v[i][j]+1ll*a.v[i][k]*b.v[k][j]%mod)%mod;
	return c;
}
int main()
{
	scanf("%lld%d",&n,&m);
	v[0]=n;while(v[len])v[len+1]=v[len]/m,v[len]%=m,len++;
	for(int i=0;i<len;i++)
	{
		if(!i)
		{
			for(int j=0;j<m;j++)
			{
				T[i][j].v[m][m]=1;
				for(int a=0;a<m;a++)
				{
					if(a!=j){T[i][j].v[a][a]=1;continue;}
					for(int b=0;b<=m;b++)T[i][j].v[a][b]=1;
				}
			}
		}
		else
		{
			for(int j=0;j<m;j++)
				if(!j)T[i][j]=s2[i-1][0];
				else T[i][j]=s2[i-1][j]*s1[i-1][j-1];
		}
		s1[i][0]=T[i][0];
		for(int j=1;j<m;j++)s1[i][j]=s1[i][j-1]*T[i][j];
		s2[i][m-1]=T[i][m-1];
		for(int j=m-2;j>=0;j--)s2[i][j]=T[i][j]*s2[i][j+1];
	}
	for(int i=0;i<=m;i++)S.v[0][i]=1;
	for(int i=len-1,j=0;i>=0;i--)
		while(v[i]--)S=S*T[i][j],j=(j+1)%m;
	printf("%d",S.v[0][m]);
	return 0;
}

#include<cstdio>
#include<algorithm>
#include<cstring>
using namespace std;
typedef long long ll;
const int N = 65;
const int MOD = 1000000007;
int m, len;
ll n, digits[N];

struct Mat {
    int a[35][35];
    Mat() { memset(a, 0, sizeof(a)); }
};

Mat mul(const Mat& x, const Mat& y) {
    Mat z;
    for (int i = 0; i <= m; ++i)
        for (int j = 0; j <= m; ++j)
            for (int k = 0; k <= m; ++k)
                z.a[i][j] = (z.a[i][j] + (ll)x.a[i][k] * y.a[k][j] % MOD) % MOD;
    return z;
}

Mat T[N][35], pref[N][35], suff[N][35], cur;

int main() {
    scanf("%lld%d", &n, &m);
    digits[0] = n;
    while (digits[len]) {
        digits[len + 1] = digits[len] / m;
        digits[len] %= m;
        ++len;
    }
    for (int i = 0; i < len; ++i) {
        if (i == 0) {
            for (int j = 0; j < m; ++j) {
                T[i][j].a[m][m] = 1;
                for (int a = 0; a < m; ++a) {
                    if (a != j) {
                        T[i][j].a[a][a] = 1;
                        continue;
                    }
                    for (int b = 0; b <= m; ++b)
                        T[i][j].a[a][b] = 1;
                }
            }
        } else {
            for (int j = 0; j < m; ++j) {
                if (j == 0)
                    T[i][j] = suff[i - 1][0];
                else
                    T[i][j] = mul(suff[i - 1][j], pref[i - 1][j - 1]);
            }
        }
        pref[i][0] = T[i][0];
        for (int j = 1; j < m; ++j)
            pref[i][j] = mul(pref[i][j - 1], T[i][j]);
        suff[i][m - 1] = T[i][m - 1];
        for (int j = m - 2; j >= 0; --j)
            suff[i][j] = mul(T[i][j], suff[i][j + 1]);
    }
    for (int i = 0; i <= m; ++i)
        cur.a[0][i] = 1;
    for (int i = len - 1, j = 0; i >= 0; --i) {
        ll cnt = digits[i];
        while (cnt--) {
            cur = mul(cur, T[i][j]);
            j = (j + 1) % m;
        }
    }
    printf("%d", cur.a[0][m]);
    return 0;
}

#include<cstdio>
#include<cstring>
#include<algorithm>
#define LL long long
using namespace std;
const int MX = 65;
const int MOD = 1000000007;
int M, L;
LL N, A[MX];

struct Matrix {
    int d[35][35];
    Matrix() { memset(d,0,sizeof(d)); }
};

Matrix operator*(const Matrix& X, const Matrix& Y) {
    Matrix Z;
    for (int i=0;i<=M;++i)
        for (int k=0;k<=M;++k) {
            LL t = X.d[i][k];
            if (!t) continue;
            for (int j=0;j<=M;++j)
                Z.d[i][j] = (Z.d[i][j] + t * Y.d[k][j]) % MOD;
        }
    return Z;
}

Matrix T[MX][35], P[MX][35], S[MX][35], R;

int main() {
    scanf("%lld%d",&N,&M);
    A[0]=N; while (A[L]) { A[L+1]=A[L]/M; A[L]%=M; ++L; }
    for (int i=0;i<L;++i) {
        if (i==0) {
            for (int j=0;j<M;++j) {
                T[i][j].d[M][M]=1;
                for (int a=0;a<M;++a) {
                    if (a!=j) { T[i][j].d[a][a]=1; continue; }
                    for (int b=0;b<=M;++b) T[i][j].d[a][b]=1;
                }
            }
        } else {
            for (int j=0;j<M;++j) {
                if (j==0) T[i][j]=S[i-1][0];
                else      T[i][j]=S[i-1][j]*P[i-1][j-1];
            }
        }
