Matrix mul(const Matrix& a, const Matrix& b) {
    static long long tmp[MAXM][MAXM];
    memset(tmp, 0, sizeof(tmp));
    const long long LIM = 8000000000000000000LL;
    for(int k=0;k<SZ;k++) {
        for(int i=0;i<SZ;i++) {
            long long ai = a.v[i][k];
            if(!ai) continue;
            for(int j=0;j<SZ;j++) {
                tmp[i][j] += ai * b.v[k][j];
                if(tmp[i][j] >= LIM) tmp[i][j] %= MOD;
            }
        }
    }
    Matrix c;
    for(int i=0;i<SZ;i++)
        for(int j=0;j<SZ;j++)
            c.v[i][j] = (int)(tmp[i][j] % MOD);
    return c;
}

Matrix rot(const Matrix& x, int d) {
    Matrix y;
    int K = SZ - 1;
    for(int i=0;i<SZ;i++)
        for(int j=0;j<SZ;j++) {
            int ni = (i == K) ? K : (i + d) % K;
            int nj = (j == K) ? K : (j + d) % K;
            y.v[ni][nj] = x.v[i][j];
        }
    return y;
}

