    int sz = k + 1;
    Matrix R(sz, Row(sz, 0));
    for (int i = 0; i < sz; ++i) {
        int ni = (i < k) ? (i + k - 1) % k : i;
        for (int j = 0; j < sz; ++j) {
            int nj = (j < k) ? (j + k - 1) % k : j;
            R[i][j] = M[ni][nj];
        }
    }
    return R;
}
Matrix pref[100];
void init() {
    ll digs = 0, tmp = n;
    while (tmp) { tmp /= k; digs++; }
    pref[0] = Matrix(k + 1, Row(k + 1, 0));
    for (int i = 1; i < k; ++i) pref[0][i][i] = 1;
    pref[0][0][k] = 1;
    pref[0][k][0] = MOD - 1;
    pref[0][k][k] = 2;
    for (int step = 0; step < digs; ++step) {
        pref[step + 1] = pref[step];
        auto cur = pref[step];
        for (int i = 1; i <= k - 1; ++i) {
            cur = shiftMat(cur);
            pref[step + 1] = matMul(pref[step + 1], cur);
        }
    }
}
Matrix solve(ll n) {
    if (n == 0) {
        Matrix I(k + 1, Row(k + 1, 0));
        for (int i = 0; i <= k; ++i) I[i][i] = 1;
        return I;
    }
    ll pw = 1, dig = 0;
    while (pw <= n / k) { pw *= k; ++dig; }
    if (n == pw) return pref[dig];
    ll steps = n / pw;
    ll left = n - steps * pw;
    auto cur = solve(0);
    auto coeff = pref[dig];
    for (ll i = 0; i < steps; ++i) {
        cur = matMul(cur, coeff);
        coeff = shiftMat(coeff);
    }
    auto other = solve(left);
    for (ll i = 0; i < steps; ++i) other = shiftMat(other);
    return matMul(cur, other);
}
