using namespace std;

typedef long long ll;

const int MOD = 1000000007;

// Flattened matrix representation: size (k+1)*(k+1)
typedef vector<int> mt;

int K; // global k for shift and multiplication

mt shift(const mt &a, int shift)
{
    int k = K;
    int n = k + 1;
    shift = (k - shift) % k;
    mt res = a;
    for (int i = 0; i < k; ++i) {
        for (int j = 0; j < k; ++j) {
            res[i * n + j] = a[((i + shift) % k) * n + ((j + shift) % k)];
        }
    }
    for (int j = 0; j < k; ++j) {
        res[k * n + j] = a[k * n + ((j + shift) % k)];
    }
    return res;
}

mt operator *(const mt &a, const mt &b)
{
    int n = K + 1;
    mt res(n * n, 0);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int tmp = 0;
            for (int l = 0; l < n; ++l) {
                tmp = (tmp + 1ll * a[i * n + l] * b[l * n + j]) % MOD;
            }
            res[i * n + j] = tmp;
        }
    }
    return res;
}

int main()
{
    ll n;
    int k;
    cin >> n >> k;
    K = k;
    int max_depth = 0;
    {
