        while (tmp != 0) {
            ++max_depth;
            tmp /= k;
        }
    }
    vector<mt> dp(max_depth);
    int sz = k + 1;
    // dp[0]
    dp[0].assign(sz * sz, 0);
    for (int i = 0; i <= k; ++i) {
        for (int j = 0; j <= k; ++j) {
            dp[0][i * sz + j] = (i == j || j == 0);
        }
    }
    mt e(sz * sz, 0);
    for (int i = 0; i <= k; ++i) {
        e[i * sz + i] = 1;
    }
    for (int depth = 1; depth < max_depth; ++depth) {
        dp[depth] = e;
        mt bs = dp[depth - 1];
        int curx = k;
        for (int i = 0; (1 << i) <= curx; ++i) {
            if (curx & (1 << i)) {
                dp[depth] = bs * shift(dp[depth], (1 << i));
                curx ^= (1 << i);
            }
            bs = bs * shift(bs, (1 << i));
        }
    }
    mt base(sz, 0);
    base[k] = 1;
    int sl = 0;
    ll x = n;
    vector<int> vec;
    while (x != 0) {
        vec.push_back(x % k);
        x /= k;
    }
    int len = int(vec.size());
    for (int cur_depth = len - 1; cur_depth >= 0; --cur_depth) {
        int rest = vec[cur_depth];
        for (int it = 0; it < rest; ++it, sl = (sl + 1) % k) {
            // base is 1 x sz, shift returns sz x sz, result is 1 x sz
            mt shifted = shift(dp[cur_depth], sl);
            mt newbase(sz, 0);
            for (int j = 0; j < sz; ++j) {
