typedef long long ll;

const int MOD = 1000000007;

typedef vector< vector< int > > mt;

mt shift(const mt &a, int shift)
{
    int k = int(a.size()) - 1;
    shift = (k - shift) % k;
    mt res = a;
    for (int i = 0; i < k; ++i) {
        for (int j = 0; j < k; ++j) {
            res[i][j] = a[(i + shift) % k][(j + shift) % k];
        }
    }
    for (int j = 0; j < k; ++j) {
        res[k][j] = a[k][(j + shift) % k];
    }
    return res;
}

mt operator *(const mt &a, const mt &b)
{
    int n = int(a.size()), k = int(a[0].size()), m = int(b[0].size());
    mt res(n, vector< int >(m, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int tmp = 0;
            for (int l = 0; l < k; ++l) {
                tmp = (tmp + 1ll * a[i][l] * b[l][j]) % MOD;
            }
            res[i][j] = tmp;
        }
    }
    return res;
}

// Recursive digit processing
void process_digits(const vector<int>& vec, int idx, mt& base, int& sl, const vector<mt>& dp, int k)
{
    if (idx < 0) return;
    int rest = vec[idx];
    for (int it = 0; it < rest; ++it, sl = (sl + 1) % k) {
        base = base * shift(dp[idx], sl);
    }
    process_digits(vec, idx - 1, base, sl, dp, k);
}

int main()
{
    ll n;
    int k;
    cin >> n >> k;
