    Mat res;
    int cur = k + 1;
    for (int i = 1; i <= cur; ++i)
        for (int m = 1; m <= cur; ++m) if (lhs.a[i][m])
            for (int j = 1; j <= cur; ++j)
                res.a[i][j] = (res.a[i][j] + (ll)lhs.a[i][m] * rhs.a[m][j]) % Mod;
    return res;
}

int main() {
    ll n;
    cin >> n >> k;
    Mat A[K];
    A[0].unit(k + 1);
    for (int i = 1; i <= k + 1; ++i) A[0].a[1][i] = 1;
    vector<int> V;
    int len = 0;
    for (ll tmp = n; tmp; tmp /= k) {
        V.push_back(tmp % k);
        Mat x = A[len];
        A[len + 1].unit(k + 1);
        ll power = k;
        int p = 0;
        while (power) {
            if (power & 1) A[len + 1] = A[len + 1] * move_mat(x, (power ^ 1) << p);
            x = move_mat(x, 1 << p) * x;
            power >>= 1;
            ++p;
        }
        ++len;
    }
    int step = 0;
    int ans[K] = {0};
    ans[k + 1] = 1;
    for (int T = (int)V.size() - 1; T >= 0; --T) {
        int cur = V[T];
        if (cur) {
            int tmp[K];
            for (int times = 0; times < cur; ++times) {
                memcpy(tmp, ans, sizeof(tmp));
                memset(ans, 0, sizeof(ans));
                Mat B = move_mat(A[T], times + step);
                for (int i = 1; i <= k + 1; ++i)
                    for (int j = 1; j <= k + 1; ++j)
                        ans[i] = (ans[i] + (ll)tmp[j] * B.a[i][j]) % Mod;
            }
        }
        step += cur;
    }
    int res = 0;
    for (int i = 1; i <= k + 1; ++i) res = (res + ans[i]) % Mod;
    cout << res << endl;
    return 0;
}

