#include <iostream>
#include <cstdio>
#include <cstdlib>
#include <cstring>

#define MAXK 30
#define MAXD 60

using namespace std;

typedef long long lint;

const lint mod = 1e9 + 7;

int K;
struct res_t {
  int many[MAXK][MAXK];
  int inside[MAXK];
  bool exist[MAXK];

  res_t() {
    memset(many, 0, sizeof(many));
    memset(inside, 0, sizeof(inside));
    memset(exist, 0, sizeof(exist));
  }

  res_t(res_t &copy, int rotate) {
    for (int i = 0; i < K; i++) {
      exist[(i+rotate)%K] = copy.exist[i];
      inside[(i+rotate)%K] = copy.inside[i];

      for (int j = 0; j < K; j++)
	many[(i+rotate)%K][(j+rotate)%K] = copy.many[i][j];
    }
  }

  res_t(const res_t &a, const res_t &b) {
    for (int i = 0; i < K; i++) {
      exist[i] = a.exist[i] || b.exist[i];

      inside[i] = a.inside[i];
      if (!a.exist[i])
	inside[i] = (inside[i] + b.inside[i]) % mod;
      for (int j = 0; j < K; j++) {
	inside[i] = (inside[i] + (lint)a.many[i][j] * b.inside[j]) % mod;

	many[i][j] = 0;
	if (!b.exist[j])
	  many[i][j] = a.many[i][j];
	if (!a.exist[i])
	  many[i][j] = (many[i][j] + b.many[i][j]) % mod;
	for (int m = 0; m < K; m++)
	  many[i][j] = (many[i][j] + (lint)a.many[i][m] * b.many[m][j]) % mod;
      }
    }
  }
} retpk[MAXD];
int digits[MAXD];

int main() {
  lint n;

  cin >> n >> K;

  int nd = 0;
  for (lint x = n; x; x /= K)
    digits[nd++] = x % K;

  retpk[0].exist[0] = true;
  retpk[0].inside[0] = 1;
  for (int j = 0; j < K; j++)
    retpk[0].many[0][j] = 1;

  for (int pk = 1; pk < nd; pk++) {
    retpk[pk] = retpk[pk-1];
    for (int v = 1; v < K; v++)
      retpk[pk] = res_t(retpk[pk], res_t(retpk[pk-1], v));
  }

  res_t result;
  int sum = 0;

  for (int d = nd-1; d >= 0; d--) {
    for (int v = 0; v < digits[d]; v++)
      result = res_t(result, res_t(retpk[d], (sum + v) % K));
    sum += digits[d];
  }

  int result_sum = 1;
  for (int i = 0; i < K; i++)
    result_sum = (result_sum + result.inside[i]) % mod;

  cout << result_sum << endl;

  return 0;
}

#include <iostream>
#include <cstdio>
#include <cstdlib>
#include <cstring>

#define MAXK 30
#define MAXD 60

using namespace std;

typedef long long lint;

const lint mod = 1e9 + 7;

int K;

// Instead of constructors, use plain functions for operations.
struct res_t {
  int many[MAXK][MAXK];
  int inside[MAXK];
  bool exist[MAXK];
};

void res_init(res_t &r) {
  memset(r.many, 0, sizeof(r.many));
  memset(r.inside, 0, sizeof(r.inside));
  memset(r.exist, 0, sizeof(r.exist));
}

void res_rotate(res_t &out, const res_t &copy, int rotate) {
  for (int i = 0; i < K; i++) {
    out.exist[(i+rotate)%K] = copy.exist[i];
    out.inside[(i+rotate)%K] = copy.inside[i];
    for (int j = 0; j < K; j++)
      out.many[(i+rotate)%K][(j+rotate)%K] = copy.many[i][j];
  }
}

void res_combine(res_t &out, const res_t &a, const res_t &b) {
  for (int i = 0; i < K; i++) {
    out.exist[i] = a.exist[i] || b.exist[i];

    out.inside[i] = a.inside[i];
    if (!a.exist[i])
      out.inside[i] = (out.inside[i] + b.inside[i]) % mod;
    for (int j = 0; j < K; j++) {
      out.inside[i] = (out.inside[i] + (lint)a.many[i][j] * b.inside[j]) % mod;

      out.many[i][j] = 0;
      if (!b.exist[j])
        out.many[i][j] = a.many[i][j];
      if (!a.exist[i])
        out.many[i][j] = (out.many[i][j] + b.many[i][j]) % mod;
      for (int m = 0; m < K; m++)
        out.many[i][j] = (out.many[i][j] + (lint)a.many[i][m] * b.many[m][j]) % mod;
    }
  }
}

res_t retpk[MAXD];
int digits[MAXD];

int main() {
  lint n;
  cin >> n >> K;

  int nd = 0;
  for (lint x = n; x; x /= K)
    digits[nd++] = x % K;

  res_init(retpk[0]);
  retpk[0].exist[0] = true;
  retpk[0].inside[0] = 1;
  for (int j = 0; j < K; j++)
    retpk[0].many[0][j] = 1;

  for (int pk = 1; pk < nd; pk++) {
    res_t tmp1, tmp2;
    res_rotate(tmp1, retpk[pk-1], 1);
    for (int v = 2; v < K; v++) {
      res_rotate(tmp2, retpk[pk-1], v);
      res_combine(tmp1, tmp1, tmp2);
    }
    // For v=1 we rotate and combine with retpk[pk]? wait original: first copy retpk[pk] = retpk[pk-1]; then for v=1..K-1 combine with rotated version. So:
    res_t base = retpk[pk-1];
    res_t rotated;
    res_rotate(rotated, retpk[pk-1], 1);
    res_combine(base, base, rotated);
    for (int v = 2; v < K; v++) {
      res_rotate(rotated, retpk[pk-1], v);
      res_combine(base, base, rotated);
    }
    retpk[pk] = base;
  }

  res_t result;
  res_init(result);
  int sum = 0;

  for (int d = nd-1; d >= 0; d--) {
    for (int v = 0; v < digits[d]; v++) {
      res_t rotated;
      res_rotate(rotated, retpk[d], (sum + v) % K);
      res_t tmp;
      res_combine(tmp, result, rotated);
      result = tmp;
    }
    sum += digits[d];
  }

  int result_sum = 1;
  for (int i = 0; i < K; i++)
    result_sum = (result_sum + result.inside[i]) % mod;

  cout << result_sum << endl;

  return 0;
}

#include <iostream>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <algorithm>

#define MAXK 30
#define MAXD 60

using namespace std;

typedef long long lint;

const lint mod = 1e9 + 7;

int K;

// Use arrays indexed by i*K+j for many, and i for inside/exist.
struct res_t {
  int many[MAXK*MAXK];
  int inside[MAXK];
  bool exist[MAXK];
};

void init_res(res_t& r) {
  fill(r.many, r.many+MAXK*MAXK, 0);
  fill(r.inside, r.inside+MAXK, 0);
  fill(r.exist, r.exist+MAXK, false);
}

void rotate_res(res_t& out, const res_t& in, int rot) {
  for (int i = 0; i < K; ++i) {
    int ni = (i+rot)%K;
    out.exist[ni] = in.exist[i];
    out.inside[ni] = in.inside[i];
    for (int j = 0; j < K; ++j) {
      int nj = (j+rot)%K;
      out.many[ni*K+nj] = in.many[i*K+j];
    }
  }
}

void combine_res(res_t& out, const res_t& a, const res_t& b) {
  for (int i = 0; i < K; ++i) {
    out.exist[i] = a.exist[i] || b.exist[i];
    out.inside[i] = a.inside[i];
    if (!a.exist[i])
      out.inside[i] = (out.inside[i] + b.inside[i]) % mod;
    for (int j = 0; j < K; ++j) {
      long long sum_inside = (long long)a.many[i*K+j] * b.inside[j];
      out.inside[i] = (out.inside[i] + sum_inside) % mod;
      out.many[i*K+j] = 0;
      if (!b.exist[j])
        out.many[i*K+j] = a.many[i*K+j];
      if (!a.exist[i])
        out.many[i*K+j] = (out.many[i*K+j] + b.many[i*K+j]) % mod;
      for (int m = 0; m < K; ++m) {
        out.many[i*K+j] = (out.many[i*K+j] + (long long)a.many[i*K+m] * b.many[m*K+j]) % mod;
      }
    }
  }
}

