    retpk[0].many[0*K+j] = 1;

  for (int pk = 1; pk < nd; ++pk) {
    res_t cur = retpk[pk-1];
    for (int v = 1; v < K; ++v) {
      res_t rot;
      rotate_res(rot, retpk[pk-1], v);
      res_t tmp;
      combine_res(tmp, cur, rot);
      cur = tmp;
    }
    retpk[pk] = cur;
  }

  res_t result;
  init_res(result);
  int sum = 0;
  for (int d = nd-1; d >= 0; --d) {
    for (int v = 0; v < digits[d]; ++v) {
      res_t rot;
      rotate_res(rot, retpk[d], (sum+v)%K);
      res_t tmp;
      combine_res(tmp, result, rot);
      result = tmp;
    }
    sum += digits[d];
  }

  int result_sum = 1;
  for (int i = 0; i < K; ++i)
    result_sum = (result_sum + result.inside[i]) % mod;

  cout << result_sum << endl;
  return 0;
