        Mat res = Mat::ident(h());
        while (e) {
            if (e & 1) res *= *this;
            *this *= *this;
            e >>= 1;
        }
        a.swap(res.a);
        return *this;
    }
    Mat operator+(const Mat& b) const { return Mat(*this) += b; }
    Mat operator-(const Mat& b) const { return Mat(*this) -= b; }
    Mat operator*(const Mat& b) const { return Mat(*this) *= b; }
