                tmp[i][j] = a[(i + K - 1) % K][(j + K - 1) % K];
            tmp[i][K] = a[(i + K - 1) % K][K];
            tmp[K][i] = a[K][(i + K - 1) % K];
        }
        tmp[K][K] = a[K][K];
        a = tmp.a;
    }
};

