            for (int j = 0; j < m; ++j)
                for (int k = 0; k < p; ++k)
                    r(i, j) = (r(i, j) + v[i][k] * b.v[k][j]) % MOD;
        return r;
    }
    M pwr(ll e) const {
        M x = *this;
        M r = M::eye(v.size());
        while (e) {
            if (e & 1) r = r.mul(x);
