void multi(const matrix& m1, const matrix& m2, matrix& to) {
    matrix tmp = {};
    for (int i = 0; i <= k; ++i)
        for (int j = 0; j <= k; ++j) {
            long long sum = 0;
            for (int p = 0; p <= k; ++p)
                sum = (sum + m1.a[i][p] * m2.a[p][j]) % mod;
            tmp.a[i][j] = sum;
        }
    to = tmp;
}

