Matrix mat_mul(const Matrix& A, const Matrix& B){
    Matrix C; C.clear();
    for(int i=0;i<35;i++){
        for(int k=0;k<35;k++){
            int aik = A[i][k];
            if(aik){
                for(int j=0;j<35;j++){
                    C[i][j] = mod_add(C[i][j], mod_mul(aik, B[k][j]));
                }
            }
        }
    }
    return C;
}
Matrix mat_add(const Matrix& A, const Matrix& B){
    Matrix C; C.clear();
    for(int i=0;i<35;i++) for(int j=0;j<35;j++) C[i][j]=mod_add(A[i][j],B[i][j]);
    return C;
}
Matrix mat_scal(const Matrix& A, int x){
    Matrix C = A;
    for(int i=0;i<35;i++) for(int j=0;j<35;j++) C[i][j]=mod_mul(C[i][j],x);
    return C;
}

