    f[0] = id;
    for (int i = 0; i <= k; ++i) f[0][i][0] = 1;
    for (int i = 1; i < ndigits; ++i) {
        f[i] = id;
        for (int j = 0; j < k; ++j)
            f[i] = f[i] * calc_matrix(i - 1, j);
    }

    ll cur = 0;
    ll pw = 1;
    --ndigits;
    for (int i = 0; i < ndigits; ++i) pw *= k;

    Matrix ans = id;
    while (cur < n) {
        while (cur + pw <= n) {
            ans = ans * calc_matrix(ndigits, sum_digits(cur));
            cur += pw;
        }
        pw /= k;
        --ndigits;
    }

    int sum = 0;
    for (int i = 0; i <= k; ++i) sum = add(sum, ans[k][i]);
    cout << sum << endl;
    return 0;
}

