Mat mat_mul(const Mat& A, const Mat& B) {
    int n = kb+1;
    Mat C(n, vector<int>(n, 0));
    for (int i = 0; i < n; ++i)
        for (int k = 0; k < n; ++k)
            if (A[i][k])
                for (int j = 0; j < n; ++j)
                    C[i][j] = (C[i][j] + (LL)A[i][k] * B[k][j]) % MOD;
    return C;
}

Mat I;
