    for (int i = 0; i < kb; ++i) {
        A[0][i].assign(kb+1, vector<int>(kb+1, 0));
        for (int j = 0; j <= kb; ++j) {
            A[0][i][j][j] = 1;
            A[0][i][i][j] = 1;
        }
