    for (int i = 1; i < 70; ++i) {
        A[i].resize(kb);
        pre.assign(kb+1, vector<int>(kb+1, 0));
        suf.assign(kb+1, vector<int>(kb+1, 0));
        pre[0] = A[i-1][0];
        for (int j = 1; j < kb; ++j)
            pre[j] = mat_mul(A[i-1][j], pre[j-1]);
        suf[kb-1] = A[i-1][kb-1];
        for (int j = kb-2; j >= 0; --j)
            suf[j] = mat_mul(suf[j+1], A[i-1][j]);
        for (int j = 0; j < kb; ++j) {
            Mat left = (j ? pre[j-1] : I);
            A[i][j] = mat_mul(left, suf[j]);
        }
    }
}

