#include<bits/stdc++.h>
using namespace std;
typedef long long ll;

const int MAXN = 32;
const int MOD = 1000000007;

int n;

inline void add_mod(int &x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
}

inline int read_int() {
    int x, f = 1;
    char c;
    while ((c = getchar()) != '-' && (c < '0' || c > '9'));
    if (c == '-') {
        c = getchar();
        f = -1;
    }
    x = c ^ '0';
    while ((c = getchar()) >= '0' && c <= '9')
        x = (x << 1) + (x << 3) + (c ^ '0');
    return x * f;
}

inline ll read_ll() {
    ll x, f = 1;
    char c;
    while ((c = getchar()) != '-' && (c < '0' || c > '9'));
    if (c == '-') {
        c = getchar();
        f = -1;
    }
    x = c ^ '0';
    while ((c = getchar()) >= '0' && c <= '9')
        x = (x << 1) + (x << 3) + (c ^ '0');
    return x * f;
}

struct Matrix {
    int a[MAXN][MAXN];

    Matrix() { memset(a, 0, sizeof(a)); }

    void clear() { memset(a, 0, sizeof(a)); }

    void set_identity() {
        clear();
        for (int i = 1; i <= n + 1; ++i) a[i][i] = 1;
    }

    Matrix operator*(const Matrix &rhs) const {
        Matrix res;
        for (int i = 1; i <= n + 1; ++i)
            for (int j = 1; j <= n + 1; ++j)
                for (int k = 1; k <= n + 1; ++k)
                    add_mod(res.a[i][j], (int)(1LL * a[i][k] * rhs.a[k][j] % MOD));
        return res;
    }
};

Matrix I, ans, A[MAXN], pre[MAXN], suf[MAXN];

int main() {
#ifndef ONLINE_JUDGE
    freopen("matrix.in", "r", stdin);
    freopen("matrix.out", "w", stdout);
#endif
    ll m = read_ll();
    n = read_int();

    I.set_identity();
    ans = I;

    for (int i = 1; i <= n; ++i) {
        A[i] = I;
        for (int j = 1; j <= n + 1; ++j)
            A[i].a[j][i] = 1;
    }

    pre[0] = I;
    suf[n + 1] = I;

    while (m) {
        ll u = m % n;
        if (u) {
            ll s = 0;
            for (ll v = m; v; v /= n)
                s = (s + v / n) % n;
            u = (s + u - 1) % n + 1;
            for (; u != s; --u) {
                if (u <= 0) u += n;
                ans = A[u] * ans;
            }
        }

        for (int i = 1; i <= n; ++i)
            pre[i] = pre[i - 1] * A[i];

        for (int i = n; i >= 1; --i)
            suf[i] = A[i] * suf[i + 1];

        for (int i = 1; i <= n; ++i)
            A[i] = suf[i] * pre[i - 1];

        m /= n;
