struct FlatMatrix {
	int n, m;
	vector<mint> data;
	FlatMatrix() {}
	FlatMatrix(int n_, int m_): n(n_), m(m_), data(n_*m_, 0) {}
	inline int height() const { return n; }
	inline int width() const { return m; }
	inline mint& at(int i, int j) { return data[i*m + j]; }
	inline const mint& at(int i, int j) const { return data[i*m + j]; }
	static FlatMatrix identity(int n) {
		FlatMatrix A(n, n);
		rep(i, n) A.at(i, i) = 1;
		return A;
	}
	inline static FlatMatrix identity(const FlatMatrix& A) { return identity(A.height()); }
	FlatMatrix& operator*=(const FlatMatrix& B) {
		int n = height(), m = B.width(), p = B.height();
		assert(p == width());
		FlatMatrix w(n, m);
		rep(i, n) rep(j, m) {
			mint x = 0;
			rep(k, p) x += at(i, k) * B.at(k, j);
			w.at(i, j) = x;
		}
		*this = w;
		return *this;
	}
};
FlatMatrix operator^(const FlatMatrix& t, ll k) {
	FlatMatrix A = t, B = FlatMatrix::identity(t);
	while(k) {
		if(k & 1) B *= A;
		A *= A;
		k >>= 1;
	}
	return B;
}

FlatMatrix getRotateMatrixFlat(int k, int t) {
	t = (t % k + k) % k;
	FlatMatrix A(k + 3, k + 3);
	rep(i, k)
		A.at(i, (i + t) % k) = 1;
	A.at(k, k) = A.at(k+1, k+1) = A.at(k+2, k+2) = 1;
	return A;
}

FlatMatrix getSingletonMatrixFlat(int k, int j) {
