typedef ModInt<1000000007> mint;

struct Matrix {
	typedef mint Num;
	vector<vector<Num> > v, w;
	Matrix() {}
	Matrix(int n, int m): v(n, vector<Num>(m)) { }
	inline int height() const { return (int)v.size(); }
	inline int width() const { return (int)v[0].size(); }
	inline Num& at(int i, int j) { return v[i][j]; }
	inline const Num& at(int i, int j) const { return v[i][j]; }
	static Matrix identity(int n) {
		Matrix A(n, n);
		rep(i, n) A.at(i, i) = 1;
		return A;
	}
	inline static Matrix identity(const Matrix& A) { return identity(A.height()); }
	Matrix transpose() const {
		int n = height(), m = width();
		Matrix T(m, n);
		rep(i, n) rep(j, m) T.at(j, i) = at(i, j);
		return T;
	}
	Matrix& operator*=(const Matrix& B) {
		int n = height(), m = B.width(), p = B.height();
		assert(p == width());
		w.assign(n, vector<Num>(m, 0));
		rep(i, n) rep(j, m) {
			Num x = 0;
			rep(k, p) x += at(i, k) * B.at(k, j);
			w[i][j] = x;
		}
		v.swap(w);
		return *this;
	}
};
Matrix operator^(const Matrix& t, ll k) {
	Matrix A = t, B = Matrix::identity(t);
	while(k) {
		if(k & 1) B *= A;
		A *= A;
		k >>= 1;
	}
	return B;
}

Matrix getRotateMatrix(int k, int t) {
	t = (t % k + k) % k;
	Matrix A(k + 3, k + 3);
	rep(i, k)
		A.at(i, (i + t) % k) = 1;
	A.at(k, k) = A.at(k+1, k+1) = A.at(k+2, k+2) = 1;
	return A;
}

Matrix getSingletonMatrix(int k, int j) {
	assert(0 <= j && j < k);
	Matrix A(k + 3, k + 3);
	rep(i, k) if(i != j)
		A.at(i, i) += 1;
	A.at(k + 1, k + 1) = A.at(k + 2, k + 2) = 1;

	A.at(k, k + 1) += 1;
	A.at(j, k + 1) -= 1;

	A.at(k, k) += 2;
	A.at(j, k) -= 1;

	A.at(k, j) += 1;
	return A;
}

int s_k(int k, long long j) {
	long long t = j; int u = 0;
	while(t > 0) {
		(u += t % k) %= k;
		t /= k;
	}
	return u;
}

int main() {
	long long n; int k;
	while(cin >> n >> k) {
		// Use column vector (k+3 x 1) and multiply on left by transposed matrices
		Matrix b(k + 3, 1);
		b.at(k, 0) = 1;
		b.at(k + 1, 0) = b.at(k + 2, 0) = 1;

		long long powk = 1; int digits = 0;
		while(powk <= n / k) powk *= k, ++ digits;

		vector<Matrix> P(digits + 1);
		P[0] = getSingletonMatrix(k, 0);
		rer(i, 1, digits) {
			P[i] = Matrix::identity(k + 3);
			rep(j, k) {
				P[i] *= P[i-1];
				P[i] *= getRotateMatrix(k, -1);
			}
		}
		// Transpose P[i] for column vector multiplication
		vector<Matrix> P_trans(digits + 1);
		rep(i, digits + 1) P_trans[i] = P[i].transpose();

		long long offset = 0;
		while(powk > 0) {
			int t = (int)((n - offset) / powk);
			rep(j, t) {
				int s = s_k(k, offset);
				Matrix R1 = getRotateMatrix(k, -s).transpose();
				Matrix R2 = getRotateMatrix(k, +s).transpose();
				b = R2 * (P_trans[digits] * (R1 * b));
				offset += powk;
			}
			powk /= k;
			-- digits;
		}

		mint ans = b.at(k + 1, 0);
		cout << ans.get() << endl;
	}
	return 0;
}

