	}
	return B;
}

Matrix getRotateMatrix(int k, int t) {
	t = (t % k + k) % k;
	Matrix A(k + 3, k + 3);
	rep(i, k)
		A.at(i, (i + t) % k) = 1;
	A.at(k, k) = A.at(k+1, k+1) = A.at(k+2, k+2) = 1;
	return A;
}

Matrix getSingletonMatrix(int k, int j) {
	assert(0 <= j && j < k);
	Matrix A(k + 3, k + 3);
	rep(i, k) if(i != j)
		A.at(i, i) += 1;
	A.at(k + 1, k + 1) = A.at(k + 2, k + 2) = 1;

	A.at(k, k + 1) += 1;
	A.at(j, k + 1) -= 1;

	A.at(k, k) += 2;
	A.at(j, k) -= 1;

	A.at(k, j) += 1;
	return A;
}

