// Recursively compute the matrix for a block of size k^d
Matrix computeBlockMatrix(int k, int d) {
	if (d == 0) return getSingletonMatrix(k, 0);
	Matrix P = Matrix::identity(k + 3);
	Matrix Pprev = computeBlockMatrix(k, d-1);
	rep(j, k) {
		P *= Pprev;
		P *= getRotateMatrix(k, -1);
	}
	return P;
}

