			rep(j, t) {
				int s = s_k(k, offset);
				b *= getRotateMatrix(k, -s);
				b *= computeBlockMatrix(k, digits);
				b *= getRotateMatrix(k, +s);
				offset += powk;
			}
			powk /= k;
			-- digits;
		}

		mint ans = b.at(0, k + 1);
		cout << ans.get() << endl;
	}
	return 0;
}

