template <typename T>
T fastRead() {
    T x = 0;
    int sign = 1;
    int c;
    while ((c = getchar()) != '-' && (c < '0' || c > '9')) {}
    if (c == '-') {
        sign = -1;
        c = getchar();
    }
    x = static_cast<T>(c ^ '0');
    while ((c = getchar()) >= '0' && c <= '9')
        x = static_cast<T>(x * 10 + (c ^ '0'));
    return static_cast<T>(x * sign);
}

inline void addMod(int &x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
}

int n;

struct Matrix {
    int a[MAXN][MAXN];
    void clear() {
        memset(a, 0, sizeof(a));
    }
    Matrix operator * (const Matrix &other) const {
        Matrix result;
        result.clear();
        for (int i = 1; i <= n + 1; ++i)
            for (int j = 1; j <= n + 1; ++j)
                for (int k = 1; k <= n + 1; ++k)
                    addMod(result.a[i][j], (int)(1LL * a[i][k] * other.a[k][j] % MOD));
        return result;
    }
};

