        A[i] = E;
        for (int j = 1; j <= n + 1; ++j)
            A[i].a[j][i] = 1;
    }

    pre[0] = E;
    suf[n + 1] = E;

    while (m) {
        ll u = m % n;
        if (u) {
            ll s = 0;
            for (ll v = m / n; v; v /= n)
                s = (s + v % n) % n;
            u = (s + u - 1) % n + 1;
            for (; u != s; --u) {
                if (u <= 0)
                    u += n;
                ans = A[(int)u] * ans;
            }
        }

        for (int i = 1; i <= n; ++i)
            pre[i] = pre[i - 1] * A[i];

        for (int i = n; i >= 1; --i)
            suf[i] = A[i] * suf[i + 1];

        for (int i = 1; i <= n; ++i)
            A[i] = suf[i] * pre[i - 1];

        m /= n;
    }

    int num = 1;
    for (int i = 1; i <= n; ++i)
        addMod(num, ans.a[n + 1][i]);

