#define fd(i,a,b) for(int i(a),end##i(b);i>=end##i;i--)
using namespace std;
const int maxn=2.7e5+5;
int m,n,k;
int mod;
int f[19][maxn];
vector<long long> g;
int cnt[maxn];
int upd(const int &x){
	if(x<0)return x+mod;
	if(x>=mod)return x-mod;
	return x;
}
void add(int &x,const int &y){
	x=upd(x+y);
}
int ksm(int x,int k){
	int ans=1;
	while(k){
		if(k&1)ans=1ll*ans*x%mod;
		x=1ll*x*x%mod;
		k>>=1;
	}
	return ans;
}
int jc[maxn],inv[maxn];
void init(int n){
	jc[0]=1;
	fr(i,1,n)jc[i]=1ll*jc[i-1]*i%mod;
	inv[n]=ksm(jc[n],mod-2);
	fd(i,n-1,0)inv[i]=1ll*inv[i+1]*(i+1)%mod;
}
void F(int *f,int n,int h){
	for(int p=1;p<n;p<<=1)
		for(int i=0;i<n;i+=p<<1)fr(k,i,i+p-1){
			add(f[k+p],h*f[k]);		
		}
}
int l;
vector<long long> operator *(vector<long long> &A,vector<long long> &B){
	static vector<long long> C;C.clear();C.resize(l+1);
	fr(i,0,l)fr(j,0,l-i)C[i+j]+=A[i]*B[j];
	fr(i,0,l)C[i]%=mod;
	return C;	
}
vector<long long> pksm(vector<long long> A,int k){
	static vector<long long> C;C.clear();C.resize(l+1);
	C[0]=1;
	while(k){
		if(k&1)C=C*A;
		A=A*A;
		k>>=1;
	}
	return C;
}
int main(){
#ifdef pig
	freopen("C.in","r",stdin);
	freopen("C.out","w",stdout);
#endif
	cin>>n>>k>>mod;
	init(n);
	if(n&1){
		cout<<ksm(k,n);
		return 0;
	}
	m=1;while(m<=n)m<<=1,l++;
	fr(i,0,m-1)cnt[i]=cnt[i>>1]+(i&1);
	init(m);
	fr(i,0,m-1){	
		f[cnt[i]][i]=inv[i];		
	}
	fr(i,0,l)F(f[i],m,1);
	g.resize(l+1);
	fr(s,0,m-1){
		fr(i,0,l)g[i]=f[i][s];
		g=pksm(g,k);
		fr(i,0,l)f[i][s]=g[i];
	}
	F(f[cnt[n]],m,-1);
	cout<<upd(ksm(k,n)-1ll*f[cnt[n]][n]*jc[n]%mod);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int maxn=2.7e5+5;
int m,n,k,mod;
int f[19][maxn];
vector<long long> gv;
int cnt[maxn];
int addmod(int x){ if(x<0) return x+mod; if(x>=mod) return x-mod; return x; }
void add2(int &x,int y){ x=addmod(x+y); }
int pw(int x,int y){
    int res=1;
    while(y){ if(y&1) res=(long long)res*x%mod; x=(long long)x*x%mod; y>>=1; }
    return res;
}
int jc[maxn],inv[maxn];
void init_fact(int up){
    jc[0]=1;
    for(int i=1;i<=up;i++) jc[i]=(long long)jc[i-1]*i%mod;
    inv[up]=pw(jc[up],mod-2);
    for(int i=up-1;i>=0;i--) inv[i]=(long long)inv[i+1]*(i+1)%mod;
}
void fwt(int *a,int len,int sign){
    for(int step=1;step<len;step<<=1)
        for(int beg=0;beg<len;beg+=step<<1)
            for(int j=beg;j<beg+step;j++){
                int x=a[j], y=a[j+step];
                if(sign==1) add2(y,x);
                else add2(x,y);
                a[j]=x; a[j+step]=y;
            }
}
int L;
vector<long long> poly_mul(vector<long long>&A, vector<long long>&B){
    vector<long long> C(L+1,0);
    for(int i=0;i<=L;i++) for(int j=0;j<=L-i;j++) C[i+j] += A[i]*B[j];
    for(int i=0;i<=L;i++) C[i]%=mod;
    return C;
}
vector<long long> poly_pow(vector<long long> A,int k){
    vector<long long> C(L+1,0); C[0]=1;
    while(k){
        if(k&1) C=poly_mul(C,A);
        A=poly_mul(A,A);
        k>>=1;
    }
    return C;
}
int main(){
    ios::sync_with_stdio(false); cin.tie(0);
    cin>>n>>k>>mod;
    init_fact(n);
    if(n&1){ cout<<pw(k,n)<<"\n"; return 0; }
    m=1; L=0; while(m<=n){ m<<=1; L++; }
    for(int i=0;i<m;i++) cnt[i]=cnt[i>>1]+(i&1);
    init_fact(m);
    for(int i=0;i<m;i++) f[cnt[i]][i]=inv[i];
    for(int s=0;s<=L;s++) fwt(f[s],m,1);
    gv.resize(L+1);
    for(int s=0;s<m;s++){
        for(int b=0;b<=L;b++) gv[b]=f[b][s];
        gv=poly_pow(gv,k);
        for(int b=0;b<=L;b++) f[b][s]=gv[b];
    }
    fwt(f[cnt[n]],m,-1);
    long long ans = pw(k,n) - (long long)f[cnt[n]][n]*jc[n]%mod;
    ans %= mod; if(ans<0) ans+=mod;
    cout<<ans<<"\n";
    return 0;
}

#include<bits/stdc++.h>
#define REP(i,a,b) for(int i=a;i<=b;++i)
#define REPD(i,a,b) for(int i=a;i>=b;--i)
using namespace std;
const int MAX=2.7e5+5;
int n,k,mod,m,L;
int cnt[MAX], fact[MAX], invfact[MAX];
int f[19][MAX];
inline int norm(int x){ if(x<0) return x+mod; if(x>=mod) return x-mod; return x; }
inline void add(int &a,int b){ a=norm(a+b); }
int modpow(int a,int e){
    int r=1;
    while(e){ if(e&1) r=1LL*r*a%mod; a=1LL*a*a%mod; e>>=1; }
    return r;
}
void precompute(int N){
    fact[0]=1; REP(i,1,N) fact[i]=1LL*fact[i-1]*i%mod;
    invfact[N]=modpow(fact[N],mod-2);
    REPD(i,N-1,0) invfact[i]=1LL*invfact[i+1]*(i+1)%mod;
}
void hadamard(int *arr,int len,int coef){
    for(int len2=1;len2<len;len2<<=1){
        for(int i=0;i<len;i+=len2<<1){
            for(int j=i;j<i+len2;j++){
                int u=arr[j], v=arr[j+len2];
                add(v,coef*u);
                arr[j]=u; arr[j+len2]=v;
            }
        }
    }
}
vector<long long> multpoly(vector<long long>&A, vector<long long>&B){
    vector<long long> C(L+1,0);
    for(int i=0;i<=L;i++) for(int j=0;j<=L-i;j++) C[i+j]+=A[i]*B[j];
    for(int i=0;i<=L;i++) C[i]%=mod;
    return C;
}
vector<long long> polpow(vector<long long> base,int exp){
    vector<long long> res(L+1,0); res[0]=1;
    while(exp){ if(exp&1) res=multpoly(res,base); base=multpoly(base,base); exp>>=1; }
    return res;
}
int main(){
    cin>>n>>k>>mod;
    precompute(n);
    if(n&1){ cout<<modpow(k,n)<<"\n"; return 0; }
    m=1; L=0; while(m<=n){ m<<=1; L++; }
    REP(i,0,m-1) cnt[i]=cnt[i>>1]+(i&1);
    precompute(m);
    REP(i,0,m-1) f[cnt[i]][i]=invfact[i];
    REP(i,0,L) hadamard(f[i],m,1);
    vector<long long> g(L+1);
    REP(s,0,m-1){
        REP(i,0,L) g[i]=f[i][s];
        g=polpow(g,k);
        REP(i,0,L) f[i][s]=g[i];
    }
    hadamard(f[cnt[n]],m,-1);
    int ans=modpow(k,n) - 1LL*f[cnt[n]][n]*fact[n]%mod;
    cout<<norm(ans)<<"\n";
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int maxsize=2.7e5+5;
int m,n,kmod;
int f[19][maxsize];
int cnt[maxsize];
int MOD;
inline int add_mod(int x){ if(x<0) return x+MOD; if(x>=MOD) return x-MOD; return x; }
inline void add_to(int &x,int y){ x=add_mod(x+y); }
long long power_mod(long long a,long long e){
    long long res=1;
    while(e){ if(e&1) res=res*a%MOD; a=a*a%MOD; e>>=1; }
    return res;
}
int fact[maxsize], invfact[maxsize];
void initialize(int lim){
    fact[0]=1;
    for(int i=1;i<=lim;i++) fact[i]=1LL*fact[i-1]*i%MOD;
    invfact[lim]=power_mod(fact[lim],MOD-2);
    for(int i=lim-1;i>=0;i--) invfact[i]=1LL*invfact[i+1]*(i+1)%MOD;
}
void walsh(int *a,int len,int sgn){
    for(int p=1;p<len;p<<=1)
        for(int start=0;start<len;start+=(p<<1))
            for(int i=start;i<start+p;i++){
                int u=a[i], v=a[i+p];
                add_to(v,sgn*u);
                a[i]=u; a[i+p]=v;
            }
}
int L;
struct Poly{
    vector<long long> coeff;
    Poly(int deg=L){ coeff.assign(deg+1,0); }
    Poly operator*(const Poly& other) const{
        Poly res(L);
        for(int i=0;i<=L;i++)
            for(int j=0;j<=L-i;j++)
                res.coeff[i+j] += coeff[i]*other.coeff[j];
        for(int i=0;i<=L;i++) res.coeff[i]%=MOD;
        return res;
    }
};
Poly poly_power(Poly base,int exp){
    Poly res(L); res.coeff[0]=1;
    while(exp){
        if(exp&1) res=res*base;
        base=base*base;
        exp>>=1;
    }
    return res;
}
int main(){
    cin>>n>>kmod>>MOD;
    initialize(n);
    if(n&1){ cout<<power_mod(kmod,n)<<"\n"; return 0; }
    m=1; L=0; while(m<=n){ m<<=1; L++; }
    for(int i=0;i<m;i++) cnt[i]=cnt[i>>1]+(i&1);
    initialize(m);
    for(int i=0;i<m;i++) f[cnt[i]][i]=invfact[i];
    for(int i=0;i<=L;i++) walsh(f[i],m,1);
    vector<long long> tmp(L+1);
    for(int s=0;s<m;s++){
        for(int i=0;i<=L;i++) tmp[i]=f[i][s];
        Poly P(tmp);
        P=poly_power(P,kmod);
        for(int i=0;i<=L;i++) f[i][s]=P.coeff[i];
    }
    walsh(f[cnt[n]],m,-1);
    int ans=power_mod(kmod,n) - 1LL*f[cnt[n]][n]*fact[n]%MOD;
    ans=add_mod(ans);
    cout<<ans<<"\n";
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
static const int MAXN=270005;
int n,k,mod,m,lv;
int cnt[MAXN], fact[MAXN], invfact[MAXN];
int f[19][MAXN];
inline int fix(int x){ if(x<0) return x+mod; if(x>=mod) return x-mod; return x; }
inline void addmod(int &a,int b){ a=fix(a+b); }
int my_pow(int a,int b){
    if(b==0) return 1;
    int h=my_pow(a,b/2);
    h=1LL*h*h%mod;
    if(b&1) h=1LL*h*a%mod;
    return h;
}
void calc_fact(int N){
    fact[0]=1;
    for(int i=1;i<=N;i++) fact[i]=1LL*fact[i-1]*i%mod;
    invfact[N]=my_pow(fact[N],mod-2);
    for(int i=N-1;i>=0;i--) invfact[i]=1LL*invfact[i+1]*(i+1)%mod;
}
void fwt(int *A,int len,int sgn){
    for(int q=1;q<len;q<<=1)
        for(int off=0;off<len;off+=(q<<1))
            for(int i=off;i<off+q;i++){
                int left=A[i], right=A[i+q];
                addmod(right,sgn*left);
                A[i]=left; A[i+q]=right;
            }
}
vector<long long> multiply(const vector<long long>&a,const vector<long long>&b){
    vector<long long> c(lv+1,0);
    for(int i=0;i<=lv;i++) for(int j=0;j<=lv-i;j++) c[i+j]+=a[i]*b[j];
    for(int i=0;i<=lv;i++) c[i]%=mod;
    return c;
}
vector<long long> poly_power(vector<long long> a,int e){
    vector<long long> c(lv+1,0); c[0]=1;
    while(e){
        if(e&1) c=multiply(c,a);
        a=multiply(a,a);
        e>>=1;
    }
    return c;
}
int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin>>n>>k>>mod;
    calc_fact(n);
    if(n&1){ cout<<my_pow(k,n)<<"\n"; return 0; }
    m=1; lv=0; while(m<=n){ m<<=1; lv++; }
    for(int i=0;i<m;i++) cnt[i]=cnt[i>>1]+(i&1);
    calc_fact(m);
    for(int i=0;i<m;i++) f[cnt[i]][i]=invfact[i];
    for(int i=0;i<=lv;i++) fwt(f[i],m,1);
    vector<long long> tmp(lv+1);
    for(int s=0;s<m;s++){
        for(int i=0;i<=lv;i++) tmp[i]=f[i][s];
        tmp=poly_power(tmp,k);
        for(int i=0;i<=lv;i++) f[i][s]=tmp[i];
    }
    fwt(f[cnt[n]],m,-1);
    int ans=my_pow(k,n) - 1LL*f[cnt[n]][n]*fact[n]%mod;
    ans=fix(ans);
    cout<<ans<<"\n";
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int LIM=270005;
int n,k,mod;
int m,deg;
int bits[LIM], fact[LIM], ifact[LIM];
int dp[19][LIM];
inline int adj(int x){ return x<0 ? x+mod : x>=mod ? x-mod : x; }
inline void r_add(int &x,int y){ x=adj(x+y); }
int qpow(int a,int b){
    int r=1;
    for(;b;b>>=1){ if(b&1) r=1LL*r*a%mod; a=1LL*a*a%mod; }
    return r;
}
void prep(int lim){
    fact[0]=1;
    for(int i=1;i<=lim;i++) fact[i]=1LL*fact[i-1]*i%mod;
    ifact[lim]=qpow(fact[lim],mod-2);
    for(int i=lim-1;i>=0;i--) ifact[i]=1LL*ifact[i+1]*(i+1)%mod;
}
void do_fwt(int *arr,int len,int sgn){
    for(int step=1;step<len;step<<=1){
        for(int base=0;base<len;base+=(step<<1)){
            int *p=arr+base;
            for(int k=0;k<step;k++) r_add(p[k+step],sgn*p[k]);
        }
    }
}
vector<long long> mul_poly(const vector<long long>&x,const vector<long long>&y){
    vector<long long> z(deg+1,0);
    for(int i=0;i<=deg;i++)
        for(int j=0;j<=deg-i;j++)
            z[i+j] += x[i]*y[j];
    for(int i=0;i<=deg;i++) z[i]%=mod;
    return z;
}
vector<long long> poly_pow(vector<long long> a,int e){
    vector<long long> res(deg+1,0); res[0]=1;
    while(e){
        if(e&1) res=mul_poly(res,a);
        a=mul_poly(a,a);
        e>>=1;
    }
    return res;
}
int main(){
