    prep(n);
    if(n&1){ printf("%d\n",qpow(k,n)); return 0; }
    m=1; deg=0;
    while(m<=n){ m<<=1; deg++; }
    for(int i=0;i<m;i++) bits[i]=bits[i>>1]+(i&1);
    prep(m);
    for(int i=0;i<m;i++) dp[bits[i]][i]=ifact[i];
    for(int i=0;i<=deg;i++) do_fwt(dp[i],m,1);
    vector<long long> g(deg+1);
    for(int s=0;s<m;s++){
        for(int i=0;i<=deg;i++) g[i]=dp[i][s];
        g=poly_pow(g,k);
        for(int i=0;i<=deg;i++) dp[i][s]=g[i];
    }
    do_fwt(dp[bits[n]],m,-1);
    int ans=qpow(k,n)-1LL*dp[bits[n]][n]*fact[n]%mod;
    printf("%d\n",adj(ans));
    return 0;
}

