        if (y & 1) res = (ll)res * x % MOD;
        x = (ll)x * x % MOD;
        y >>= 1;
    }
    return res;
}

inline void add_mod(int &x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
}

inline void sub_mod(int &x, int y) {
    x -= y;
    if (x < 0) x += MOD;
}

void fwt(int *a, int len) {
    for (int i = 1; i < len; i <<= 1)
        for (int j = 0; j < len; j += i << 1)
            for (int k = 0; k < i; k++)
                add_mod(a[j + k + i], a[j + k]);
}

void ifwt(int *a, int len) {
    for (int i = 1; i < len; i <<= 1)
        for (int j = 0; j < len; j += i << 1)
            for (int k = 0; k < i; k++)
                sub_mod(a[j + k + i], a[j + k]);
}

void poly_ln(int *a, int *b, int n) {
    b[0] = 0;
    for (int i = 1; i <= n; i++) {
        long long cur = (ll)a[i] * i % MOD;
        for (int j = 1; j < i; j++) {
            cur -= (ll)b[j] * a[i - j] % MOD * j % MOD;
            cur %= MOD;
        }
        if (cur < 0) cur += MOD;
        b[i] = cur * pwr(i, MOD - 2) % MOD;
    }
}

void poly_exp(int *a, int *b, int n) {
    b[0] = 1;
    for (int i = 1; i <= n; i++) {
        long long cur = 0;
        for (int j = 1; j <= i; j++) {
            cur += (ll)a[j] * b[i - j] % MOD * j % MOD;
            cur %= MOD;
        }
        b[i] = cur * pwr(i, MOD - 2) % MOD;
    }
}

