    while (y) {
        if (y & 1) res = (ll)res * x % MOD;
        x = (ll)x * x % MOD;
        y >>= 1;
    }
    return res;
}

void FWT(int *a, int len) {
    for (int step = 1; step < len; step <<= 1) {
        int jump = step << 1;
        for (int i = 0; i < len; i += jump) {
            int *A = a + i;
            int *B = a + i + step;
            for (int j = 0; j < step; ++j) {
                int v = B[j] + A[j];
                if (v >= MOD) v -= MOD;
                B[j] = v;
            }
        }
    }
}

void IFWT(int *a, int len) {
    for (int step = 1; step < len; step <<= 1) {
        int jump = step << 1;
        for (int i = 0; i < len; i += jump) {
            int *A = a + i;
            int *B = a + i + step;
            for (int j = 0; j < step; ++j) {
                int v = B[j] - A[j];
                if (v < 0) v += MOD;
                B[j] = v;
            }
        }
    }
}

void poly_ln(int *a, int *b, int n) {
    b[0] = 0;
    for (int i = 1; i <= n; ++i) {
        long long cur = (ll)a[i] * i % MOD;
        for (int j = 1; j < i; ++j) {
            cur -= (ll)b[j] * a[i - j] % MOD * j % MOD;
            cur %= MOD;
        }
        if (cur < 0) cur += MOD;
        b[i] = cur * invNum[i] % MOD;
    }
}

void poly_exp(int *a, int *b, int n) {
    b[0] = 1;
    for (int i = 1; i <= n; ++i) {
        long long cur = 0;
        for (int j = 1; j <= i; ++j) {
            cur += (ll)a[j] * b[i - j] % MOD * j % MOD;
            cur %= MOD;
        }
        b[i] = cur * invNum[i] % MOD;
    }
}

