}

void zeta_transform(ll a[D][M], int rows) {
    for (int t = 0; t <= rows; ++t) {
        for (int len = m; len >= 2; len >>= 1) {
            int half = len >> 1;
            for (int j = 0; j < m; j += len)
                for (int k = 0; k < half; ++k)
                    a[t][j + k + half] += a[t][j + k];
        }
        for (int j = 0; j < m; ++j) a[t][j] %= P;
    }
