        for (int len = 2; len <= m; len <<= 1) {
            int half = len >> 1;
            for (int j = 0; j < m; j += len)
                for (int k = 0; k < half; ++k)
                    a[t][j + k + half] -= a[t][j + k];
        }
        for (int j = 0; j < m; ++j) a[t][j] = (a[t][j] % P + P) % P;
    }
}

