    for (int i = maxi - 1; i >= 0; i--)
        inv[i] = inv[i + 1] * (i + 1) % p;
}
int lower(int x)
{
    int tmp = 1;
    for (; tmp < x; tmp <<= 1);
    return tmp;
}
void FWT(int *now, int len, bool type = false)
{
    long long *T = t[0];
    for (int i = 0; i < len; i ++) T[i] = now[i];
    if (type)
        for (int i = 1; i < len; i <<= 1)
            for (int j = 0; j < len; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    T[i + k] -= T[k];
    else
        for (int i = 1; i < len; i <<= 1)
            for (int j = 0; j < len; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    T[i + k] += T[k];
    for (int i = 0; i < len; i ++) {
        now[i] = T[i] % p;
        if (now[i] < 0) now[i] += p;
    }
}
