ll h[20], p[20];

inline int pwr(int x, int y) {
    int z = 1;
    while (y) {
        if (y & 1) z = (ll)z * x % Mod;
        x = (ll)x * x % Mod;
        y >>= 1;
    }
    return z;
}

inline void add_mod(int &x, int y) {
    x += y;
    if (x >= Mod) x -= Mod;
}

inline void sub_mod(int &x, int y) {
    x -= y;
    if (x < 0) x += Mod;
}

void fwt(int *a, int m) {
    for (int i = 1; i < m; i <<= 1)
        for (int j = 0; j < m; j += i << 1)
            for (int k = 0; k < i; k++)
                add_mod(a[j + k + i], a[j + k]);
}

void ifwt(int *a, int m) {
    for (int i = 1; i < m; i <<= 1)
        for (int j = 0; j < m; j += i << 1)
            for (int k = 0; k < i; k++)
                sub_mod(a[j + k + i], a[j + k]);
}

void poly_ln() {
    p[0] = 0;
    for (int i = 1; i <= nn; i++) {
        p[i] = h[i] * i;
        for (int j = 1; j < i; j++)
            p[i] -= p[j] * h[i - j] % Mod * j;
        p[i] = p[i] % Mod * inv[i] % Mod;
    }
    for (int i = 0; i <= nn; i++) h[i] = (p[i] + Mod) % Mod;
}

void poly_exp() {
    p[0] = 1;
    for (int i = 1; i <= nn; i++) {
        p[i] = 0;
        for (int j = 1; j <= i; j++)
            p[i] += h[j] * p[i - j] % Mod * j;
        p[i] = p[i] % Mod * inv[i] % Mod;
    }
    for (int i = 0; i <= nn; i++) h[i] = p[i];
}

