typedef long long ll;

#define FOR(i, a, b) for (int i = (a); i <= (b); ++i)
#define FORD(i, a, b) for (int i = (a); i >= (b); --i)

const int N = 262144;

int L, m, K, MOD, length;
int pw2[20], fact[N], invv[N], pcnt[N], A[20][N], B[20][N];
ll q[20], r[20];

inline int qpow(int x, int y) {
    int z = 1;
    while (y) {
        if (y & 1) z = (ll)z * x % MOD;
        x = (ll)x * x % MOD;
        y >>= 1;
    }
    return z;
}

inline void add_mod(int &x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
}

inline void sub_mod(int &x, int y) {
    x -= y;
    if (x < 0) x += MOD;
}

template <typename T>
void fwht(T *a, int n) {
    for (int i = 1; i < n; i <<= 1)
        for (int j = 0; j < n; j += i << 1)
            for (int k = 0; k < i; k++)
                add_mod(a[j + k + i], a[j + k]);
}

template <typename T>
void ifwht(T *a, int n) {
    for (int i = 1; i < n; i <<= 1)
        for (int j = 0; j < n; j += i << 1)
            for (int k = 0; k < i; k++)
                sub_mod(a[j + k + i], a[j + k]);
}

void calc_ln() {
    q[0] = 0;
    FOR(i, 1, m) {
        q[i] = r[i] * i;
        FOR(j, 1, i - 1)
            q[i] -= q[j] * r[i - j] % MOD * j;
        q[i] = q[i] % MOD * invv[i] % MOD;
    }
    FOR(i, 0, m) r[i] = (q[i] + MOD) % MOD;
}

void calc_exp() {
    q[0] = 1;
    FOR(i, 1, m) {
        q[i] = 0;
        FOR(j, 1, i)
            q[i] += r[j] * q[i - j] % MOD * j;
        q[i] = q[i] % MOD * invv[i] % MOD;
    }
    FOR(i, 0, m) r[i] = q[i];
}

int main() {
    scanf("%d%d%d", &L, &K, &MOD);
    int all = qpow(K, L);

    if (L & 1) {
        printf("%d\n", all);
        return 0;
    }

    fact[0] = 1;
    FOR(i, 1, L) fact[i] = (ll)fact[i - 1] * i % MOD;

    invv[L] = qpow(fact[L], MOD - 2);
    FORD(i, L - 1, 0) invv[i] = (ll)invv[i + 1] * (i + 1) % MOD;

    FOR(s, 1, L) pcnt[s] = pcnt[s ^ (s & -s)] + 1;

    FOR(i, 0, 18)
