            if ((i >> (j - 1)) & 1) s += pw2[j];
        A[pcnt[i]][i] = invv[s];
    }

    FOR(i, 2, m)
        invv[i] = (ll)(MOD - MOD / i) * invv[MOD % i] % MOD;

    FOR(i, 0, m) fwht(A[i], length);

    FOR(s, 0, length - 1) {
        FOR(i, 0, m) r[i] = A[i][s];
        calc_ln();
        FOR(i, 0, m) r[i] = r[i] * K;
        calc_exp();
        FOR(i, 0, m) B[i][s] = r[i];
    }

    ifwht(B[m], length);

    int ans = (ll)B[m][length - 1] * fact[L] % MOD;
    ans = (all - ans + MOD) % MOD;

    printf("%d\n", ans);
    return 0;
}

