class Solver {
public:
    int n, kk, P;
    vector<ll> fact, invFact;
    vector<vector<ll>> memo;

    ll modPow(ll a, ll b) {
        ll ret = 1;
        while (b) {
            if (b & 1) ret = ret * a % P;
            a = a * a % P;
            b >>= 1;
        }
        return ret;
    }

    int lowbit(int x) const {
        return x & -x;
    }

    ll dfs(int cur, int mask) {
        ll &res = memo[cur][mask];
        if (res != -1) return res;

        if (mask == 0) {
            res = fact[n];
            for (int i = 1; i <= cur; ++i)
                res = res * (kk - i + 1) % P;
            return res;
        }

        int rest = mask - lowbit(mask);
        res = 0;
        for (int sub = rest; sub > 0; sub = (sub - 1) & rest)
            res = (res + invFact[mask - sub] * dfs(cur + 1, sub)) % P;
        res = (res + invFact[mask] * dfs(cur + 1, 0)) % P;
        return res;
    }

    void solve() {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);

        cin >> n >> kk >> P;
