        for (int i = 1; i <= n; ++i)
            fact[i] = fact[i - 1] * i % P;

        invFact.assign(n + 1, 1);
        invFact[n] = modPow(fact[n], P - 2);
        for (int i = n; i > 0; --i)
            invFact[i - 1] = invFact[i] * i % P;

        memo.assign(26, vector<ll>(n + 1, -1));

        ans = (ans - dfs(0, n) + P) % P;
        cout << ans << '\n';
    }
};

