    for (int i = 1; i <= n; ++i)
        fact[i] = fact[i - 1] * i % P;

    invFact[n] = modPow(fact[n], P - 2);
    for (int i = n; i > 0; --i)
        invFact[i - 1] = invFact[i] * i % P;

    memset(memo, -1, sizeof(memo));

    stack<Frame> st;
    st.push({0, n, 0});

    while (!st.empty()) {
        Frame f = st.top();

        if (memo[f.cur][f.mask] != -1) {
            st.pop();
