ull fastpow(ull a, ull b) {
    ull res = 1;
    while (b) {
        if (b & 1ULL) res = (res * a) % mod;
        a = (a * a) % mod;
        b >>= 1ULL;
    }
    return res;
}

ull binom(int a, int b) {
    return (fact[a] * invfact[b] % mod) * invfact[a - b] % mod;
