    int limit = (int)max(n, k);
    fact[0] = 1ULL;
    for (int i = 1; i <= limit; ++i) fact[i] = fact[i - 1] * (ull)i % mod;
    invfact[limit] = fastpow(fact[limit], mod - 2ULL);
    for (int i = limit - 1; i >= 0; --i)
        invfact[i] = invfact[i + 1] * (ull)(i + 1) % mod;

    for (int i = 1; i <= (int)n; ++i) prev_dp[i] = invfact[i];

    ull ans = prev_dp[(int)n] * binom((int)k, 1) % mod;
    int maxLayer = min(18, (int)k);

