        fill(cur_dp, cur_dp + (int)n + 1, 0ULL);

        for (int j = (int)n; j > 0; j = (j - 1) & (int)n) {
            if (prev_dp[j] == 0) continue;
            int rest = (int)n ^ j;
            for (int l = rest; l > j; l = (l - 1) & rest) {
