    for (int i = n-1; i >= 0; --i) ifac[i] = (ll)ifac[i+1] * (i+1) % MOD;
    inv[1] = 1;
    for (int i = 2; i <= n; ++i) inv[i] = (ll)(MOD - MOD/i) * inv[MOD % i] % MOD;
}

