        ll s = 0;
        for (int j = 1; j < i; ++j)
            s = (s + (ll)f[i-j] * g[j] % MOD * j) % MOD;
        g[i] = (f[i] + s * (MOD - inv[i])) % MOD;
    }
}

void exp(int *f, int *g, int n) {
    g[0] = 1;
    for (int i = 1; i < n; ++i) {
        ll s = 0;
        for (int j = 1; j <= i; ++j)
            s = (s + (ll)g[i-j] * f[j] % MOD * j) % MOD;
        g[i] = s * inv[i] % MOD;
    }
}

