void inverse_subset_sum() {
    for (int bit = 0; bit < 17; ++bit) {
        int step = 1 << bit;
        for (int mask = 0; mask < (1 << 17); ++mask) {
            if (mask & step) B[mask] -= B[mask ^ step];
        }
    }
}

