            }
        }
    }
    for (int idx = 0; idx < 17; ++idx)
        for (int mask = 0; mask < (1<<17); ++mask)
            mat[idx][mask] %= mod;
}

void inverse_sos() {
    for (int bit = 0; bit < 17; ++bit) {
        int bitmask = 1 << bit;
        for (int mask = 0; mask < (1<<17); ++mask) {
