ll power(ll base, ll exp) {
    ll result = 1;
    base %= MOD;
    while (exp) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    scanf("%d %d %d", &n, &k, &MOD);
    if (n % 2 == 1) {
        cout << power(k, n) << "\n";
        return 0;
    }
