    for (int i = 1; i <= n; ++i) fact[i] = fact[i-1] * i % MOD;
    inv_fact[n] = power(fact[n], MOD-2);
    for (int i = n-1; i >= 0; --i) inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;
    n >>= 1;
    for (int i = 0; i <= n; ++i) {
        int pc = __builtin_popcount(i);
        arr[pc][i] = inv_fact[i*2];
    }
    for (int i = 0; i < 17; ++i)
        for (int bit = 0; bit < 17; ++bit)
            for (int mask = 0; mask < (1 << 17); ++mask)
                if ((mask >> bit) & 1)
                    arr[i][mask] += arr[i][mask ^ (1 << bit)];
    for (int i = 0; i < 17; ++i)
        for (int mask = 0; mask < (1 << 17); ++mask)
            arr[i][mask] %= MOD;
    int target = __builtin_popcount(n);
    for (int mask = 0; mask < (1 << 17); ++mask) {
        memset(dp, 0, sizeof(dp));
        dp[0][0] = 1;
        for (int j = 1; j <= k; ++j) {
            for (int u = 0; u <= 17; ++u) {
                ll coeff = arr[u][mask];
                for (int v = 0; u + v <= 17; ++v)
                    dp[j][u+v] = (dp[j][u+v] + coeff * dp[j-1][v]) % MOD;
            }
        }
        b[mask] = dp[k][target];
    }
    for (int bit = 0; bit < 17; ++bit) {
        for (int mask = 0; mask < (1 << 17); ++mask) {
            if ((mask >> bit) & 1)
                b[mask] = (b[mask] - b[mask ^ (1 << bit)]) % MOD;
        }
    }
    ll ans = (power(k, n*2) - (b[n] % MOD) * fact[n*2] % MOD + MOD) % MOD;
    cout << ans << "\n";
    return 0;
}

