// Compute the falling factorial (x)_len mod mod
ll falling(int x, int len) {
    ll r = 1;
    for (int i = 0; i < len; ++i) r = r * (x - i) % mod;
    return r;
}

int main() {
    scanf("%d%d%d", &n, &k, &mod);
