    while (n) {
        if (n & 1) res = (ll)res * x % MOD;
        x = (ll)x * x % MOD;
        n >>= 1;
    }
    return res;
}

int highest_power_of_two(int x) {
    return 1 << __lg(x);
}

int permutation(int n, int m) {
