const int MAXN = 250010;
long long fact[MAXN], inv_fact[MAXN];
long long dp[30][MAXN];
int popcnt[MAXN];
long long n, m, mod;

long long modinv(long long a, long long mod) {
    long long b = mod, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= mod;
    if (u < 0) u += mod;
    return u;
}

long long powmod(long long a, long long b, long long mod) {
    long long res = 1;
    while (b) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

void add(long long &x, long long y) {
    x += y;
    if (x >= mod) x %= mod;
}

int main() {
    cin >> n >> m >> mod;
    fact[0] = fact[1] = 1;
    for (int i = 2; i <= n; i++) fact[i] = fact[i - 1] * i % mod;
    inv_fact[0] = inv_fact[1] = 1;
    for (int i = 2; i <= n; i++) {
        long long inv_i = modinv(i, mod);
        inv_fact[i] = inv_fact[i - 1] * inv_i % mod;
    }
    long long ans = powmod(m, n, mod);
    for (int i = 1; i <= n; i++) popcnt[i] = popcnt[i >> 1] + (i & 1);
    if (n & 1) {
        cout << ans << endl;
        return 0;
    }
    dp[0][0] = 1;
    int limit = min(0LL + popcnt[n], m);
    for (int i = 0; i < limit; i++) {
        for (int j = 0; j < n; j++) {
            if (!dp[i][j]) continue;
            int x = n ^ j;
            for (int k = x, r; k > j; k = (k - 1) & x) {
                r = k | j;
                add(dp[i + 1][r], dp[i][j] * inv_fact[k]);
            }
        }
    }
    long long sum = 0;
    for (int i = 1; i <= m; i++)
        sum = (sum + dp[i][n] * fact[m] % mod * inv_fact[m - i] % mod * fact[n]) % mod;
    ans = (ans - sum + mod) % mod;
    cout << ans << endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define LL long long
#define MN 250005
int Mod;
int ksm(int a,int x){
	LL ans=1,w=a;
	while(x){
		if(x&1)ans=ans*w%Mod;
		w=w*w%Mod;
		x>>=1;
	}
	return ans;
}
int n,k;
int fac[MN],dfac[MN],inv[MN],f[19][MN];
int solve(int use,int S){
	if(f[use][S]!=-1)return f[use][S];
	int ret=0;
	if(!S){
		int ret=fac[n];
		for(int i=1;i<=use;++i)
			ret=1LL*ret*(k-i+1)%Mod;
//		cerr<<"!S "<<use<<" "<<S<<": "<<ret<<endl;
		return f[use][S]=ret;
	}
	if(use>k)return 0;
	int lbit=S&(-S);
	int U=S-lbit;
	for(int T=U;;T=(T-1)&U){
//		cerr<<"? "<<S<<" "<<T<<" "<<lbit<<endl;
		ret=(1LL*dfac[S-T]*solve(use+1,T)+ret)%Mod;	
		if(!T)break;
	}
//	cerr<<use<<" "<<S<<": "<<ret<<endl;
	return f[use][S]=ret;
}
int main(){
	scanf("%d%d%d",&n,&k,&Mod);
	if(n&1){printf("%d\n",ksm(k,n));return 0;}	
	fac[0]=dfac[0]=fac[1]=dfac[1]=inv[1]=1;
	for(int i=2;i<=n;++i){
		fac[i]=1ll*fac[i-1]*i%Mod;
		inv[i]=1ll*(Mod-Mod/i)*inv[Mod%i]%Mod;
		dfac[i]=1ll*dfac[i-1]*inv[i]%Mod;
	}
	for(int i=0;i<=18;++i)
		for(int j=0;j<=n;++j)
			f[i][j]=-1;
	printf("%d\n",(ksm(k,n)-solve(0,n)+Mod)%Mod);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long LL;
const int MN = 250005;
int MOD;
int power(int a, int x) {
    LL res = 1, base = a;
    while (x) {
        if (x & 1) res = res * base % MOD;
        base = base * base % MOD;
        x >>= 1;
    }
    return (int)res;
}
int n, k;
int fac[MN], ifac[MN], inv[MN], dp[19][MN];
int main() {
    scanf("%d%d%d", &n, &k, &MOD);
    if (n & 1) {
        printf("%d\n", power(k, n));
        return 0;
    }
    fac[0] = ifac[0] = fac[1] = ifac[1] = inv[1] = 1;
    for (int i = 2; i <= n; ++i) {
        fac[i] = (LL)fac[i-1] * i % MOD;
        inv[i] = (LL)(MOD - MOD / i) * inv[MOD % i] % MOD;
        ifac[i] = (LL)ifac[i-1] * inv[i] % MOD;
    }
    for (int i = 0; i <= 18; ++i)
        for (int j = 0; j <= n; ++j)
            dp[i][j] = -1;
    // iterative DP: compute dp[use][S] for use from k down to 0
    for (int use = k; use >= 0; --use) {
        for (int S = 0; S <= n; ++S) {
            if (S == 0) {
                int val = fac[n];
                for (int i = 1; i <= use; ++i)
                    val = (LL)val * (k - i + 1) % MOD;
                dp[use][S] = val;
                continue;
            }
            if (use > k) {
                dp[use][S] = 0;
                continue;
            }
            int ret = 0;
            int low = S & -S;
            int U = S - low;
            for (int T = U; ; T = (T - 1) & U) {
                ret = (ret + (LL)ifac[S - T] * dp[use+1][T]) % MOD;
                if (T == 0) break;
            }
            dp[use][S] = ret;
        }
    }
    int ans = (power(k, n) - dp[0][n] + MOD) % MOD;
    printf("%d\n", ans);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define ll long long
const int MAXN = 250005;
int mod;
int fastpow(int a, int e) {
    ll r = 1, w = a;
    while (e) {
        if (e & 1) r = r * w % mod;
        w = w * w % mod;
        e >>= 1;
    }
    return r;
}
int N, K;
int fact[MAXN], invfact[MAXN], invnum[MAXN], memo[19][MAXN];
int dfs(int used, int mask) {
    if (memo[used][mask] != -1) return memo[used][mask];
    int res = 0;
    if (mask == 0) {
        res = fact[N];
        for (int i = 1; i <= used; ++i)
            res = (ll)res * (K - i + 1) % mod;
        return memo[used][mask] = res;
    }
    if (used > K) return 0;
    int low = mask & -mask;
    int rest = mask - low;
    for (int sub = rest; ; sub = (sub - 1) & rest) {
        res = (res + (ll)invfact[mask - sub] * dfs(used + 1, sub)) % mod;
        if (sub == 0) break;
    }
    return memo[used][mask] = res;
}
int main() {
    scanf("%d%d%d", &N, &K, &mod);
    if (N & 1) {
        printf("%d\n", fastpow(K, N));
        return 0;
    }
    fact[0] = invfact[0] = fact[1] = invfact[1] = invnum[1] = 1;
    for (int i = 2; i <= N; ++i) {
        fact[i] = (ll)fact[i-1] * i % mod;
        invnum[i] = (ll)(mod - mod / i) * invnum[mod % i] % mod;
        invfact[i] = (ll)invfact[i-1] * invnum[i] % mod;
    }
    for (int i = 0; i <= 18; ++i)
        for (int j = 0; j <= N; ++j)
            memo[i][j] = -1;
    int ans = (fastpow(K, N) - dfs(0, N) + mod) % mod;
    printf("%d\n", ans);
    return 0;
}

