#include <bits/stdc++.h>
using namespace std;

const int Maxn = 1 << 19 | 5;
int n, k, p, maxi, ct[Maxn], f[Maxn];
int tmp1[20][Maxn], tmp2[20][Maxn], tmp3[20][Maxn];
long long pp;
long long t[20][Maxn];
long long fac[Maxn], inv[Maxn];
long long fast_pow(long long x, long long y)
{
    long long ans = 1, now = x;
    while (y)
    {
        if (y & 1) ans = ans * now % p;
        now = now * now % p;
        y >>= 1;
    }
    return ans;
}
void init(void)
{
    fac[0] = 1;
    for (int i = 1; i <= maxi; i++)
        fac[i] = fac[i - 1] * i % p;
    inv[maxi] = fast_pow(fac[maxi], p - 2);
    for (int i = maxi - 1; i >= 0; i--)
        inv[i] = inv[i + 1] * (i + 1) % p;
}
int lower(int x)
{
    int tmp = 1;
    for (; tmp < x; tmp <<= 1);
    return tmp;
}
void FWT(int *now, int len, bool type = false)
{
	long long *T = t[0];
	for (int i = 0; i < len; i ++) T[i] = now[i];
	if (type)
		for (int i = 1; i < len; i <<= 1)
			for (int j = 0; j < len; j += (i << 1))
				for (int k = j; k < i + j; k++)
					T[i + k] -= T[k];
	else
		for (int i = 1; i < len; i <<= 1)
			for (int j = 0; j < len; j += (i << 1))
				for (int k = j; k < i + j; k++)
					T[i + k] += T[k];
	for (int i = 0; i < len; i ++) {
		now[i] = T[i] % p;
		if (now[i] < 0) now[i] += p;
	}
}
inline void __a (long long &x) { x >= pp ? x -= pp : x; }
void multi(void)
{
    for (int j = 0; j <= 19; j++)
    {
        memset(tmp1[j], 0, sizeof(int[maxi + 1]));
        memset(t[j], 0, sizeof(long long[maxi + 1]));  
    }
    for (int j = 0; j <= maxi; j++)
        tmp1[ct[j]][j] = f[j];
    for (int j = 0; j <= 19; j++)
        FWT(tmp1[j], maxi + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= maxi; s++)
                __a(t[q + l][s] += 1ll * tmp1[q][s] * tmp2[l][s]);
    for (int q = 0; q <= 19; q++)
		for (int s = 0; s <= maxi; s++)
			tmp3[q][s] = t[q][s] % p;
    for (int j = 0; j <= 19; j++)
        FWT(tmp3[j], maxi + 1, true);
    for (int j = 0; j <= maxi; j++)
        f[j] = tmp3[ct[j]][j];
}
void multi2(void)
{
    static int tmp[20][Maxn];
    for (int i = 0; i <= 19; i++)
        memset(t[i], 0, sizeof(long long[maxi + 1]));
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= maxi; s++)
                __a(t[q + l][s] += 1ll * tmp2[q][s] * tmp2[l][s]);
    for (int q = 0; q <= 19; q++)
		for (int s = 0; s <= maxi; s++)
			tmp[q][s] = t[q][s] % p;
    for (int i = 0; i <= 19; i++)
        FWT(tmp[i], maxi + 1, true);
    for (int i = 0; i <= 19; i++)
        memset(tmp2[i], 0, sizeof(int[maxi + 1]));
    for (int i = 0; i <= maxi; i++)
        tmp2[ct[i]][i] = tmp[ct[i]][i];
    for (int i = 0; i <= 19; i++)
        FWT(tmp2[i], maxi + 1);
}
int main()
{
    scanf("%d%d%d", &n, &k, &p);
	pp = 1ll * p * p;
    if (n & 1)
    {
        printf("%lld", fast_pow(k, n));
        return 0;
    }
    f[0] = 1;
    maxi = lower(n + 1) - 1;
    init();
    for (int i = 0; i <= maxi; i++)
        ct[i] = __builtin_popcount(i);
    for (int i = 0; i <= maxi; i++)
        tmp2[ct[i]][i] = inv[i];
    for (int i = 0; i <= 19; i++)
        FWT(tmp2[i], maxi + 1);
    int res_k = k;
    while (k)
    {
        cerr << k << endl;
        if (k & 1) multi();
        k >>= 1;
        if (k) multi2();
    }
    printf("%lld", (fast_pow(res_k, n) - fac[n] * f[n] % p + p) % p);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1 << 19 | 5;
int n, k, p, sizeLimit, popCount[MAXN], arr[MAXN];
int bucket1[20][MAXN], bucket2[20][MAXN], bucket3[20][MAXN];
long long mod2;
long long helper[20][MAXN];
long long fact[MAXN], invFact[MAXN];

long long power(long long base, long long exp) {
    long long res = 1, cur = base;
    while (exp) {
        if (exp & 1) res = res * cur % p;
        cur = cur * cur % p;
        exp >>= 1;
    }
    return res;
}

void factorialInit() {
    fact[0] = 1;
    for (int i = 1; i <= sizeLimit; i++) fact[i] = fact[i - 1] * i % p;
    invFact[sizeLimit] = power(fact[sizeLimit], p - 2);
    for (int i = sizeLimit - 1; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % p;
}

int nextPowerOfTwoMinusOne(int x) {
    int tmp = 1;
    while (tmp < x) tmp <<= 1;
    return tmp - 1;
}

void FWT(int *a, int len, bool inverse = false) {
    long long *tmpArr = helper[0];
    for (int i = 0; i < len; i++) tmpArr[i] = a[i];
    if (inverse) {
        for (int step = 1; step < len; step <<= 1)
            for (int i = 0; i < len; i += (step << 1))
                for (int j = i; j < i + step; j++)
                    tmpArr[j + step] -= tmpArr[j];
    } else {
        for (int step = 1; step < len; step <<= 1)
            for (int i = 0; i < len; i += (step << 1))
                for (int j = i; j < i + step; j++)
                    tmpArr[j + step] += tmpArr[j];
    }
    for (int i = 0; i < len; i++) {
        a[i] = tmpArr[i] % p;
        if (a[i] < 0) a[i] += p;
    }
}

inline void reduce(long long &val) {
    if (val >= mod2) val -= mod2;
}

void convolutionWithArr() {
    for (int j = 0; j <= 19; j++) {
        fill(bucket1[j], bucket1[j] + sizeLimit + 1, 0);
        fill(helper[j], helper[j] + sizeLimit + 1, 0);
    }
    for (int j = 0; j <= sizeLimit; j++) bucket1[popCount[j]][j] = arr[j];
    for (int j = 0; j <= 19; j++) FWT(bucket1[j], sizeLimit + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= sizeLimit; s++)
                reduce(helper[q + l][s] += 1LL * bucket1[q][s] * bucket2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= sizeLimit; s++)
            bucket3[q][s] = helper[q][s] % p;
    for (int j = 0; j <= 19; j++) FWT(bucket3[j], sizeLimit + 1, true);
    for (int j = 0; j <= sizeLimit; j++) arr[j] = bucket3[popCount[j]][j];
}

void convolutionWithSelf() {
    static int temp[20][MAXN];
    for (int i = 0; i <= 19; i++) fill(helper[i], helper[i] + sizeLimit + 1, 0);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= sizeLimit; s++)
                reduce(helper[q + l][s] += 1LL * bucket2[q][s] * bucket2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= sizeLimit; s++)
            temp[q][s] = helper[q][s] % p;
    for (int i = 0; i <= 19; i++) FWT(temp[i], sizeLimit + 1, true);
    for (int i = 0; i <= 19; i++) fill(bucket2[i], bucket2[i] + sizeLimit + 1, 0);
    for (int i = 0; i <= sizeLimit; i++) bucket2[popCount[i]][i] = temp[popCount[i]][i];
    for (int i = 0; i <= 19; i++) FWT(bucket2[i], sizeLimit + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    mod2 = 1LL * p * p;
    if (n & 1) {
        printf("%lld", power(k, n));
        return 0;
    }
    arr[0] = 1;
    sizeLimit = nextPowerOfTwoMinusOne(n + 1);
    factorialInit();
    for (int i = 0; i <= sizeLimit; i++) popCount[i] = __builtin_popcount(i);
    for (int i = 0; i <= sizeLimit; i++) bucket2[popCount[i]][i] = invFact[i];
    for (int i = 0; i <= 19; i++) FWT(bucket2[i], sizeLimit + 1);
    int originalK = k;
    while (k) {
        cerr << k << endl;
        if (k & 1) convolutionWithArr();
        k >>= 1;
        if (k) convolutionWithSelf();
    }
    printf("%lld", (power(originalK, n) - fact[n] * arr[n] % p + p) % p);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

#define MAXN (1 << 19 | 5)
#define MAXP 20

int n, k, p;
int lim, cnt[MAXN], poly[MAXN];
int layer1[MAXP][MAXN], layer2[MAXP][MAXN], layer3[MAXP][MAXN];
long long modSq;
long long inter[MAXP][MAXN];
long long fact[MAXN], invf[MAXN];

long long powmod(long long a, long long b) {
    long long r = 1;
    while (b) {
        if (b & 1) r = r * a % p;
        a = a * a % p;
        b >>= 1;
    }
    return r;
}

void init_fact() {
    fact[0] = 1;
    for (int i = 1; i <= lim; i++) fact[i] = fact[i - 1] * i % p;
    invf[lim] = powmod(fact[lim], p - 2);
    for (int i = lim - 1; i >= 0; i--) invf[i] = invf[i + 1] * (i + 1) % p;
}

int pow2_minus1(int x) {
    int s = 1;
    while (s < x) s <<= 1;
    return s - 1;
}

void hadamard(int *arr, int len, bool rev = false) {
    long long *tmp = inter[0];
    for (int i = 0; i < len; i++) tmp[i] = arr[i];
    if (rev) {
        for (int h = 1; h < len; h <<= 1)
            for (int i = 0; i < len; i += (h << 1))
                for (int j = i; j < i + h; j++)
                    tmp[j + h] -= tmp[j];
    } else {
        for (int h = 1; h < len; h <<= 1)
            for (int i = 0; i < len; i += (h << 1))
                for (int j = i; j < i + h; j++)
                    tmp[j + h] += tmp[j];
    }
    for (int i = 0; i < len; i++) {
        arr[i] = tmp[i] % p;
        if (arr[i] < 0) arr[i] += p;
    }
}

static inline void add_mod(long long &x) {
    if (x >= modSq) x -= modSq;
}

void multiply_poly() {
    for (int i = 0; i < MAXP; i++) {
        memset(layer1[i], 0, sizeof(int) * (lim + 1));
        memset(inter[i], 0, sizeof(long long) * (lim + 1));
    }
    for (int i = 0; i <= lim; i++) layer1[cnt[i]][i] = poly[i];
    for (int i = 0; i < MAXP; i++) hadamard(layer1[i], lim + 1);
    for (int a = 0; a < MAXP; a++)
        for (int b = 0; a + b < MAXP; b++)
            for (int i = 0; i <= lim; i++)
                add_mod(inter[a + b][i] += 1LL * layer1[a][i] * layer2[b][i]);
    for (int a = 0; a < MAXP; a++)
        for (int i = 0; i <= lim; i++)
            layer3[a][i] = inter[a][i] % p;
    for (int a = 0; a < MAXP; a++) hadamard(layer3[a], lim + 1, true);
    for (int i = 0; i <= lim; i++) poly[i] = layer3[cnt[i]][i];
}

void multiply_self() {
    static int tmp[MAXP][MAXN];
    for (int i = 0; i < MAXP; i++) memset(inter[i], 0, sizeof(long long) * (lim + 1));
    for (int a = 0; a < MAXP; a++)
        for (int b = 0; a + b < MAXP; b++)
            for (int i = 0; i <= lim; i++)
                add_mod(inter[a + b][i] += 1LL * layer2[a][i] * layer2[b][i]);
    for (int a = 0; a < MAXP; a++)
        for (int i = 0; i <= lim; i++)
            tmp[a][i] = inter[a][i] % p;
    for (int a = 0; a < MAXP; a++) hadamard(tmp[a], lim + 1, true);
    for (int a = 0; a < MAXP; a++) memset(layer2[a], 0, sizeof(int) * (lim + 1));
    for (int i = 0; i <= lim; i++) layer2[cnt[i]][i] = tmp[cnt[i]][i];
    for (int a = 0; a < MAXP; a++) hadamard(layer2[a], lim + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    modSq = 1LL * p * p;
    if (n & 1) {
        printf("%lld", powmod(k, n));
        return 0;
    }
    poly[0] = 1;
    lim = pow2_minus1(n + 1);
    init_fact();
    for (int i = 0; i <= lim; i++) cnt[i] = __builtin_popcount(i);
    for (int i = 0; i <= lim; i++) layer2[cnt[i]][i] = invf[i];
    for (int i = 0; i < MAXP; i++) hadamard(layer2[i], lim + 1);
    int orig_k = k;
    while (k) {
        cerr << k << endl;
        if (k & 1) multiply_poly();
        k >>= 1;
        if (k) multiply_self();
    }
    printf("%lld", (powmod(orig_k, n) - fact[n] * poly[n] % p + p) % p);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXB = 1 << 19 | 5;
const int LAYERS = 20;

int n, k, p;
int lim, bits[MAXB], fvec[MAXB];
int bucketA[LAYERS][MAXB], bucketB[LAYERS][MAXB], bucketC[LAYERS][MAXB];
long long pp;
long long tempArr[LAYERS][MAXB];
long long fact[MAXB], invfact[MAXB];

long long binpow(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = res * base % p;
        base = base * base % p;
        exp >>= 1;
    }
    return res;
}

void precompute_factorials() {
    fact[0] = 1;
    for (int i = 1; i <= lim; i++) fact[i] = fact[i - 1] * i % p;
    invfact[lim] = binpow(fact[lim], p - 2);
    for (int i = lim - 1; i >= 0; i--) invfact[i] = invfact[i + 1] * (i + 1) % p;
}

int get_power_bound(int x) {
    int v = 1;
    while (v < x) v <<= 1;
    return v;
}

void fwt_transform(int *vec, int len, bool invert = false) {
    long long *tmp = tempArr[0];
    for (int i = 0; i < len; i++) tmp[i] = vec[i];
    if (invert) {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += (step << 1)) {
                for (int j = i; j < i + step; j++) {
                    tmp[j + step] -= tmp[j];
                }
            }
        }
    } else {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += (step << 1)) {
                for (int j = i; j < i + step; j++) {
                    tmp[j + step] += tmp[j];
                }
            }
        }
    }
    for (int i = 0; i < len; i++) {
        vec[i] = tmp[i] % p;
        if (vec[i] < 0) vec[i] += p;
    }
}

inline void safe_add(long long &x) {
    if (x >= pp) x -= pp;
}

void combine(int *result, bool self) {
    static int store[LAYERS][MAXB];
    if (self) {
        for (int i = 0; i < LAYERS; i++) memset(tempArr[i], 0, sizeof(long long) * (lim + 1));
        for (int a = 0; a < LAYERS; a++)
            for (int b = 0; a + b < LAYERS; b++)
                for (int i = 0; i <= lim; i++)
                    safe_add(tempArr[a + b][i] += 1LL * bucketB[a][i] * bucketB[b][i]);
        for (int a = 0; a < LAYERS; a++)
            for (int i = 0; i <= lim; i++)
                store[a][i] = tempArr[a][i] % p;
        for (int a = 0; a < LAYERS; a++) fwt_transform(store[a], lim + 1, true);
        for (int a = 0; a < LAYERS; a++) memset(bucketB[a], 0, sizeof(int) * (lim + 1));
        for (int i = 0; i <= lim; i++) bucketB[bits[i]][i] = store[bits[i]][i];
        for (int a = 0; a < LAYERS; a++) fwt_transform(bucketB[a], lim + 1);
    } else {
        for (int i = 0; i < LAYERS; i++) {
            memset(bucketA[i], 0, sizeof(int) * (lim + 1));
            memset(tempArr[i], 0, sizeof(long long) * (lim + 1));
        }
        for (int i = 0; i <= lim; i++) bucketA[bits[i]][i] = fvec[i];
        for (int a = 0; a < LAYERS; a++) fwt_transform(bucketA[a], lim + 1);
        for (int a = 0; a < LAYERS; a++)
            for (int b = 0; a + b < LAYERS; b++)
                for (int i = 0; i <= lim; i++)
                    safe_add(tempArr[a + b][i] += 1LL * bucketA[a][i] * bucketB[b][i]);
        for (int a = 0; a < LAYERS; a++)
            for (int i = 0; i <= lim; i++)
                bucketC[a][i] = tempArr[a][i] % p;
        for (int a = 0; a < LAYERS; a++) fwt_transform(bucketC[a], lim + 1, true);
        for (int i = 0; i <= lim; i++) fvec[i] = bucketC[bits[i]][i];
    }
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    pp = 1LL * p * p;
    if (n & 1) {
        printf("%lld", binpow(k, n));
        return 0;
    }
    fvec[0] = 1;
    lim = get_power_bound(n + 1) - 1;
    precompute_factorials();
    for (int i = 0; i <= lim; i++) bits[i] = __builtin_popcount(i);
    for (int i = 0; i <= lim; i++) bucketB[bits[i]][i] = invfact[i];
    for (int i = 0; i < LAYERS; i++) fwt_transform(bucketB[i], lim + 1);
    int orig = k;
    while (k) {
        cerr << k << endl;
        if (k & 1) combine(bucketC, false);
        k >>= 1;
        if (k) combine(bucketC, true);
    }
    printf("%lld", (binpow(orig, n) - fact[n] * fvec[n] % p + p) % p);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = (1 << 19) + 5;
const int DEPTH = 20;

int n, k, p;
int bound, popcnt[MAXN], f[MAXN];
int layerA[DEPTH][MAXN], layerB[DEPTH][MAXN], layerC[DEPTH][MAXN];
long long tempStorage[DEPTH][MAXN];
long long factorial[MAXN], invFactorial[MAXN];
long long modSq;

long long exp_mod(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % p;
        a = a * a % p;
        e >>= 1;
    }
    return r;
}

void compute_factorials() {
    factorial[0] = 1;
    for (int i = 1; i <= bound; i++) factorial[i] = factorial[i - 1] * i % p;
    invFactorial[bound] = exp_mod(factorial[bound], p - 2);
    for (int i = bound - 1; i >= 0; i--) invFactorial[i] = invFactorial[i + 1] * (i + 1) % p;
}

int min_power_above(int x) {
    int r = 1;
    while (r < x) r <<= 1;
    return r;
}

void FWT_core(int *arr, int len, bool reverse_op = false) {
    long long *buf = tempStorage[0];
    for (int i = 0; i < len; i++) buf[i] = arr[i];
    if (reverse_op) {
        for (int step = 1; step < len; step <<= 1)
            for (int i = 0; i < len; i += (step << 1))
                for (int j = i; j < i + step; j++)
                    buf[j + step] -= buf[j];
    } else {
        for (int step = 1; step < len; step <<= 1)
            for (int i = 0; i < len; i += (step << 1))
                for (int j = i; j < i + step; j++)
                    buf[j + step] += buf[j];
    }
    for (int i = 0; i < len; i++) {
        arr[i] = buf[i] % p;
        if (arr[i] < 0) arr[i] += p;
    }
}

inline void ensure_under_mod_sq(long long &v) {
    if (v >= modSq) v -= modSq;
}

void multiply_A_B() {
    for (int i = 0; i < DEPTH; i++) {
        memset(layerA[i], 0, sizeof(int) * (bound + 1));
        memset(tempStorage[i], 0, sizeof(long long) * (bound + 1));
    }
    for (int i = 0; i <= bound; i++) layerA[popcnt[i]][i] = f[i];
    for (int i = 0; i < DEPTH; i++) FWT_core(layerA[i], bound + 1);
    for (int a = 0; a < DEPTH; a++)
        for (int b = 0; a + b < DEPTH; b++)
            for (int i = 0; i <= bound; i++)
                ensure_under_mod_sq(tempStorage[a + b][i] += 1LL * layerA[a][i] * layerB[b][i]);
    for (int a = 0; a < DEPTH; a++)
        for (int i = 0; i <= bound; i++)
            layerC[a][i] = tempStorage[a][i] % p;
    for (int a = 0; a < DEPTH; a++) FWT_core(layerC[a], bound + 1, true);
    for (int i = 0; i <= bound; i++) f[i] = layerC[popcnt[i]][i];
}

void multiply_B_B() {
    static int tmp[DEPTH][MAXN];
    for (int i = 0; i < DEPTH; i++) memset(tempStorage[i], 0, sizeof(long long) * (bound + 1));
    for (int a = 0; a < DEPTH; a++)
        for (int b = 0; a + b < DEPTH; b++)
            for (int i = 0; i <= bound; i++)
                ensure_under_mod_sq(tempStorage[a + b][i] += 1LL * layerB[a][i] * layerB[b][i]);
    for (int a = 0; a < DEPTH; a++)
        for (int i = 0; i <= bound; i++)
            tmp[a][i] = tempStorage[a][i] % p;
    for (int a = 0; a < DEPTH; a++) FWT_core(tmp[a], bound + 1, true);
    for (int a = 0; a < DEPTH; a++) memset(layerB[a], 0, sizeof(int) * (bound + 1));
    for (int i = 0; i <= bound; i++) layerB[popcnt[i]][i] = tmp[popcnt[i]][i];
    for (int a = 0; a < DEPTH; a++) FWT_core(layerB[a], bound + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    modSq = 1LL * p * p;
    if (n & 1) {
        printf("%lld", exp_mod(k, n));
        return 0;
    }
    f[0] = 1;
    bound = min_power_above(n + 1) - 1;
    compute_factorials();
    for (int i = 0; i <= bound; i++) popcnt[i] = __builtin_popcount(i);
    for (int i = 0; i <= bound; i++) layerB[popcnt[i]][i] = invFactorial[i];
    for (int i = 0; i < DEPTH; i++) FWT_core(layerB[i], bound + 1);
    int k_copy = k;
    while (k) {
        cerr << k << endl;
        if (k & 1) multiply_A_B();
        k >>= 1;
        if (k) multiply_B_B();
    }
    printf("%lld", (exp_mod(k_copy, n) - factorial[n] * f[n] % p + p) % p);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

constexpr int MaxB = (1 << 19) + 5;
constexpr int Layers = 20;

int n, k, p;
int limit, bt[MaxB], coeff[MaxB];
int boxA[Layers][MaxB], boxB[Layers][MaxB], boxC[Layers][MaxB];
long long mods[Layers][MaxB];
long long p2;
long long fac[MaxB], invF[MaxB];

long long fp(long long a, long long b) {
    long long res = 1;
    while (b) {
        if (b & 1) res = res * a % p;
        a = a * a % p;
        b >>= 1;
    }
    return res;
}

void prepare() {
    fac[0] = 1;
    for (int i = 1; i <= limit; i++) fac[i] = fac[i - 1] * i % p;
    invF[limit] = fp(fac[limit], p - 2);
    for (int i = limit - 1; i >= 0; i--) invF[i] = invF[i + 1] * (i + 1) % p;
}

int roundToPow(int x) {
    int y = 1;
    while (y < x) y <<= 1;
    return y;
}

void FWTh(int *a, int len, bool rev = false) {
    long long *tmp = mods[0];
    for (int i = 0; i < len; i++) tmp[i] = a[i];
    if (rev) {
        for (int m = 1; m < len; m <<= 1)
            for (int b = 0; b < len; b += (m << 1))
                for (int j = b; j < b + m; j++)
                    tmp[j + m] -= tmp[j];
    } else {
        for (int m = 1; m < len; m <<= 1)
            for (int b = 0; b < len; b += (m << 1))
                for (int j = b; j < b + m; j++)
                    tmp[j + m] += tmp[j];
    }
    for (int i = 0; i < len; i++) {
        a[i] = tmp[i] % p;
        if (a[i] < 0) a[i] += p;
    }
}

inline void normalize(long long &x) {
    if (x >= p2) x -= p2;
}

void conv(bool mode) {
    static int aux[Layers][MaxB];
    if (mode) {
        for (int i = 0; i < Layers; i++) memset(mods[i], 0, sizeof(long long) * (limit + 1));
        for (int u = 0; u < Layers; u++)
            for (int v = 0; u + v < Layers; v++)
                for (int i = 0; i <= limit; i++)
                    normalize(mods[u + v][i] += 1LL * boxB[u][i] * boxB[v][i]);
        for (int u = 0; u < Layers; u++)
            for (int i = 0; i <= limit; i++)
                aux[u][i] = mods[u][i] % p;
        for (int u = 0; u < Layers; u++) FWTh(aux[u], limit + 1, true);
        for (int u = 0; u < Layers; u++) memset(boxB[u], 0, sizeof(int) * (limit + 1));
        for (int i = 0; i <= limit; i++) boxB[bt[i]][i] = aux[bt[i]][i];
        for (int u = 0; u < Layers; u++) FWTh(boxB[u], limit + 1);
    } else {
        for (int i = 0; i < Layers; i++) {
            memset(boxA[i], 0, sizeof(int) * (limit + 1));
            memset(mods[i], 0, sizeof(long long) * (limit + 1));
        }
        for (int i = 0; i <= limit; i++) boxA[bt[i]][i] = coeff[i];
        for (int u = 0; u < Layers; u++) FWTh(boxA[u], limit + 1);
        for (int u = 0; u < Layers; u++)
            for (int v = 0; u + v < Layers; v++)
                for (int i = 0; i <= limit; i++)
                    normalize(mods[u + v][i] += 1LL * boxA[u][i] * boxB[v][i]);
        for (int u = 0; u < Layers; u++)
            for (int i = 0; i <= limit; i++)
                boxC[u][i] = mods[u][i] % p;
        for (int u = 0; u < Layers; u++) FWTh(boxC[u], limit + 1, true);
        for (int i = 0; i <= limit; i++) coeff[i] = boxC[bt[i]][i];
    }
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    p2 = 1LL * p * p;
    if (n & 1) {
        printf("%lld", fp(k, n));
        return 0;
    }
    coeff[0] = 1;
    limit = roundToPow(n + 1) - 1;
    prepare();
    for (int i = 0; i <= limit; i++) bt[i] = __builtin_popcount(i);
    for (int i = 0; i <= limit; i++) boxB[bt[i]][i] = invF[i];
    for (int i = 0; i < Layers; i++) FWTh(boxB[i], limit + 1);
    int ok = k;
    while (k) {
        cerr << k << endl;
        if (k & 1) conv(false);
        k >>= 1;
        if (k) conv(true);
    }
    printf("%lld", (fp(ok, n) - fac[n] * coeff[n] % p + p) % p);
    return 0;
}

#include<cstdio>
