int fact[N], invFact[N];

int add(int a, int b) {
    int res = a + b;
    if (res >= mod) res -= mod;
    return res;
}

int mul(int a, int b) {
    return (long long)a * b % mod;
}

int power(int x, int y) {
    int res = 1;
    while (y) {
        if (y & 1) res = mul(res, x);
        x = mul(x, x);
        y >>= 1;
    }
    return res;
}

int C(int i, int j) {
    return mul(mul(fact[i], invFact[j]), invFact[i - j]);
}

