vector<pair<int,int>> tp;
inline int bfs(int n, int k) {
    static queue<pair<int,int>> que;
    que.push(make_pair(n, k));
    while(!que.empty()) {
        n = que.front().first, k = que.front().second;
        que.pop();
        tp.push_back(make_pair(n, k));
        if(n == 0 || k == 0) continue;
        int di = (1 << Log[n]);
        for(int i = n; i >= di; i -= 2) {
            if(cumTrail[i] + cumTrail[n - i] == cumTrail[n] && !vis[n - i][k - 1]) {
                vis[n - i][k - 1] = 1;
                que.push(make_pair(n - i, k - 1));
            }
        }
    }
    for(int i = tp.size() - 1; i >= 0; --i) {
        n = tp[i].first, k = tp[i].second;
        if(n == 0) { dp[n][k] = 1; continue; }
        if(k == 0) { dp[n][k] = 0; continue; }
        int di = (1 << Log[n]);
        for(int i = n; i >= di; i -= 2) {
            if(cumTrail[i] + cumTrail[n - i] == cumTrail[n])
                dp[n][k] = ((long long)dp[n][k] + (long long)C(n, i) * dp[n - i][k - 1] % mod * k) % mod;
        }
    }
    return dp[n][k];
}

int main() {
    R(n), R(k), R(mod);
    fact[0] = 1;
    memset(vis, 0, sizeof(vis));
    Log[0] = -1;
    for(int i = 1; i <= 262150; ++i) {
        fact[i] = (long long)fact[i - 1] * i % mod;
        Log[i] = Log[i >> 1] + 1;
        cumTrail[i] = cumTrail[i - 1] + getcnt(i);
    }
    // compute modular inverses of numbers 1..262150
    int invNum[262155];
    invNum[1] = 1;
    for(int i = 2; i <= 262150; ++i) {
        invNum[i] = mod - (long long)(mod / i) * invNum[mod % i] % mod;
    }
    // compute factorial inverses using invNum
    invFact[0] = 1;
    for(int i = 1; i <= 262150; ++i) {
        invFact[i] = (long long)invFact[i - 1] * invNum[i] % mod;
    }
    // note: original invFact[262150] = modPow(fact[262150], mod-2) then backwards.
    // Our method gives same result because invFact[i] = (i!)^{-1} mod mod.
    // But we need to ensure invFact[0] = 1, which we set.
    // The original also sets inv[0] = inv[1] after loop; we don't need that.
    if(n & 1) {
        cout << modPow(k, n) << '\n';
    } else {
        int ans = modPow(k, n);
        ans = ((ans - bfs(n, k)) % mod + mod) % mod;
        cout << ans << '\n';
    }
    return 0;
}

