void addTo(int &x, int y) { x = safe(x + y); }
int mpow(int base, int exp) {
    int res = 1;
    while (exp) {
        if (exp & 1) res = 1ll * res * base % mod;
        base = 1ll * base * base % mod;
        exp >>= 1;
    }
    return res;
}
int fct[2005], invfct[2005];
void setup(int lim) {
    fct[0] = 1;
    for (int i = 1; i <= lim; i++) fct[i] = 1ll * fct[i-1] * i % mod;
    invfct[lim] = mpow(fct[lim], mod - 2);
    for (int i = lim - 1; i >= 0; i--) invfct[i] = 1ll * invfct[i+1] * (i+1) % mod;
}
int choose(int n, int k) {
    if (n < 0 || k < 0 || n < k) return 0;
    return 1ll * fct[n] * invfct[n-k] % mod * invfct[k] % mod;
}
int triSum(int x) { return x * (x + 1) / 2; }
vector<int> mulVects(const vector<int> &a, const vector<int> &b) {
    vector<int> c(a.size() + b.size() - 1, 0);
    for (size_t i = 0; i < a.size(); i++)
        for (size_t j = 0; j < b.size(); j++) {
            long long prod = 1ll * a[i] * b[j] % mod;
            c[i+j] = safe(c[i+j] + prod);
        }
    return c;
}
