    for (int i = 0; i <= n; i++) {
        for (int j = C[i][0] = 1; j <= i; j++) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P;
        }
    }
    for (int i = f1[0] = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            f1[i] = (f1[i] + 1LL * f1[j - 1] * f1[i - j] % P * C[i - 1][j - 1]) % P;
            int t = (1LL * f1[j - 1] * g1[i - j] + 1LL * g1[j - 1] * f1[i - j]) % P
                * (i + 1) % P;
            g1[i] = (g1[i] + (1LL * f1[j - 1] * f1[i - j] % P * (C[j][2] +
                C[i - j + 1][2]) % P + t) % P * C[i - 1][j - 1]) % P;
        }
        f1[i] = 1LL * (i + 1) * f1[i] % P;
    }
