                f2[i][j] = (f2[i][j] + bf * f1[k] % P * C[j][k]) % P;
                g2[i][j] = (g2[i][j] + (bf * g1[k] + bg * f1[k]) % P * C[j][k]) % P;
            }
        }
    }
    printf("%d\n", g2[n][m]);
    return 0;
}

