const int maxn = 510;
int n, m, P;
int C[maxn][maxn], f1[maxn], f2[maxn][maxn], g1[maxn], g2[maxn][maxn];

int main() {
    scanf("%d %d %d", &n, &m, &P);
    // Compute binomial coefficients using recurrence
    for (int i = 0; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % P;
    }
    // Compute f1 and g1
    f1[0] = 1;
    for (int i = 1; i <= n; ++i) {
        long long sum_f = 0, sum_g = 0;
        for (int j = 1; j <= i; ++j) {
            long long a = 1LL * f1[j-1] * f1[i-j] % P;
            sum_f = (sum_f + a * C[i-1][j-1]) % P;
            long long t = (1LL * f1[j-1] * g1[i-j] + 1LL * g1[j-1] * f1[i-j]) % P;
            t = 1LL * t * (i+1) % P;
            long long b = (a * (C[j][2] + C[i-j+1][2]) % P + t) % P;
            sum_g = (sum_g + b * C[i-1][j-1]) % P;
        }
        f1[i] = 1LL * (i+1) * sum_f % P;
        g1[i] = sum_g;
    }
    // Compute f2 and g2
    f2[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= min(i, m); ++j) {
            f2[i][j] = f2[i-1][j];
            g2[i][j] = g2[i-1][j];
            for (int k = 1; k <= j; ++k) {
                long long base_f = (i - k) ? f2[i-k-1][j-k] : 1;
                long long base_g = (i - k) ? g2[i-k-1][j-k] : 0;
                f2[i][j] = (f2[i][j] + base_f * f1[k] % P * C[j][k]) % P;
                g2[i][j] = (g2[i][j] + (base_f * g1[k] + base_g * f1[k]) % P * C[j][k]) % P;
            }
        }
    }
    printf("%d\n", g2[n][m]);
    return 0;
}

