typedef long long ll;

struct Mint {
    static int mod;
    int v;
    Mint() : v(0) {}
    Mint(ll _v) { v = (int)(_v % mod); if (v < 0) v += mod; }
    int val() const { return v; }
    Mint& operator+=(const Mint& o) {
        v += o.v;
        if (v >= mod) v -= mod;
        return *this;
    }
    Mint& operator-=(const Mint& o) {
        v -= o.v;
        if (v < 0) v += mod;
        return *this;
    }
    Mint& operator*=(const Mint& o) {
        v = (ll)v * o.v % mod;
        return *this;
    }
    friend Mint operator+(Mint a, const Mint& b) { return a += b; }
    friend Mint operator-(Mint a, const Mint& b) { return a -= b; }
    friend Mint operator*(Mint a, const Mint& b) { return a *= b; }
};

