            if (k > 0) {
                crst = (crst * F[k-1] + cur * RST[k-1]) % MOD;
                cur = (cur * F[k-1]) % MOD;
            }
            if (k < i) {
                crst = (crst * F[i-k-1] + cur * RST[i-k-1]) % MOD;
                cur = (cur * F[i-k-1]) % MOD;
            }
            RST[i] = (RST[i] + crst * (i + 2LL) + cur * (sum(k) + sum(i-k))) % MOD;
            F[i] = (F[i] + (i + 2LL) * cur) % MOD;
