            int term2=mul(comb,i+1);
            g[i]=add(g[i],mul(term2,add(mul(f[j-1],g[i-j]),mul(g[j-1],f[i-j]))));
            int extra=(j-1)*j/2+(i-j+1)*(i-j)/2;
            g[i]=add(g[i],mul(mul(comb,extra),mul(f[j-1],f[i-j])));
        }
    }
