				if(dp1[k][i] >= mod) dp1[k][i] -= mod;

				dp2[k][i] += (int)((1ll * c[j] * dp1[max(k-j-1, 0)][i-j] % mod) * choose(i, j) % mod);
				if(dp2[k][i] >= mod) dp2[k][i] -= mod;
				dp2[k][i] += (int)((1ll * f[j] * dp2[max(k-j-1, 0)][i-j] % mod) * choose(i, j) % mod);
				if(dp2[k][i] >= mod) dp2[k][i] -= mod;
