        fat[i] = (int)(1LL * fat[i-1] * i % mod);
        inv[i] = mod - (int)(1LL * (mod/i) * inv[mod%i] % mod);
        inv_fat[i] = (int)(1LL * inv_fat[i-1] * inv[i] % mod);
    }
}

int dp1(int k, int i) {
    if(i == 0) return 1;
    if(i > k) return 0;
    if(done1[k][i]) return memo1[k][i];
    int res = (k > 0 ? dp1(k-1, i) : 0);
    for(int j = 1; j <= i; j++) {
        res = (res + (int)(1LL * f[j] * dp1(max(k-j-1, 0), i-j) % mod * choose(i, j) % mod)) % mod;
    }
    memo1[k][i] = res;
    done1[k][i] = true;
    return res;
}

int dp2(int k, int i) {
    if(i == 0) return 0;
    if(i > k) return 0;
    if(done2[k][i]) return memo2[k][i];
    int res = (k > 0 ? dp2(k-1, i) : 0);
    for(int j = 1; j <= i; j++) {
        res = (res + (int)(1LL * c[j] * dp1(max(k-j-1, 0), i-j) % mod * choose(i, j) % mod)) % mod;
        res = (res + (int)(1LL * f[j] * dp2(max(k-j-1, 0), i-j) % mod * choose(i, j) % mod)) % mod;
    }
    memo2[k][i] = res;
    done2[k][i] = true;
    return res;
}

int main() {
    int n, m;
    scanf("%d %d %d", &n, &m, &mod);
    calc();
    f[0] = 1;
    for(int i = 1; i <= m; i++) {
        for(int j = 0; j < i; j++) {
            f[i] = (f[i] + (int)(1LL * choose(i-1, j) * f[j] % mod * f[i-1-j] % mod)) % mod;
            c[i] = (c[i] + (int)(1LL * (i+1) * choose(i-1, j) % mod *
                ((1LL * f[j] * c[i-1-j] + 1LL * f[i-1-j] * c[j]) % mod) % mod)) % mod;
            c[i] = (c[i] + (int)(1LL * choose(i-1, j) * ((p(j) + p(i-1-j)) % mod) % mod *
                (1LL * f[j] * f[i-1-j] % mod))) % mod;
        }
        f[i] = (int)(1LL * f[i] * (i+1) % mod);
    }
    printf("%d\n", dp2(n, m));
    return 0;
}

