            ll sr = sum[m-1-k] * inv[m-1-k] % mod;
            add_cnt = (add_cnt + cl * cr % mod * (m+1)) % mod;
            add_sum = (add_sum + (cl * sr + sl * cr) % mod * (m+1)) % mod;
            ll term = (k*(k+1)+(m-k)*(m-k-1))/2 % mod;
            add_sum = (add_sum + cl * cr % mod * term) % mod;
        }
        cnt[m] = add_cnt * fac[m-1] % mod;
        sum[m] = add_sum * fac[m-1] % mod;
    }
    vector<vector<ll>> cnt_ans(N+1, vector<ll>(M+1, 0)), sum_ans(N+1, vector<ll>(M+1, 0));
    cnt_ans[0][0] = 1;
    for(int i = 1; i <= N; i++) {
        for(int j = 0; j <= min(i, M); j++) {
            cnt_ans[i][j] = cnt_ans[i-1][j];
            sum_ans[i][j] = sum_ans[i-1][j];
            if(j == i) {
                cnt_ans[i][j] = (cnt_ans[i][j] + cnt[i] * inv[i]) % mod;
                sum_ans[i][j] = (sum_ans[i][j] + sum[i] * inv[i]) % mod;
            }
            for(int k = 1; k <= min(j, i-1); k++) {
                ll c = cnt[k] * inv[k] % mod;
                ll s = sum[k] * inv[k] % mod;
                ll add_c = cnt_ans[i-1-k][j-k] * c % mod;
                ll add_s = (sum_ans[i-1-k][j-k] * c + cnt_ans[i-1-k][j-k] * s) % mod;
                cnt_ans[i][j] = (cnt_ans[i][j] + add_c) % mod;
                sum_ans[i][j] = (sum_ans[i][j] + add_s) % mod;
            }
            cnt_ans[i][j] %= mod;
            sum_ans[i][j] %= mod;
        }
    }
    ll ans = sum_ans[N][M] * fac[M] % mod;
    cout << ans << "\n";
}

#include <cstdio>
#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;
typedef long long ll;

ll mod_pow(ll a, ll e, ll mod) {
    ll r = 1;
    while(e) {
        if(e & 1) r = r * a % mod;
        a = a * a % mod;
        e >>= 1;
    }
    return r;
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int N, M;
    ll MOD;
    cin >> N >> M >> MOD;
    vector<ll> fact(N+1, 1), inv_fact(N+1, 1);
    for(int i=1; i<=N; ++i) {
        fact[i] = fact[i-1] * i % MOD;
        inv_fact[i] = inv_fact[i-1] * mod_pow(i, MOD-2, MOD) % MOD;
    }
    vector<ll> C(M+1, 0), S(M+1, 0);
    C[0] = 1;
    for(int m=1; m<=M; ++m) {
        ll csum = 0, ssum = 0;
        for(int k=0; k<m; ++k) {
            ll c_left = C[k] * inv_fact[k] % MOD;
            ll c_right = C[m-1-k] * inv_fact[m-1-k] % MOD;
            ll s_left = S[k] * inv_fact[k] % MOD;
            ll s_right = S[m-1-k] * inv_fact[m-1-k] % MOD;
            csum = (csum + c_left * c_right % MOD * (m+1)) % MOD;
            ssum = (ssum + (c_left * s_right + s_left * c_right) % MOD * (m+1)) % MOD;
            ll geo = (k*(k+1) + (m-k)*(m-k-1)) / 2;
            ssum = (ssum + c_left * c_right % MOD * (geo % MOD)) % MOD;
        }
        C[m] = csum * fact[m-1] % MOD;
        S[m] = ssum * fact[m-1] % MOD;
    }
    vector<vector<ll>> dp_cnt(N+1, vector<ll>(M+1, 0)), dp_sum(N+1, vector<ll>(M+1, 0));
    dp_cnt[0][0] = 1;
    // j outer, i inner
    for(int j=0; j<=M; ++j) {
        for(int i=j; i<=N; ++i) {
            if(i==0 && j==0) continue;
            dp_cnt[i][j] = (i>=1 ? dp_cnt[i-1][j] : 0);
            dp_sum[i][j] = (i>=1 ? dp_sum[i-1][j] : 0);
            if(j == i) {
                dp_cnt[i][j] = (dp_cnt[i][j] + C[i] * inv_fact[i]) % MOD;
                dp_sum[i][j] = (dp_sum[i][j] + S[i] * inv_fact[i]) % MOD;
            }
            for(int k=1; k<=min(j, i-1); ++k) {
                ll c = C[k] * inv_fact[k] % MOD;
                ll s = S[k] * inv_fact[k] % MOD;
                dp_cnt[i][j] = (dp_cnt[i][j] + dp_cnt[i-1-k][j-k] * c) % MOD;
                dp_sum[i][j] = (dp_sum[i][j] + dp_sum[i-1-k][j-k] * c + dp_cnt[i-1-k][j-k] * s) % MOD;
            }
            dp_cnt[i][j] %= MOD;
            dp_sum[i][j] %= MOD;
        }
    }
    ll ans = dp_sum[N][M] * fact[M] % MOD;
    cout << ans << "\n";
}

