typedef long long ll;

ll powmod(ll a, ll e, ll mod) {
    ll r = 1;
    while(e) {
        if(e & 1) r = r * a % mod;
        a = a * a % mod;
        e >>= 1;
    }
    return r;
}

struct Info {
    ll c; // count
    ll s; // sum
    Info(ll cc = 0, ll ss = 0) : c(cc), s(ss) {}
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int N, M;
    ll MOD;
    cin >> N >> M >> MOD;
    vector<ll> fact(N+1, 1), inv_fact(N+1, 1);
    for(int i = 1; i <= N; i++) {
        fact[i] = fact[i-1] * i % MOD;
        inv_fact[i] = inv_fact[i-1] * powmod(i, MOD-2, MOD) % MOD;
    }
    vector<Info> arr(M+1);
    arr[0] = Info(1, 0);
    for(int m = 1; m <= M; m++) {
        ll cnt_sum = 0, sum_sum = 0;
        for(int k = 0; k < m; k++) {
            ll cl = arr[k].c * inv_fact[k] % MOD;
            ll cr = arr[m-1-k].c * inv_fact[m-1-k] % MOD;
            ll sl = arr[k].s * inv_fact[k] % MOD;
            ll sr = arr[m-1-k].s * inv_fact[m-1-k] % MOD;
            cnt_sum = (cnt_sum + cl * cr % MOD * (m+1)) % MOD;
            sum_sum = (sum_sum + (cl * sr + sl * cr) % MOD * (m+1)) % MOD;
            ll geom = (k*(k+1) + (m-k)*(m-k-1)) / 2;
            sum_sum = (sum_sum + cl * cr % MOD * (geom % MOD)) % MOD;
        }
        arr[m].c = cnt_sum * fact[m-1] % MOD;
        arr[m].s = sum_sum * fact[m-1] % MOD;
    }
    vector<vector<Info>> dp(N+1, vector<Info>(M+1));
    dp[0][0].c = 1;
    for(int i = 1; i <= N; i++) {
        for(int j = 0; j <= min(i, M); j++) {
            dp[i][j].c = dp[i-1][j].c;
            dp[i][j].s = dp[i-1][j].s;
            if(j == i) {
                dp[i][j].c = (dp[i][j].c + arr[i].c * inv_fact[i]) % MOD;
                dp[i][j].s = (dp[i][j].s + arr[i].s * inv_fact[i]) % MOD;
            }
            for(int k = 1; k <= min(j, i-1); k++) {
                ll cc = arr[k].c * inv_fact[k] % MOD;
                ll ss = arr[k].s * inv_fact[k] % MOD;
                dp[i][j].c = (dp[i][j].c + dp[i-1-k][j-k].c * cc) % MOD;
                dp[i][j].s = (dp[i][j].s + dp[i-1-k][j-k].s * cc + dp[i-1-k][j-k].c * ss) % MOD;
            }
            dp[i][j].c %= MOD;
            dp[i][j].s %= MOD;
        }
    }
    ll ans = dp[N][M].s * fact[M] % MOD;
    cout << ans << "\n";
}

