struct modulus {
    int mod;
    int value;
    modulus(int mod_, ll v = 0) : mod(mod_), value(v % mod + (v % mod < 0 ? mod : 0)) {}
    modulus& norm() { if (value >= mod) value -= mod; return *this; }
    modulus operator-() const { return modulus(mod) - *this; }
    modulus& operator+=(const modulus& other) {
        value += other.value;
        if (value >= mod) value -= mod;
        return *this;
    }
    modulus& operator-=(const modulus& other) {
        value -= other.value;
        if (value < 0) value += mod;
        return *this;
    }
    modulus& operator*=(const modulus& other) {
        value = (ll)value * other.value % mod;
        return *this;
    }
    modulus& operator/=(const modulus& other) {
        return *this *= other.inverse();
    }
    modulus power(int exp) const {
        modulus res(mod, 1), x = *this;
        while (exp > 0) {
            if (exp & 1) res *= x;
            x *= x;
            exp >>= 1;
        }
        return res;
    }
    modulus inverse() const {
        return power(mod - 2);
    }
    int get() const { return value; }
    friend modulus operator+(const modulus& a, const modulus& b) { return modulus(a) += b; }
    friend modulus operator-(const modulus& a, const modulus& b) { return modulus(a) -= b; }
    friend modulus operator*(const modulus& a, const modulus& b) { return modulus(a) *= b; }
    friend modulus operator/(const modulus& a, const modulus& b) { return modulus(a) /= b; }
    friend ostream& operator<<(ostream& out, const modulus& m) { out << m.value; return out; }
    friend istream& operator>>(istream& in, modulus& m) {
        ll x; in >> x;
        m = modulus(m.mod, x);
        return in;
    }
};

modulus fact[modmax], finv[modmax];
void init_factorial(int mod) {
    fact[0] = modulus(mod, 1);
    for (int i = 1; i < modmax; i++) fact[i] = fact[i-1] * modulus(mod, i);
    finv[modmax-1] = fact[modmax-1].inverse();
    for (int i = modmax-2; i >= 0; i--) finv[i] = finv[i+1] * modulus(mod, i+1);
}

void solve() {
    int n, m;
    cin >> n >> m;
    int MOD;
    cin >> MOD;
    init_factorial(MOD);
    modulus ans(MOD, 0);
    auto pow_mod = [&](int base, int exp) -> modulus {
        modulus res(MOD, 1), b(MOD, base);
        while (exp) {
            if (exp & 1) res *= b;
            b *= b;
            exp >>= 1;
        }
        return res;
