    invfact[MAXV-1] = fact[MAXV-1].pow(mod-2);
    for(int i = MAXV-2; i >= 0; i--) invfact[i] = invfact[i+1] * MOD(mod, i+1);
}

int mod_power(int base, int exp, int mod) {
    int res = 1 % mod;
    int cur = base % mod;
    while(exp) {
        if(exp & 1) res = (ll)res * cur % mod;
        cur = (ll)cur * cur % mod;
        exp >>= 1;
    }
    return res;
}

