struct modular {
    static int mod;
    int v;
    modular(long long x = 0) {
        v = int(x % mod);
        if (v < 0) v += mod;
    }
    static int mod_pow(int a, int e) {
        int res = 1;
        while (e) {
            if (e & 1) res = (ll)res * a % mod;
            a = (ll)a * a % mod;
            e >>= 1;
        }
        return res;
    }
    modular& operator+=(const modular& o) {
        v += o.v;
        if (v >= mod) v -= mod;
        return *this;
    }
    modular& operator-=(const modular& o) {
        v -= o.v;
        if (v < 0) v += mod;
        return *this;
    }
    modular& operator*=(const modular& o) {
        v = (ll)v * o.v % mod;
        return *this;
    }
    modular& operator/=(const modular& o) {
        return *this *= o.inv();
    }
    modular inv() const {
        return modular(mod_pow(v, mod-2));
    }
    modular pow(int e) const {
        return modular(mod_pow(v, e));
    }
    friend modular operator+(modular a, const modular& b) { a += b; return a; }
    friend modular operator-(modular a, const modular& b) { a -= b; return a; }
    friend modular operator*(modular a, const modular& b) { a *= b; return a; }
    friend modular operator/(modular a, const modular& b) { a /= b; return a; }
    friend ostream& operator<<(ostream& os, const modular& m) { os << m.v; return os; }
