    }
    for(int i=0;i<=n;i++) {
        dp[i][0]=mp(1,0);
        for(int j=1;j<=i && j<=m;j++) {
            if(i!=j) {
                for(int k=1;k<=i;k++) {
                    pii part = p_mul(p_mul(dp[k-1][k-1], dp[i-k][j-k+1]), mp(C[j][k-1],0));
                    dp[i][j] = p_add(dp[i][j], part);
                }
            } else {
                for(int k=1;k<=i;k++) {
                    int a = k*k - sum_range(1,k) + sum_range(k+1,i) - k*(i-k);
                    pii fact = p_mul(p_mul(dp[k-1][k-1], dp[i-k][i-k]), mp(C[i-1][k-1],0));
                    pii term = mp(i+1, a);
                    dp[i][j] = p_add(dp[i][j], p_mul(fact, term));
                }
            }
        }
    }
    cout<<dp[n][m].se;
    return 0;
}

