static const int MAXN = 500;
ll c[MAXN + 1][MAXN + 1];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> mod;

    // binomial coefficients: c[i][j] = C(i+j, i) mod mod
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= n; ++j) {
            if (i == 0 || j == 0) c[i][j] = 1;
            else c[i][j] = (c[i-1][j] + c[i][j-1]) % mod;
        }
    }

    // a[k] = (cnt, sum) for trees of total "blocks" k
    vector<pll> a(m + 1, {0, 0});
    a[0] = {1, 0};
    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j < i; ++j) {
            ll cnt = a[j].first * a[i-1-j].first % mod;
            ll sum = (a[j].second * a[i-1-j].first + a[j].first * a[i-1-j].second) % mod;
            sum = (sum * (i + 1) + (ss(j) + ss(i-1-j)) % mod * cnt) % mod;
            cnt = cnt * (i + 1) % mod * c[j][i-1-j] % mod;
            sum = sum * c[j][i-1-j] % mod;
            a[i].first = (a[i].first + cnt) % mod;
            a[i].second = (a[i].second + sum) % mod;
        }
    }

    // dp[i][j] = (cnt, sum) after placing i positions and using j blocks
    vector<vector<pll>> d(n + 2, vector<pll>(m + 1, {0, 0}));
    d[0][0] = {1, 0};
    for (int i = 0; i <= n + 1; ++i) {
        for (int j = 0; j <= m; ++j) {
            int maxk = min(n - i, m - j);
            for (int k = 0; k <= maxk; ++k) {
                ll cnt = a[k].first * d[i][j].first % mod;
                ll sum = (a[k].second * d[i][j].first + a[k].first * d[i][j].second) % mod;
                cnt = cnt * c[j][k] % mod;
                sum = sum * c[j][k] % mod;
                int ni = i + k + 1, nj = j + k;
                d[ni][nj].first = (d[ni][nj].first + cnt) % mod;
                d[ni][nj].second = (d[ni][nj].second + sum) % mod;
            }
        }
    }

    cout << d[n + 1][m].second << '\n';
    return 0;
}

