        for (int k = 0; k < i; ++k) {
            ll c = comb(i - 1, k);
            ll fk = f[k], fik = f[i - 1 - k];
            ll gk = g[k], gik = g[i - 1 - k];
            f[i] = (f[i] + fk * fik % P * c) % P;
            g[i] = (g[i] + ((gk * fik + fk * gik) % P * (i + 1) % P + fk * fik % P * (sum(k) + sum(i - 1 - k)) % P) * c) % P;
        }
        f[i] = f[i] * (i + 1) % P;
    }

    vector<vector<ll>> F(m + 1, vector<ll>(n + 1, 0));
    vector<vector<ll>> G(m + 1, vector<ll>(n + 1, 0));
    for (int j = 0; j <= n; ++j) F[0][j] = 1;
    // swapped loops: outer j, inner i
    for (int j = 1; j <= n; ++j) {
        for (int i = 1; i <= m; ++i) {
            if (i == j) {
                F[i][j] = f[i];
                G[i][j] = g[i];
            } else if (i < j) {
                F[i][j] = F[i][j-1];
                G[i][j] = G[i][j-1];
                for (int l = 1; l <= i; ++l) {
                    ll c = comb(i, l);
                    ll fl = f[l], gl = g[l];
                    ll Fil = F[i-l][j-1-l], Gil = G[i-l][j-1-l];
                    F[i][j] = (F[i][j] + Fil * fl % P * c) % P;
                    G[i][j] = (G[i][j] + (Gil * fl + Fil * gl) % P * c) % P;
                }
            }
            // if i > j, F[i][j] remains 0 (unused)
        }
    }
    cout << G[m][n] << endl;
    return 0;
}

