}

int main() {
    ll n = read(), m = read(), P = read();
    int N = n + 1;
    vector<ll> fact(N + 1, 1), invf(N + 1, 1);
    for (int i = 1; i <= N; ++i) fact[i] = fact[i-1] * i % P;
    invf[N] = modpow(fact[N], P - 2, P);
    for (int i = N; i >= 1; --i) invf[i-1] = invf[i] * i % P;

    auto comb = [&](int x, int y) -> ll {
        if (x < y || y < 0) return 0;
        return fact[x] * invf[y] % P * invf[x - y] % P;
    };
    auto sum = [](int x) -> ll { return (ll)x * (x + 1) / 2; };

    vector<ll> f(m + 1, 0), g(m + 1, 0);
    f[0] = 1;
    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j < i; ++j) {
            ll c = comb(i - 1, j);
            ll fj = f[j], fij = f[i - 1 - j];
            ll gj = g[j], gij = g[i - 1 - j];
            f[i] = (f[i] + fj * fij % P * c) % P;
            g[i] = (g[i] + ((gj * fij + fj * gij) % P * (i + 1) % P + fj * fij % P * (sum(j) + sum(i - 1 - j)) % P) * c) % P;
        }
        f[i] = f[i] * (i + 1) % P;
    }

    // Recursive memoization for F and G
    vector<vector<ll>> F(m + 1, vector<ll>(n + 1, -1));
    vector<vector<ll>> G(m + 1, vector<ll>(n + 1, -1));
    function<ll(int,int)> getF = [&](int i, int j) -> ll {
        if (i == 0) return 1LL;
        if (j < i) return 0LL;
        if (F[i][j] != -1) return F[i][j];
        ll res = getF(i, j - 1);
        for (int l = 1; l <= i; ++l) {
            ll c = comb(i, l);
            res = (res + getF(i - l, j - 1 - l) * f[l] % P * c) % P;
        }
        return F[i][j] = res;
    };
    function<ll(int,int)> getG = [&](int i, int j) -> ll {
        if (i == 0) return 0LL;
        if (j < i) return 0LL;
        if (G[i][j] != -1) return G[i][j];
        ll res = getG(i, j - 1);
        for (int l = 1; l <= i; ++l) {
            ll c = comb(i, l);
            ll fl = f[l], gl = g[l];
            ll Fil = getF(i - l, j - 1 - l);
            ll Gil = getG(i - l, j - 1 - l);
            res = (res + (Gil * fl + Fil * gl) % P * c) % P;
        }
        return G[i][j] = res;
    };
    cout << getG(m, n) << endl;
    return 0;
}

