            P2[i] += P1[j-1]*P1[i-j]*nCr(i-1,j-1)*(nCr(j,2)+nCr(i-j+1,2));
        }
    }
    Q1[0][0]=1;
    for(i=1;i<=N;i++) {
        for(j=0;j<i;j++) {
            Q1[i][j]=Q1[i-1][j];
            Q2[i][j]=Q2[i-1][j];
            for(l=1;l<=j;l++) {
                Q1[i][j] += P1[l]*Q1[i-l-1][j-l]*nCr(j,l);
                Q2[i][j] += (P1[l]*Q2[i-l-1][j-l]+P2[l]*Q1[i-l-1][j-l])*nCr(j,l);
            }
        }
        Q1[i][i]=P1[i];
        Q2[i][i]=P2[i];
    }
    cout<<Q2[N][M]<<'\n';
}
