#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
static ll MO;
struct mint {
    ll x;
    mint(ll a=0) { if (MO && (a>=MO || a<0)) a=(a%MO+MO)%MO; x=a; }
    mint pw(ll e=MO-2) { mint a(*this), r(1); for(;e;e>>=1) { if(e&1) r*=a; a*=a; } return r; }
    mint& operator+=(mint a) { x+=a.x; if(x>=MO) x-=MO; return *this; }
    mint& operator-=(mint a) { x+=MO-a.x; if(x>=MO) x-=MO; return *this; }
    mint& operator*=(mint a) { x=x*a.x%MO; return *this; }
    mint& operator/=(mint a) { assert(a.x); *this*=a.pw(); return *this; }
    mint operator+(mint a) const { mint r(*this); return r+=a; }
    mint operator-(mint a) const { mint r(*this); return r-=a; }
    mint operator*(mint a) const { mint r(*this); return r*=a; }
    mint operator/(mint a) const { mint r(*this); return r/=a; }
    friend ostream& operator<<(ostream& os, mint a) { os<<a.x; return os; }
};
int N, M;
mint dpA[505], dpB[505], dpC[505][505], dpD[505][505];
ll Cnk(ll n, ll k) {
    static ll fac[400005], inv[400005], finv[400005];
    if (fac[0]==0) {
        inv[1]=fac[0]=finv[0]=1;
        for (int i=2;i<=400004;i++) inv[i]=inv[MO%i]*(MO-MO/i)%MO;
        for (int i=1;i<=400004;i++) fac[i]=fac[i-1]*i%MO, finv[i]=finv[i-1]*inv[i]%MO;
    }
    if (k<0 || k>n) return 0;
    return finv[k]*fac[n]%MO*finv[n-k]%MO;
}
void solve() {
    cin>>N>>M>>MO;
    dpA[0]=1;
    for (int i=1; i<=N; ++i) {
        for (int j=1; j<=i; ++j) {
            dpA[i] += mint(i+1)*dpA[j-1]*dpA[i-j]*Cnk(i-1,j-1);
        }
    }
    for (int i=1; i<=N; ++i) {
        for (int j=1; j<=i; ++j) {
            dpB[i] += mint(i+1)*(dpB[i-j]*dpA[j-1] + dpA[i-j]*dpB[j-1])*Cnk(i-1,j-1);
            dpB[i] += dpA[j-1]*dpA[i-j]*Cnk(i-1,j-1)*(Cnk(j,2)+Cnk(i-j+1,2));
        }
    }
    dpC[0][0]=1;
    for (int i=1; i<=N; ++i) {
        for (int j=0; j<i; ++j) {
            dpC[i][j]=dpC[i-1][j];
            dpD[i][j]=dpD[i-1][j];
            for (int l=1; l<=j; ++l) {
                dpC[i][j] += dpA[l]*dpC[i-l-1][j-l]*Cnk(j,l);
                dpD[i][j] += (dpA[l]*dpD[i-l-1][j-l] + dpB[l]*dpC[i-l-1][j-l])*Cnk(j,l);
            }
        }
        dpC[i][i]=dpA[i];
        dpD[i][i]=dpB[i];
    }
    cout<<dpD[N][M]<<'\n';
}
