using namespace std;

int MOD;

inline int add(int a, int b) { int s = a + b; return s >= MOD ? s - MOD : s; }
inline int sub(int a, int b) { int d = a - b; return d < 0 ? d + MOD : d; }
inline int mul(int a, int b) { return (long long)a * b % MOD; }

const int MAXN = 1050;
int n, m;
int f[MAXN], g[MAXN];
int fact[MAXN], inv_fact[MAXN];

int binom(int n, int k) {
    if (k < 0 || k > n) return 0;
    return mul(fact[n], mul(inv_fact[k], inv_fact[n - k]));
}

int modpow(int a, int e) {
    int res = 1;
    while (e) {
        if (e & 1) res = mul(res, a);
        a = mul(a, a);
        e >>= 1;
    }
    return res;
}

void precompute_fact(int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = mul(fact[i-1], i);
    inv_fact[n] = modpow(fact[n], MOD - 2);
    for (int i = n; i >= 1; --i) inv_fact[i-1] = mul(inv_fact[i], i);
}

int main() {
    cin >> n >> m >> MOD;
    precompute_fact(max(m, n - m + 1));
    f[1] = 2; g[1] = 0;
    for (int i = 2; i <= m; ++i) {
        f[i] = mul(f[i-1], 2 * (i + 1));
        g[i] = mul(g[i-1], 2 * (i + 1));
        g[i] = add(g[i], mul(f[i-1], i * (i - 1)));
        for (int j = 1; j < i; ++j) {
            int k = i - j - 1;
            int c = mul(binom(j + k, j), j + k + 2);
            f[i] = add(f[i], mul(c, mul(f[j], f[k])));
            g[i] = add(g[i], mul(c, mul(f[j], g[k])));
            g[i] = add(g[i], mul(c, mul(g[j], f[k])));
            int w = j * (j + 1) / 2 + k * (k + 1) / 2;
            g[i] = add(g[i], mul(mul(binom(j + k, j), w), mul(f[j], f[k])));
        }
    }
    static int dp[MAXN][MAXN][2];
    memset(dp, 0, sizeof(dp));
    dp[0][0][0] = 1;
    for (int i = 0; i <= m; ++i)
        for (int j = 0; j <= m; ++j)
            for (int o = 0; o < 2; ++o) {
                int cur = dp[i][j][o];
                if (!cur) continue;
                if (o == 0) {
                    for (int k = 1; k + j <= m; ++k) {
                        int coeff = mul(cur, binom(j + k, k));
                        dp[i+1][j+k][0] = add(dp[i+1][j+k][0], mul(coeff, f[k]));
                        dp[i+1][j+k][1] = add(dp[i+1][j+k][1], mul(coeff, g[k]));
                    }
                } else {
                    for (int k = 1; k + j <= m; ++k) {
                        int coeff = mul(cur, binom(j + k, k));
                        dp[i+1][j+k][1] = add(dp[i+1][j+k][1], mul(coeff, f[k]));
                    }
                }
            }
    int ans = 0;
    for (int i = 1; i <= m; ++i)
        ans = add(ans, mul(dp[i][m][1], binom(n - m + 1, i)));
    cout << ans << '\n';
    return 0;
}

