typedef long long LL;
const int SZ = 510;
int N, M, MOD;
LL comb[SZ][SZ];
LL fArr[SZ], gArr[SZ];
LL dp[SZ][SZ], ways[SZ][SZ];
LL dpTmp[SZ][SZ], waysTmp[SZ][SZ];
LL dpPrev[SZ][SZ], waysPrev[SZ][SZ];

void push(LL &a, LL b) {
    a = (a + b) % MOD;
}

LL pairVal(LL x) {
    return (x * (x - 1) / 2) % MOD;
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> N >> M >> MOD;
    for (int i = 0; i < SZ; ++i) comb[i][0] = 1;
    for (int i = 1; i < SZ; ++i)
        for (int j = 1; j <= i; ++j)
            comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD;

    fArr[0] = 0; gArr[0] = 1;
    for (int i = 1; i <= M; ++i) {
        for (int j = 1; j <= i; ++j) {
            LL mul = comb[i-1][j-1];
            LL a1 = mul * fArr[j-1] % MOD * gArr[i-j] % MOD * (i+1) % MOD;
            LL a2 = mul * gArr[j-1] % MOD * fArr[i-j] % MOD * (i+1) % MOD;
            LL a3 = mul * gArr[j-1] % MOD * gArr[i-j] % MOD
                    * ((pairVal(j) + pairVal(i-j+1)) % MOD) % MOD;
            push(fArr[i], (a1 + a2 + a3) % MOD);
            push(gArr[i], mul * gArr[j-1] % MOD * gArr[i-j] % MOD * (i+1) % MOD);
        }
    }

    dp[0][0] = 0; ways[0][0] = 1;
    for (int i = 0; i < N; ++i) {
        fill(&dpTmp[0][0], &dpTmp[0][0] + SZ*SZ, 0);
        fill(&waysTmp[0][0], &waysTmp[0][0] + SZ*SZ, 0);
        int upperJ = min(i, M);
        for (int j = 0; j <= upperJ; ++j) {
            int upperK = min(j, M);
            for (int k = 0; k <= upperK; ++k) {
                if (k == 0) {
                    dpPrev[i][j] = dp[j][0];
                    waysPrev[i][j] = ways[j][0];
                }
                push(dpTmp[j][0], dp[j][k]);
                push(waysTmp[j][0], ways[j][k]);
                int rem = M - (j - k);
                push(waysTmp[j+1][k+1], waysPrev[i-k][j-k] * comb[rem][k+1] % MOD * gArr[k+1] % MOD);
                LL b1 = dpPrev[i-k][j-k] * comb[rem][k+1] % MOD * gArr[k+1] % MOD;
                LL b2 = waysPrev[i-k][j-k] * comb[rem][k+1] % MOD * fArr[k+1] % MOD;
                push(dpTmp[j+1][k+1], (b1 + b2) % MOD);
            }
        }
        for (int j = 0; j < SZ; ++j)
            for (int k = 0; k < SZ; ++k) {
                dp[j][k] = dpTmp[j][k];
                ways[j][k] = waysTmp[j][k];
            }
    }

    LL res = 0;
    for (int j = 0; j <= M; ++j)
        push(res, dp[M][j]);
    cout << res << "\n";
    return 0;
}

