class Modular {
public:
    ll val;
    Modular() : val(0) {}
    Modular(ll v) { val = v >= 0 ? v % mod : v % mod + mod; }
    Modular mod_pow(ll e) const {
        if(e==0) return 1;
        Modular t = mod_pow(e/2);
        return (e&1) ? t*t*(*this) : t*t;
    }
    Modular inv() const {
        static unordered_map<ll,ll> cache;
        if(cache.find(val) != cache.end()) return cache[val];
        if(cache.size() < 100000) {
            ll res = mod_pow(mod-2).val;
            cache[val] = res;
            return res;
        }
        return mod_pow(mod-2);
    }
    Modular operator+(const Modular &b) const { return Modular((val + b.val) % mod); }
    Modular operator-(const Modular &b) const { return Modular((val - b.val + mod) % mod); }
    Modular operator*(const Modular &b) const { return Modular((val * b.val) % mod); }
    Modular operator/(const Modular &b) const { return *this * b.inv(); }
    Modular &operator+=(const Modular &b) { val = (val + b.val) % mod; return *this; }
    Modular &operator-=(const Modular &b) { val = (val - b.val + mod) % mod; return *this; }
    Modular &operator*=(const Modular &b) { val = (val * b.val) % mod; return *this; }
    Modular &operator/=(const Modular &b) { val = (val * b.inv().val) % mod; return *this; }
    bool operator==(const Modular &b) const { return val == b.val; }
    bool operator!=(const Modular &b) const { return val != b.val; }
};

