int main(){
	scanf("%d%d%d",&n,&m,&mo);
	for(int i=0;i<=n+1;i++){
		C[i][0]=1;
		for(int j=1;j<=i;j++)
			C[i][j]=(C[i-1][j-1]+C[i-1][j])%mo; // swapped order
	}
	f[0]=1; g[0]=0; f[1]=2; g[1]=0;
	for(int i=2;i<=n;i++){
		ll tmp1 = f[i-1]*(i+1)*2 % mo;
		f[i] = (f[i] + tmp1) % mo;
		ll tmp2 = f[i-1]*i%mo*(i-1) % mo;
		g[i] = (g[i] + tmp2) % mo;
		ll tmp3 = g[i-1]*(i+1)*2 % mo;
		g[i] = (g[i] + tmp3) % mo;
		for(int j=1;j+1<i;j++){
			int k=i-j-1;
			ll comb = C[j+k][k];
			ll term1 = f[j]*f[k]%mo*(j+k+2)%mo*comb % mo;
			f[i] = (f[i] + term1) % mo;
			ll term2 = (g[j]*f[k] + g[k]*f[j])%mo*(j+k+2)%mo*comb % mo;
			g[i] = (g[i] + term2) % mo;
			ll sum_sq = (1ll*(j+1)*j/2 + 1ll*(k+1)*k/2) % mo;
			ll term3 = f[j]*f[k]%mo*comb%mo*sum_sq % mo;
			g[i] = (g[i] + term3) % mo;
		}
	}
	f0[0][0]=1; g0[0][0]=0;
	for(int i=0;i<=m;i++) for(int j=0;j<=m;j++) if(f0[i][j]){
		for(int k=1;j+k<=m;k++){
			ll comb = C[j+k][k];
			f0[i+1][j+k] = (f0[i+1][j+k] + f0[i][j]*f[k]%mo*comb) % mo;
			g0[i+1][j+k] = (g0[i+1][j+k] + (g0[i][j]*f[k] + f0[i][j]*g[k])%mo*comb) % mo;
		}
	}
	ans=0;
	for(int i=1;i<=m;i++) if(n+1-m-i>=0){
		ll add = g0[i][m] * P(n+1-m-i,i+1) % mo;
		ans = (ans + add) % mo;
	}
	printf("%lld\n",ans);
}

