		for (int j = 1; j <= i; ++j) {
			C[i][j] = C[i-1][j] + C[i-1][j-1];
			if (C[i][j] >= mod) C[i][j] -= mod;
		}
	}

	dp1[0].first = 1;
	for (int i = 1; i <= m; ++i) {
		for (int j = 1; j <= i; ++j) {
			int w = (ll)dp1[j-1].first * dp1[i-j].first % mod * C[i-1][j-1] % mod;
			addmod(dp1[i].second, (sum1(j-1) + sum1(i-j)) * (ll)w % mod);
			addmod(dp1[i].second, (ll)dp1[j-1].second * dp1[i-j].first % mod * (i+1) % mod * C[i-1][j-1] % mod);
			addmod(dp1[i].second, (ll)dp1[j-1].first * dp1[i-j].second % mod * (i+1) % mod * C[i-1][j-1] % mod);
			addmod(dp1[i].first, (ll)w * (i+1) % mod);
		}
	}

	dp2[0][0][0].first = dp2[1][0][0].first = 1;
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j <= i; ++j) {
			for (int len = 1; len <= n-i; ++len) {
				addmod(dp2[1][i+len][j].first, dp2[0][i][j].first);
				addmod(dp2[1][i+len][j].second, dp2[0][i][j].second);

				addmod(dp2[0][i+len][j+len].first, (ll)dp2[1][i][j].first * dp1[len].first % mod * C[j+len][j] % mod);
