        inv_fact[i] = mul(inv_fact[i - 1], inv_num[i]);
    }
}
inline int C(int n, int m) {
    if (n < m || m < 0) return 0;
    return mul(mul(fact[n], inv_fact[m]), inv_fact[n - m]);
}
inline int P(int n, int m) { return C(n + m - 1, m - 1); }

int F[MAXN], G[MAXN], S[MAXN];
int DPF[MAXN][MAXN], DPG[MAXN][MAXN];

int main() {
    scanf("%d %d %d", &n, &m, &mod);
    precompute(500);
    for (int i = 1; i <= n; i++) S[i] = add(S[i - 1], i);
    F[0] = 1; F[1] = 2;
    G[0] = 0; G[1] = 0;
    for (int i = 2; i <= n; i++) {
        // Unroll the two contributions to g[i] into single expression
        for (int j = 0; j < i; j++) {
            int comb = C(i - 1, j);
            int term_f = mul(comb, mul(F[j], F[i - 1 - j]));
            F[i] = add(F[i], mul(term_f, i + 1));
            int term_g = mul(comb, mul(F[j], F[i - 1 - j]));
            G[i] = add(G[i], mul(term_g, S[j] + S[i - 1 - j]));
            term_g = mul(add(mul(G[j], F[i - 1 - j]), mul(G[i - 1 - j], F[j])), i + 1);
            G[i] = add(G[i], mul(term_g, comb));
        }
    }
    DPF[0][0] = 1; DPG[0][0] = 0;
    for (int i = 0; i <= m; i++)
        for (int j = 0; j <= m; j++) {
            if (!DPF[i][j]) continue;
            for (int k = 1; k + j <= m; k++) {
                int c = C(j + k, k);
                DPF[i + 1][j + k] = add(DPF[i + 1][j + k], mul(mul(DPF[i][j], F[k]), c));
                DPG[i + 1][j + k] = add(DPG[i + 1][j + k], mul(add(mul(DPG[i][j], F[k]), mul(DPF[i][j], G[k])), c));
            }
        }
    int ans = 0;
    for (int i = 1; i <= m; i++)
        if (n + 1 - m >= i)
            ans = add(ans, mul(DPG[i][m], P(n + 1 - m - i, i + 1)));
    printf("%d\n", ans);
    return 0;
}

