using namespace std;
const int N = 505;
int n, m, mod;
int C[N][N];
int way[N], sum[N];
int f[N][N], g[N][N];
bool visF[N][N], visG[N][N];

int add(int a, int b) { if (a + b >= mod) return a + b - mod; return a + b; }
int mul(int a, int b) { return (long long)a * b % mod; }
int get(int i) { return i * (i + 1) / 2; }

int calcF(int i, int j) {
	if (i == 0 && j == 0) return 1;
	if (visF[i][j]) return f[i][j];
	visF[i][j] = true;
	int res = 0;
	for (int k = 0; k <= j && k < i; ++k) {
		int ni = i - k - 1;
		int nj = j - k;
		res = add(res, mul(mul(calcF(ni, nj), way[k]), C[j][nj]));
	}
	return f[i][j] = res;
}

int calcG(int i, int j) {
	if (i == 0 && j == 0) return 0;
	if (visG[i][j]) return g[i][j];
	visG[i][j] = true;
	int res = 0;
	for (int k = 0; k <= j && k < i; ++k) {
		int ni = i - k - 1;
		int nj = j - k;
		int a = mul(calcF(ni, nj), sum[k]);
		int b = mul(calcG(ni, nj), way[k]);
		res = add(res, mul(add(a, b), C[j][nj]));
	}
	return g[i][j] = res;
}

