			sum[i] = add(sum[i], mul(mul(mul(add(get(j), get(i-j-1)), way[j]), way[i-j-1]), c));
			sum[i] = add(sum[i], mul(mul(i+1, add(mul(sum[j], way[i-j-1]), mul(way[j], sum[i-j-1]))), c));
		}

