			}
		}
	}
	cout << val[n][m] << endl;
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int N = 505;
int n, m, mod;
int C[N][N];
int w[N], s[N];
int f[N][N], g[N][N];

int add(int a, int b) { return (a + b >= mod) ? a + b - mod : a + b; }
int mul(int a, int b) { return (long long)a * b % mod; }
int tri(int i) { return i * (i + 1) / 2; }

void computeWays() {
	w[0] = 1;
	for (int i = 1; i <= m; ++i) {
		for (int j = 0; j < i; ++j) {
			int c = C[i-1][j];
			w[i] = add(w[i], mul(mul(i+1, c), mul(w[j], w[i-j-1])));
			s[i] = add(s[i], mul(mul(mul(add(tri(j), tri(i-j-1)), w[j]), w[i-j-1]), c));
			s[i] = add(s[i], mul(mul(i+1, add(mul(s[j], w[i-j-1]), mul(w[j], s[i-j-1]))), c));
		}
	}
}

void computeDP() {
	f[0][0] = 1;
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j <= m; ++j) {
			for (int k = 0; j + k <= m && i + k + 1 <= n; ++k) {
				f[i+k+1][j+k] = add(f[i+k+1][j+k], mul(mul(f[i][j], w[k]), C[j+k][j]));
				g[i+k+1][j+k] = add(g[i+k+1][j+k], mul(add(mul(f[i][j], s[k]), mul(g[i][j], w[k])), C[j+k][j]));
			}
		}
	}
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	cin >> n >> m >> mod;

	for (int i = 0; i <= m; ++i) {
		C[i][0] = 1;
		for (int j = 1; j <= i; ++j)
			C[i][j] = add(C[i-1][j-1], C[i-1][j]);
	}

	computeWays();
	n++;
	computeDP();
	cout << g[n][m] << endl;
	return 0;
}

